window.PACK={"book":{"id":"diwan-barudi","title":"ديوان محمود سامي البارودي","type":"diwan","author":"محمود سامي البارودي (ت ١٣٢٢هـ (١٩٠٤م))","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"hadith","packVersion":"11a13690ffe8"},"items":[{"id":"diwan-barudi:1","bookId":"diwan-barudi","type":"poem","seq":1,"chapter":"البحر: بسيط تام","title":"قلدت جيد المعالى حلية الغزل","page":"","text":"قلدت جيد المعالى حلية الغزل … \nيأبى لى الغى لا يميل به … عن شرعة المجد سحر الأعين النجل\nأهيم بالبيض في الأغماد باسمة … عن غرة النصر ، لا بالبيض في الكلل\nوقلت في الجد ما أغنى عن الهزل … في لذة الصحو ما يغنى عن الثمل\nكم بين منتدب يدعو لمكرمة … وبين معتكف يبكي على طلل\nلولا التفاوت بين الخلق ما ظهرت … لم يخط فيها امرؤ إلا على زلل\nفانهض إلى صهوات المجد معتليا … فالباز لم يأو إلا عالي القلل\nودع من الأمر أدناه لأبعده … في لجة\nقد يظفر الفاتك الألوى بحاجته … ويقعد العجز بالهيابة الوكل\nوكن على حذر تسلم ، فرب فتى … ألقى به الأمن بين اليأس والوجل\nولا يغرنك بشر من أخى ملق … فرونق الآل لا يشفى من الغلل\nلو يعلم ما في الناس من دخن … لبات من ود ذي القربى على دخل\n … فالكحل أشبه في العينين بالكحل\nواخش النميمة ، واعلم أن قائلها … يصليك من حرها نارا بلا شعل\nكم فرية صدعت أركان مملكة … ومزقت شمل ود غير منفصل\nفاقبل وصاتي ، ولا تصرفك لاغية … عنى ؛ فما كل رام من بنى ثعل\nإني امرؤ كفنى حلمي ، وأدبني … كر الجديدين من ماض ومقتبل\nفما سريت قناع الحلم عن سفه … ولا مسحت جبين العز من خجل\nحلبت أشطر هذا الدهر تجربة … وذقت مافيه من صاب ، ومن عسل\nفما وجدت على الأيام باقية … أشهى إلى النفس من حرية العمل\nلكننا غرض للشر في زمن … أهل العقول به في طاعة الخمل\nقامت به من رجال السوء طائفة … أدهى على النفس من بؤس على ثكل\nمن كل وغد يكاد الدست يدفعه … بغضا ، ويلفظه الديوان من ملل\nذلت بهم مصر بعد العز ، واضطربت … قواعد الملك ، حتى ظل في خلل\nوأصبحت دولة ( الفسطاط ) خاضعة … بعد الإباء ، وكانت زهرة الدول\nقوم إذا أبصروني مقبلا وجموا … غيظا ، وأكبادهم تنقد من دغل\n … فالشمس وهي ضياء آفة المقل\nنزهت نفسي عما يدنيون به … ونخلة الروض تأبى شيمة الجعل\nبئس العشير ، وبئست مصر من بلد … أضحت مناخا لأهل الزور والخطل\nأرض تأثل فيها الظلم ، وانقذفت … صواعق الغدر بين السهل والجبل\nوأصبح الناس في عمياء مظلمة … \nلم أدر ما حل بالأبطال من خور … بعد المراس ، وبالأسياف من فلل\nأصوحت شجرات المجد ، أم نضبت … غدر الحمية حتى ليس من رجل ؟\nلا يدفعون يداعنهم ، ولو بلغت … مس العفافة من جبن ، ومن خزل\nخافوا المنية ، فاحتالوا ، وما علموا … أن المنية لا ترتد بالحيل\nففيم يتهم الإنسان خالقه … وكل نفس لها قيد من الأجل ؟\nهيهات يلقى الفتى أمنا يلد به … ما لم يخض نحوه بحرا من الوهل\nفما لكم لا تعاف الضيم أنفسكم … ولا تزول غواشيكم من الكسل ؟\nوتلك مصر التي أفنى الجلاد بها … لفيف أسلافكم في الأعصر الأول\nقوم أقروا عماد الحق وامتلكوا … أزمة الخلق من حاف ومنتعل\nجنوا ثمار العلا بالبيض ، واقتطفوا … من بين شوك العوالي زهرة الأمل\nفأصبحت مصر تزهو بعد كدرتها … في يانع من أساكيب الندى خضل\nلم تنبت الأرض إلا بعدما اختمرت … أقطارها بدم الأعناق والقلل\nشنوا بها غارة ألقت بروعتها … أمنا يولف بين الذئب والحمل\nحتى إذا أصبحت في معقل أشب … يرد عنها يد العادي من الملل\nأخنى الزمان على فرسانها ، فغدت … من بعد منعتها مطروقة السبل\nفأي عار جلبتم بالخمول على … ما شاده السيف من فخر على زحل\nإن لم يكن للفتى عقل يعيش به … فإنما هو معدود من الهمل\nفبادروا الأمر قبل الفوت ، وانتزعوا … شكالة الريث ، فالدنيا مع العجل\nوقلدوا أمركم شهما أخا ثقة … يكون رداء لكم في الحادث الجلل\nماضي البصيرة ، غلاب ، إذا اشتبهت … مسالك الرأي صاد الباز بالحجل\nإن قال بر ، وإن ناداه منتصر … لبى ، وإن هم لم يرجع بلا نفل\nيجلو البديهة باللفظ الوجيز إذا … عز الخطاب ، وطاشت أسهم الجدل\nولا تلجوا إذا ما الرأي لاح لكم … إن اللجاجة مدعاة إلى الفشل\nقد يدرك المرء بالتدبير ما عجزت … عنه الكماة ، ولم يحمل على بطل\nهيهات ، ما النصر في حد الأسنة ، بل … بقوة الرأي تمضي شوكة الأسل\nوطالبوا بحقوق أصبحت غرضا … لكل منتزع سهما ، ومختتل\nولا تخافوا نكالا فيه منشوكم … فالحوت في اليم لا يخشى من البلل\nعيش الفتى في فناء الذل منقصة … والموت في العز فخر السادة النبل\nلا تتركوا الجد أو يبدو اليقين لكم … فالجد مفتاح باب المطلب العضل\nطورا عراكا ، وأحيانا مياسرة … رياضة المهر بين العنف والمهل\nحتى تعود سماء الأمن ضاحية … ويرفل العدل في ضاف من الحلل\nهذي نصيحة من لا يبتغي بدلا … بكم ، وهل بعد قوم المرء من بدل ؟\nأسهرت جفني لكم في نظم قافية … ما إن لها في قديم الشعر من مثل\nكالبرق في عجل ، والرعد في زجل … والغيث في هلل ، والسيل في همل\nغراء ، تعلقها الأسماع من طرب … وتستطير بها الألباب من جذل\nحولية ، صاغها فكر أقر له … بالمعجزات قبيل الإنس والخبل\nتلوح أبياتها شطرين في نسق … كالمرفية قد سلت من الخلل\nإن أخلقت جدة الأشعار أثلها … لفظ أصيل ، ومعنى غير منتحل\nتفنى النفوس ، وتبقى وهي ناضرة … على الدهور بقاء السبعة الطول"},{"id":"diwan-barudi:2","bookId":"diwan-barudi","type":"poem","seq":2,"chapter":"البحر: طويل","title":"طربت ، ولولا الحلم أدركني الجهل","page":"","text":"طربت ، ولولا الحلم أدركني الجهل … وعاودني ما كان من شرتي قبل\nفرحت ، كأني خامرتني سبيئة … من الراح ، من يعلق بها الدهر لا يسلو\nسليلة كرم ، شاب في المهد رأسها … ودب لها نسل ، وما مسها بعل\nإذا ولجت بيت الضمير ، رأيتها … وراء بنات الصدر ، تسفل ، أو تعلو\nكأن لها ضغنا على العقل كامنا … فإن هي حلت منزلا رحل العقل\nتعبر عن سر الضمير بألسن … من السكر مقرون بصحتها النقل\nمحببة للنفس ، وهي بلاؤها … كما حببت في فتكها الأعين النجل\nيكاد يذود الليث عن مستقره … إذا ما تحسى كأسها العاجز الوغل\nترى لخوابيها أزيزا ، كأنها … خلايا تغنت في جوانبها النحل\nسواكن آطام ، زفتها مع الضحى … يدا عاسل يشتار ، أو خابط يفلو\nدنا ، ثم ألقى النار بين بيوتها … فطارت شعاعا ، لا يقر لها رحل\nمروعة ، هيجت ، فضلت سبيلها … فسارت على الدنيا ، كما انتشر الرجل\nفبت أداري القلب بعض شجونه … وأزجر نفسي أن يلم بها الهزل\nوما كنت أدري - والشباب مطية … إلى الجهل - أن العشق يعقبه الخبل\nرمى الله هاتيك العيون بما رمت … وحاسبها حسبان من حكمه العدل\nفقد تركتني ساهي العقل ، سادرا … إلى الغي ، لا عقد لدي ، ولا حل\nأسير ، وما أدري إلى أين ينتهي … بي السير ، لكني تلقفني السبل\nفلا تسألني عن هواي ؛ فإنني … وربك أدري كيف زلت بي النعل ؟\nفما هي إلا أن نظرت فجاءة … بحلوان حيث انهار ، وانعقد الرمل\nإلى نسوة مثل الجمان ، تناسقت … فرائده حسنا ، وألفه الشمل\nمن الماطلات المرء ما قد وعدنه … كذابا ؛ فلا عهد لهن ، ولا إل\nتكنفن تمثالا من الحسن رائعا … يجن جنونا عند رؤيته العقل\nفكان الذي لولاه ما درت هائما … أرود الفيافي ، لا صديق ، ولا خل\nفويلمها من نظرة مضرجية … رميت بها من حيث واجهني الأثل\nرميت بها والقلب خلو من الهوى … فما برحت حتى استقل به شغل\nلقد علقت ما ليس للنفس دونها … غناء ، ولا منها لذي صبوة وصل\nفتاة يحار الطرف في قسماتها … لها منظر من رائد العين لا يخلو\nلطيفة مجرى الروح ، لو أنها مشت … على ساربات الذر ما آده الحمل\nلها نظرة سكرى ، إذا أرسلت بها … إلى كبد ؛ فالويل من ذاك والثكل\nتريق دماء حرم الله سفكها … وتخرج منها ، لا قصاص ، ولا عقل\nلنا كل يوم في هواها مصارع … يهيج الردى فيها ، ويلتهب القتل\nمصارع شوق ، ليس يجري بها دم … ومرمى نفوس لا يطير به نبل\nهنيئا لها نفسي ، على أن دونها … فوارس ، لا خرس الصفاح ، ولا عزل\nمن القوم ضرابي العراقيب والطلى … إذا استنت الغارات ، أو فغر المحل\nإذا نامت الأضغان عن وتراتها … فقومي قوم لا ينام لهم ذحل\nرجال أولو بأس شديد ونجدة … فقولهم قول ، وفعلهم فعل\nإذا غضبوا ردوا إلى الأفق شمسه … وسال بدفاع القنا الحزن والسهل\nمساعير حرب ، لا يخافون ذلة … ألا إن تهياب الحروب هو الذل\nإذا أطرقوا أبصرت ، بالقوم خيفة … لإطراقهم ، أو بينوا ركد الحفل\nوإن زلت الأقدام في درك غاية … تحار بها الألباب كان لها الخصل\nأولئك قومي ، أي قوم وعدة … فلا ربعهم محل ، ولا ماؤهم ضحل\nيفيضون بالمعروف فيضا ، فليس في … عطائهم وعد ، ولا بعده مطل\nفزرهم تجد معروفهم داني الجنى … عليك ، وباب الخير ليس له قفل\nترى كل مشبوب الحمية ، لم يسر … إلى فئة إلا وطائره يعلو\nبعيد الهوى ، لا يغلب الظن رأيه … ولا يتهادى بين تسراعه المهل\nتصيح القنا مما يدق صدورها … طعانا ، ويشكو فعل ساعده النصل\nإذا صال روى السيف حر غليله … وإن قال أورى زنده المنطق الفصل\nله بين مجرى القول آيات حكمة … يدور على آدابها الجد والهزل\nتلوح عليه من أبيه وجده … مخايل ساوى بينها الفرع والأصل\nفأشيبنا في ملتقى الخيل أمرد … وأمردنا في كل معضلة كهل\nلنا الفصل فيما قد مضى ، وهو قائم … لدينا ، وفيما بعد ذاك لنا الفضل"},{"id":"diwan-barudi:3","bookId":"diwan-barudi","type":"poem","seq":3,"chapter":"البحر: طويل","title":"مضى اللهو ، إلا أن يخبر سائل","page":"","text":"مضى اللهو ، إلا أن يخبر سائل … وولى الصبا إلا بواق قلائل\nبواق تماريها أفانين لوعة … يورثها فكر على النأي شاغل\nفللشوق منى عبرة مهراقة … وخبل إذا نام الخليون خابل\nألفت الضنى إلف السهاد ، فلو سرى … بي البرء غالتني لذاك الغوائل\nفلله هذا الشوق ! أي جراحة … أسال بنا ؟ حتى كأنا نقاتل\nرضينا بحكم الحب فينا ، وإننا … للد إذا التفت علينا الجحافل\nوإنا رجال تعلم الحرب أننا … بنوها ، ويدري المجد ماذا نحاول\nإذا ما ابتنى الناس الحصون ، فمالنا … سوى البيض والسمر اللدان معاقل\nفما للهوى يقوى علي بحكمه ؟ … ألم يدر أني الشمري الحلاحل ؟\nوإني لثبت الجأش ، مستحصد القوى … إذا أخذت أيدي الكماة الأفاكل\nإذا ما اعتقلت الرمح والرمح صاحبي … على الشر قال القرن : إني هازل\nلطاعنت حتى لم أجد من مطاعن … ونازلت حتى لم أجد من ينازل\nوشاغبت هذا الدهر مني بعزمة … أرتني سبيل الرشد والغي حائل\nإذا أنت أعطتك المقادير حكمها … فأضيع شيء ما تقول العواذل\nوما المرء إلا أن يعيش محسدا … تنازع فيه الناجذين الأنامل\nلعمرك ما الأخلاق إلا مواهب … مقسمة بين الورى ، وفواضل\nوما الناس إلا كادحان : فعالم … يسير على قصد ، وآخر جاهل\nفذو العلم مأخوذ بأسباب علمه … وذو الجهل مقطوع القرينة جافل\nفلا تطلبن في الناس مثقال ذرة … من الود ؛ أم الود في الناس هابل\nمن العار أن يرضى الفتى غير طبعه … وأن يصحب الإنسان من لا يشاكل\nبلوت ضروب الناس طرا ، فلم يكن … سوى ' المرصفى ' الحبر في الناس كامل\nهمام أراني الدهر في طي برده … وفقهني حتى اتقتني الأماثل\nأخ حين لا يبقى أخ ، ومجامل … إذا قل عند النائبات المجامل\nبعيد مجال الفكر ، لو خال خيلة … أراك بظهر الغيب ما الدهر فاعل\nطرحت بني الأيام لما عرفته … وما الناس عند البحث إلا مخايل\nفلو سامني ما يورد النفس حتفها … لأوردتها ؛ والحب للنفس قاتل\nفلا برحت مني إليه تحية … تناقلها عني الضحى والأصائل\nولا زال غض العمر ، ممتنع الذرا … مريع الفنا ، تطوى إليه المراحل"},{"id":"diwan-barudi:4","bookId":"diwan-barudi","type":"poem","seq":4,"chapter":"البحر: طويل","title":"عصيت نذير الحلم في طاعة الجهل","page":"","text":"عصيت نذير الحلم في طاعة الجهل … وأغضبت في مرضاة حب المها عقلي\nونازعت أرسان البطالة والصبا … إلى غاية لم يأتها أحد قبلي\nفخذ في حديث غير لومي ، فإنني … بجب الغواني عن ملامك في شغل\nإذا كان سمع المرء عرضة ألسن … فما هو إلا للخديعة والختل\nرويدك ، لا تعجل بلوم على امرىء … أصاب هوى نفس ؛ ففي الدهر ما يسلي\nفليست بعار صبوة المرء ذي الحجا … إذا سلمت أخلاقه من أذى الخبل\nوإني وإن كنت ابن كأس ولذة … لذو تدرإ يوم الكريهة والأزل\nوقور ، وأحلام الرجال خفيفة … صبور ، ونار الحرب مرجلها يغلي\nإذا راعت الظلماء غيري ، فإنما … هلال الدجى قوسي ، وأنجمه نبلي\nأنا ابن الوغى ، والخيل ، والليل ، والظبا … وسمر القنا ، والرأي ، والعقد ، والحل\nفقل للذي ظن المعالي قريبة … رويدا ؛ فليس الجد يدرك بالهزل\nفما تصدق الآمال إلا لفاتك … إذا هم لم تعطفه قارعة العذل\nله بالفلا شغل عن المدن والقرى … وفي رائدات الخيل شغل عن الأهل\nإذا ارتاب أمرا ألهبته حفيظة … تميت الرضا بالسخط ، والحلم بالجهل\nفلا تعترف بالذل خوف منية … فإن احتمال الذل شر من القتل\nولا تلتمس نيل المنى من خليقة … فتجني ثمار اليأس من شجر البخل\nفما الناس إلا حاسد ذو مكيدة … وآخر محني الضلوع على دخل\nتباع هوى ، يمشون فيه كما مشى … وسماع لغو ، يكتبون كما يملى\nوما أنا والأيام شتى صروفها … بمهتضم جاري ، ولا خاذل خلي\nأسير على نهج الوفاء سجية … وكل امرئ في الناس يجري على الأصل\nتركت ضغينات النفوس لأهلها … وأكبرت نفسي أن أبيت على ذحل\nكذلك دأبي منذ أبصرت حجتي … وليدا ؛ وحب الخير من سمة النبل\nورب صديق كشف الخبر نفسه … فعاينت منه الجور في صورة العدل\nوهبت له ما قد جنى من إساءة … ولو شئت ، كان السيف أدنى إلى الفصل\nومستخبر عني ، وما كان جاهلا … بشأني ، ولكن عادة البغض للفضل\nأتى سادرا ، حتى إذا قر أوجست … سويداؤه شرا ؛ فأغضى على ذل\nومن حدثته النفس بالغي بعد ما … تناهى إليه الرشد سار على بطل\nوإني لأستحيي من المجد أن أرى … صريع مرام لا يفوز بها خصلي\nأقول وأتلو القول بالفعل كلما … أردت ؛ وبئس القول كان بلا فعل\nأرى السهل مقرونا بصعب ، ولا أرى … بغير اقتحام الصعب مدرك السهل\nويوم كأن النقع فيه غمامة … لها أثر من سائل الطعن كالوبل\nتقحمته فردا سوى النصل وحده … وحسب الفتى أن يطلب النصر بالنصل\nلويت به كفي ، وأطلقت ساعدي … وقلت لدهري : ويك ! فامض على رسل\nفما يبعث الغارات إلا مهندى … ولا يركب الأخطار إلا فتى مثلي"},{"id":"diwan-barudi:5","bookId":"diwan-barudi","type":"poem","seq":5,"chapter":"البحر: بسيط تام","title":"ردوا علي الصبا من عصري الخالي","page":"","text":"ردوا علي الصبا من عصري الخالي … وهل يعود سواد اللمة البالي ؟\nماض من العيش ، ما لاحت مخايله … في صفحة الفكر إلا هاج بلبالي ؟\nسلت قلوب ؛ فقرت في مضاجعها … بعد الحنين ، وقلبي ليس بالسالي\nلم يدر من بات مسرورا بلذته … أني بنار الأسى من هجره صالي\nيا غاضبين علينا ! هل إلى عدة … بالوصل يوم أناغي فيه إقبالي\nغبتم ؛ فأظلم يومي بعد فرقتكم … وساء صنع الليالي بعد إجمال\nقد كنت أحسبني منكم على ثقة … حتى منيت بما لم يجر في بالي\nلم أجن في الحب ذنبا أستحق به … عتبا ، ولكنها تحريف أقوال\nومن أطاع رواة السوء - نفره … عن الصديق سماع القيل والقال\nأدهى المصائب غدر قبله ثقة … وأقبح الظلم صد بعد إقبال\nلا عيب في سوى حرية ملكت … أعتني عن قبول الذل بالمال\nتبعت خطة آبائي ؛ فسرت بها … على وتيرة آداب وآسال\nفما يمر خيال الغدر في خلدي … ولا تلوح سمات الشر في خالي\nقلبي سليم ، ونفسي حرة ويدي … مأمونة ، ولساني غير ختال\nلكنني في زمان عشت مغتربا … في أهله حين قلت فيه أمثالي\nبلوت دهري ؛ فما أحمدت سيرته … في سابق من لياليه ، ولا تالي\nحلبت شطريه : من يسر ، ومعسرة … وذقت طعميه : من خصب ، وإمحال\nفما أسفت لبؤس بعد مقدرة … ولا فرحت بوفر بعد إقلال\nعفافة نزهت نفسي ؛ فما علقت … بلوثة من غبار الذم أذيالي\nفاليوم لا رسني طوع القياد ، ولا … قلبي إلى زهرة الدنيا بميال\nلم يبق لي أرب في الدهر أطلبه … إلا صحابة حر صادق الخال\nوأين أدرك ما أبغيه من وطر … والصدق في الدهر أعيا كل محتال ؟\nلا في ' سرنديب ' لي إلف أجاذبه … فضل الحديث ، ولا خل ؛ فيرعى لي\nأبيت منفردا في رأس شاهقة … مثل القطامي فوق المربإ العالي\nإذا تلفت لم أبصر سوى صور … في الذهن ، يرسمها نقاش آمالي\nتهفو بي الريح أحيانا ، ويلحفني … برد الطلال ببرد منه أسمال\nففي السماء غيوم ذات أروقة … وفي الفضاء سيول ذات أو شال\nكأن قوس الغمام الغر قنطرة … معقودة فوق طامي الماء سيال\nإذا الشعاع تراءى خلفها نشرت … بدائعا ذات ألوان وأشكال\nفلو تراني وبردي بالندى لثق … لخلتني فرخ طير بين أدغال\nغال الردى أبويه ؛ فهو منقطع … في جوف غيناء ، لا راع ، ولا والي\nأزيغب الرأس ، لم يبد الشكير به … ولم يصن نفسه من كيد مغتال\nكأنه كرة ملساء من أدم … خفية الدرز ، قد علت بجريال\nيظل في نصب ، حران ، مرتقبا … نقع الصدى بين أسحار وآصال\nيكاد صوت البزاة القمر يقذفه … من وكره بين هابي الترب جوال\nلا يستطيع انطلاقا من غيابته … كأنما هو معقول بعقال\nفذاك مثلي ، ولم أظلم ، وربتما … فضلته بجوى حزن ، وإعوال\nشوق ، ونأي ، وتبريح ، ومعتبة … يا للحمية من غذري وإهمالي\nأصبحت لا أستطيع الثوب أسحبه … وقد أكون وضافي الدرع سربالي\nولا تكاد يدي شبا قلمي … وكان طوع بناني كل عسال\nفإن يكن جف عودي بعد نضرته … فالدهر مصدر إدبار وإقبال\nوإن غدوت كريم العم والخال … بصدق ما كان من وسمي وإغفالي\nراجعت قهرس آثاري ، فما لمحت … بصيرتي فيه ما يزري بأعمالي\nفكيف ينكر قومي فضل بادرتي … وقد سرت حكمي فيهم ، وأمثالي ؟\nأنا ابن قولي ؛ وحسبي في الفخار به … وإن غدوت كريم العمم والخال\nولي من الشعر آيات مفصلة … تلوح في وجنة الأيام كالخال\nينسى لها الفاقد المحزون لوعته … ويهتدى بسناها كل قوال\nفانظر لقولي تجد نفسي مصورة … في صفحتيه ؛ فقولي خط تمثالي\nولا تغرنك في الدنيا مشاكلة … بين الأنام ؛ فليس النبع كالضال\nإن ابن آدم لولا عقله شبح … مركب من عظام ذات أوصال"},{"id":"diwan-barudi:6","bookId":"diwan-barudi","type":"poem","seq":6,"chapter":"البحر: طويل","title":"سما الملك مختالا بما أنت فاعل","page":"","text":"سما الملك مختالا بما أنت فاعل … وعادت بك الأيام وهي أصائل\nربأت من العلياء قنة سودد … يقصر عنها صاغرا من يطاول\nوأدركت في عصر الشبيبة غاية … من الفضل لم يبلإ مداها الأفاضل\nفخيرك مأمول ، وفضلك واسع … وظلك ممدود ، وعدلك شامل\nمساع جلاها الرأي ؛ فهي كواكب … لها بين أفلاك القلوب منازل\nيقصر قاب الفكر عنها ، وينتهى … أخو الجد عن إدراكها وهو ذاهل\nوكيف ينال الفهم منها نصيبه … وأقربها للنيرات حبائل ؟\nإليك تناهى المجد ، حتى لوانه … أراد مزيدا لم يجد ما يحاول\nفمر بالذي تهواه ؛ فالسعد قائم … بما تشتهي ، والله بالنصر كافل\nفقد تصدق الآمال والحزم رائد … وتقترب الغايات والنجد عامل\nوأي صنيع بعد فضلك يرتجى … وأنت مليك في البرية عادل ؟\nيعم الرضا ما قام بالحق صادع … وتبقى العلا ما دام للسيف حامل\nفيا طالبا مسعاته ؛ لينالها … رويدك ؛ إن الحرص للنفس خاذل\nفما كل من راض البديهة عاقل … ولا كل من خاض الكريهة باسل\nولولا اختلاف الناس في درجاتهم … لعادل ' قسا ' في الفصاحة ' باقل '\nهو الملك المكفول بالنصر جنده … إذا احمر بأس ، أو تنمر باطل\nله بدهات لا تغب ، وعزمة … مؤيدة ، تعنو إليها الجحافل\nفآرأوه في المشكلات كواكب … وهماته في المعضلات مناصل\nتدل مساعيه على فضل نفسه … وللشمس من نور عليها دلائل\nفيا ملكا عمت أياديه ، والتقت … به فرق الآمال وهي جوافل\nبك اخضرت الآمال بعد ذبولها … وحقت وعود الظن وهي مخايل\nبسطت يد بالخير فينا كريمة … هي الغيث ، أو في الغيث منها شمائل\nوأيقظت ألباب الرجال ؛ فسارعوا … إلى الجد ؛ حتى ليس في الناس خامل\nوما ' مصر ' إلا جنة ، بك أصبحت … منورة أفنانها والخمائل\nطلعت عليها طلعة البدر ، أشرقت … بلألائه الآفاق والليل لائل\nوأجريت ماء العدل فيها ؛ فأصبحت … وساحاتها للواردين مناهل\nولم يأت من أوطانه ' النيل ' سائحا … إلى ( مصر إلا وهو حران سائل )8\nفيأيها الصادي إلى العدل والندى … هلم ؛ فذا بحر له\nمليك أقر الأمن والخوف شامل … وأحيا رميم العدل والجور قاتل\nفسله الرضا ، وانزل بساحة ملكه … فثم الأماني ، والعلا ، والفواضل\nرعى الله يوما قربتني سعوده … إلى سدة تأوى إليها الأماثل\nلثمت بها كفا ، هي … تفيض سماحا ، والبنان جداول\nنطقت بفضل منك ، لولاه لم يدر … لساني ، ولم يحفل بقولي فاضل\nولا أدعي أني بلغت بمدحتي … علاك ؛ ولكن جهد ما أنا قائل\nوكيف أوفى منطق الشكر حقه … ودون ثنائي من علاك مراحل ؟\nوحسبي عذرا أنك الشمس رفعة … وكيف ينال الكوكب المتناول ؟\nلتهن بك الدنيا ؛ فأنت جمالها … فلولاك أمسى جيدها وهو عاطل\nودم للعلا ما ذر بالأفق شارق … وما حن من شوق على الأيك هادل\nولا زالت الأيام تتلو مدائحي … عليك ، ويمليها الضحى والأصائل"},{"id":"diwan-barudi:7","bookId":"diwan-barudi","type":"poem","seq":7,"chapter":"البحر: طويل","title":"ألا ، حي من ( أسماء ) رسم المنازل","page":"","text":"ألا ، حي من ( أسماء ) رسم المنازل … وإن هي لم ترجع بيانا لسائل\nخلاء تعفتها الروامس ، والتقت … عليها أهاضيب الغيوم الحوافل\nفلأيا عرفت الدار بعد ترسم … أراني بها ما كان بالأمس شاغلي\nغدت وهي مرعى للظباء ، وطالما … غنت وهي مأوى للحسان العقائل\nفللعين منها بعد تزيال أهلها … معارف أطلال ، كوحي الرسائل\nفأسبلت العينان فيها بواكف … من الدمع ، يجري بعد سح بوابل\nديار التي هاجت علي صبابتي … وأغرت بقلبي لاعجات البلابل\nمن الهيف ، مقلاق الوشاحين ، غادة … سليمة مجرى الدمع ، ريا الخلاخل\nإذا ما دنت فوق الفراش لوسنة … جفا خصرها عن ردفها المتخاذل\nتعلقتها في الحي إذ هي طفلة … وإذ أنا مجلوب إلي وسائلي\nفلما استقر الحب في القلب وانجلت … غيابته - هاجت علي عواذلي\nفيا ليت أن العهد باق ، وأننا … دوارج في غفل من العيش خامل\nتمر بنا رعيان كل قبيلة … فما يمنحونا غير نظرة غافل\nصغيرين لم يذهب بنا الظن مذهبا … بعيدا ، ولم يسمع لنا بطوائل\nنسير إذا ما القوم ساروا غدية … إلى كل بهم راتعات وجامل\nوإن نحن عدنا بالعشي أضافنا … إليه سديل من نقا متقابل\nفويل لهذا الدهر ، ماذا أراده … إلينا ، وقد كنا كرام المحاصل ؟\nعلى عفة قد يعلم الله أنها … مبرأة من كل غي وباطل\nولكنها الأيام لم تأت صالحا … من الأمر إلا أعقبت بالتنازل\nإذا ما تذكرت الزمان الذي مضى … تساقط نفسي إثر تلك القبائل\nقبائل أفنتها الحروب ، ولم تكن … لتفنى كرام الناس ما لم تقاتل\nقضت بعدهم نفسي عزاء ، وأصحبت … عشوزنتي ، وانقاد للذل كاهلي\nوأصبحت مغلول اليدين عن التي … أحاولها ، والدهر جم الغوائل\nصريع لبانات تقسمن نفسه … وغادرنه نهب الأكف الخواتل\nكأني لم أعقد مع الفجر راية … ولم أدرع باسمي للكمي المنازل\nولم أبعث الخيل المغيرة في الضحا … بكل ركوب للكريهة باسل\nنزائع يعلكن الشكيم على الوجى … إذا عريت أمثالها في المنازل\nمن القوم ، باد مجدهم في شمالهم … ولا مجد إلا داخل في الشمائل\nإذا ما دعوت المرء منهم لدعوة … على عجل - لباك غير مسائل\nيكفكف أولى الخيل منه بطعنة … تمج دما ، مطعونها غير وائل\nيكون عشاء الزاد آخر آكل … ويوم اختلاج الطعن أول حامل\nقضوا ما قضوا من دهرهم ، ثم فوزوا … إلى دار خلد ظلها غير زائل"},{"id":"diwan-barudi:8","bookId":"diwan-barudi","type":"poem","seq":8,"chapter":"البحر: بسيط تام","title":"رد الصبا بعد شيب اللمة الغزل","page":"","text":"رد الصبا بعد شيب اللمة الغزل … وراح بالجد ما يأتي به الهزل\nوعاد ما كان من صبر إلى جزع … بعد الإباء ؛ وأيام الفتى دول\nفليصرف اللوم عني من برمت به … فليس للقلب في غير الهوى شغل\nوكيف أملك نفسي بعد ما ذهبت … يوم الفراق شعاعا إثر من رحلوا ؟\nتقسمتني النوى من بعدهم ، وعدت … عنهم عواد ؛ فلا كتب ، ولا رسل\nفالصبر منخذل ، والدمع منهمل … والعقل مختبل ، والقلب مشتغل\nأرتاح إن مر من تلقائهم نسم … تسري به في أريج العنبر الأصل\nساروا ، فما اتخذت عيني بهم بدلا … إلا الخيال ، وحسبي ذلك البدل\nفخل عنك ملامي يا عذول ، فقد … سرت فؤادي - على ضعف به - العلل\nلا تحسبن الهوى سهلا ؛ فأيسره … خطب لعمرك لو ميزته جلل\nيستنزل الملك من أعلى منابره … ويستوي عنده الرعديد والبطل\nفكيف أدرأ عن نفسي وقد علمت … أن ليس لي بمناواة الهوى قبل ؟\nفلو قدرت على شيء هممت به … في الحب ، لكن قضاء خطه الأزل\nوللمحبة قبلي سنة سلفت … في الذاهبين ؛ ولي فيمن مضى مثل\nفإن تكن نازعتني النفس باطلها … وأطلعتني على أسرارها الكلل\nفقد أسير أمام القوم ضاحية … والجو بالباترات البيض مشتعل\nبكل أشقر قد زانت قوائمه … حجوله غير يمنى زانها العطل\nكأنه خاض نهر الصبح ، فانتبذت … يمناه وانبث في أعطافه الطفل\nزرق حوافره ، سود نواظره … خضر جحافله ، في خلقه ميل\nكأن في حلقه ناقوس راهبة … باتت تحركه ، أو راعد زجل\nيمر بالوحش صرعى في مكامنها … فما تبين له شدا ؛ فتنخذل\nيرى الإشارة في وحى ؛ فيفهمها … ويسمع الزجر من بعد ؛ فيمتثل\nلا يملك النظرة العجلاء صاحبها … حتى تمر بعطفيه فتحتبل\nإن مر بالقوم حلوا عقد حبوتهم … واستشرفت نحوه الألباب والمقل\nتقوده بنت خمس ؛ فهو يتبعها … ويستشيط إذا ها هي به الرجل\nأمضي به الهول مقداما ، ويصحبني … ماضي الغرار إذا ما استفحل الوهل\nيمر بالهام مر البرق في عجل … وقت الضراب ، ولم يعلق به بلل\nترى الرجال وقوفا بعد فتكته … بهم ، يظنون أحياء وقد قتلوا\nكأنه شعلة في الكف قائمة … تهفو بها الريح أحيانا ، وتعتدل\nلولا الدماء التي يسقى بها نهلا … لكاد من شدة اللألاء يشتعل\nيقل ما بقيت في الكف قبضته … كل الحديد ، ولم يثأر به فلل\nبل رب سارية هطلاء دانية … تنمو السوام بها ، والنبت يكتهل\nكأن آثارها في كل ناحية … ريط منشرة في الأرض ، أو حلل\nيممتها برفاق إن دعوت بهم … لبوا سراعا ، وإن أنزل بهم نزلوا\nقصدا إلى الصيد ، لا نبغي به بدلا … وكل نفس لها في شأنها عمل\nحتى إذا ألمع الرواد من بعد … وجاء فارطهم يعلو ويستفل\nتغازت الخيل ، حتى كدن من مرح … يذهبن في الأرض لولا اللجم والشكل\nفما مضت ساعة ، أو بعض ثانية … إلا وللصيد في ساحاتنا نزل\nفكان يوما قضينا فيه لذتنا … كما اشتهينا ؛ فلا غش ، ولا دغل\nهذا هو العيش ، لا لغو الحديث ، ولا … ما يستغير به ذو الإفكة النمل\nإن النميمة والأفواه تضرمها … نار محرقة ليست لها شعل\nفاتبع هواك ، ودع ما يستراب به … فأكثر الناس - إن جربتهم - همل\nواحذر عدوك تسلم من خديعته … إن العداوة جرح ليس يندمل\nوعالج السر بالكتمان تحمده … فربما كان في إفشائه الزلل\nولا تكن مسرفا غرا ، ولا بخلا … فبئست الخلة : الإسراف ، والبخل\nولا يهمنك بعض الأمر تسأمه … لا ينتهي الشغل حتى ينتهي الأجل\nواعرف مواضع ما تأتيه من عمل … فليس في كل حين يحسن العمل\nفالريث يحمد في بعض الأمور ، كما … في بعض حالاته يستحسن العجل\nهذا هو الأدب المأثور ، فارض به … علما لنفسك ؛ فالأخلاق تنتقل\nمن كل بيت إذا الإنشاد سيره … فليس يمنعه سهل ، ولا جبل\nلم تبن قافية فيه على خلل … كلا ، ولم تختلف في رصفها الجمل\nفلا سناد ، ولا حشو ، ولا قلق … ولا سقوط ، ولا سهو ، ولا علل\nتغايرت فيه أسماع وأفئدة … فكل ناد ( عكاظ حين يرتجل )\nلا تنكر الكاعب الحسناء منطقه … ولا يعاد على قوم ، فيبتذل"},{"id":"diwan-barudi:9","bookId":"diwan-barudi","type":"poem","seq":9,"chapter":"البحر: رجز تام","title":"عم الحيا ، واستنت الجداول","page":"","text":"عم الحيا ، واستنت الجداول … وفاضت الغدران والمناهل\nوازينت بنورها الخمائل … وغردت في أيكها البلابل\nوشمل البقاع خير شامل … فصفحة الأرض نبات خائل\nوجبهة الجو غمام حافل … وبين هذين نسيم جائل\nتندى به الأسحار والأصائل … كأنما النبات بحر هائل\nوليس إلا الأكمات ساحل … وشامخ الدوح سفين جافل\nمعتدل طورا ، وطورا مائل … تهفو به الجنوب والشمائل\nوالباسقات الشمخ الحوامل … مشمورة عن سوقها الذلاذل\nملوية في جيدها العثاكل … معقودة في رأسها الفلائل\nللبسر فيها قانئ وناصل … مخضب ، كأنه الأنامل\nكأنه من ذهب قنادل … من العراجين لها سلاسل\nللمجنون بينها أزامل … تخالها محزونة تسائل\nلها دموع ذرف هوامل … كأنها أم بنين ثاكل\nفي جيدها من ضفرها حبائل … من القواديس ، لها جلاجل\nتدور كالشهب لها منازل … فصاعد ، ودافق ، ونازل\nوالماء ما بين الغياض سائل … تحنو على شطانه الغياطل\nكأنها حوائم نواهل … والطير في أفنانها هوادل\nتزهو بها الأسحار والأصائل … فانهض إلى نيل المنى يا غافل\nوانعم ، فأيام الصبا قلائل … والمرء في الدنيا خيال زائل\nوالدهر للإنسان يوما آكل … وكل شيء في الزمان باطل"},{"id":"diwan-barudi:10","bookId":"diwan-barudi","type":"poem","seq":10,"chapter":"البحر: طويل","title":"وذي حدب يلتج بالسفن كلما","page":"","text":"وذي حدب يلتج بالسفن كلما … زفته نئوج ؛ فهو يعلو ويسفل\nكأن اطراد الموج فوق سراته … نعائم في عرض السماوة جفل\nإذا شاغبته الريح جاش عبابه … وظل أعالي موجه يتجفل\nيهيج ؛ فيرغو ، أو يعج ، كأنما … تخبطه من أولق الضغن أزفل\nتقسمه خلقان : لين ، وشدة … بعصفة ريح ، فهو داه ؛ وأرفل\nعلونا مطاه وهو ساج ، فما انبرت … له الريح حتى ظل يهفو ، ويرفل\nكأنا على أرجوحة ، كلما ونت … أحال عليها قائم ، ليس يغفل\nفطورا لنا في غمرة اللج مسبح … وطورا لنا بين السماكين محفل\nفلا هو إن رعناه بالجد يرعوي … ولا إن سألناه الهوادة يحفل\nعرونا - فأبخلناه - فضل حبائه … ومن عجب إمساكه وهو نوفل\nقليل على عهد الإخاء ثباته … فأسفله عال ، وعاليه سافل\nإذا حركته غضبة مات حلمه … وظل على أضيافه يتأفل\nشديد الحميا ؛ يرهب الناس بطشه … ولكنه من نفخة الريح يجفل\nكأن أعالي الموج عهن مشعث … به ، وانحدار السيح شعر مفلفل\nذكرنا به ما قد مضى من ذنوبنا … وفي الناس إن لم يرحم الله غفل\nوكيف ترانا صانعين ، وكلنا … بقارورة صماء ، والباب مقفل ؟\nفلا تبتئس إن فات حظ ، فربما … أضاءت مصابيح الدجى وهي أفل\nفقد يبرأ الداء العضال ، وينجلي … ضباب الرزايا ، والمسافر يقفل\nوكيف يخاف المرء حيفا ، وربه … بأحسن ما يرجو من الرزق يكفل ؟"},{"id":"diwan-barudi:11","bookId":"diwan-barudi","type":"poem","seq":11,"chapter":"البحر: مجزوء الرمل","title":"أهلال بين هاله ؟","page":"","text":"أهلال بين هاله ؟ … أم غزال في غلاله ؟\nصاد باللحظ فؤادي … أترى الهدب حباله ؟\nغرني ، ثم تولى … ليت شعري ، ما بدا له ؟\nأنا من شوقي إليه … واقع بين ضلاله\nأيها الظالم ! هب لي … مرة منك العداله\nوارع لي حق وداد … فيك ، لم أقطع حباله\nمنطق عذب ، ومعنى … يبسم السحر خلاله\nكل بيت كنسيج الر … روض حسنا وطلاله\nأنا في الشعر عريق … لم أرثه عن كلاله\nكان ( إبراهيم ) خالي … فيه مشهور المقاله\nوسما جدي ' علي ' … يطلب النجم ، فناله\nفهو لي إرث كريم … سوف يبقى في السلاله"},{"id":"diwan-barudi:12","bookId":"diwan-barudi","type":"poem","seq":12,"chapter":"البحر: سريع","title":"يا ناصر الحق على الباطل !","page":"","text":"يا ناصر الحق على الباطل ! … خذ لي بحقي من يدي ماصلي\nجار على ضعفي بسلطانه … وما رثى للمدمع الهاطل\nأجرجني عما حوته يدي … من كسبي الحر بلا ناطل\nمن غير ما ذنب ، سوى منطق … ذي رونق ، كالصارم القاطل\nأتلو به الحق ، وأرمي به … نحر العدا في الرهج الساطل\nفإن أكن جردت من ثروتي … ففضل ربي حلية العاطل"},{"id":"diwan-barudi:13","bookId":"diwan-barudi","type":"poem","seq":13,"chapter":"البحر: وافر تام","title":"لأمر ما تحيرت العقول","page":"","text":"لأمر ما تحيرت العقول … فهل تدري الخلائق ما تقول ؟\nتغيب الشمس ، ثم تعود فينا … وتذوي ، ثم تخضر البقول\nطبائع لا تغب ، مرددات … كما تعرى وتشتمل الحقول\nفسيان الجهول إذا تناهت … به الأيام ، والفطن العقول\nيزول الخلق طورا بعد طور … وتختلف الحقائق والنقول\nفما جرت الظنون على يقين … تفيء به ، ولا صح المقل"},{"id":"diwan-barudi:14","bookId":"diwan-barudi","type":"poem","seq":14,"chapter":"البحر: سريع","title":"ما الدهر إلا ضوء شمس علا","page":"","text":"ما الدهر إلا ضوء شمس علا … وكوكب غام ، ونبت بقل\nوراحل أعقبه نازل … ما قيل قد خيم حتى استقل\nعماية يخبط فيها النهى … عجزا ، ولا تبصر فيها المقل\nفبادر النقلة ، واعمل لها … ما شئت ؛ فالدهر سريع النقل\nواصمت عن الشر إذا لم تطق … دفعا ، وإن صادفت خيرا فقل\nوسر إذا ما عرضت فرصة … فالبدر قد ينمو إذا ما انتقل\nمن طلب الأمر بأسبابه … ساعده المقدور إما عقل\nقد يجبن الأعزل وهو الفتى … ويشجع النكس إذا ما اعتقل"},{"id":"diwan-barudi:15","bookId":"diwan-barudi","type":"poem","seq":15,"chapter":"البحر: كامل تام","title":"لا تركنن إلى الزمان ؛ فربما","page":"","text":"لا تركنن إلى الزمان ؛ فربما … خدعت مخيلته الفؤاد الغافلا\nواصبر على ما كان منه ؛ فكلما … ذهب الغداة أتى العشية قافلا\nكفل الشقاء لمن أناخ بربعه … وكفى ابن آدم بالمصائب كافلا\nيمشي الضراء إلى النفوس ، وتارة … يسعى لها بين الأسنة رافلا\nلا يرهب الضرغام بين عرينه … بأسا ، ولا يدع الظباء مطافلا\nبينا ترى نجم السعادة طالعا … فوق الأهلة إذ تراه آفلا\nفإذا سألت الدهر معرفة به … فاسأل لتعرفه النعام الجافلا\nفالدهر كالدولاب ، يخفض عاليا … من غير ما قصد ، ويرفع سافلا"},{"id":"diwan-barudi:16","bookId":"diwan-barudi","type":"poem","seq":16,"chapter":"البحر: كامل تام","title":"إن شئت أن تحوى المعالي ، فادرع","page":"","text":"إن شئت أن تحوى المعالي ، فادرع … صبرا ؛ فإن الصبر غنم عاجل\nاحلم كأنك جاهل ، واذكر كأن … نك ذاهل ، وافطن كأنك غافل\nفلقما بفضى إلى آرابه … في الدهر إلا العالم المتجاهل"},{"id":"diwan-barudi:17","bookId":"diwan-barudi","type":"poem","seq":17,"chapter":"البحر: بسيط تام","title":"لا تحسب الناس في الدنيا على ثقة","page":"","text":"لا تحسب الناس في الدنيا على ثقة … من أمرهم ، بل على ظن وتخييل\nحب الحياة ، وبغض الموت أورثهم … جبن الطباع ، وتصديق الأباطيل"},{"id":"diwan-barudi:18","bookId":"diwan-barudi","type":"poem","seq":18,"chapter":"البحر: طويل","title":"ألا ، إن أخلاق الرجال وإن نمت","page":"","text":"ألا ، إن أخلاق الرجال وإن نمت … فأربعة منها تفوق على الكل :\nوقار بلا كبر ، وصفح بلا أذى … وجود بلا من ، وحلم بلا ذل"},{"id":"diwan-barudi:19","bookId":"diwan-barudi","type":"poem","seq":19,"chapter":"البحر: وافر تام","title":"تسابق في المكارم تعل قدرا","page":"","text":"تسابق في المكارم تعل قدرا … فسبق الناس للخيرات نضل\nإذا ذهب الكرام ، فلا رجاء … وإن ذهب الرجاء ، فليس فضل"},{"id":"diwan-barudi:20","bookId":"diwan-barudi","type":"poem","seq":20,"chapter":"البحر: طويل","title":"إذا ستر الفقر امرأ ذا نباهة","page":"","text":"إذا ستر الفقر امرأ ذا نباهة … فلا بد يوما أن يشيد به الفضل\nفإن لهيب النار مهما كفأته … إلى أسفل قسرا ، فلا بد أن يعلو"},{"id":"diwan-barudi:21","bookId":"diwan-barudi","type":"poem","seq":21,"chapter":"البحر: طويل","title":"لعمرك ما الإنسان إلا ابن يومه","page":"","text":"لعمرك ما الإنسان إلا ابن يومه … وما العيش إلا لبثة وزيال\nوما الدهر إلا دفتر في خلاله … تصاوير لم يعهد لهن مثال\nففي صفحة منه زمان قد انقضى … وفي وجه أخرى دولة ورجال"},{"id":"diwan-barudi:22","bookId":"diwan-barudi","type":"poem","seq":22,"chapter":"البحر: كامل تام","title":"طهر لسانك ما استطعت ، ولا تكن","page":"","text":"طهر لسانك ما استطعت ، ولا تكن … خبا يقرب للنفوس ضلالها\nإن الوقيعة لا تعود بخزية … أو سبة إلا على من قالها"},{"id":"diwan-barudi:23","bookId":"diwan-barudi","type":"poem","seq":23,"chapter":"البحر: بسيط تام","title":"ليس الصديق الذي تعلو مناسبه","page":"","text":"ليس الصديق الذي تعلو مناسبه … بل الصديق الذي تزكو شمائله\nإن رابك الدهر لم تفشل عزائمه … أو نابك الهم لم تفتر وسائله\nيرعاك في حالتي بعد ومقربة … ولا تغبك من خير فواضله\nلا كالذي يدعى ودا ، وباطنه … بحمر أقاده تغلى مراجله\nيذم فعل أخيه مظهرا أسفا … ليوهم الناس أن الحزن شامله\nوذاك منه عداء في مجاملة … فاحذره ، واعلم بأن الله خاذله"},{"id":"diwan-barudi:24","bookId":"diwan-barudi","type":"poem","seq":24,"chapter":"البحر: كامل تام","title":"الحب معنى لا يحيط بسره","page":"","text":"الحب معنى لا يحيط بسره … وصف ، ولا يجري عليه مثال\nكالكهرباءة دركها متعذر … ونسيمها متحدر سيال\nوكذلك الأرواح يظهر فعلها … ويغيب عنا سرها الفعال\nحكم تملكها الغموض فلم يحط … برموزها في العالمين مقال"},{"id":"diwan-barudi:25","bookId":"diwan-barudi","type":"poem","seq":25,"chapter":"البحر: خفيف تام","title":"ليس لي غير خالك الحجر الأس","page":"","text":"ليس لي غير خالك الحجر الأس … ود في كعبة المحاسن قبله\nفأثبني على الجمال زكاة … وزكاة الجمال في الخد قبله"},{"id":"diwan-barudi:26","bookId":"diwan-barudi","type":"poem","seq":26,"chapter":"البحر: كامل تام","title":"يا هاجري ظلما بغير خطيئة","page":"","text":"يا هاجري ظلما بغير خطيئة … هل لي إلى الصفح الجميل سبيل ؟\nماذا يضرك لو سمحت بنظرة … تحيا بها نفس عليك تسيل ؟"},{"id":"diwan-barudi:27","bookId":"diwan-barudi","type":"poem","seq":27,"chapter":"البحر: بسيط تام","title":"من ظنني موضعا يوما لحاجته","page":"","text":"من ظنني موضعا يوما لحاجته … كنت الحري بأن أعطيه ما سألا\nله علي بحسن الظن مأثرة … لا يستقل بها شكري وإن جملا"},{"id":"diwan-barudi:28","bookId":"diwan-barudi","type":"poem","seq":28,"chapter":"البحر: بسيط تام","title":"عاتبته ، لا لأمر فيه معتبة","page":"","text":"عاتبته ، لا لأمر فيه معتبة … عليه ، لكن لأرعى وردة الخجل\nفألبست ياسمين الخد خجلته … ورردا جنيا ، جناه رائد المقل"},{"id":"diwan-barudi:29","bookId":"diwan-barudi","type":"poem","seq":29,"chapter":"البحر: بسيط تام","title":"دع المخافة ، واعلم أن صاحبها","page":"","text":"دع المخافة ، واعلم أن صاحبها … وإن تحصن لا ينجو من الغيل\nلو كان للمرء علم يستدل به … على العواقب ، لم يركن إلى الحيل"},{"id":"diwan-barudi:30","bookId":"diwan-barudi","type":"poem","seq":30,"chapter":"البحر: طويل","title":"يعزى الفتى في كل رزء ، وليته","page":"","text":"يعزى الفتى في كل رزء ، وليته … يعزى على فقد الشباب المزايل\nفكم بين مفقود يعاش بغيره … وآخر يزري بالهوى والوسائل\nإذا المرء لم يبك الشباب ، فما الذي … يعز عليه ، وهو أكرم راحل ؟"},{"id":"diwan-barudi:31","bookId":"diwan-barudi","type":"poem","seq":31,"chapter":"البحر: خفيف تام","title":"كل صعب سوى المذلة سهل","page":"","text":"كل صعب سوى المذلة سهل … وحياة الكريم في الضيم قتل\nليس يقوى امرؤ على الذل ما لم … يك فيه من صبغة اللؤم دخل\nإن مر الحمام أعذب وردا … من حياة فيها شقاء وذل\nأنا راض بترك مالي وأهلي … فالعفاف الثراء ، والناس أهل\nلا يلمني على الحفيظة قوم … غرهم منظر الحياة ؛ فضلوا\nألفوا الضيم خسية الموت ، والضي … م - لعمري - فج خسيس ، وثكل\nكيف لا أنصر الرشاد على الغى … ي ، وعقلي معي ، وفي النفس فضل ؟\nإنما المرء باللسان وبالقل … ب ، فإن خاب منهما ، فهو فسل\nقدك يا نفس ، فالتصبر إلا … في لقاء الحروب غبن وجهل\nفابعثيها شعواء ، يحكم فيها … منصل صارم ، ورمح متل\nهو إما الحمام ، أو عيشة خض … راء فيها لمن تفيأ ظل\nإن ملكا فيه ( فلان ) وزيرا … لمباح للخائنين وبل\nأهوج ، أحمق ، شتيم ، لئيم … أغتم ، أبله ، زنيم ، عتل\nصغرت رأسه ، وأفرط في الطول … شواه ، وعنقه ؛ فهو صعل\nأبرزت ثدرة الطبيعة منه … شكل لؤم ، إن كان للؤم شكل\nهدف للعيوب ، في كل عضو … منه سهم للطاعنين ونصل\nنسلته من استها أم سوء … ما لها غير طائف الليل بعل\nكن كما شئت يا فلان ، وما شا … ءت رجال ؛ فأنت للؤم أهل\nليس تغنى الألقاب عن كرم الأص … ل ، فمجد الفتى عفاف وعقل\nأنت من عنصر ، لو اتكأ الذر … ر عليه ، لآده منه حمل\nنازعتك اليهود ، واختلفت في … ك النصارى ، فأنت لا شك بغل\nإن بيت الوزان لم يزنوا شي … ئا ، ولكن فيهم على ذاك ثقل\nكثروا عدة ، ولو أحصن البا … ب أبوهم عن الزناة ، لقلوا\nلو عزونا كل امريء لأبيه … من فراخ الوزان ، لم يبق نسل\nكل وغد أهدى إلى اللؤم من با … ز ، ولكن من الحمار أضل\nقد تغذى باللؤم إذ هو طفل … وتمادى في الغي إذ هو كهل\nليس فيهم من تحمد العين رؤيا … ه ، ولا منهم إلى النفس خل\nأدركوا في العيوب أبعد خصل … كل حي له بما شاء خصل\nكيف لا تشمل الدناءة قوما … نشئوا في الصغار حين استهلوا ؟\nهم - لعمري - أذل من قدم النع … ل نفوسا ، والنعل منهم أجل\nكنت لا أحسن الهجاء ، ولكن … علمتني صفاتهم كيف أتلو\nكل شيء يفنى ، ولكن هجائي … فيك باق ما عاقب السيف صقل"},{"id":"diwan-barudi:32","bookId":"diwan-barudi","type":"poem","seq":32,"chapter":"البحر: طويل","title":"وصالك لي هجر ، وهجرك لي وصل","page":"","text":"وصالك لي هجر ، وهجرك لي وصل … فزدني صدودا ما استطعت ، ولا تأل\nإذا كان قربي منك بعدا عن المنى … فلا حمت اللقيا ، ولا اجتمع الشمل\nوكيف أود القرب من متلون … كثير خبايا الصدر ، شيمته الختل\nفليت الذي بيني وبينك ينتهى … إلى حيث لا طلح يرف ولا أثل\nخبثت ، فلو طهرت بالماء لاكتسى … بك الماء خبثا لا يحل به الغسل\nفوجهك منحوس ، وكعبك سافل … وقلبك مدغول ، وعقلك مختل\nبك اسودت الأيام بعد ضيائها … وأصبح نادي الفضل ليس به أهل\nفلو لم تكن في الدهر ما انقض حادث … بقوم ، ولا زلت بذي أمل نعل\nفما نكبة إلا وأنت رسولها … ولا خيبة إلا وأنت لها أصل\nأذم زمانا أنت فيه ، وبلدة … طلعت عليها ؛ إنه زمن وغل\nذمامك مخفور ، وعهدك ضائع … ورأيك مأفون ، وعقلك مختل\nمخاز لو ان النجم حمل بعضها … لعاجله من دون إشراقه أفل\nفسر غير مأسوف عليك ، فإنما … قصارى ذميم العهد أن يقطع الحبل"},{"id":"diwan-barudi:33","bookId":"diwan-barudi","type":"poem","seq":33,"chapter":"البحر: طويل","title":"إلى الله أشكو طول ليلي ، وجارة","page":"","text":"إلى الله أشكو طول ليلي ، وجارة … تبيت إلى وقت الصباح بإعوال\nلها صبية لا بارك الله فيهم … قباح النواصي ، لا ينمن على حال\nصوارخ ، لا يهدأن إلا مع الضحا … من الشر ، في بيت من الخير ممحال\nترى بينهم يا فرق الله بينهم … لهيب صياح يصعد الفلك العالي\nكأنهم مما تنازعن أكلب … طرقن على حين المساء برئبال\nفهجن جميعا هيجة فزعت لها … كلاب القرى ، ما بين سهل وأجبال\nفلم يبق من كلب عقور وكلبة … من الحي إلا جاء بالعم والخال\nوفزعت الأنعام والخيل ؛ فانبرت … تجاوب بعضا في رغاء وتصهال\nفقامت رجال الحي تحسب أنها … أصيبت بجيش ذي غوارب ذيال\nفمن حامل رمحا ، ومن قابض عصا … ومن فزع يتلو الكتاب بإهلال\nومن صبية ريعت لذاك ، ونسوة … قوائم دون الباب يهتفن بالوالي\nفيا رب ، هب لي من لدنك تصبرا … على ما أقاسيه ، وخذهم بزلزال"},{"id":"diwan-barudi:34","bookId":"diwan-barudi","type":"poem","seq":34,"chapter":"البحر: مجزوء الكامل","title":"يا قلب ، ما لك لا تفي","page":"","text":"يا قلب ، ما لك لا تفي … ق من الهوى ؟ يا قلب ، ما لك ؟\nأو ما بدا لك أن تعو … د عن الصبا ؟ أو ما بدا لك ؟\nأم خلت أن يد الزما … ن قصيرة عن أن تنالك\nهيهات ، صد بك الهوى … عن أن تريع ، ولن إخالك\nسلم أمورك للذي … أنشاك من عدم وعالك\nودع التعلق بالمحا … ل ؛ فإنه يبري محالك\nفعساك تنزع من يد ال … أهواء يا قلبي حبالك"},{"id":"diwan-barudi:35","bookId":"diwan-barudi","type":"poem","seq":35,"chapter":"البحر: مجزوء الرمل","title":"أيها المغرور ، مهلا","page":"","text":"أيها المغرور ، مهلا … لست للتكريم أهلا\nكيف صادفت الأماني ؟ … هل رأيت الصعب سهلا ؟\nخلتها ماء نميرا … فاشربن علا ، ونهلا\nأين أهل الدار ؟ فانظر … هل ترى بالدار أهلا ؟\nرب حسن في ثياب … عاد غسلينا ومهلا ؟\nوعيون كن سودا … صرن عند الموت شهلا\nسوف يلقى كل باغ … في الورى خزيا وبهلا\nإنما الدنيا غرور … لم تدع طفلا وكهلا\nكم حكيم ضل فيها … فاكتسى بالعلم جهلا"},{"id":"diwan-barudi:36","bookId":"diwan-barudi","type":"poem","seq":36,"chapter":"البحر: بسيط تام","title":"بقوة العلم تقوى شوكة الأمم","page":"","text":"بقوة العلم تقوى شوكة الأمم … فالحكم في الدهر منسوب إلى القلم\nكم بين ما تلفظ الأسياف من علق … وبين ما تنفث الأقلام من حكم\nلو أنصف الناس كان الفضل بينهم … بقطرة من مداد ، لا بسفك دم\nفاعكف على العلم ، تبلغ شأو منزلة … في الفضل محفوفة بالعز والكرم\nفليس يجنى ثمار الفوز يانعة … من جنة العلم إلا صادق الهمم\nلو لم يكن في المساعي ما يبين به … سبق الرجال ، تساوى الناس في القيم\nوللفتى مهلة في الدهر ، إن ذهبت … أوقاتها عبثا ، لم يخل من ندم\nلولا مداولة الأفكار ما ظهرت … خزائن الأرض بين السهل والعلم\nكم أمة درست أشباحها ، وسرت … أرواحها بيننا في عالم الكلم\nفانظر إلى الهرمين الماثلين تجد … غرائبا لا تراها النفس في الحلم\nصرحان ، ما دارت الأفلاك منذ جرت … على نظيرهما في الشكل والعظم\nتضمنا حكما بادت مصادرها … لكنها بقيت نقشا على رضم\nقوم طوتهم يد الأيام ؛ فاتقرضوا … وذكرهم لم يزل حيا على القدم\nفكم بها صور كادت تخاطبنا … جهرا بغير لسان ناطق وفم\nتتلو ل ( هرمس ) آيات تدل على … فضل عميم ، ومجد باذخ القدم\nآيات فخر ، تجلى نورها ؛ فغدت … مذكورة بلسان العرب والعجم\nولاح بينهما ' بلهيب ' متجها … للشرق ، يلحظ مجرى النيل من أمم\nكأنه رابض للوثب ، منتظر … فريسة ؛ فهو يرعاها ، ولم ينم\nرمز يدل على أن العلوم إذا … عمت بمصر نزت من وهدة العدم\nفاستيقظوا يا بني الأوطان ، وانتصبوا … للعلم ؛ فهو مدار العدل في الأمم\nولا تظنوا نماء المال ، وانتسبوا … فالعلم أفضل ما يحويه ذو نسم\nفرب ذي ثروة بالجهل محتقر … ورب ذي خلة بالعلم محترم\nشيدوا المدارس ؛ فهي الغرس إن بسقت … أفنانه أثمرت غضا من النعم\nمغنى علوم ، ترى الأبناء عاكفة … على الدروس به ، كالطير في الحرم\nمن كل كهل الحجا في سن عاشرة … يكاد منطقه ينهل بالحكم\nكأنها فلك لاحت به شهب … تغني برونقها عن أنجم الظلم\nيجنون من كل علم زهرة عبقت … بنفحة تبعث الأرواح في الرمم\nفكم ترى بينهم من شاعر لسن … أو كاتب فطن ، أو حاسب فهم\nونابغ نال من علم الحقوق بها … مزية ألبسته خلعة الحكم\nولج هندسة تجري بحكمته … جداول الماء في هال من الأكم\nبل ، كم خطيب شفى نفسا بموعظة … وكم طبيب شفى جسما من السقم\nمؤدبون بآداب الملوك ، فلا … تلقى بهم غير عالي القدر محتشم\nقوم بهم تصلح الدنيا إذا فسدت … ويفرق العدل بين الذئب والغنم\nوكيف يثبت ركن العدل في بلد … لم ينتصب بينها للعلم من علم ؟\nما صور الله للأبدان أفئدة … إلا ليرفع أهل الجد والفهم\nوأسعد الناس من أفضى إلى أمد … في الفضل ، وامتاز بالعالي من الشيم\nلولا الفضيلة لم يخلد لذي أدب … ذكر على الدهر بعد الموت والعدم\nفلينظر المرء فيما قدمت يده … قبل المعاد ، فإن العمر لم يدم"},{"id":"diwan-barudi:37","bookId":"diwan-barudi","type":"poem","seq":37,"chapter":"البحر: طويل","title":"لعزة هذي اللاهيات النواعم","page":"","text":"لعزة هذي اللاهيات النواعم … تذل عزيزات النفوس الكرائم\nفما كنت لولاهن تهتاجني الصبا … أصيلا ، ويشجيني هدير الحمائم\nولا شاقني برق تألق موهنا … كزند توالي قدحه كف ضارم\nوبيضاء ريا الردف ، مهضومة الحشا … يقل ضحاها جنح أسود فاحم\nمن العين ، يحمى خدرها كل ضيغم … بعيد مشق الجفن ، عبل المعاصم\nفلولا هواها ما تغنت حمامة … بغصن ، ولا انهلت شئون الغمائم\nولا التهب البرق اللموع ، ولا غدت … تحن مطايا نا حنين الروائم\nأما ، وهلال في دجنة طرة … يلوح ، ودر في عقيق مباسم\nلقد أودع البين المشت بمهجتي … ندوبا ، كأثر الوشم من كف واشم\nوكم ليلة ساورتها نابغية … سقتني بما مجت شفاه الأراقم\nكأن الثريا كف عذراء طفلة … به رعشة للبين ، بادي الخواتم\nإذا اضطربت تحت الظلام تخالها … دموع العذارى في حداد المآتم\nوبرق يماني أرقت لومضه … يطير بهداب كثير الزمازم\nكأن اصطخاب الرعد في جنباته … هدير فحول ، أو زئير ضراغم\nتخالفت الأهواء فيها : فعاذر … هواي الذي أشكو ، وآخر لائمي\nونافسني ، في حبها كل كاشح … يلف على الشحناء عوج الحيازم\nفكم صاحب ألقاه يحمل صدره … فؤاد عدو في ثياب مسالم\nأغالطه قولي ، وأمحضه الوفا … كأني بما في صدره غير عالم\nومن لم يغالط في الزمان عدوه … ويبدي له الحسنى ، فليس بحازم\nفيا ربة الخال التي هدرت دمي … وألقت إلى أيدي الفراق شكائمي\nإليك استثرت العين محلولة العرا … وفيك رعيت النجم رعي السوائم\nفلا تتركي نفسي تذوب ، ومهجتي … تسيل دما بين الدموع السواجم\nأقول لركبس مدلجين ، هفت بهم … رياح الكرى ، ميل الطلى والعمائم\nتجد بهم كوم المهاري لواغبا … على ما تراه ، داميات المناسم\nتصيخ إلى رجع الحداء ، كأنها … تحن إلى إلف قديم مصارم\nويلحقها من روعة السوط جنة … فتمرق شعثا من فجاج المخارم\nلهن إلى الحادي التفاتة وامق … فمن رازح معى ، وآخر رازم\nألا أيها الركب الذي خامر السرى … بكل فتى للبين أغبر ساهم\nقفا بي قليلا ، وانظرا بي ؛ أشتفي … بلثم الحصى بين اللوى فالنعائم\nفكم عهد صدق مر فيه ، وأعصر … تولت عجالا دون تهويم نائم\nأبيت لها دامي الجفون مسهدا … طريح الثرى ، محمر طرف الأباهم\nوما هاجني إلا عصيفير روضة … على ملعب من دوحة الضال ناعم\nيصيح ، فما أدري : لفرقة صاحب … كريم السجايا ، أم يغني لقادم ؟\nكأن العصيفير استطير فؤاده … سرورا برب المكرمات الجسائم\nأبو المجد ، نجل الجود ، خال زمانه … أخو الفخر ' إسماعيل ' خدن المكارم\nقشيب الصبا ، كهل التدابير جامع … صنوف العلا والمجد في صدر جازم\nتجمع فيه الحلم ، والبأس ، والندى … فليس له في مجده من مزاحم\nذكاء ' أرسطاليس ' في حلم ' أحنف ' … وهمة ' عمرو ' في سماحة ' حاتم '\nله تحت أستار الغيوب ، وفوقها … عيون ترى الأشياء ، لا وهم واهم\nفنظرته وحي ، وساكن صدره … فؤاد خبير ، ناطق بالعظائم\nتكاد لعلياه الملائك ترتمي … على كتفيه ، كالطيور الحوائم\nأراه ، فيمحوني الجلال ، وأنتحي … أغالط أفكاري ، ولست بحالم\nوتوهمني نفسي الكذاب سفاهة … ألا ، إنما الأوهام طرق المآثم\nهو السيف ، في حديه لين وشدة … فتلقاه حلو البشر ، مر المطاعم\nتراه لدى الخطب الملم مجمعا … عرا الحلم ، ثبت الجأش ، ماضي العزائم\nله النظرة الشزراء ، يعقبها الرضا … لإسعاف مظلوم ، وإرغام ظالم\nفلولا ندى كفيه أوقد بأسه … لدى الروع أطراف الظبا واللهاذم\nولولا ذكاه أعشبت بيمينه … قنا الخط ، واخضلت طروس المظالم\nله بيت مجد ، زفرفت دون سقفه … حمام الدراري ، مشمخر الدعائم\nفمن رامه ، فليتخذ من قصائدي … سطورا إلى مرقاه مثل السلالم\nفيابن الألى سادوا الورى ، وانتهوا إلى … تمام العلا من قبل نزع التمائم\nأهنيك بالملك الذي طال جيده … بعزك ، حتى حل بيت النعائم\nلسودته بالفخر ، فابيض وجهه … بأسمر خطي ، وأبيض صارم\nتداركته من قبل أن كاد ينمحي … لفرط تباريح الدهور الغواشم\nبكى زمنا ، واغبر ، حتى أتيته … فعاد رحيب الصدر ، طلق المباسم\nوسست الورى بالعدل حتى تشوقا … إليك التوى جيد الدهور القدائم\nوجئت مجيء البدر مد شعاعه … على أفق بالجون وحف القوادم\nبرأي كخيط الشمس نورا ، تخاله … فرندا تمشى في خدود الصوارم\nفلو مصر تدري أرسلت لك نيلها … ليلقاك في جنح من الليل قاتم\nوجاءت لك الأهرام تسعى تشوقا … إلى دار ( قسطنطين سعي النسائم )\nفبوركت في ملك ورثت ذماءه … وخلدته في نسل مجد أكارم\nبهم كل غطريف ، يمد إلى العلا … يدا خلقت فينا لبذل المكارم\nيجول مجال البرق والخيل ترتمي … بأعطافها في المأزق المتلاحم\nفما روضة غناء باكرها الحيا … بأوطف ساج ، أشعل البرق ساجم\nيضوع بها نشر العبير ، فتغدي … تقاسمه فينا أكف النواسم\nإذا الشمس لاحت من خلال ظلالها … على الأرض ، لاحت مثل دور الدراهم\nيقيل بها سرب المها وهو آمن … فمن أربد ساج ، وأحور باغم\nبألطف من أخلاقهم وصفاتهم … إذا العود ضمته أكف العواجم\nوما الشعر من دأبي ، ولا أنا شاعر … ولا عادتي نعت الصوى والمعالم\nولكن حداني جوده ؛ فاستثارني … لوصف معاليه العظام الجسائم\nوكيف ، وجدواه ثنت ضبع همتي … وهزت إلى نظم القريض قوادمي\nفتلك لآل ، أم ربيع تفتحت … أزاهره كالزهر ، أم نظم ناظم ؟\nوما هو إلا عقد مدح نظمته … لجيد علاه في صدر المواسم\nفعش ما تغنت بالأراك حمامة … وما اتجهت للبرق نظرة شائم\nلك السعد خدن ، والمهابة صاحب … وشخص العلا والنصر في زي خادم"},{"id":"diwan-barudi:38","bookId":"diwan-barudi","type":"poem","seq":38,"chapter":"البحر: كامل تام","title":"أسل الديار عن الحبيب في الحشا","page":"","text":"أسل الديار عن الحبيب في الحشا … دار له مأهولة ومقام\nومن العناء سؤال خاشعة الصوى … بيد الفناء ، جوابها إرمام\nذكرت بها النفس اللجوج زمانها … إن التذكر للنفوس غرام\nإذ للهوى ثمر يرف ، وللصبا … كأس تشف ، وللمنى إلمام\nتستن فيها العين بين مخانس … فيها السلام تعانق ولزام\nفي فتية فاض النعيم عليهم … ونماهم التبجيل والإعظام\nذهبت بهم شيم الملوك ، فليس في … تلعابهم هذر ، ولا إبرام\nلا ينطقون بغير آداب الهوى … سمح النفوس ، على البلاء كرام\nمن كل أبلج ، يستضاء بنوره … كالبدر ، جلى صفحتيه غمام\nسهل الخليفة ، لا يسوء جليسه … يبقى ، وعاقبة النفوس حمام\nمتواضع للقوم ، تحسب أنه … مولى لهم في الدار ، وهو همام\nتتقاصر الأفهام دون فعاله … وتسير تحت لوائه الأقوام\nفإذا تكلم فالرؤس خواضع … وإذا تناهض فالصفوف قيام\nحتى انتبهنا بعد ما ذهب الصبا … إن الخلاعة والصبا أحلام\nلا تحسبن العيش دام لمترف … هيهات ، ليس على الزمان دوام\nتأتي الشهور ، وتنتهى أيامها … لمع السراب ، وتنقضي الأعوام\nوالناس فيما بين ذلك وارد … أو صادر ، تجري به الأيام\nلا طائر ينجو ، ولا ذو مخلب … \nفادرأ هموم النفس عنك إذا اعترت … بالكأس ؛ فهي على الهموم حسام\nفالعيش ليس يدوم في ألوانه … إلا إذا دارت عليه الجام\nمن خمرة تذر الكبير إذا انتشى … بعد اشتعال الشيب وهو غلام\nلعب الزمان بها ، فغادر جسمها … شبحا تحار لدركه الأفهام\nحمراء ، دار بها الحباب فصورت … فلكا تحف سماءه الأجرام\nلا تستقيم العين في لمعانها … وتزل عند لقائها الأقدام\nتعشو الركاب ، فإن تبلج كأسها … ساروا ، وإن زال الضياء أقاموا\nحبست بأكلف ، لم يقم بفنائه … نور ، ولم يبرح عليه ظلام\nحتى إذا رقدت ، وقر قرارها … سلست ؛ فليس لذوقها إيلام\nتسم العيون بنارها ، لكنها … برد على شرابها وسلام\nفاصقل بها صدأ الهموم ، ولا تكن … غرأ تطير بلبه الأوهام\nواعلم بأن المرء ليس بخالد … والدهر فيه صحة وسقام\nيهوى الفتى طول الحياة ، وإنها … داء له دون الشغاف عقام\nفاطمح بطرفك ، هل ترى من أمة … خلدت ؟ وهل لابن السبيل مقام ؟\nهذي المدائن قد خلت من أهلها … بعد النعيم ، وهذه الأهرام\nلا شيء يبقى ، غير أن خديعة … في الدهر تنكل دونها الأحلام\nولقد تبينت الأمور بغيرها … وأتى على النقض والإبرام\nفإذا السكون تحرك ، وإذا الخمو … د تلهب ، وإذا السكوت كلام\nوإذا الحياة - ولا حياة - منية … تحيا بها الأجساد وهي رمام\nهذا يحل وذاك يرحل كارها … عنه : فصلح تارة ، وخصام\nفالنور - لو بينت أمرك - ظلمة … والبدء لو فكرت فيه ختام"},{"id":"diwan-barudi:39","bookId":"diwan-barudi","type":"poem","seq":39,"chapter":"البحر: كامل تام","title":"ذهب الصبا ، وتولت الأيام","page":"","text":"ذهب الصبا ، وتولت الأيام … فعلى الصبا ، وعلى الزمان سلام\nتالله أنسى ما حييت عهوده … ولكل عهد في الكرام ذمام\nإذ نحن في عيش ترف ظلاله … ولنا بمعترك الهوى آثام\nتجري علينا الكأس بين مجالس … فيها السلام تعانق ولزام\nفي فتية فاض النعيم عليهم … ونماهم التبجيل والإعظام\nذهبت بهم شيم الملوك ، فليس في … تلعابهم هذر ، ولا إبرام\nلا ينطقون بغير آداب الهوى … سمح النفوس ، على البلاء كرام\nمن كل أبلج يستضاء بنوره … كالبدر حلى صفحتيه غمام\nسهل الخليقة ، لا يسوء جليسه … بين المقامة ، واضح ، بسام\nمتواضع للقوم ، تحسب أنه … مولى في الدار وهو همام\nترنو العيون إليه في أفعاله … وتسير تحت لوائه الأقوام\nفإذا تكلم فالرؤس خواضع … وإذا تناهض فالصفوف قيام\nنلهو ونلعب بين خضر حدائق … ليست بغير خيولنا تستام\nحتى انتبهنا بعد ما ذهب الصبا … إن اللذاذة والصبا أحلام\nلا تحسبن العيش دام لمترف … هيهات ، ليس على الزمان دوام\nتأتي الشهور ، وتنتهي ساعاتها … لمع السراب ، وتنقضي الأعوام\nوالناس فيما بين ذلك وارد … أو صادر ، تجري به الأيام\nلا طائر ينجو ، ولا ذو مخلب … يبقى ، وعاقبة الحياة حمام\nفادرأ هموم النفس عنك إذا اعترت … بالكأس ؛ فهي على الهموم حسام\nفالعيش ليس يدوم في ألوانه … إلا إذا دارت عليه الجام\nمن خمرة تذر الكبير إذا انتشى … بعد اشتعال الشيب وهو غلام\nلعب الزمان بها ، فغادر جسمها … شبحا تهافت دونه الأوهام\nحمراء ، دار بها الحباب ؛ فصورت … فلكا تحف سماءه الأجرام\nلا تستقيم العين في لمعانها … وتزول عند لقائها الأقدام\nتعشو الركاب ، فإن تبلج كأسها … ساروا ، وإن زال الضياء أقاموا\nحبست بأكلف ، لم يصل لفنائه … نور ، ولم يسرح عليه ظلام\nحتى إذا اصطفقت ، وطار فدامها … وثبت ، فلم تثبت لها الأجسام\nوقدت حميتها ، فلولا مزجها … بالماء بعد الماء ، شب ضرام\nتسم العيون بنورها ، لكنها … برد على شرابها وسلام\nفاصقل بها صدأ الهموم ، ولا تكن … غرا تطيش بلبه الالام\nواعلم بأن المرء ليس بخالد … والدهر فيه صحة وسقام\nيهوى الفتى طول الحياة ، وإنها … داء له لو يستبين عقام\nفاطمح بطرفك ، هل ترى من أمة … خلدت ؟ وهل لابن السبيل مقام ؟\nهذي المدائن قد خلت من أهلها … بعد النظام ، وهذه الأهرام\nلا شيء يخلد ، غير أن خديعة … في الدهر تنكل دونها الأحلام\nولقد تبينت الأمور بغيرها … وأتى على النقض والإبرام\nفإذا السكون تحرك ، وإذا الخمو … د تلهب ، وإذا السكوت كلام\nوإذا الحياة - ولا حياة - منية … تحيا بها الأجساد وهي رمام\nهذا يحل ، وذاك يرحل كارها … عنه ، فصلح تارة ، وخصام\nفالنور - لو بينت أمرك - ظلمة … والبدء لو فكرت فيه ختام"},{"id":"diwan-barudi:40","bookId":"diwan-barudi","type":"poem","seq":40,"chapter":"البحر: طويل","title":"ألا ، حي بالمقياس ريا المعالم","page":"","text":"ألا ، حي بالمقياس ريا المعالم … وقل لها منا تحية قادم\nملاعب آرام ، ومأوى حمائم … ومسقط أنداء ، ومسرى نسائم\nأحاطت به للنيل من كل جانب … جداول تسقيه سلاف الغمائم\nتدور مدار الطوق من حيث تلتقي … مسيرا ، وتنسل انسلال الأراقم\nإذا ضاحكتها الشمس رفت متونها … رفيف الثنايا خلف حمر المباسم\nوإن سلسلتها الريح أبدت سبائكا … مقدرة ، كالوشم فوق المعاصم\nتجوس خلال الباسقات ، وتنتهى … إلى ساعد في غمرة النيل ساجم\nترى حولها الأشجار ولهى مكبة … على الماء ، فعل الصاديات الحوائم\nومنبعثات في الهواء ، كأنها … بيارق لهو ركزت في المواسم\nمن اللاء قد آلين يشربن ، أو تلى … منابتها غور البحار الخضارم\nإذا لاعبت أعرافها الريح خلتها … فوارس تعصو بالسيوف الصوارم\nيلوح بها طلع نضيد ، كأنه … فرائد ساوى بينها كف ناظم\nإذا ما أتى ميقاتها ، وتضرجت … حسبت عقيقا في صحاف الكمائم\nمسارح لهو ، لو رأى ( الشعب ) حسنها … لعض على ما فاته بالأباهم\nذكرت بها عصرا تولى ، ولذة … تقضت . وما عهد الزمان بدائم\nوما تحسن الأيام إلا بأهلها … ولا الدار إلا بالصديق الملائم\nفيا نعم ما ولت به دولة الصبا … ولم ترعه من عهدنا المتقادم\nإذ العيش أفنان ، ونحن عصابة … ألو ترف : ما بين غاد وهائم\nنسير على دين الوفاء ، ولم يكن … سوى الحب من قاض علينا وحاكم\nإذا قال منا قائل ، قام دونه … شهيد عليه ، صادق ، غير آثم\nيحوم عليه والمنايا مسفة … ويدرأ عنه في صدور اللهاذم\nإذا ألهبته غضبة ، وترجحت … به سورة ، أغرى الظبا بالجماجم\nفقد مر ذاك العصر إلا لبانة … معلقة بين الحشا والحيازم\nإذا ذكرتها النفس يوما تراجعت … عليها عقابيل الهموم القدائم\nومنزلة للأنس كنا نحلها … ونرعى بها اللذات رعي السوائم\nعفت ، وكأن لم تغن بالأمس ، والتقت … عليها أعاصير الرياح الهواجم\nوما خير دنيا لا بقاء لعهدها … وما طيب عيش ربه غير سالم\nعلى هذه تمضي الليالي ، وينقضي … حديث المنى فيها ، كأحلام نائم"},{"id":"diwan-barudi:41","bookId":"diwan-barudi","type":"poem","seq":41,"chapter":"البحر: سريع","title":"يا ناعس الطرف ، إلى كم تنام ؟","page":"","text":"يا ناعس الطرف ، إلى كم تنام ؟ … أسهرتني فيك ، ونام الأنام\nأوشك هذا الليل أن ينقضي … والعين لا تعرف طيب المنام\nويلاه من ظبي الحمى ؛ إنه … جرعني - بالصد - مر الحمام\nيغضب من قولي ' آه ' وهل … قولي ( آه يابن ودي حرام ؟ )\nلا كتبه تترى ، ولا رسله … تأتي ، ولا الطيف يوافى لمام\nالله في عين جفاها الكرى … فيكم ، وقلب قد براه الغرام\nطال النوى من بعدكم ، وانقضت … بشاشة العيش ، وساء المقام\nأرتاح إن مر نسيم الصبا … والبرء لي فيه معا ، والسقام\nيا ليتني في السلك حرف سرى … أو ريشة بين خوافي الحمام\nحتى أوافى مصر في لحظة … أقضي بها في الحب حق الذمام\nمولاي ! ، قد طال مرير النوى … فكل يوم مر بي ألف عام\nأنظر حولي ، لا أرى صاحبا … إلا جماهير ، وخيلا ، وخيلا صيام\nوديدبانا صارخا في الدجى … يرجع وراء ؛ إنه لا أمام\nيقتبل الصبح ، ويمضي الدجى … وينقضي النور ، ويأتي الظلام\nولا كتاب من حبيب أتى … ولا أخو صدق يرد السلام\nفي هضبة من أرض ' دبريجة ' … ليس بها غير بغاث وهام\nوراءنا … سواد جيش مكفهر لهام\nفتلك حالي - لا رمتك النوى - … فكيف أنتم بعدنا يا همام ؟"},{"id":"diwan-barudi:42","bookId":"diwan-barudi","type":"poem","seq":42,"chapter":"البحر: خفيف تام","title":"حي مغنى الهوى بوادي الشآم","page":"","text":"حي مغنى الهوى بوادي الشآم … وادع باسمي تجبك ورق الحمام\nهن يعرفنني بطول حنيني … بين تلك السهول والآكام\nفلقد طالما هتفن بشدوي … وتناقلن ما حلا من هيامي\nولكم سرت كالنسيم عليلا … أتقرى ملاعب الآرام\nفي شعار من الضنى ، نسجته … بخيوط الدموع أيدي الغرام\nكلما شمت بارقا خلت ثغرا … باسما من خلال تلك الخيام\nوالهوى يجعل الخلاج يقينا … ويغر الحليم بالأوهام\nخطرات لها بمرآة قلبي … صور لا تزول كالأحلام\nما تجلت على المخيلة إلا … أذكرتني ما كان من أيامي\nذاك عصر خلا ، وأبقى حديثا … نتعاطاه بيننا كالمدام\nكلما زحزحت بنانة فكري … عنه ستر الخيال لاخ أمامي\nيا نسيم الصبا فديتك بلغ … أهل ذاك الحمى عبير سلامي\nواقض عني حق الزيارة ، واذكر … فرط وجدي بهم ، وطول سقامي\nأنا راض منهم بذكرة ود … أو كتاب إن لم أفز بلمام\nهم أباحوا الهوى حريم فؤادي … وأذلوا للعاذلين خطامي\nأتمناهم ، ودون التلاقي … قذفات من لج أخضر طامي\nصائل الموج كالفحول تراغى … من هياج ، وترتمي باللغام\nوترى السفن كالجبال ، تهادى … خافقات البنود والأعلام\nتعتلي تارة ، وتهبط أخرى … في فضاء بين السها والرغام\nهي كالدهم جامحات ، ولكن … ليس يثنى جماحها بلجام\nكل أرجوحة ترى القوم فيها … خشعا بين ركع وقيام\nلا يفيقون من دوار : فهاو … ليديه ، وراعف الأنف دامي\nيستغيثون ، فالقلوب هواف … حذر الموت ، والعيون سوامي\nفي وعاء يحدونه بدعاء … لجلال المهيمن العلام\nذاك بحر يليه بر ترامى … فيه خوص المطي مثل النعام\nفسوادي بمصر ثاو ، وقلبي … في إسار الهوى بأرض الشآم\nأخدع النفس بالمنى ، وهي تأبى … وخداع المنى غذاء الأنام\nفمتى يسمح الزمان ، فألقى … ب ' شكيب ' ما فاتني من مرام\nهو خل ، لبست منه خلالا … عبقات ، كالنور في الأكمام\nصادق الود ، لا يخيس بعهد … وقليل في الناس رعى الذمام\nجمعتنا الآداب قبل التلاقي … بنسيم الأرواح ، لا الأجسام\nوبلغنا بالود ما لم ينله … بحياة القربى ذوو الأرحام\nفلئن لم نكن بأرض ، فإنا … لاتصال الهوى بدار مقام\nوائتلاف النفوس أصدق عهدا … من لقاء لم يقترن بدوام\nألمعي له بديهة رأي … تدرك الغيب من وراء لثام\nوقريض كما وشت نسمات … بضمير الأزهار إثر الغمام\nهزني شعره ؛ فأيقظ مني … فكرة كان حظها في المنام\nسمتها القول بعد لأي ، فبضت … بيسير لم يرو عود ثمام\nفارض مني بما تيسر منها … رب ثمد فيه غنى عن جمام\nولو اني أردت شرح ودادي … واشتياقي لضاق وسع الكلام\nأنا هواك فطرة ، ليس فيها … من مساغ للنقض والإبرام\nوإذا الحب لم يكن ذا دواع … كان أرسى قواعدا من شمام\nفتقبل شكري على حسن ود … رحت منه مقلدا بوسام\nأتباهى به إذا كان غيري … يتباهى بزينة الإنعام\nدمت في نعمة ترف حلاها … فوق فرع من طيب أصلك نامى"},{"id":"diwan-barudi:43","bookId":"diwan-barudi","type":"poem","seq":43,"chapter":"البحر: طويل","title":"أشدت بذكرى بادئا ومعقبا","page":"","text":"أشدت بذكرى بادئا ومعقبا … وأمسكت ، لم أهمس ، ولم أتكلم\nوما ذاك ضنا بالوداد على امرىء … حباني به ، لكن تهيب مقدمي\nفأما وقد حق الجزاء ؛ فلم أكن … لأنطق إلا بالثناء المنمنم\nوكيف أذود الفضل عن مستقره … وأنكر ضوء الشمس بعد توسم\nوأنت الذي نوهت باسمي ، ورشتني … بقول سرا عني قناع التوهم\nلك السبق دوني في الفضيلة ، فاشتمل … بحلتها ؛ فالفضل للمتقدم\nودونكها يا بن الكرام حبيرة … من النظم سداها بمدح العلا فمي"},{"id":"diwan-barudi:44","bookId":"diwan-barudi","type":"poem","seq":44,"chapter":"قصائد","title":"هجوته لا بالغا لؤمه","page":"","text":"هجوته لا بالغا لؤمه … لكنني كفكفت من غربه\nفإن أكن قد نلت من عرضه … فإننى دنست شعرى به\nفلا يلومن سوى نفسه … من سلط الناس على ثلبه"},{"id":"diwan-barudi:45","bookId":"diwan-barudi","type":"poem","seq":45,"chapter":"البحر: طويل","title":"هوى كان لي أن ألبس المجد معلما","page":"","text":"هوى كان لي أن ألبس المجد معلما … فلما ملكت السبق عفت التقدما\nومن عرف الدنيا رأى ما يسره … من العيش هما يترك الشهد علقما\nوأي نعيم في حياة وراءها … مصائب لو حلت بنجم لأظلما\nإذا كان عقبى كل حي منية … فسيان من حل الوهاد ، ومن سما\nومن عجب أنا نرى الحق جهرة … ونلهو ، كأنا لا نحاذر مندما\nيود الفتى في كل يوم لبانة … فإن نالها أنحى لأخرى ، وصمما\nطماعة نفس تورد المرء مشرعا … من البؤس لا يعدوه أو يتحطما\nأرى كل حي غافلا عن مصيره … ولو رام عرفان الحقيقة لانتمى\nفأين الألى شادوا ، وبادوا ؟ ألم نكن … نحل كما حلوا ، ونرحل مثلما ؟\nمضوا ، وعفت آثارهم غير ذكرة … تشيد لنا منهم حديثا مرجما\nسل الأورق الغريد في عذباته … أناح على أشجانه ، أم ترنما ؟\nترجح في مهد من الأيك ، لا يني … يميل عليه مائلا ومقوا\nينوح على فقد الهديل ، ولم يكن … رآه ، فيا لله ! كيف تهكما ؟\nوشتان من يبكي على غير عرفة … جزافا ، ومن يبكي لعهد تجرما\nلعمري لقد غال الردى من أحبه … وكان بودي أن أموت ويسلما\nوأي حياة بعد أم فقدتها … كما يفقد المرء الزلال على الظما\nتولت ، فولى الصبر عني ، وعادني … غرام عليها ، شف جسمي ، وأسقما\nولم يبق إلا ذكرة تبعث الأسى … وطيف يوافيني إذا الطرف هوما\nوكانت لعيني قرة ، ولمهجتي … سرورا ، فخاب الطرف والقلب منهما\nفلولا اعتقادي بالقضاء وحكمه … لقطعت نفسي لهفة وتندما\nفيا خبرا شف الفؤاد ؛ فأوشكت … سويداؤه أن تستحيل ، فتسجما\nإليك ؛ فقد ثلمت عرشا ممنعا … وفللت صمصاما ، وذللت ضيغما\nأشاد به الناعي ، وكنت محاربا … فألقيت من كفى الحسام المصمما\nوطارت بقلبي لوعة لو أطعتها … لأوشك ركن المجد أن يتهدما\nولكنني راجعت حلمي ، لأنثني … عن الحرب محمود اللقاء مكرما\nفلما استرد الجند صبغ من الدجى … وعاد كلا الجيشين يرتاد مجثما\nصرفت عناني راجعا ، ومدامعي … على الخد يفضحن الضمير المكتما\nفيا أمتا ؛ زال العزاء ، وأقبلت … مصائب تنهى القلب أن يتلوما\nوكنت أرى الصبر الجميل مثوبة … فصرت أراه بعد ذلك مأثما\nوكيف تلذ العيش نفس تدرعت … من الحزن ثوبا بالدموع منمنما ؟\nتألمت فقدان الأحبة جازعا … ومن شفه فقد الحبيب تألما\nوقد منت أخشى أن أراك سقيمة … فكيف وقد أصبحت في الترب أعظما ؟\nبلغت مدى تسعين في خير نعمة … ومن صحب الأيام دهرا تهدما\nإذا زاد عمر المرء قل نصيبه … من العيش والنقصان آفة من نما\nفيا ليتنا كنا ترابا ، ولم نكن … خلقنا ، ولم نقدم إلى الدهر مقدما\nأبى طبع هذا الدهر أن يتكرما … وكيف يدي من كان بالبخل مغرما ؟\nأصاب لدينا غرة ؛ فأصابنا … وأبصر فينا ذلة ؛ فتحكما\nوكيف يصون الدهر مهجة عاقل … وقد أهلك الحيين : عادا ، وجرهما\nهو الأزلم الخداع ، يحفر إن رعى … ويغدر إن أوفى ، ويصمي إذا رمى\nفكم خان عهدا ، واستباح أمانة … وأخلف وعدا ، واستحل محرما\nفإن تكن الأيام أخنت بصرفها … علي ، فأي الناس يبقى مسلما ؟\nوإني لأدري أن عاقبة الأسى … وإن طال لا يروي غليلا تضرما\nولكنها نفس ترى الصبر سبة … عليها ، وترضى بالتلهف مغنما\nوكيف أراني ناسيا عهد خلة … ألفت هواها : ناشئا ، ومحكما\nولولا أليم الخطب لم أمر مقلة … بدمع ، ولم أفغر بقافية فما\nفيا ربة القبر الكريم بما حوى … وقتك الردى نفسي وأين ؟ وقلما\nوهل يستطيع المرء فدية راحل … تخرمه المقدار فيمن تخرما ؟\nسقتك يد الرضوان كأس كرامة … من الكوثر الفياض معسولة اللمى\nولا زال ريحان التحية ناضرا … عليك ، وهفاف الرضا متنسما\nليبك عليك القلب ، لا العين ؛ إنني … أرى القلب أوفى بالعهود وأكرما\nفوالله لا أنساك ما ذر شارق … وما حن طير بالأراك مهينما\nعليك سلام لا لقاءة بعده … إلى الحشر إذ يلقى الأخير المقدما"},{"id":"diwan-barudi:46","bookId":"diwan-barudi","type":"poem","seq":46,"chapter":"البحر: بسيط تام","title":"وغد تكون من لؤم ، ومن دنس","page":"","text":"وغد تكون من لؤم ، ومن دنس … فما يغار على عرض ، ولا حسب\nيلتذ بالطعن فيه والهجاء ، كما … يلتذ بالحك والتظفير ذو الجرب"},{"id":"diwan-barudi:47","bookId":"diwan-barudi","type":"poem","seq":47,"chapter":"البحر: منسرح","title":"أي فتى للعظيم نندبه","page":"","text":"أي فتى للعظيم نندبه … شاط على أنصل الرماح دمه\nأسلمه صحبه ، وما علموا … أن سوف يمحو وجودهم عدمه\nزال الألى حاذوا مصارعهم … ولم تزل عن مكانها قدمه\nطاح بجثمانه الردى ، ورقا … إلى سموات ربه نسمه\nنعم فتى الحرب في الهياج إذ … شب لظى البأاء ، واعتلى ضرمه\nقد ألفت صحبة القنا يده … واعتاد ( لبيك في السماح فمه )\nليس بهيابة ، ولا وكل … بل صادق ي اللقاء معترفه\nإن صال فل العدا بصولته … أو قال أروت مشاشنا كلمه\nينكفت الجيش حين يفجؤه … ويصعق القرن حين يلتزمه\nبكى بدمع الفرند صارمه … وانشق من طول حزنه قلمه\nفمن إلى ملجإ الضعيف إذا … أقبل ليل ، وأطبقت ظلمه\nومن يقود الزحوف راجفة … واليوم بالحرب ساطع قتمه\nمات ، وأبقى شجا لفرقته … يكاد يفري قلوبنا ألمه\nفاذهب ، عليك السلام من بطل … مات ، وعاشت من بعده نعمه"},{"id":"diwan-barudi:48","bookId":"diwan-barudi","type":"poem","seq":48,"chapter":"البحر: خفيف تام","title":"كيف أهجوك والدناءة سور","page":"","text":"كيف أهجوك والدناءة سور … من حديد يقيك طعنى وضربى\nلك عرض أرق نسجا من الري … يح ، وأوهى من طيلسان ابن حرب"},{"id":"diwan-barudi:49","bookId":"diwan-barudi","type":"poem","seq":49,"chapter":"البحر: طويل","title":"سلامة عرضي في خفارة صارمي","page":"","text":"سلامة عرضي في خفارة صارمي … وإن كان مالي نهبة للمكارم\nبلغت علا لا يبلغ النجم شأوها … إذا هو لم ينهض لها بقوادم\nإذا المرء لم يطرب إلى اللهو والصبا … فما هو إلا من عداد البهائم\nفأية أرض لم تجبها سوابقي … وغمرة بأس لم تخضها صوارمي\nوما الليل إلا هبوة من كتائبي … ولا الشهب إلا لمعة من لهاذمي\nجنان تحيد الأسد عنه ، وعزمة … هي الموت بين المأزق المتلاحم\nولكنني أمسيت للحب خاضعا … وللحب سلطان على كل حاكم\nوبي من صميم العرب حوراء طفلة … نحيلة مجرى البند ، ريا المعاصم\nلها نظرة لو خامرت قلب حازم … لأصبح مسلوب النهى ، غير حازم\nأطعت الهوى فيها وإن كان ظالما … وعاصيت في حبي لها كل راحم\nومن عجب أنى أدين لحكمها … وأكبر أن أنقاد طوع الخزائم\nفقلبي حر ، لا يدين لصولة … وعودي صلب ، لا يلين لعاجم"},{"id":"diwan-barudi:50","bookId":"diwan-barudi","type":"poem","seq":50,"chapter":"البحر: بسيط تام","title":"وذى خلال كأن الله صورها","page":"","text":"وذى خلال كأن الله صورها … من صبغة اللؤم ، أو من حمأة الريب\nنال العلاء ، ولكن خاب رائده … عن نجعة الفضل والآداب والحسب\nهجوته رغبة فى الصدق ، إذ نفرت … شمائلى عن مقال المدح فى الكذب"},{"id":"diwan-barudi:51","bookId":"diwan-barudi","type":"poem","seq":51,"chapter":"البحر: مديد تام","title":"دع حبيب القلب يا سقم","page":"","text":"دع حبيب القلب يا سقم … فبنفسي ، لا به الألم\nكيف حل السقم في بدن … خلقت من حسنه النعم ؟\nيا لها من لوعة شعبت … ركن قلبي وهو ملتئم !\nمنعوني عن زيارته … وحمى قلبي له حرم\nحكموا أني به دنف … أنا راض بالذي حكموا\nأولوا وجدي به عبثا … ليتهم قالوا بما علموا\nأتهموني في مودته … والهوى من شأنه التهم\nرب ، ! قنعهم بفريتهم … والنتصف منهم بما زعموا\nواشف نفسا أنت بارئها … فإليك البرء والسقم"},{"id":"diwan-barudi:52","bookId":"diwan-barudi","type":"poem","seq":52,"chapter":"البحر: وافر تام","title":"عدمت حمية ، وسقمت ودا","page":"","text":"عدمت حمية ، وسقمت ودا … فلم تدرك لمكرمة نصيبا\nفما أحزنت فى حرب عدوا … ولا أفرحت فى سلم حبيبا"},{"id":"diwan-barudi:53","bookId":"diwan-barudi","type":"poem","seq":53,"chapter":"البحر: طويل","title":"مضى ' حسن ' في حلبة الشعر سابقا","page":"","text":"مضى ' حسن ' في حلبة الشعر سابقا … وأدرك ، لم يسبق ، ولم يأل ( مسلم )\nوباراهما ' الطائي ' ، فاعترفت له … شهود المعاني بالتي هي أحكم\nوأبدع في القول ( الوليد ) ؛ فشعره … على ما تراه العين وشي منمنم\nوأدرك في الأمثال ( أحمد ) غاية … تبذ الخطى ، ما بعدها متقدم\nوسرت على آثارهم ، ولربما … سبقت إلى أشياء والله أعلم"},{"id":"diwan-barudi:54","bookId":"diwan-barudi","type":"poem","seq":54,"chapter":"البحر: منسرح","title":"إلام يهفو بحلمك الطرب ؟","page":"","text":"إلام يهفو بحلمك الطرب ؟ … أبعد خمسين فى الصبا أرب ؟\nهيهات ولى الشباب ، واقتربت … ساعة ورد دنا بها القرب\nفليس دون الحمام مبتعد … وليس نحو الحياة مقترب\nكل امرئ سائر لمنزلة … ليس له عن فنائها هرب\nوساكن بين جيرة قذف … لا نسب بينهم ، ولا قرب\nفي قفرة للصلال مزدحف … فيها ، وللضاريات مضطرب\nوشاهد موقفا يدان به … فالويل للظالمين والحرب\nفاربأ يفاعا ، أو اتخذ سربا … إن كان يغني اليفاع والسرب\nلا الباز ينجو من الحمام ، ولا … يخلص منه الحمام والخرب\nمسلط فى الورى : فلا عجم … يبقى على فتكه ، ولا عرب\nفكم قصور خلت ، وكم أمم … بادت ، فغصت بجمعها الترب\nفمنزل عامر بقاطنه … ومنزل بعد أهله خرب\nيغدو الفتى لاهيا بعيشته … وليس يدرى ما الصاب والضرب\nويقتنى نبعة يصيد بها … ونبع من حارب الردى غرب\nلا يبلغ الربح أو يفارقه … كماتح خان كفه الكرب\nيا واردا لا يمل مورده … حذار من أن يصيبك الشرب\nتصبو إلى اللهو غير مكترث … واللهو فيه البوار والترب\nوتترك البر غير محتسب … أجرا ، وبالبر تفتح الأرب\nدع الحميا ، فلابن حانتها … من صدمة الكأس لهذم ذرب\nتراه نصب العيون متكئا … وعقله فى الضلال مغترب\nفبئست الخمرمن مخادعة … لسلمها فى القلوب محترب\nإذا تفشت بمهجة قتلت … كما تفشى فى المبرك الجرب\nفتب إلى الله قبل مندمة … تكثر فيها الهموم والكرب\nواعتد على الخير ، فالموفق من … هذبه الاعتياد والدرب\nوجد بما قد حوت يداك ، فما … ينفع ثم اللجين والغرب\nفإن للدهر لو فطنت له … قوسا من الموت سهمها غرب"},{"id":"diwan-barudi:55","bookId":"diwan-barudi","type":"poem","seq":55,"chapter":"البحر: طويل","title":"لعمرك ما يدعى الفتى بين قومه","page":"","text":"لعمرك ما يدعى الفتى بين قومه … بذي كرم حتى يكون كريما\nولن يلبث المرء الضنين بماله … إذا خاف غرما أن يعد لئيما\nفليس الفتى من حاز مالا ، وإنما … فتى القوم من أغنت يداه عديما\nفمز بين ما تختار في الفعل ، والتمس … لنفسك حظا كي تكون عظيما"},{"id":"diwan-barudi:56","bookId":"diwan-barudi","type":"poem","seq":56,"chapter":"البحر: خفيف تام","title":"أدر الكأس يا نديم ، وهات","page":"","text":"أدر الكأس يا نديم ، وهات … واسقنيها على جبين الغداة\nشاق سمعى الغناء فى رونق الفج … ر ، وسجع الطيور في العذبات\nأي شيء أشهى إلى النفس من كأ … س مدار على بساط بنات ؟\nهو يوم تعطرت طرفاه … بشمال مسكية النفحات\nباسم الزهر ، عاطر النشر ، هامى ال … قطر ، واني الصبا ، عليل المهاة\nمسرح للعيون يمتد فيه … نفس الريح بين ماض وآت\nفامتثل دعوة الصبوح ، وبادر … فرصة الدهر قبل وشك الفوات\nوتدرج معي إلى روضة المن … يل ذات النخيل والثمرات\nفهى مرعى الهوى ، ومغنى التصابى … ومراح المنى ، ومسرى الحياة\nألفتها النفوس ، فهى إليها … من أليم الأشواق في حسرات\nتبعث اللهو والسرور ، وتمحو … من فؤاد الحزين كل شكاة\nبين ندمان كالكواكب حسنا … ورعابيب كالدمى خفرات\nيتساقون بالكئوس مداما … هى كالشمس فى قميص إياة\nفى أباريق كالطيور اشرأبت … حذر الفتك من صياح البزاة\nحانيات على الكئوس من الرأ … فة ، يرضعنهن كالأمهات\nلا ترى العين بينهم غير صب … بسماع ، أو هائم بفتاة\nومغن إذا شدا خلت أن ال … أرض ظلت تدور بالفلوات\nملك السمع والفؤاد بلحن … يفتن الغيد داخل الحجرات\nيبعث الصوت مرسلا ، فإذا ما … غض منه استدار بين اللهاة\nغرد يبطل الحديث ، وينسى … ربة الحزن لوعة الذكرات\nتلك والله لذة العيش ، لا سو … م الأمانى فى عالم الخطرات"},{"id":"diwan-barudi:57","bookId":"diwan-barudi","type":"poem","seq":57,"chapter":"البحر: طويل","title":"له نظرتا جود ، وبأس أثارتا","page":"","text":"له نظرتا جود ، وبأس أثارتا … غمامين سالا بالفواضل والدم\nفكم أحيت الأولى لبانة معشر … وكم أردت الأخرى حشاشة مجرم"},{"id":"diwan-barudi:58","bookId":"diwan-barudi","type":"poem","seq":58,"chapter":"البحر: مجزوء الرمل","title":"زمزمى الكأس وهاتى","page":"","text":"زمزمى الكأس وهاتى … واسقنيها يا مهاتى\nوامزجيها برضاب … منك معسول اللهاة\nإنما الراح مدار ال … أنس في كل الجهات\nطالما عاصيت فيها … أهل ودى ونهاتى\nلا أبالى فى هواها … بسماع الترهات\nكيف أخشى قول داه ؟ … أنا من قوم دهاة"},{"id":"diwan-barudi:59","bookId":"diwan-barudi","type":"poem","seq":59,"chapter":"البحر: مجزوء الوافر","title":"عليل ، أنت مسقمه","page":"","text":"عليل ، أنت مسقمه … فما لك لا تكلمه ؟\nسرى فيه الضنى حتى … بدت للعين أعظمه\nفلا إن باح تعذره … ولا إن ناح ترحمه\nإذا كان الهوى ذنبي … فقل لي : كيف أكتمه ؟\nودمعي أنت مرسله … وقلبي أنت مؤلمه\nولا والله مالي في ال … هوى ذنب ، فأعلمه\nفويلي من غريب الدل … ل أبلاني تحكمه\nتردد في محبته … ولم يسمح بها فمه\nغزال أحور العيني … ن ، لا يسلو متيمه\nبهيم بحسن صورته … فؤادي ، وهو يظلمه\nنسبت به ، فبان على … جبين الشعر ميسمه\nفما لي في الذي أملي … ه من فضل ، فأغنمه\nولكن حسنه يبدو … إلى عيني ، فترسمه\nوينثر لفظه درا … على سمعي ، فأنظمه\nولولا ذاك ما لاحت … بأفق الشعر أنجمه\nفقل ما شئت في شعري … وخير القول أحكمه"},{"id":"diwan-barudi:60","bookId":"diwan-barudi","type":"poem","seq":60,"chapter":"البحر: كامل تام","title":"سمع الخلى تأوهى فتلفتا","page":"","text":"سمع الخلى تأوهى فتلفتا … وأصابه عجب ، فقال من الفتى ؟\nفأجبته إني امرؤ لعب الأسى … بفؤاده يوم النوى فتشتتا\nانظر إلى تجد خيالا باليا … تحت الثياب ، يكاد ألا ينعتا\nقد كان لي قلب أصاب سواده … سهم لطرف فاتر فتفتتا\nتبع الهوى قلبى فهام ، وليته … قبل التوغل في البلاء تثبتا\nألقته في شرك المحبة غادة … هيهات ، ليس بصاحبي إن أفلتا\nكالورد خدا ، والبنفسج طرة … والغصن قدا ، والغزالة ملفتا\nنظرت بكحلاوين أودعتا الهوى … بالقلب حتى هام ، ثم تخلتا\nتالله لو علم العذول بما جنى … طرفى على لساءه أن يشمتا\nطرف أطلت عنانه ليصيب لي … بعض المنى ، فأصابني لما أتى\nيا قلب حسبك قد أفاق معاشر … وأراك تدأب في الهوى ، فإلى متى ؟"},{"id":"diwan-barudi:61","bookId":"diwan-barudi","type":"poem","seq":61,"chapter":"البحر: وافر تام","title":"وفاتنة الحديث ، لها نكات","page":"","text":"وفاتنة الحديث ، لها نكات … تحول بسحرها دون المرام\nشكوت لها ضنى جسدي ، فقالت … بطرفي ما بجسمك من سقام\nفقلت : عدي بوصل منك صبا … برته يد الصبابة والغرام\nفقالت : سوف تلقاني قريبا … فقلت : متى ؟ فقالت : في المنام"},{"id":"diwan-barudi:62","bookId":"diwan-barudi","type":"poem","seq":62,"chapter":"البحر: خفيف تام","title":"لا تعاشر ما عشت أحمق ، واعلم","page":"","text":"لا تعاشر ما عشت أحمق ، واعلم … أنه في الوجود حي كميت\nليس بين الجنون والحمق إلا … مثل ما بين أدهم وكميت"},{"id":"diwan-barudi:63","bookId":"diwan-barudi","type":"poem","seq":63,"chapter":"البحر: مجتث","title":"ذنبي إليك غرامي","page":"","text":"ذنبي إليك غرامي … فعل يحل ملامي ؟\nيا ظالمي في هواه … هلا رعيت ذمامي\nحتام تعرض عني … ولا ترد سلامي\nعطفا علي ؛ فإني … برى هواك عظامي\nفكيف تنكر وجدي ؟ … أما رأيت سقامي ؟\nويلاه مما ألاقي … من لوعتي وهيامي\nرق النسيم لحالي … وسال دمع الغمام\nوساعدتني ، فناحت … علي ورق الحمام\nفيا سمير فؤادي … في يقظتي ومنامي\nمتى يفوز بوصل … أسير لحظك ( سامي )"},{"id":"diwan-barudi:64","bookId":"diwan-barudi","type":"poem","seq":64,"chapter":"البحر: طويل","title":"رأيت بصحراء القرافة نسوة","page":"","text":"رأيت بصحراء القرافة نسوة … نوازع ، لا يأوين حزنا إلى بيت\nينحن على ميت سيتبعن إثره … ومن عجب ميت ينوح على ميت"},{"id":"diwan-barudi:65","bookId":"diwan-barudi","type":"poem","seq":65,"chapter":"البحر: بسيط تام","title":"قالت أراك عليل الجسم ، قلت لها","page":"","text":"قالت أراك عليل الجسم ، قلت لها … من شفه الحب أبلى جسمه السقم\nقالت : فهل من دواء يستطب به … قلت : الوصال ، فراحت وهيتبتسم\nفبت في حيرة ، لا القلب مصطبر … والوصول إلى ما يشتهي أمم\nومن أطاع هواه غير مكترث … بما يكون ، فعقبي أمره ندم"},{"id":"diwan-barudi:66","bookId":"diwan-barudi","type":"poem","seq":66,"chapter":"البحر: مجزوء الرمل","title":"كل حى سيموت","page":"","text":"كل حى سيموت … ليس في الدنيا ثبوت\nحركات سوف تفنى … ثم يتلوها خفوت\nوكلام ليس يحلو … بعده إلا السكوت\nأيها السادر قل لى … أين ذاك الجبروت ؟\nكنت مطبوعا على النط … ق ، فما هذا الصموت ؟\nليت شعرى ، أهمود … ما أراه ، أم قنوت ؟\nأين أملاك لهم في … كل أفق ملكوت\nزالت التيجان عنهم … وخلت تلك التخوت\nأصبحت أوطانهم من … بعدهم وهي خبوت\nلا سميع يفقه القو … ل ، ولا حي يصوت\nعمرت منهم قبور … وخلت منهم بيوت\nلم تذد عنهم نحوس الد … هر إذ حانت بخوت\nخمدت تلك المساعي … وانقضت تلك النعوت\nإنما الدنيا خيال … باطل سوف يفوت\nليس للإنسان فيها … غير تقوى الله قوت"},{"id":"diwan-barudi:67","bookId":"diwan-barudi","type":"poem","seq":67,"chapter":"البحر: طويل","title":"ألا ، لا تلم صبا على طول سقمه","page":"","text":"ألا ، لا تلم صبا على طول سقمه … ودعه ، فليس الأمر فيه لحكمه\nفليس الهوى مما يرد بحيلة … ولكنه يثني الفتى دون عزمه\nوما يستوي جان أتى الإثم طائعا … وآخر لم يقرفه إلا برغمه\nإذا ما أقر المرء يوما بذنبه … فماذا الذي تغنى لجاجة خصمه ؟"},{"id":"diwan-barudi:68","bookId":"diwan-barudi","type":"poem","seq":68,"chapter":"البحر: طويل","title":"إلى الله أشكو أنني بين معشر","page":"","text":"إلى الله أشكو أنني بين معشر … سواء لديهم طيب وخبيث\nلهم ألسن إن رمن أمرا بلغنه … من النفس ، مصنوع لهن حديث\nترث على قرب الوداد عهودهم … وكيف يدوم الشيء وهو رثيث ؟\nفليس لهم في سالف الدهر محتد … قديم ، ولا في المكرمات حديث\nبرمت بهم حتى سئمت مكانتى … وأنكرت طيب العيش وهو دميث\nإذا لم يغثنى الله منهم بفضله … فما لي بين العالمين مغيث"},{"id":"diwan-barudi:69","bookId":"diwan-barudi","type":"poem","seq":69,"chapter":"البحر: طويل","title":"منحتك ألقاب العلا ، فادعني باسمي","page":"","text":"منحتك ألقاب العلا ، فادعني باسمي … فما تخفض الألقاب حرا ، ولا تسمى\nإذا كان عقبان الجديد إلى بلى … فلا فرق ما بين الحديث ولا الرسم\nتأمل إلى الدنيا بعين بصيرة … لعلك ترضى بالقليل من القسم\nفما العيش إلا خطرة عرضية … تزول كما زال الحثيث من النسم\nوهل نحن إلا مثل من كان قبلنا ؟ … فسوف تعاني الجدب يا راعي الوسمي\nلعمري لنعم المرء من بات راضيا … بما خصه من فيضه سابق الرسم\nتفلسف قوم في المقال ، وما دروا … جريرة ما أبقوا على الدهر من وسم\nولو راجعوا هذي النفوس لعالجوا … بترك الخطايا معضل الداء بالحسم\nفدع هذه الدنيا وإن هي أقبلت … عليك بإيماض البشاشة والبسم\nفلو جرب الإنسان أخلاق دهره … لأمسك باليأس المريح عن العسم\nفمن لي برأي صادق أقتفي به … مدارج قوم أدركوا الأمر بالقسم\nبرتني تباريح الحياة ، فلم تدع … لدي سوى روح تردد في جسم\nيقولون ' محمود ' ، ويا ليت أنني … كما زعموا ، أوليت لي طائعا كاسمي"},{"id":"diwan-barudi:70","bookId":"diwan-barudi","type":"poem","seq":70,"chapter":"البحر: خفيف تام","title":"آه من غربة وفقد حبيب","page":"","text":"آه من غربة وفقد حبيب … أورثا مهجتي عذابا مكيثا\nلا تسلنى عما أقاسى ، فإنى … بين قوم لا يفقهون حديثا"},{"id":"diwan-barudi:71","bookId":"diwan-barudi","type":"poem","seq":71,"chapter":"البحر: كامل تام","title":"قالوا : ألا تصف الغرام لنا","page":"","text":"قالوا : ألا تصف الغرام لنا … حتى يحيط بنعته الفهم ؟\nفأجبتهم : هيهات أنعت ما … يعتل دون صفاته الوهم\nالحب ينفذ بالفؤاد كما … يمضي على غلوائه السهم\nيعنو لسورته المليك ، ولا … يقوى على صدماته الشهم"},{"id":"diwan-barudi:72","bookId":"diwan-barudi","type":"poem","seq":72,"chapter":"البحر: طويل","title":"ألا قل لقوم شامتين تربصوا","page":"","text":"ألا قل لقوم شامتين تربصوا … تهزم شر بالمنية كارث\nأرى ستر خطب قد ترفع وانبرت … تلوح لهم منه وجوه الحوادث"},{"id":"diwan-barudi:73","bookId":"diwan-barudi","type":"poem","seq":73,"chapter":"البحر: وافر تام","title":"أدرها قبل تغريد الحمامه","page":"","text":"أدرها قبل تغريد الحمامه … فما ينفى الهموم سوى المدامه\nمعتقة ، إذا سلكت ضميرا … محت عنه الكلالة والسآمه\nألم تر كيف أصبحت الغوادي … لها في كل ناحية علامه ؟\nفكم في الأرض من مجرى غدير … وكم في الجو من مسرى غمامه\nفبادر صفوة الأيام تغنم … لذاذتها ، ولا تخش الملامه\nولا تحزن على شيء تولى … فإن الحزن مقراض السلامه"},{"id":"diwan-barudi:74","bookId":"diwan-barudi","type":"poem","seq":74,"chapter":"البحر: بسيط تام","title":"يا صارم اللحظ من أغراك بالمهج","page":"","text":"يا صارم اللحظ من أغراك بالمهج … حتى فتكت بها ظلما بلا حرج\nما زال يخدع نفسي وهي لاهية … حتى أصاب سواد القلب بالدعج\nطرف ، لو ان الظبا كانت كلحظته … يوم الكريهة ، ما أبقت على ودج\nأوحى إلى القلب ، فانقادت أزمته … طوعا إليه ، وخلاني ولم يعج\nفكيف لى بتلافيه ؟ وقد علقت … به حبائل ذاك الشادن الغنج\nكادت تذيب فؤادي نار لوعته … لو لم أكن من مسيل الدمع في لجج\nلولا الفواتن من غزلان ( كاظمة ) ما كان للحب سلطان على المهج ) 8 ( فهل إلى صلة من غادر عدة … تشفي تباريح قلب بالفراق شج\nأبيت أرعى نجوم الليل فى ظلم … يخشى الضلالة فيها كل مدلج\nكأن أنجمه والجو معتكر … غيد بأخبية ينظرن من فرج\nليل غياهبه حيرى ، وأنجمه … حسرى ، وساعاته في الطول كالحجج\nكأنما الصبح خاف الليل حين رأى … ظلماءه ذات أسداد ، فلم يلج\nفليت من لامني لانت شكيمته … فكف عني فضول المنطق السمج\nيظن بى سفها أنى على سرف … ولا يكاد يرى ما فيه من عوج\nفاعدل عن اللوم إن كنت امرأ فطنا … فاللوم في الحب معدود من الهوج\nهيهات يسلك لوم العاذلين إلى … قلب بحب رسول الله ممتزج\nهو النبي الذي لولا هدايته … لكان أعلم من في الأرض كالهمج\nأنا الذى بت من وجدى بروضته … أحن شوقا كطير البانة الهزج\nهاجت بذكراه نفسي ، فاكتست ولها … وأى صب بذكر الشوق لم يهج ؟\nفما احتيالي ؟ ونفسي غير صابرة … على البعاد ، وهمى غير منفرج\nلا أستطيع براحا إن هممت ، ولا … أقوى على دفع ما بالنفس من حوج\nلو كان للمرء حكم في تنقله … ما كان إلا إلى مغناه منعرجى\nفهل إلى صلة الآمال من سبب ؟ … أم هل إلى ضيقة الأحزان من فرج ؟\nيا رب بالمصطفى هب لى - وإن عظمت … جرائمي رحمة تغني عن الحجج\nولا تكلنى إلى نفسى فإن يدى … مغلولة ، وصباحى غير منبلج\nما لي سواك ، وأنت المستعان إذا … ضاق الزحام غداة الموقف الحرج\nلم يبق لي أمل إلا إليك ، فلا … تقطع رجائي ، فقد أشفقت من حرجي"},{"id":"diwan-barudi:75","bookId":"diwan-barudi","type":"poem","seq":75,"chapter":"البحر: طويل","title":"متى ينقضي عمر الحياة ؛ فتنقضي","page":"","text":"متى ينقضي عمر الحياة ؛ فتنقضي … مآرب كانت علة للمظالم\nتساوت نفوس الخلق في الشر ؛ فاستعذ … برب البرايا من جهول وعالم\nولو عرفوا ما أنكروه لأيقنوا … بأن نعيم الدهر خدعة حالم\nتأمل رويدا يا بن ودي ، هل ترى … على صفحات الأرض غير معالم ؟\nيظن عليل القوم في الطب برأه … ولم يدر أن الطب ليس بسالم\nفطر للسها ، أو فاتخذ لك سلما … لترقى إلى أبراجه بالسلالم\nوكيف تنال النفس في الدهر عيشة … تلذ بها ، والدهر غير مسالم ؟"},{"id":"diwan-barudi:76","bookId":"diwan-barudi","type":"poem","seq":76,"chapter":"البحر: بسيط تام","title":"أبعد ستين لى حاج فأطلبها ؟","page":"","text":"أبعد ستين لى حاج فأطلبها ؟ … هيهات ، ما لامرىء بعد الصبا حاج\nإن ابن آدم في الدنيا على خطر … لا يستقيم له قصد ومنهاج\nكأنما هو فى فلك تحيط به … من جانبيه أعاصير وأمواج\nيهوى البقاء ، ومكروه الفناء به … ويستعز بأمن فيه إزعاج\nلا أحفل الطير إن غنت ، وإن نعبت … سيان عندي صفار وشحاج\nيستعظمون من الحجاج صولته … وكل قوم بهم للظلم حجاج"},{"id":"diwan-barudi:77","bookId":"diwan-barudi","type":"poem","seq":77,"chapter":"البحر: طويل","title":"خليلي ! ، ما في الدهر أطول حسرة","page":"","text":"خليلي ! ، ما في الدهر أطول حسرة … من المرء يلقى فرصة فيخيم\nوإن امرأ يلقى فواضل نعمة … بأرض ، وينوي غيرها لمليم"},{"id":"diwan-barudi:78","bookId":"diwan-barudi","type":"poem","seq":78,"chapter":"البحر: طويل","title":"هنيئا لريا ما تضم الجوانح","page":"","text":"هنيئا لريا ما تضم الجوانح … وإن طوحت بى فى هواها الطوائح\nفتاة لها في منصب الحسن سورة … تقصر عنها الغيد وهى رواجح\nأحاط على مثل الكثيب إزارها … ودارت على مثل القناة الوشائح\nففى الغصن منها إن تثنت مشابه … وفى البدر منها إن تجلت ملامح\nمحاسن ربات الحجال كثيرة … ولكنها إن وازنتها مقابح\nكأن اهتزاز القرط فى صفح جيدها … سنا كوكب فى مطلع الفجر لائح\nلها ذكرة عندي وطيف ، كلاهما … بتمثالها غاد علي ورائح\nعجبت لعيني كيف تظمأ دونها … وإنسانها فى لجة الماء سابح\nأحن لها شوقا ، ودون مزارها … مسالك يأويها الردى ومنادح\nفياف يضل النجم فى قذفاتها … وتظلع فيها النائجات البوارح\nولجة بحر كلما هب عاصف … من الريح ، دوى موجها المتناطح\nفقلبى تحت السرد كالنار لافح … ودمعي فوق الخد كالماء سافح\nولو كنت مطلوق العنان لما ثنت … هواى الفيافى والبحارالطوافح\nولكنني في جحفل ليس دونه … براح لذي عذر ، ولا عنه بارح\nيكافحنى شوقى إذا الليل جننى … وأغدو على جمع العدا فأكافح\nخصيمان : هذا بالفؤاد مخيم … وذلك عن مرمى القذيفة نازح\nوما بي ما أخشاه من صولة العدا … لو ان الهوى يولي يدا ، أو يسامح\nفيا ( روضة المقياس ) حياك عارض … من المزن خفاق الجناحين دالح\nضحوك ثنايا البرق ، تجري عيونه … بودق به تحيا الربى والصحاصح\nتحوك بخيط المزن منه يد الصبا … لها حلة تختال فيها الأباطح\nمنازل حل الدهر فيها تمائمى … وصافحنى فيها القنا والصفائح\nوإن أحق الأرض بالشكر منزل … يكون به للمرء خل مناصح\nفهل ترجع الأيام فيه بما مضت … ويجري بوصل من ( أميمة سانح ؟ )4\nلعمرى لقد طال النوى ، وتقاذفت … مهامه دون الملتقى ومطاوح\nوأصبحت في أرض يحار بها القطا … وترهبها الجنان وهى سوارح\nبعيدة أقطار الدياميم ، لو عدا ( سليك ) بها شأوا قضى وهو رازح )7 ( تصيح بها الأصداء فى غسق الدجى … صياح الثكالى هيجتها النوائح\nتردت بسمور الغمام جبالها … وماجت بتيار السيول البطائح\nفأنجادها للكاسرات معاقل … وأغوارها للعاسلات مسارح\nمهالك ينسى المرء فيها خليله … وينذر عن سوم العلا من ينافح\nفلا جو إلا سمهري وقاضب … ولا أرض إلا شمرى وسابح\nترانا بها كالأسد نرصد غارة … يطير بها فتق من الصبح لامح\nمدافعنا نصب العدا ، ومشاتنا … قيام ، تليها الصافنات القوارح\nثلاثة أصناف تقيهن ساقة … صيال العدا إن صاح بالشر صائح\nفلست ترى إلا كماة بواسلا … وجردا تخوض الموت وهي ضوابح\nنغير على الأبطال والصبح باسم … ونأوى إلى الأدغال والليل جانح\nبكى صاحبي لما رأى الحرب أقبلت … بأبنائها ، واليوم أغبر كالح\nولم يك مبكاه لخوف ، وإنما … توهم أني في الكريهة طائح\nفقال اتئد قبل الصيال ، ولاتكن … لنفسك حربا ، إننى لك ناصح\nألم تر معقود الدخان ، كأنما … على عاتق الجوزاء منه سرائح ؟\nوقد نشأت للحرب مزنة قسطل … لها مستهل بالمنية راشح\nفلا رأى إلا أن تكون بنجوة … فإنك مقصود المكانة واضح\nفقلت تعلم أنما هى خطة … يطول بها مجد ، وتخشى فضائح\nفما كل ما ترجو من الأمر ناجع … ولا كل ما تخشى من الخطب فادح\nفقد يهلك الرعديد فى عقر داره … وينجو من الحتف الكمي المشايح\nوكل امرئ يوما ملاق حمامه … وإن عار فى أرسانه وهو جامح\nفما بارح إلا مع الخير سانح … ولا سانح إلا مع الشر بارح\nفإن عشت صافحت الثريا ، وإن أمت … فأن كريما من تضم الصفائح"},{"id":"diwan-barudi:79","bookId":"diwan-barudi","type":"poem","seq":79,"chapter":"البحر: طويل","title":"أخو العلم في الدنيا لذي الجهل محوج","page":"","text":"أخو العلم في الدنيا لذي الجهل محوج … وكل له عند القياس معالم\nفلولا وجود العلم ما عاش جاهل … ولولا وجود الجهل ما عاش عالم"},{"id":"diwan-barudi:80","bookId":"diwan-barudi","type":"poem","seq":80,"chapter":"البحر: بسيط تام","title":"ماذا على قرة العينين لو صفحت","page":"","text":"ماذا على قرة العينين لو صفحت … وعاودت بوصال بعد ما صفحت\nبايعتها القلب إيجابا بما وعدت … فيالها صفقة فى الحب ما ربحت\nقد يزعم الناس أن البخل مقطعة … فما لقلبى يهواها وماسمحت ؟\nخوطية القد ، لو مر الحمام بها … لم يشتبه أنها من أيكه انتزحت\nخفت معاطفها ، لكن روادفها … بمثل ما حملتني في الهوى رجحت\nويلاه من لحظها الفتاك إن نظرت … وآه من قدها العسال إن سنحت\nيموت قلبي ويحيا حيرة وهدى … في عالم الوجد إن صدت وإن جنحت\nكالبدر إن سفرت ، والظبي إن نظرت … والغصن إن خطرت ، والزهر إن نفحت\nواخجلة البدر إن لاحت أسرتها … وحيرة الرشإ الوسنان إن لمحت\nلها روابط لا تنفك آخذة … بعروة القلب إن جدت ، وإن مزحت\nيا سرحة الأمل الممنوع جانبه … ويا غزالة وادي الحسن إن سرحت\nترفقى بفؤاد أنت منيته … ومقلة لسوى مرآك ما طمحت\nحاشاك أن تسمعى قول الوشاة بنا … فإنها ربما غشت إذا نصحت\nأفسدت في حبكم نفسى جوى وأسى … والنفس فى الحب مهما أفسدت صلحت\nما زلت أسحرها بالشعر تسمعه … من ذات فهم ، تجيد القول إن شرحت\nحتى إذا علمت ما حل بى ، ورأت … سقمي ، وخافت على نفس بها افتضحت\nحنت رثت عطفت مالت صبت عزمت … همت سرت وصلت عادت دنت منحت\nفبت فى وصلها فى نعمة عظمت … ما شئت ، أو جنة أبوابها فتحت\nأنال من ثغرها الدرى ما سألت … نفسي ، ومن خدها الوردي ما اقترحت\nفي روضة بسمت أزهارها ، ونمت … أفنانها ، وسجت أظلالها ، وضحت\nتكللت بجمان القطر ، واتزرت … بسندس النبت والريحان ، واتشحت\nترنح الغصن من أشواقه طربا … لما رأى الطير فى أوكارها صدحت\nصح النسيم بها وهو العليل ، وقد … مالت بخمر الندى أغصانها ، وصحت\nوليلة سال في أعقابها شفق … كأنها بحسام الفجر قد ذبحت\nطالت ، وقصرها لهوي بغانية … إن أعرضت قتلت ، أو أقبلت فضحت\nهيفاء ، إن نطقت غنت ، وإن خطرت … رنت ، وإن فوقت ألحاظها جرحت\nدارت علينا بها الكاسات مترعة … بخمرة لو بدت فى ظلمة قدحت\nحمراء سلسلها الإبريق في قدح … كشعلة لفحت في ثلجة نصحت\nروح إذا سلكت في هامد نبضت … عروقه ، أو دنت من صخرة رشحت\nطارت بألبابنا سكرا ، ولا عجب … وهى الكميت إذا فى حلبة جمحت\nحتى بدا الفجر من أطراف ظلمتها … كغرة فى جواد أدهم وضحت\nفيا لها ليلة ما كان أحسنها … لو أنها لبثت حولا وما برحت"},{"id":"diwan-barudi:81","bookId":"diwan-barudi","type":"poem","seq":81,"chapter":"البحر: مجزوء الرمل","title":"أنا في الحب وفي","page":"","text":"أنا في الحب وفي … ليس لي بالغدر علم\nلا تظنوا بي سوءا … إن بعض الظن إثم"},{"id":"diwan-barudi:82","bookId":"diwan-barudi","type":"poem","seq":82,"chapter":"البحر: مجزوء المتدارك","title":"املإ القدح","page":"","text":"املإ القدح … واعص من نصح\nوارو غلتى … بابنة الفرح\nفالفتى متى … ذاقها انشرح\nوهي إن سرت … فى العليل صح\nأو صبا بها … باخل سمح\nهجر الكرى … واغد نصطبح\nفالدجى مضى … والسنا لمح\nوالحمام فى … أيكه صدح\n … حيثما سرح\nواصطحب بمن … يبعث المرح\nفيه للمنى … كل مقترح\nواحذر الذي … إن وعى سبح\nكلما رأى … فرصة قدح\nليس من أسا … مثل من جرح\nأين من رأى … فاسدا صلح ؟\nكل من وشى … سوف يفتضح\nفاترك الأذى … فالأذى ترح\nواسع للعلا … من سعى نجح\nوارع ما حوت … هذه الملح"},{"id":"diwan-barudi:83","bookId":"diwan-barudi","type":"poem","seq":83,"chapter":"البحر: بسيط تام","title":"وليلة بيضاء الكأس لامعة","page":"","text":"وليلة بيضاء الكأس لامعة … أدركت باللهو فيها كل مقترح\nأحييتها بعد ما نام الخلي بها … بغادة لو رأتها الشمس لم تلح\nفلو تأملتني والكأس دائرة … لخلتنى ملكا يختال من مرح\nوكيف لا تبلغ الأفلاك منزلتي … والبدر فى مجلسى والشمس فى قدحى"},{"id":"diwan-barudi:84","bookId":"diwan-barudi","type":"poem","seq":84,"chapter":"البحر: طويل","title":"إذا ما كتمت الحب كان شرارة","page":"","text":"إذا ما كتمت الحب كان شرارة … وإن بحت بالكتمان كان ملاما\nفكيف احتيالي بين أمرين أشكلا … علي ، فصارا شقوة وغراما ؟"},{"id":"diwan-barudi:85","bookId":"diwan-barudi","type":"poem","seq":85,"chapter":"البحر: بسيط تام","title":"والوعة القلب من غزلان أخبية","page":"","text":"والوعة القلب من غزلان أخبية … تكاد تسكر من أحداقها الراح\nمن كل مائسة كالغصن قد جمعت … بدائعا ، كلها للحسن أوضاح\nفالعين نرجسة ، والشعر سوسنة … والنهد رمانة ، والخد تفاح"},{"id":"diwan-barudi:86","bookId":"diwan-barudi","type":"poem","seq":86,"chapter":"البحر: بسيط تام","title":"ما لي بودك بعد اليوم إلمام","page":"","text":"ما لي بودك بعد اليوم إلمام … فاذهب ؛ فأنت لئيم العهد نمام\nقد كنت أحسبني أدركت مأربة … من المنى ، فإذا ما خلت أحلام\nهيهات مني الرضا من بعد تجربة … إن المودة بين الناس أقسام\nفاطلب لنفسك غيري ؛ إنني رجل … يأبى لي الغدر أخوال وأعمام\nكل امرئ تابع أعراق نبعته … والخير والشر أنساب وأرحام\nفانظر لفعل الفتى تعرف مناسبه … إن الفعال لأصل المرء إعلام\nولا يغرنك وجه راق منظره … فالنصل فيه المنايا وهو بسام\nما كل ذي منسر فتخاء كاسرة … كلا ، ولا كل ذي نابين ضرغام\nفإن يكن غرني حلمي فلا عجب … إن الحسام لينبو وهو صمصام\nظننت خيرا ، ولم أدرك عواقبه … فكان شرا . وبعض الظن آثام\nفيا لها ضلة ! ما إن أبهت لها … حتى تردت بها في الشر أقدام\nآليت أكذب نفسي بعدها سفها … إن المنى عند صدق النفس أوهام\nفيا بن تزدريه النفس من ضعة … فما يحس له وجد وإعدام\nدع الفخار ، وخذ فيما خلقت له … من الصغار ؛ فإن الطبع إلزام\nواذكر مكانك من ' عباس ' حيث مضت … عليك في الدار أعوام وأعوام\nتبيت مرتفعا في ظل دسكرة … لكل باغ بها وجد وتهيام\nوفوق ظهرك للأنفاس معترك … وفي حشاك لنار الفسق إضرام\nويلمها خزية طارت بشنعتها … صحائف ، وجرت بالذم أقلام\nفاخسأ ؛ فما الكلب أدنى منك منزلة … و( اخسأ لمثلك إعزاز وإكرام )0\nهذا الذي تكره الأبصار طلعته … فحظها منه إيذاء وإيلام\nفي وجهه سمة للغدر بينة … وبين جنبيه أحقاد وأوغام\nله على الشر إقدام ، وليس له … إلا عن الخير والمعروف إحجام\nكأنما أنفه من طول سجدته … في حانة اللهو حرف فيه إدغام\nكعقرب الماء يمشي مشية صددا … فخلفه عند جد الأمر إقدام\nأبدى بعاتقه المنديل سيمته … وحت موضعه من كفه الجام\nوكيف يصلح أمر الناس في بلد … حكامه لبنات اللهو خدام ؟\nقد يممته المخازي ؛ فهي نازلة … منه بحيث تلاقي اللؤم والذام\nما إن أصبت له خلقا ، فأحمده … فكل أخلاقه للنفس آلام\nفظ ، غليظ ، مقيت ، ساقط ، وجم … وغد ، لئيم ، ثقيل الظل ، حجام\nجاءت به عجز ليست بطاهرة … لها بمدرجة الفحشاء أزلام\nمستيقظ للمخازي ، غير أن له … طرفا عن العرض والأوتار نوام\nأستغفر الله إلا من عداوته … فإنها لجلال الله إعظام\nفاذهب كما ذهب الطاعون من بلد … تقفوه باللعن أرواح وأجسام\nوهاك ما أنت أهل في الهجاء له … فالهجو فيك لنقض الحق إبرام\nمن كل قافية في الأرض سائرة … لها بعرضك إنجاد وإتهام\nشعر لوجه المخازي منه سافية … يحاصب ، ولأنف الجهل إرغام\nتبلى العظام ، ويبقى ذكره أبدا … في كل عصر له سجع وترنام"},{"id":"diwan-barudi:87","bookId":"diwan-barudi","type":"poem","seq":87,"chapter":"البحر: طويل","title":"ألا يا حمام الأيك إلفك حاضر","page":"","text":"ألا يا حمام الأيك إلفك حاضر … وغصنك مياد ، ففيم تنوح ؟\nغدوت سليما في نعيم وغبطة … ولكن قلبي بالغرام جريح\nفإن كنت لى عونا على الشوق فاستعر … لعينيك دمعا ، فالبكاء مريح\nوإلا فدعنى من هديلك ، وانصرف … فليس سواء باذل وشحيح"},{"id":"diwan-barudi:88","bookId":"diwan-barudi","type":"poem","seq":88,"chapter":"البحر: وافر تام","title":"هجوتك غير مبتدع مقالا","page":"","text":"هجوتك غير مبتدع مقالا … سوى ما فيك من دنس وشؤم\nفإن تجزع فمن خور وجبن … وإن تصبر فمن ضعة ولؤم"},{"id":"diwan-barudi:89","bookId":"diwan-barudi","type":"poem","seq":89,"chapter":"البحر: رجز تام","title":"سارية خفاقة الجناح","page":"","text":"سارية خفاقة الجناح … تواصل الغدو بالرواح\nتبيت في مهد من البطاح … باكية بمدمع سفاح\nضحاكة كثيرة النواح … منشورة فى الأفق كالوشاح\nتحملها كواهل الرياح … "},{"id":"diwan-barudi:90","bookId":"diwan-barudi","type":"poem","seq":90,"chapter":"البحر: متقارب تام","title":"ألا ، من معيني على صاحب","page":"","text":"ألا ، من معيني على صاحب … جرعت بصحبته العلقما ؟\nيسوء الخليل ، ويؤذي الجلي … س ، ويأنف إن زل أن يندما\nيلوم على غير ذنب جرى … ويغضب من قبل أن يفهما\nفإن قلت : ( مهلا ) لوى شدقه … وإن لم أجب قوله برطما\nله جهلات تميت الرضا … وحمق يكاد يسيل الدما\nيكابر في الحق إن مضه … ولا يدع الظن أو يأثما\nفلا أنا منه أرى راحة … ولا أنا عنه أرى منسما\nتبدل أنسي به وحشة … وعاد نهاري به مظلما\nفلا رحم الله يوما جرى … علي به طائرا أشأما"},{"id":"diwan-barudi:91","bookId":"diwan-barudi","type":"poem","seq":91,"chapter":"البحر: سريع","title":"يا كوكب الصبح متى ينقضى","page":"","text":"يا كوكب الصبح متى ينقضى … عمر الدجى ؟ يا كوكب الصبح\nقد سد حصن الليل أبوابه … فاتل عليه سورة الفتح\nإني أرى أنجمه قد ونت … فما لها أيد على السبح\nوقد بدا ذو ذنب طالعا … كأنه سنبلة القمح"},{"id":"diwan-barudi:92","bookId":"diwan-barudi","type":"poem","seq":92,"chapter":"البحر: كامل تام","title":"كم غادر الشعراء من متردمكم غادر الشعراء من متردم","page":"","text":"كم غادر الشعراء من متردمكم غادر الشعراء من متردم … ولرب تال بذ شأو مقدم\nفي كل عصر عبقري ، لا يني … يفرى الفر بكل قول محكم\nوكفاك بي رجلا إذا اعتقل النهى … بالصمت ، أو رعف السنان بعندم\nأحييت أنفاس القريض بمنطقي … وصرعت فرسان العجاج بلهذمي\nوفرغت ناصية العلا بفضائل … هن الكواكب في النهار المظلم\nسل مصر عني إن جهلت مكانتي … تخبرك عن شرف وعز أقدم\nبله ، نشأت مع النبات بأرضها … ولثمت ثغر غديره المتبسم\nفنسيمها روحي ، ومعدن تربها … جسمي ، وكوثر نيلها محيا دمي\nفإذا نطقت فبالثناء على الذي … أولته من فضل علي وأنعم\nأهلي بها ، وأحبتي ، وكفى بهم … إن كانت الأبناء خور الأعظم\nوأحق دار بالكرامة منزل … للقلب فيه علاقة ق لم تصرم\nهي جنة الحسن التي زهراتها … حور المها ، وهزار أيكتها فمي\nما إن خلعت بها سيور تمائمي … حتى لبست بها حمائل مخذمي\nوغنيت عن قلتي بعامل أسمر … وسلوت عن مهدي بصهوة أدهم\nوفجرت ينبوع البيان بمنطق … عذب ، رويت به غليل الحرم\nولكم أثرت غيابة من قسطل … بمهندي ، وحللت عقدة مبرم\nأختال طورا فوق ذروة منبر … وأكر طورا فوق نهد شيظم\nحتى ربأت من المعالي هضبة … شماء تزلق أخمص المتسنم\nنشأت بطبعي للقريض بدائع … ليست بنحلة شاعر متقدم\nيصبو بها ' الحكمي ' صبوة عاشق … وتخف من طرب عريكة ' مسلم '\nقومته بعد اعوجاج قناته … والرمح ليس يروق غير مقوم\nفقر يكاد السحر يبلغ بعض ما … في طيها لو كان غير محرم\nمتشابه الطرفين ، ينبىء صدره … عما تلاحق ؛ فهو بادي المعلم\nأحكمت منطقه بلهجة مفلق … يقظ البديهة ، في القريض محكم\nيبتذ أهبة كل فارس بهمة … ويزم شقشقة الفتيق المقرم\nذللت منه غواربا لا تمتطى … وخطمت منه موارنا لم تخطم\nشعر جمعت به ضروب محاسن … لم تجتمع قبلي لحي ملهم\nفإذا نسبت فتنت كل مقنع … وإذا نأمت ذعرت كل ملثم\nكالروض تسمع منه نغمة بلبل … والغيل تسمع منه زأرة ضيغم\nأدركت قاصية المحامد والعلا … وشأوت فيها كل أصيد مسنم\nفأنا ابن نفسي إن فخرت ، وإن أكن … لأغرمن سلف الأكارم أنتمى\nوالفخر بالآباء ليس بنافع … \nهذا ، وربت لذة باشرتها … في ظل أخضر بالعرار منمنم\nطفق النسيم يحوك بروده … بأنامل تمرى خيوط المرزم\nفبكل أفق مزنة فياضة … وبكل أرض جدول كالأرقم\nهاتيك تجري في السماء كأنها … سفن ، وهذا في الخمائل يرتمي\nفالروض بين موشح ومؤزر … والزهر بين مدنر ومدرهم\nطلق الجبين ، تبسمت أزهاره … عن در قطر كالعقود منظم\nعبق الإزار ، كأنما جرت الصبا … فيه بجؤنة عنبر لم تختم\nصبح الغمام غصونه ؛ فترنحت … طربا لرجع الطائر المترنم\nفنسيمه أرج ، وطائر أيكه … هزج ، وجدوله برود المبسم\nيستوقف الألباب حسن روائه … ويصيد عين الناظر المتوسم\nوالمرء طوع يد الزمان ، يقوده … قود الجنيب لغاية لم تعلم\nفلك يدور ، وأنجم لا تأتلي … تبدو وتغرب في فضاء أقتم\nصور إذا ناديتها لم تستجب … أو رمت منها النطق لم تتكلم\nفدع الخفي ، وخذ لنفسك حظها … مما بدا لك ؛ فهو أهنأ مغنم\nلا يستطيع المرء يبلغ ما نأى … عنه ، ولو صعد السماء بسلم\nبينا يشق به الجواء ترفعا … أهوى به في كسر بيت مظلم\nإن الحياة شهية ما لم تكن … غرضا لإمرة ظالم لم يرحم\nلا أرتضي عيش الجبان ، ولا أرى … فضلا لذي حسب إذا لم يقدم\nولرب ملحمة سريت قناعها … عن وجه نصر بالغبار ملثم\nلو كان للإنسان علم بالذي … في الغيب لم يفرح ، ولم يتندم\nفدع الأمور إلى مدبر شأنها … وارغب عن الدنيا بنفسك تسلم"},{"id":"diwan-barudi:93","bookId":"diwan-barudi","type":"poem","seq":93,"chapter":"البحر: وافر تام","title":"بلغت مداك من أرب فسيحي","page":"","text":"بلغت مداك من أرب فسيحي … فأنت اليوم فى جو فسيح\nتركت الجسم فيما كان منه … وغبت بلجة لون المسيح\nفعادت صورة الجثمان عطلا … لفقدك مثل دينار مسيح\nولو يقوى لسار ، وكيف يقوى … على هول السرى قدم الكسيح ؟\nسبحت بغمرة كالشمس نورا … وعام من الخجالة في مسيح\nفليتك ترجعين لنا بصدق … يباغت كل ختال مسيح\nبربك هل وجدت كما وجدنا … خلافا بين أحمد والمسيح ؟"},{"id":"diwan-barudi:94","bookId":"diwan-barudi","type":"poem","seq":94,"chapter":"البحر: طويل","title":"بأي غزال في الخدور تهيم","page":"","text":"بأي غزال في الخدور تهيم … وغزلان ' نجد ' ما لهن حميم ؟\nيقدن زمام النفس وهي أبية … ويخدعن لب المرء وهو حكيم\nفإياك أن تغشى الديار مخاطرا … فدون حماها للأسود نئيم\nفوارس لا يعصون أمر حمية … ولا يرهبون الخطب وهو عظيم\nيصونون في حجب الأكلة ظبية … لها نسب بين الحسان صميم\nمن الهيف ، أما نعت ما في إزارها … فراب ، وأما خصرها فهضيم\nأناة براها الله في الحسن آية … يدين إليها جاهل وحليم\nيميل بها سكر الشباب إذا مشت … كما مال بالغصن الروي نسيم\nلعمرك ما أدري ، أدمية بيعة … تردد فيها الحسن ، أم هي ريم ؟\nيلومونني أن همت وجدا بحسنها … وأي امرىء بالحسن ليس يهيم ؟\nوهل يغلب المرء الهوى وهو غالب … ويخفي شكاة القلب وهو كليم ؟\nفإن أك محسورا بها ، فلربما … ملكت عنان القلب وهو كظيم\nوكابدت فيها ما لو انقض بعضه … على جبل لانهال منه قويم\nفيا ربة البيت المنيع جواره … أما من مسام عندكم فأسيم ؟\nبخلت علينا بالسلام ضنانة … وجدك مطروق الفناء كريم\nفكيف تلوميني على ما أصابني … من الحب يا ( ليلى وأنت غريم ؟ )7\nوقد عشت دهرا لا أدين لظالم … ولم يحتكم يوما علي زعيم\nفأنت التي مرهت عيني بالبكا … وأسقمت هذا القلب وهو سليم\nتنامين عن ليلي ، وعيني قريحة … وتشجين قلبي ، وهو فيك مليم\nمنحتك نفسي ، وهي نفس عزيزة … علي ، وما لي من هواك قسيم\nفإن يك جسمي عن فنائك راحل … فإن هوى قلبي عليك مقيم\nشكوت إلى من ليس يرحم باكيا … وما كل من يشكى إليه رحيم\nفحتام ألقى في الهوى ما يسوءني … وأحمل عبء الصبر وهو عظيم\nوإني لحر بين قومي ، وإنما … تعبدني حلو الدلال رخيم\nوإني وإن كنت المسالم في الهوى … لذو تدرإ في النائبات خصيم\nأفل شباة الخصم وهو منازل … وأرهب كر الطرف وهو سقيم\nألا ، قاتل الله الهوى ، ما ألذه ! … على أنه مر المذاق أليم\nطويت له نفسي على ما يسوءها … وأصبحت لا يلوي علي حميم\nفمن لي بقلب غير هذا ؟ فإنني … به عند روعات الفراق عليم\nكأني أداري منه بين جوانحي … لظى ، حرها يكوي الحشا ، ويضيم\nبلوت له طعمين : أما مذاقه … فعذب ، وأما سؤره فوخيم\nوجربت إخوان الصفاء ، فلم أجد … صديقا له في الطيبات قسيم\nلهم نزوات بينهن تفاوت … وعن على طول اللقاء ذميم\nبمن يثق الإنسان والغدر شيمة … لكل ابن أنثى ، والوفاء عقيم ؟\nفلا تعتمد إلا على الله في الذي … تود من الحاجات ؛ فهو رحيم\nولا تبتئس من محنة ساقها القضا … إليك ، فكم بؤس تلاه نعيم\nفقد تورق الأشجار بعد ذبولها … ويخضر ساق النبت وهو هشيم\nإذا ما أراد الله إتمام حاجة … أتتك على وشك وأنت مقيم"},{"id":"diwan-barudi:95","bookId":"diwan-barudi","type":"poem","seq":95,"chapter":"البحر: خفيف تام","title":"هو ماقلت فاحذرنها صباحا","page":"","text":"هو ماقلت فاحذرنها صباحا … غارة تملأ الفضاء رماحا\nتترك الماء لا يسوغ لظام … وترد الدم الحرام مباحا\nلا ترى بينها سوى عبقرى … يألف الطعن نجدة وارتياحا\nلهج بالحروب ، لا يألف الخف … ض ، ولا يصحب الفتاة الرداحا\nمسعر للوغى ، أخو غدوات … تجعل الأرض مأتما وصياحا\nلا يرى عاتبا على شيم الده … ر ، ولا عابثا ، ولا مزاحا\nيفعل الفعلة التي تبهر النا … س ، وترنو لها العيون طماحا\nلا كمن يسأل الوفود عن الأن … باء عجزا ، ويرقب الأشباحا\nفاعتبر أيها المجاهر بالقو … ل ، ولا تبعثن عليك نواحا\nإن في بردتي هاتين ليثا … يقص القرن ، أو يفل السلاحا\nسدكات بالرمح منه بنان … تملأ الأرض والسماء جراحا\nأنا من معشر كرام على الده … ر أفادوه عزة وصلاحا\nفرعوا بالقنا قنان المعالى … وأعدوا لبابها مفتاحا\nعمروا الأرض مدة ثم زالوا … مثلما زالت القرون اجتياحا\nوأتت بعدهم على ليال … لاأرى فى سمائها مصباحا\nفسقاهم منزل الغيث سجلا … يجعل النبت للعراء وشاحا"},{"id":"diwan-barudi:96","bookId":"diwan-barudi","type":"poem","seq":96,"chapter":"البحر: بسيط تام","title":"سبقت بالفضل ؛ فاسمع ما وحاه فمي","page":"","text":"سبقت بالفضل ؛ فاسمع ما وحاه فمي … فأنت أولى بهذا الدر من كلمي\nيا رائد الود ! قد صادفت منتجعا … بين الجوانح ؛ فانزله ، ولا ترم\nأوليتني منك فضلا قد ملكت به … قلبي ، فهاك يدي في الود ، فاحتكم\nإن المودة إن صحت غدت نسبا … بين الأباعد تغنيهم عن الرحم\nفثق بذمة عهد فيك صادقة … فليس كل خليل صادق الذمم\nواعذر إذا لم أجد في القول متسعا … فالمرء لا يبلغ الأفلاك بالهمم\nلا زلت ترفل في أثواب عافية … موشية بطراز الحمد والنعم"},{"id":"diwan-barudi:97","bookId":"diwan-barudi","type":"poem","seq":97,"chapter":"البحر: كامل تام","title":"أبنى الكنانة أبشروا بمحمد","page":"","text":"أبنى الكنانة أبشروا بمحمد … وثقوا براع فى المكارم أوحد\nفهو الزعيم لكم بكل فضيلة … تبقى مآثرها ، وعيش أرغد\nملك نمته أرومة علوية … ملكت بسؤددها عنان الفرقد\nيقظ البصيرة لو سرت في عينه … سنة الرقاد ، فقلبه لم يرقد\nبدهاته قيد الصواب ، وعزمه … شرك الفوارس فى العجاج الأربد\nفإذا تنمر فهو , , زيد ، ، فى الوغى … وإذا تكلم فهو ( قيس في الندي )\nمتقسم ما بين حنكة أشيب … صدقت مخيلته ، وحلية أمرد\nلا يستريح إلى الفراغ ، ولا يرى … عيشا يلذ به إذا لم يجهد\nفنهاره غيث اللهيف ، وليله … في طاعة الرحمن ليل العبد\nلهج بحب الصالحات ، فكلما … بلغ النهاية من صنيع يبتدي\nخلق تميز عن سواه بفضله … والفضل في الأخلاق إرث المحتد\nإقليد معضلة ، ومعقل عائذ … وسماء منتجع ، وقبلة مهتد\nحسنت به الأيام حتى أسفرت … عن وجه معشوق الشمائل أغيد\nوصفت موارد مصر حتى أصبحت … بعد الكدورة شرعة للورد\nفالعدل يرعاها برأفة والد … والبأس يحميها بصولة أصيد\nبلغت بفضل ( محمد ) ما أملت … من عيشة رغد وجد أسعد\nهو ذلك الملك الذي أوصافه … فى الشعر حلية راجز ومقصد\nفبنوره فى كل جنح نهتدى … وبهديه في كل خطب نفتدي\nسن المشورة ، وهى أكرم خطة … يجرى عليها كل راع مرشد\nهي عصمة الدين التي أوحى بها … رب العباد إلى النبي ( محمد )\nفمن استعان بها تأيد ملكه … ومن استهان بأمرها لم يرشد\nأمران ما اجتمعا لقائد أمة … إلا جنى بهما ثمار السؤدد\nجمع يكون الأمر فيما بينهم … شورى ، وجند للعدو بمرصد\nهيهات يحيا الملك دون مشورة … ويعز ركن المجد ما لم يعمد\nفالسيف لا يمضي بدون روية … والرأي لا يمضي بغير مهند\nفاعكف على الشورى تجد فى طيها … من بينات الحكم مالم يوجد\nلا غرو أن أبصرت في صفحاتها … صور الحوادث ، فهي مرآة الغد\nفالعقل كالمنظار يبصر ما نأى … عنه قريبا ، دون لمس باليد\nوكفاك علمك بالأمور ، وليس من … سلك السبيل كحائر لم يهتد\nفلأنت أول من أفاد بعدله … حرية الأخلاق بعد تعبد\nأطلقت كل مقيد ، وحللت ك … ل معقد ، وجمعت كل مبدد\nوتمتعت بالعدل منك رعية … كانت فريسة كل باغ معتد\nفاسلم لخير ولا ية عزت بها … نفس النصيح ، وذل كل مفند\nضرحت قذاة الغي عن جفن الهدى … وسرت قناع اليأس عن أمل ند\nضمت إليك زمام كل مثلث … وثنت إليك عنان كل موحد\nوتألفت بعد العداوة أنفس … سكنت بعدلك في نعيم سرمد\nفحباك ربك بالجميل كرامة … لجزيل ما أوليت أمة ( أحمد )8\nوتهن بالملك الذي ألبسته … شرفا بمثل ردائه لم يرتد\nبزغت به شمس الهداية بعد ما … أفلت ، وأبصر كل طرف أرمد\nلم يبق من ذى خلة إلا اغتدى … بجميل صنعك مصدرا للوفد\nبلغت بك الآمال أبعد غاية … قصرت على الإغضاء طرف الحسد\nفاسعد ودم واغنم وجد وانعم وسد … وابدأ وعد وتهن واسلم وازدد\nلا زال عدلك فى الأنام مخلدا … فالعدل في الأيام خير مخلد"},{"id":"diwan-barudi:98","bookId":"diwan-barudi","type":"poem","seq":98,"chapter":"البحر: كامل تام","title":"خل العتاب ؛ فلو طلبت مهذبا","page":"","text":"خل العتاب ؛ فلو طلبت مهذبا … أعياك مطلبه بهذا العالم\nإن كان لي ذنب إليك جرى به … قدر ؛ فإني من سلالة آدم"},{"id":"diwan-barudi:99","bookId":"diwan-barudi","type":"poem","seq":99,"chapter":"البحر: طويل","title":"رضيت من الدنيا بما لا أوده","page":"","text":"رضيت من الدنيا بما لا أوده … وأي امرىء يقوى على الدهر زنده ؟\nأحاول وصلا والصدود خصيمه … وأبغي وفاء والطبيعة ضده\nحسبت الهوى سهلا ، ولم أدر أنه … أخو غدرات يتبع الهزل جده\nتخف له الأحلام وهى رزينة … ويعنو له من كل صعب أشده\nومن عجب أن الفتى وهو عاقل … يطيع الهوى فيما ينافيه رشده\nيفر من السلوان ، وهو يريحه … ويأوى إلى الأشجان ، وهى تكده\nوما الحب إلا حاكم غير عادل … إذا رام أمرا لم يجد من يصده\nله من لفيف الغيد جيش ملاحة … تغير على مثوى الضمائر جنده\nذوابله قاماته ، وسيوفه … لحاظ العذارى ، والقلائد سرده\nإذا ماج بالهيف الحسان ، تأرجت … مسالكه ، واشتق فى الجو نده\nفأي فؤاد لا تذوب حصاته … غراما ، وطرف ليس يقذيه سهده ؟\nبلوت الهوى حتى اعترفت بكل ما … جهلت ، فلا يغررك فالصاب شهده\nظلوم له في كل حي جريرة … يضج لها غور الفضاء ونجده\nإذا احتل قلبا مطمئنا تحركت … وساوسه في الصدر ، واختل وكده\nفإن كنت ذا لب فلا تقربنه … فغير بعيد أن يصيبك حده\nوقد كنت أولى بالنصيحة لو صغا … فؤادى ، ولكن خالف الحزم قصده\nإذا لم يكن للمرء عقل يقوده … فيوشك أن يلقى حساما يقده\nلعمرى لقد ولى الشباب ، وحل بى … من الشيب خطب لا يطاق مرده\nفأي نعيم في الزمان أرومه ؟ … وأى خليل للوفاء أعده ؟\nوكيف ألوم الناس فى الغدر بعدما … رأيت شبابى قد تغيرعهده ؟\nوأبعد مفقود شباب رمت به … صروف الليالى عند من لا يرده\nفمن لي بخل صادق أستعينه … على أملى ، أو ناصر أستمده ؟\nصحبت بنى الدنيا طويلا فلم أجد … خليلا ، فهل من صاحب أستجده\nفأكثر من لاقيت لم يصف قلبه … وأصدق من واليت لم يغن وده\nأطالب أيامى بما ليس عندها … ومن طلب المعدوم أعياه وجده\nفما كل حي ينصر القول فعله … ولا كل خل يصدق النفس وعده\nوأصعب ما يلقى الفتى فى زمانه … صحابة من يشفي من الداء فقده\nوللنجح أسباب إذا لم يفز بها … لبيب من الفتيان لم يور زنده\nولكن إذا لم يسعد المرء جده … على سعيه لم يبلغ السؤل جده\nوما أنا بالمغلوب دون مرامه … ولكنه قد يخذل المرء جهده\nوما أبت بالحرمان إلا لأننى ( أود من الأيام ما لا توده ) )( فإن يك فارقت الرضا فلبعدما … صحبت زمانا يغضب الحر عبده\nأبى الدهر إلا أن يسود وضيعه … ويملك أعناق المطالب وغده\nتداعت لدرك الثأر فينا ثعاله … ونامت على طول الوتيرة أسده\nفحتام نسري في دياجير محنة … يضيق بها عن صحبة السيف غمده\nإذا المرء لم يدفع يد الجور إن سطت … عليه ، فلا يأسف إذا ضاع مجده\nومن ذل خوف الموت ، كانت حياته … أضر عليه من حمام يؤده\nوأقتل داء رؤية العين ظالما … يسيء ، ويتلى في المحافل حمده\nعلام يعيش المرء فى الدهر خاملا ؟ … أيفرح فى الدنيا بيوم يعده ؟\nيرى الضيم يغشاه فيلتذ وقعه … كذي جرب يلتذ بالحك جلده\nإذا المرء لاقى السيل ثمت لم يعج … إلى وزر يحميه أرداه مده\nعفاء على الدنيا إذا المرء لم يعش … بها بطلا يحمي الحقيقة شده\nمن العار أن يرضى الفتى بمذلة … وفى السيف ما يكفى لأمر يعده\nوإنى امرؤ لا أستكين لصولة … وإن شد ساقى دون مسعاى قده\nأبت لي حمل الضيم نفس أبية … وقلب إذا سيم الأذى شب وقده\nنمانى إلى العلياء فرع تأثلت … أرومته في المجد ، وافتر سعده\nوحسب الفتى مجدا إذا طالب العلا … بما كان أوصاه أبوه وجده\nإذا ولد المولود منا فدره … دم الصيد ، والجرد العناجيج مهده\nفإن عاش فالبيد الدياميم داره … وإن مات فالطير الأضاميم لحده\nأصد عن المرمى القريب ترفعا … وأطلب أمرا يعجز الطير بعده\nولا بد من يوم تلاعب بالقنا … أسود الوغى فيه ، وتمرح جرده\nيمزق أستار النواظر برقه … ويقرع أصداف المسامع رعده\nتدبر أحكام الطعان كهوله … وتملك تصريف الأعنة مرده\nقلوب الرجال المستبدة أكله … وفيض الدماء المستهلة ورده\nأحمل صدر النصل فيه سريرة … تعد لأمر لا يحاول رده\nفإما حياة مثل ما تشتهى العلا … وإما ردى يشفى من الداء وفده"},{"id":"diwan-barudi:100","bookId":"diwan-barudi","type":"poem","seq":100,"chapter":"البحر: طويل","title":"سكوتي إذا دام الحديث كلام","page":"","text":"سكوتي إذا دام الحديث كلام … وتقليب عيني في الوجوه ملام\nوصبري على الأيام لا من مذلة … ولكن يد مغلولة وحسام\nألام على أني صبرت ، وهل فتى … على الصبر إن قل المعين يلام ؟"},{"id":"diwan-barudi:101","bookId":"diwan-barudi","type":"poem","seq":101,"chapter":"البحر: كامل تام","title":"ظن الظنون فبات غير موسد","page":"","text":"ظن الظنون فبات غير موسد … حيران يكلأ مستنير الفرقد\nتلوي به الذكرات حتى إنه … ليظل ملقى بين أيدي العود\nطورا يهم بأن يزل بنفسه … سرفا ، وتارات يميل على اليد\nفكأنما افترست بطائر حلمه … مشمولة ، أوساغ سم الأسود\nقالوا غدا يوم الرحيل ، ومن لهم … خوف التفرق أن أعيش إلى غد ؟\nهى مهجة ذهب الهوى بشغافها … معمودة ، إن لم تمت فكأن قد\nيأهل ذا البيت الرفيع مناره … أدعوكم يا قوم دعوة مقصد\nإني فقدت اليوم بين بيوتكم … عقلي ، فردوه علي لأهتدي\nأو فاستقيدونى ببعض قيانكم … حتى ترد إلي نفسي ، أو تدي\nبل يا أخا السيف الطويل نجاده … إن أنت لم تحم النزيل فأغمد\nهذي لحاظ الغيد بين شعابكم … فتكت بنا خلسا بغير مهند\nمن كل ناعمة الصبا بدوية … ريا الشباب سليمة المتجرد\nهيفاء إن خطرت سبت ، وإذا رنت … سلبت فؤاد العابد المتشدد\nيخفضن من أبصارهن تختلا … للنفس ، فعل القانتات العبد\nفإذا أصبن أخا الشباب سلبنه … ورمين مهجته بطرف أصيد\nوإذا لمحن أخا المشيب قلينه … وسترن ضاحية المحاسن باليد\nفلئن غدوت دريئة لعيونها … فلقد أفل زعارة المتمرد\nولقد شهدت الحرب فى إبانها … ولبئس راعي الحي إن لم أشهد\nتتقصف المران فى حجراتها … ويعود فيها السيف مثل الأدرد\nعصفت بها ريح الردى ، فتدفقت … بدم الفوارس كالأتي المزبد\nما زلت أطعن بينها حتى انثنت … عن مثل حاشية الرداء المجسد\nولقد هبطت الغيث يلمع نوره … فى كل وضاح الأسرة أغيد\nتجرى به الآرام بين مناهل … طابت مواردها ، وظل أبرد\nبمضمر أرن كأن سراته … بعد الحميم سبيكة من عسجد\nخلصت له اليمنى ، وعم ثلاثة … منه البياض إلى وظيف أجرد\nفكأنما انتزع الأصيل رداءه … سلبا ، وخاض من الضحى في مورد\nزجل يردد في اللهاة صهيله … رفعا كزمزمة الحبي المرعد\nمتلفتا عن جانبيه ، يهزه … مرح الصبا كالشارب المتغرد\nفإذا ثنيت له العنان وجدته … يمطو كسيد الردهة المتورد\nوإذا أطعت له العنان رأيته … يطوي المهامه فدفدا في فدفد\nيكفيك منه إذا أحس بنبأة … شد كمعمعة الأباء الموقد\nصلب السنابك لا يمر بجلمد … فى الشد إلا رض فيه بجلمد\nنعم العتاد إذا الشفاه تقلصت … يوم الكريهة فى العجاج الأربد\nولقد شربت الخمر بين غطارف … شم المعاطس كالغصون الميد\nيتلاعبون على الكئوس إذا جرت … لعبا يروح الجد فيه ويغتدي\nلا ينطقون بغير ما أمر الهوى … فكلامهم كالروض مصقول ندى\nمن كل وضاح الجبين كأنه … قمر توسط جنح ليل أسود\nبل رب غانية طرقت خباءها … والنجم يطرف عن لواحظ أرمد\nقالت وقد نظرت إلي : فضحتني … فارجع لشأنك فالرجال بمرصد\nفمسحتها حتى اطمأن فؤادها … ونفيت روعتها برأي محصد\nوخرجت أخترق الصفوف من العدا … متلثما والسيف يلمع فى يدى\nفلنعم ذاك العيش لو لم ينقض … ولنعم هذا العيش إن لم ينفد\nيرجو الفتى فى الدهر طول حياته … ونعيمه ، والمرء غير مخلد"},{"id":"diwan-barudi:102","bookId":"diwan-barudi","type":"poem","seq":102,"chapter":"البحر: مجزوء الكامل","title":"يا بانة ! من لي بضمك ؟","page":"","text":"يا بانة ! من لي بضمك ؟ … يا زهرة ! من لي بشمك ؟\nيا بنت سيدة النسا … ء ! ترفقي بحياة أمك\nما في منبت شعرة … إلا به أثر لسهمك\nكلا ، ولا في مهجتي … من طول صدك غير همك\nأصبحت ممتنع الكرى … لما جفاني بدر تمك\nإن لم تجودي باللقا … ء المحب ، ولا بلثمك\nفتسامحي لي مرة … حتى أفوز بلثم كمك"},{"id":"diwan-barudi:103","bookId":"diwan-barudi","type":"poem","seq":103,"chapter":"البحر: طويل","title":"سرى البرق مصريا فأرقني وحدي","page":"","text":"سرى البرق مصريا فأرقني وحدي … وأذكرني ما لست أنساه من عهد\nفيا برق حدثنى ، وأنت مصدق … عن الآل والأصحاب ما فعلوا بعدي\nوعن روضة المقياس تجرى خلالها … جداول يسديها الغمام بما يسدي\nإذا صافحتها الريح رهوا تجعدت … حبائكها مثل المقدرة السرد\nوإن ضاحكتها الشمس رفت ، كأنها … مناضل سلت للضراب من الغمد\nنعمت بها دهرا ، وما كل نعمة … حبتك بها الأيام إلا إلى الرد\nفوا أسفا إذ ليس يجدي تأسف … على ما طواه الدهر من عيشنا الرغد\nإذ الدهر سمح ، والليالى سميعة … و' لمياء ' لم تخلف بليانها وعدى\nفتاة تريك الشمس تحت خمارها … إذا سفرت ، والغصن في معقد البند\nمن الفاتنات الغيد ، لو مر ظلها … على قانت دبت به سورة الوجد\nفتالله أنسى عهدها ما ترنمت … بنات الضحى بين الأراكة والرند\nحلفت بما وارى الخمار من الحيا … وما ضمت الأردان من حسب عد\nوباللؤلؤ المنضود بين يواقت … هي الشهد ظنا ، بل ألذ من الشهد\nيمينا لو استسقيت أرضا به الحيا … لخاض بها الرعيان فى كلأ جعد\nلأنت وأي الناس أنت ؟ حبيبة … إلى ولو عذبت قلبى بالصد\nإليك سلبت العين طيب منامها … وفيك رعيت النجم في أفقه وحدي\nوذللت هذى النفس بعد إبائها … ولولاك لم تسمح بحل ولا عقد\nفحتام تجزيني بودي جفوة ؟ … أما ترهبين الله في حرمة المجد ؟\nسلى عنى الليل الطويل ، فإنه … خبير بما أخفيه شوقا ، وما أبدي\nهل اكتحلت عيناى إلا بمدمع … إذا ذكرتك النفس سال على خدي ؟\nأصبر عنك النفس وهي أبية … وهيهات صبر الظامئات عن الورد\nكأني ألاقي من هواك ابن خيسة … أخا فتكات ، لا ينهنه بالرد\nتنكب ممساه ، وأخطأ صيده … فأقعى على غيظ من الجوع والكد\nله نعرات بالفلاة كأنها … على عدواء الدار جلجلة الرعد\nيمزق أستار الظلام بأعين … تطير شرارا كالسقاط من الزند\nكأنهما ماويتان أديرتا … إلى الشمس ، فانبثا شعاعا من الوقد\nفهذا الذى ألقاه منك على النوى … فراخي وثاقي يابنة القوم ، أو شدي"},{"id":"diwan-barudi:104","bookId":"diwan-barudi","type":"poem","seq":104,"chapter":"البحر: طويل","title":"دع الهزل ، واحذر ترهات المنادمه","page":"","text":"دع الهزل ، واحذر ترهات المنادمه … فكم من غوي قد أسال المنى دمه\nفمه ، لا تفه ، بالقول قبل انتقاده … فرب كلام فض من قائل فمه"},{"id":"diwan-barudi:105","bookId":"diwan-barudi","type":"poem","seq":105,"chapter":"البحر: طويل","title":"هو البين حتى لاسلام ولا رد","page":"","text":"هو البين حتى لاسلام ولا رد … ولا نظرة يقضى بها حقه الوجد\nلقد نعب الوابور بالبين بينهم … فساروا ، ولازموا جمالا ، ولا شدوا\nسرى بهم سير الغمام ، كأنما … له في تنائى كل ذى خلة قصد\nفلا عين إلا وهى عين من البكى … ولا خد إلا للدموع به خد\nفيا سعد ، حدثني بأخبار من مضى … فأنت خبير بالأحاديث يا سعد\nلعل حديث الشوق يطفئ لوعة … من الوجد ، أو يقضي بصاحبه الفقد\nهو النار في الأحشاء ، لكن لوقعها … على كبدى مما ألذ به برد\nلعمر المغانى وهى عندى عزيزة … بساكنها ما شاقني بعدها عهد\nلكانت وفيها ما ترى عين ناظر … وأمست وما فيها لغير الأسى وفد\nخلاء من الألاف إلاعصابة … حداهم إلى عرفانها أمل فرد\nدعتهم إليها نفحة عنبرية … وبالنفحة الحسناء قد يعرف الورد\nوقفنا فسلمنا ، فردت بألسن … صوامت ، إلا أنها ألسن لد\nفمن مقلة عبرى ، ومن لفح زفرة … لها شرر بين الحشا ما له زند\nفيا قلب صبرا إن ألم بك النوى … فكل فراق أو تلاق له حد\nفقد يشعب الإلفان أدناهما الهوى … ويلتئم الضدان أقصاهما الحقد\nعلى هذه تجري الليالي بحكمها … فآونة قرب ، وآونة بعد\nوما كنت لولا الحب أخضع للتي … تسئ ، ولكن الفتى للهوى عبد\nفعودي صلب لا يلين لغامز … وقلبي سيف لا يفل له حد\nإباء كما شاء الفخار وصبوة … يذل لها فى خيسه الأسد الورد\nوإنا أناس ليس فينا معابة … سوى أن وادينا بحكم الهوى نجد\nنلين - وإن كنا أشداء - للهوى … ونغضب في شروى نقير فنشتد\nوحسبك منا شيمة عربية … هي الخمر ما لم يأت من دونها حرد\nوبى ظمأ لم يبلغ الماء ريه … وفى النفس أمر ليس يدركه الجهد\nأود وما ود امرىء نافعا له … وإن كان ذا عقل إذا لم يكن جد\nوما بي من فقر لدنيا ، وإنما … طلاب العلا مجد ، وإن كان لي مجد\nوكم من يد لله عندي ونعمة … يعض عليها كفه الحاسد الوغد\nأنا المرء لا يطغيه عز لثروة … أصاب ، ولا يلوي بأخلاقه الكد\nأصد عن الموفور يدركه الخنا … وأقنع بالميسور يعقبه الحمد\nومن كان ذا نفس كنفسي تصدعت … لعزته الدنيا ، وذلت له الأسد\nومن شيمى حب الوفاء سجية … وما خير قلب لا يدوم له عهد ؟\nولكن إخوانا بمصر ورفقة … نسونا ، فلا عهد لديهم ، ولا وعد\nأحن لهم شوقا ، على أن دوننا … مهامه تعيا دون أقربها الربد\nفيا ساكني الفسطاط ! ما بال كتبنا … ثوت عندكم شهرا وليس لها رد ؟\nأفى الحق أنا ذاكرون لعهدكم … وأنتم علينا ليس يعطفكم ود ؟\nفلا ضير ، إن الله يعقب عودة … يهون لها بعد المواصلة الصد\nجزى الله خيرا من جزاني بمثله … على شقة غزر الحياة بها ثمد\nأبيت لذكراكم بها متململا … كأني سليم ، أو مشت نحوه الورد\nفلا تحسبونى غافلا عن ودادكم … رويدا ، فما فى مهجتى حجر صلد\nهو الحب لا يثنيه نأي ، وربما … تأرج من مس الضرام له الند\nنأت بي عنكم غربة وتجهمت … بوجهي أيام خلائقها نكد\nأدور بعينى لا أرى غير أمة … من الروس بالبلقان يخطئها العد\nجواث على هام الجبال لغارة … يطير بها ضوء الصباح إذا يبدو\nإذا نحن سرنا صرح الشر باسمه … وصاح القنا بالموت ، واستقتل\nفأنت ترى بين الفريقين كبة … يحدث فيها نفسه البطل الجعد\nعلى الأرض منها بالدماء جداول … وفوق سراة النجم من نقعها لبد\nإذا اشتبكوا ، أو راجعوا الزحف خلتهم … بحورا توالى بينها الجزر والمد\nنشلهم شل العطاش ونت بها … مراغمة السقيا ، وماطلها الورد\nفهم بين مقتول طريح ، وهارب … طليح ، ومأسور يجاذبه القد\nنروح إلى الشورى إذا أقبل الدجى … ونغدو عليهم بالمنايا إذا نغدو\nونقع كلج … ولا معقل إلا المناصل والجرد\nصبرت له والموت يحمر تارة … وينغل طورا في العجاج فيسود\nفما كنت إلا الليث أنهضه الطوى … وما كنت إلا السيف فارقه الغمد\nصئول وللأبطال همس من الونى … ضروب وقلب القرن فى صدره يعدو\nفما مهجة إلا ورمحي ضميرها … ولا لبة إلا وسيفي لها عقد\nوما كل ساع بالغ سؤل نفسه … ولا كل طلاب يصاحبه الرشد\nإذا القلب لم ينصرك في كل موطن … فما السيف إلا آلة حملها إد\nإذا كان عقبى كل شئ وإن زكا … فناء ، فمكروه الفناء هو الخلد\nوتخليد ذكر المرء بعد وفاته … حياة له ، لا موت يلحقها بعد\nففيم يخاف المرء سورة يومه … وفى غده ما ليس من وقعه بد\nليضن بي الحساد غيظا ، فإنني … لآنافهم رغم وأكبادهم وقد\nأنا القائل المحمود من غير سبة … ومن شيمة الفضل العداوة والضد\nفقد يحسد المرء ابنه وهو نفسه … ورب سوار ضاق عن حمله العضد\nفلا زلت محسودا على المجد والعلا … فليس بمحسود فتى وله ند"},{"id":"diwan-barudi:106","bookId":"diwan-barudi","type":"poem","seq":106,"chapter":"البحر: طويل","title":"أراك الحمى ! شوقي إليك شديد","page":"","text":"أراك الحمى ! شوقي إليك شديد … وصبرى ونومى فى هواك شريد\nمضى زمن لم يأتنى عنك قادم … ببشرى ، ولم يعطف على بريد\nوحيد من الخلان في أرض غربة … ألا كل من يبغي الوفاء وحيد\nفهل لغريب طوحته يد النوى … رجوع ؟ وهل للحائمات ورود ؟\nوهل زمن ولى ، وعيش تقيضت … غضارته بعد الذهاب يعود ؟\nأعلل نفسي بالقديم ، وإنما … يلذ اقتبال الشيء وهو جديد\nوما ذكرى الأيام إلا لأنها … ذمام لعرفان الصبا وعهود\nفليس بمفقود فتى ضمه الثرى … ولكن من غال البعاد فقيد\nألا أيها اليوم الذى لم أكن له … ذكورا ، سوى أن قيل لى هو عيد\nأتسألنا لبس الجديد سفاهة … وأثوابنا ما قد علمت حديد ؟\nفحظ أناس منه كأس وقينة … وحظ رجال ذكرة ونشيد\nليهن به من بات جذلان ناعما … أخا نشوات ما عليه حقود\nترى أهله مستبشرين بقربه … فهم حوله لا يبرحون شهود\nإذا سار عنهم سار وهو مكرم … وإن عاد فيهم عاد وهو سعيد\nيخاطب كلا بالذي هو أهله … فمبدئ شكر تارة ومعيد\nفمن لغريب ( سرنسوف ) مقامه … رمت شمله الأيام ، فهو لهيد\nبلاد بها ما بالجحيم ، وإنما … مكان اللظى ثلج بها وجليد\nتجمعت البلغار والروم بينها … وزاحمها التاتار ، فهي حشود\nإذا راطنوا بعضا سمعت لصوتهم … هديدا تكاد الأرض منه تميد\nقباح النواصي والوجوه ، كأنهم … لغير أبي هذا الأنام جنود\nسواسية ، ليسوا بنسل قبيلة … فتعرف آباء لهم وجدود\nلهم صور ليست وجوها ، وإنما … تناط إليها أعين وخدود\nيخورون حولي كالعجول ، وبعضهم … يهجن لحن القول حين يجيد\nأدور بعينى لا أرى بينهم فتى … يرود معى فى القول حيث أرود\nفلا أنا منهم مستفيد غريبة … ولا أنا فيهم ما أقمت مفيد\nفمن لي بأيام مضت قبل هذه … بمصر ؟ وعيشى لو يدوم حميد\nعسى الله يقضى قربة بعد غربة … فيفرح باللقيا أب ووليد"},{"id":"diwan-barudi:107","bookId":"diwan-barudi","type":"poem","seq":107,"chapter":"البحر: سريع","title":"الشعر زين المرء ما لم يكنالشعر زين المرء ما لم يكن","page":"","text":"الشعر زين المرء ما لم يكنالشعر زين المرء ما لم يكن … وسيلة للمدح والذام\nقد طالما عز به معشر … وربما أزرى بأقوام\nفاجعله فيما شئت من حكمة … أو عظة ، أو حسب نامي\nواهتف به من قبل إطلاقه … فالسهم منسوب إلى الرامي"},{"id":"diwan-barudi:108","bookId":"diwan-barudi","type":"poem","seq":108,"chapter":"البحر: طويل","title":"تولى الصبا عنى ، فكيف أعيده","page":"","text":"تولى الصبا عنى ، فكيف أعيده … وقد سار فى وادى الفناء بريده ؟\nأحاول منه رجعة بعد ما مضى … وذلك رأي غاب عني سديده\nفما كل جفر غاض يرتد نبعه … ولا كل ساق جف يخضر عوده\nفإن أك فارقت الشباب فقبله … بكيت رضاعا بان عنى حميده\nوأى شباب لا يزول نعيمه ؟ … وسربال عيش ليس يبلى جديده ؟\nفلا غرو إن شابت من الحزن لمتى … فإنى فى دهر يشيب وليده\nيهدم من أجسادنا ما يشيده … وينقص من أنفاسنا ما يزيده\nأرى كل شيء لا يدوم ، فما الذي … ينال امرؤ من حب ما لا يفيده ؟\nولكن نفسا ربما اهتاج شوقها … فحنت ، وقلبا ربما اعتاد عيده\nفوا حسرتا ! كم زفرة إثر لوعة … إذا عصفت بالقلب كادت تبيده\nأحن إلى وادي النقا ، ويسرني … على بعده أن تستهل سعوده\nوأصدقه ودى ، وإن كنت عالما … بأن النقا لم يدن منى بعيده\nمعان هوى تجرى بدمعى وهاده … وتشرق من نيران قلبى نجوده\nتضن بإهداء السلام ظباؤه … وتكرم مثوى الطارقين أسوده\nتساهم فيه البأس والحسن ، فاستوت … ضراغمه عند اللقاء وغيده\nتلاقت به أسيافه ولحاظه … ومالت به أرماحه وقدوده\nفكم من صريع لا تداوى جراحه … وكم من أسير لاتحل قيوده\nوفى الحى ظبى إن ترنمت باسمه … تنمر واشيه ، وهاج حسوده\nتهيم به أستاره وخدوره … وتعشقه أقراطه وعقوده\nتأنق فيه الحسن فامتد فرعه … إلى قدميه واستدارت نهوده\nفللمسك رياه ، وللبان قده … وللورد خداه ، وللظبي جيده\nفإياك أن تغتر يا صاح بالهوى … فإن الردى حلف الهوى وعقيده\nوما أنا ممن يرهب الموت إن سطا … إذا لم تكن نجل العيون شهوده\nأفل أنابيب القنا ، ويفلنى … قوام تندت بالعبير بروده\nفإن أنا سالمت الهوى فلطالما … شهدت الوغى والطعن يذكو وقوده\nوتحت جناح الدرع مني ابن فتكة … معودة ألا تحط لبوده\nإذا حركته همة نحو غاية … تسامى إليها في رعيل يقوده\nومعترك للخيل في جنباته … صهيل يهد الراسيات وئيده\nبعيد سماء النقع ، ينقض نسره … على جثث القتلى ، وينغل سيده\nترف على هام الكماة سيوفه … وتخفق بين الجحفلين بنوده\nإذا اشتجرت فيه الرماح تراجعت … سوافر عن نصر يضيء عموده\nتقحمته والرمح صديان ينتحي … نطاف الكلى ، والموت يمضى وعيده\nفما كنت إلا الغيث طارت بروقه … وما كنت إلا الرعد دوى هديده\nأنا الرجل المشفوع بالفعل قوله … إذا ما عقيد القوم رثت عقوده\nتعودت صدق القول حتى لو أننى … تكلفت قولا غيره لا أجيده\nأضاحك وجه المرء يغشاه بشره … وأعلم أن القلب تغلي حقوده\nومن لم يدار الناس عاداه صحبه … وأنكره من قومه من يسوده\nفمن لي بخل أستعين بقربه … على أمل لم يبق إلا شريده\nأحاول ودا لا يشان بغدرة … ودون الذي أرجوه ما لا أريده\nسمعت قديما بالوفاء فليتني … علمت على الأيام أين وجوده\nفإن أنا لم أملك صديقا فإننى … لنفسى صديق لا تخيس عهوده\nوحسب الفتى من رأيه خير صاحب … يوازره في كل خطب يئوده\nإذا لم يكن للمرء من بدهاته … نصير ، فأخلق أن تخيب جدوده\nوإنى وإن أصبحت فردا فإننى … بنفسى عشير ليس ينجو طريده\nولي من بديع الشعر ما لو تلوته … على جبل لانهال فى الدو ريده\nإذا اشتد أورى زندة الحرب لفظه … وإن رق أزرى بالعقود فريده\nيقطع أنفاس الرياح إذا سرى … ويسبق شأو النيرين قصيده\nإذا ما تلاه منشد في مقامة … كفى القوم ترجيع الغناء نشيده\nسيبقى به ذكرى على الدهر خالدا … وذكر الفتى بعد الممات خلوده"},{"id":"diwan-barudi:109","bookId":"diwan-barudi","type":"poem","seq":109,"chapter":"البحر: خفيف تام","title":"أيها الشاعر المجيد ! تدبر","page":"","text":"أيها الشاعر المجيد ! تدبر … واجعل القول منك ذا تحكيم\nلا تذم اللئيم ، ووامدح كريما … إن مدح الكريم ذم اللئيم"},{"id":"diwan-barudi:110","bookId":"diwan-barudi","type":"poem","seq":110,"chapter":"البحر: خفيف تام","title":"كرم الطبع شيمة الأمجاد","page":"","text":"كرم الطبع شيمة الأمجاد … وجفاء الأخلاق شأن الجماد\nلن يسود الفتى ولو ملك الحك … مة ما لم يكن من الأجواد\nولعمرى لرقة الطبع أولى … من عناد يجر حرب الفساد\nقد ينال الحليم بالرفق ما لي … س ينال الكمي يوم الجلاد\nفاقرن الحلم بالسماحة تبلغ … كل ما رمت نيله من مراد\nوضع البر حيث يزكو لتجني … ثمر الشكر من غراس الأيادي\nواحذر الناس ما استطعت فإن الن … اس أحلاس خدعة وتعادي\nرب خل تراه طلق المحيا … وهو جهم الضمير بالأحقاد\nفتأمل مواقع اللحظ تعلم … ما طوته صحائف الأكباد\nإن في العين وهو عضو صغير … لدليلا على خبايا الفؤاد\nوأناس صحبت منهم ذئابا … تحت أثواب ألفة ووداد\nيتمنون لى العثار ، ويلقو … نى بوجه إلى المودة صادى\nسابقونى فقصروا عن لحاقى … إنما السبق من خصال الجواد\nأنا ما بين نعمة وحسود … والمعالي كثيرة الحساد\nفليموتوا بغيظهم ، فاحتمال ال … غيظ موت لهم بلا ميعاد\nكيف تبيض من أناس وجوه … صبغ اللؤم عرضهم بسواد ؟\nأظهروا زخرف الخداع ، وأخفوا … ذات نفس كالجمر تحت الرماد\nفترى المرء منهم ضاحك الس … ن وفى ثوبه دماء العباد\nمعشر لا وليدهم طاهر المه … د ولا كهلهم عفيف الوساد\nتلك آثارهم تدل على ما … كان منهم من جفوة وتبادى\nليس من يطلب المعالى للفخ … ر كمن يطلب العلا للزاد\nوقليلا ما يصلح المرء للج … د إذا كان ساقط الأجداد\nفاعتصم بالنهى تفز بنعيم الد … هر غضا ، فالعقل خير عتاد\nإن في الحكمة البليغة للرو … ح غذاء كالطب للأجساد"},{"id":"diwan-barudi:111","bookId":"diwan-barudi","type":"poem","seq":111,"chapter":"البحر: بسيط تام","title":"في قائم السيف إن عز الرضا حكم","page":"","text":"في قائم السيف إن عز الرضا حكم … فالحكم للسيف إن لم تصدع الكلم\nتأبى لي الضيم نفس حرة ويد … أطاعها المرهفان : السيف والقلم\nوعزمة بعثتها همة شهرت … بها على الدهر عضبا ليس ينثلم\nوفتية كأسود الغاب ، ليس لهم … إلا الرماح إذا احمر الوغى أجم\nكالبرق إن عزموا ، والرعد إن صدموا … والغيث إن رحموا ، والسيل إن هجموا\nإن حاربوا معشرا في جحفل غلبوا … أو خاصموا فءة في محفل خصموا\nلا يرهبون المنايا أن تلم بهم … كأن لقى المنايا عندهم حرم\nمرفهون ، حسان في مجالسهم … وفي الحروب إذا لاقيتهم بهم\nمن كل أزهر ، كالدينار غرته … يجلو الكريهة منه كوكب ضرم\nلا يركنون إلى الدنيا وزينتها … إذا هم شعروا بالذل ، أو نقموا\nقد حبب الموت كره الضيم في نفر … لولاهم لم تدم في العالم النعم\nماتوا كراما ، وأبقوا للعلا أثرا … نالت به شرف الحرية الأمم\nفكيف يرضى الفتى بالذل يحمله … والذل تأنفه العبدان والخدم ؟\nإن لم يكن للفتى فضل ومحمية … فإن وجدانه في أهله عدم\nفالحلم ما لم يكن عن قدرة خور … والصبر في غير مرضاة العلا ندم\nفارغب بنفسك عن حال تضتام بها … فليس بعد اطراح الذل ما يصم\nولا تخف ورد موت أنت وارده … من أخطأته الرزايا غاله الهرم\nإن العلا أثر تحيا بذكرته … أسماء قوم طوى أحسابها القدم"},{"id":"diwan-barudi:112","bookId":"diwan-barudi","type":"poem","seq":112,"chapter":"البحر: كامل تام","title":"أيد المنون قدحت أى زناد","page":"","text":"أيد المنون قدحت أى زناد … وأطرت أى شعلة بفؤادى\nأوهنت عزمى وهو حملة فيلق … وحطمت عودى وهو رمح طراد\nلم أدر هل خطب ألم بساحتى … فأناخ ، أم سهم أصاب سوادي ؟\nأقذى العيون فأسبلت بمدامع … تجرى على الخدين كالفرصاد\nما كنت أحسبني أراع لحادث … حتى منيت به فأوهن آدى\nأبلتنى الحسرات حتى لم يكد … جسمي يلوح لأعين العواد\nأستنجد الزفرات وهي لوافح … وأسفه العبرات وهي بوادي\nلا لوعتى تدع الفؤاد ، ولا يدى … تقوى على رد الحبيب الغادى\nيا دهر ، فيم فجعتني بحليلة ؟ … كانت خلاصة عدتي وعتادي\nإن كنت لم ترحم ضناي لبعدها … أفلا رحمت من الأسى أولادى ؟\nأفردتهن فلم ينمن توجعا … قرحى العيون رواجف الأكباد\nألقين در عقودهن ، وصغن من … در الدموع قلائد الأجياد\nيبكين من وله فراق حفية … كانت لهن كثيرة الإسعاد\nفخدودهن من الدموع ندية … وقلوبهن من الهموم صوادى\nأسليلة القمرين ! أى فجيعة … حلت لفقدك بين هذا النادي ؟\nأعزز على بأن أراك رهينة … في جوف أغبر قاتم الأسداد !"},{"id":"diwan-barudi:113","bookId":"diwan-barudi","type":"poem","seq":113,"chapter":"البحر: طويل","title":"ألم يأن أن يرضى عن الدهر مغرم","page":"","text":"ألم يأن أن يرضى عن الدهر مغرم … أم العمر يفنى والمآرب تعدم ؟\nأحاول وصلا من حبيب ممنع … وبعض أماني النفس غيب مرجم\nوما كل من رام العظائم نالها … ولا كل من خاض الكريهة يغنم\nيسر الفتى من عشقه ما يسوؤه … وفي الراح لهو للنفوس ومغرم\nولو كان للإنسان علم يدله … على خافيات الغيب ما كان يندم\nكتمت الهوى خوف الوشاة ، فلم يزل … بي الدمع حتى بان ما كنت أكتم\nوكيف أداري النفس وهي مشوقة … وأحلم عنها والهوى ليس يحلم ؟\nوتحت جناح الليل مني ابن لوعة … يرق إليه الطائر المترنم\nإذا مد من أنفاسه لاح بارق … وإن حل من أجفانه فاض خضرم\nوإن التي يشتاقها القلب غادة … لها الرمح قد ، والمهند معصم\nينم بها صبح من البيض أزهر … ويكتمها نقع من الليل مظلم\nإذا راسلت كانت رسالة حبها … بضرب الظبا توحى ، وبالطعن تعجم\nلها من دماء الصيد في حومة الوغى … شراب ، ومن هام الفوارس مطعم\nفتلك التي لا وصلها متوقع … لدينا ، ولا سلوانها متصرم\nعلقت بها ، وهي المعالي ، وقلما … يهيم بها إلا الشجاع المصمم\nهوى ، ليس فيه للملامة مسلك … ولا لامرىء ناجى به النفس مأثم\nتلذ به الآلام وهي مبيرة … ويحلو به طعم الردى وهو علقم\nفمن يك بالبيض الكواعب مغرما … فإني بالبيض القواضب مغرم\nأسير وأنفاس العواصف ركد … وأسري وألحاظ الكواكب نوم\nوما بين سل السيف والموت فرجة … لدى الحرب إلا ريثما أتكلم\nأنا المرء لا يثنيه عما يرومه … نهيت العدا والشر عريان أشأم\nأغير على الأبطال والصبح أشهب … وآوي إلى الضيفان والليل أدهم\nويصحبني في كل روع ثلاثة : … حسام ، وطرف أعوجي ، ولهذم\nوينصرني في كل جمع ثلاثة : … لسان ، وبرهان ، ورأي محكم\nفما أنا بالمغمور إن عن حادث … ولا بالذي إن أشكل الأمر يفحم\nلساني كنصلي في المقال ، وصارمي … كغرب لساني حين لم يبق مقدم\nإذا صلت فدتني ' فراس ' بشيخها … وإن قلت حياني ' شبيب ' و' أكثم '\nفلا تحتقر فضل الكلام ؛ فإنه … من القول ما يبني المعالي ، ويهدم\nوما هو إلا جوهر الفضل والنهى … يسرد في سلك المقال ، وينظم\nفما كل من حاك القصائد شاعر … ولا كل من قال النسيب متيم\nفإن يك عصر القول ولى ، فإنني … بفضلي وإن كنت الأخير مقدم"},{"id":"diwan-barudi:114","bookId":"diwan-barudi","type":"poem","seq":114,"chapter":"البحر: منسرح","title":"كيف طوتك المنون يا ولدى ؟","page":"","text":"كيف طوتك المنون يا ولدى ؟ … وكيف أودعتك الثرى بيدى ؟\nواكبدي يا ( علي ) بعدك ! لو … كانت تبل الغليل ' واكبدى '\nفقدك سل العظام منى ، ور … د الصبر عنى ، وفت فى عضدى\nكم ليلة فيك لاصباح لها … سهرتها باكيا بلا مدد\nدمع وسهد ، وأى ناظرة … تبقى على المدمعين والسهد ؟\nلهفى على لمحة النجابة ! لو … دامت إلى أن تفوز بالسدد\nما كنت أدري إذ كنت أخشى علي … ك العين أن الحمام بالرصد\nفاجأني الدهر فيك من حيث لا … أعلم ختلا ، والدهر كالأسد\nلولا اتقاء الحياء لاعتضت بال … حلم هياما يحيق بالجلد\nلكن أبت نفسى الكريمة أن … أثلم حد العزاء بالكمد\nفليبك قلبى عليك ، فالعين لا … تبلغ بالدمع رتبة الخلد\nإن يك أخنى الردى عليك ؛ فقد … أخنى أليم الضنى على جسدى\nعليك مني السلام توديع لا … قال ، ولكن توديع مضطهد"},{"id":"diwan-barudi:115","bookId":"diwan-barudi","type":"poem","seq":115,"chapter":"البحر: سريع","title":"يا لك من ذي أدب ! أطلعت","page":"","text":"يا لك من ذي أدب ! أطلعت … فكرته ثاقبة الأنجم\nحاز مدى قصر عن شأوه … كل أخي سابقة مرجم\nفهو إذا قال علا ، أو جرى … برز ، أو ناضل لم يحجم\nذو فكرة فاضت بما أودعت … من حكمة ، كالعارض المثجم\nذاك فتى ، نبعته لم تلن … لعاجم من خور المعجم\nألفاظه تعزى إلى ' يعرب ' … وفكره مقتبس من ( جم )\nلم ينظم الحوسي عجبا به … ولم يسم الورد بالحوجم\nلكنه راز الحجا ، فاكتفى … بواضح القول عن المعجم\nدان له بالفضل عن خبرة … كل فصيح القول ، أو أعجم\nدل على معدنه فضله … دلالة التبر على المنجم"},{"id":"diwan-barudi:116","bookId":"diwan-barudi","type":"poem","seq":116,"chapter":"البحر: بسيط تام","title":"لا فارس اليوم يحمي السرح بالوادي","page":"","text":"لا فارس اليوم يحمي السرح بالوادي … طاح الردى بشهاب الحرب والنادي\nمات الذى ترهب الأقران صولته … ويتقي بأسه الضرغامة العادي\nهانت لميتته الدنيا ، وزهدنا … فرط الأسى بعده فى الماء والزاد\nهل للمكارم من يحيي مناسكها ؟ … أم للضلالة بعد اليوم من هادي ؟\nجف الندى ، وانقضى عمر الجدا ، وسرى … حكم الردى بين أرواح وأجساد\nفلتمرح الخيل لهوا في مقاودها … ولتصدإ البيض ملقاة بأغماد\nمضى ، وخلفني في سن سابعة … لا يرهب الخصم إبراقي وإرعادي\nإذا تلفت لم ألمح أخاثقة … يأوى إلى ولا يسعى لإنجادى\nفالعين ليس لها من دمعها وزر … والقلب ليس له من حزنه فادي\nفإن أكن عشت فردا بين آصرتى … فها أنا اليوم فرد بين أندادي\nبلغت من فضل ربى ما غنيت به … عن كل قار من الأملاك أو بادى\nفما مددت يدى إلا لمنح يد … ولا سعت قدمى إلا لإسعاد\nتبعت نهج أبى فضلا ومحمية … حتى برعت ، وكان الفضل للبادي\nأبى ، ومن كأبى فى الحى نعلمه ؟ … أوفى وأكرم في وعد وإيعاد\nمهذب النفس ، غراء شمائله … بعيد شأو العلا ، طلاع أنجاد\nقد كان لي وزرا آوي إليه إذا … غاض المعين ، وجف الزرع بالوادي\nلا يستبد برأى قبل تبصرة … ولا يهم بأمر قبل إعداد\nتراه ذا أهبة فى كل نائبة … كالليث مرتقبا صيدا بمرصاد"},{"id":"diwan-barudi:117","bookId":"diwan-barudi","type":"poem","seq":117,"chapter":"البحر: طويل","title":"وما مصر عمر الدهر إلا غنيمة","page":"","text":"وما مصر عمر الدهر إلا غنيمة … لمن حل مغناها ، ونهب مقسم\nتداولها الملاك من كل أمة … ونال بها حظا فصيح وأعجم\nفما أهلها إلا عبيد لمن سطا … ولا ريعها إلا لمن شاء مغنم\nعدادك في سلك البرية خزية … ودعواك حق الملك أدهى وأعظم\nلقد هانت الدنيا على الناس عندما … رأوك بها في ملك ( يوسف تحكم )\nفإن تك أولتك المقادير حكمها … فقد حازها من قبل عبد مزنم\nوشتان عبد بالمحجة ناطق … وحر إذا ناقشته القول أغتم\nفهذا أذل الملك وهو معزز … وذاك أعز الملك وهو مهضم\nفمن شك في حكم القضاء ، فهذه … جلية ما شاء القضاء المحتم"},{"id":"diwan-barudi:118","bookId":"diwan-barudi","type":"poem","seq":118,"chapter":"البحر: طويل","title":"ترحل من وادى الأراكة بالوجد","page":"","text":"ترحل من وادى الأراكة بالوجد … فبات سقيما لا يعيد ، ولا يبدي\nسقيما تظل العائدات حوانيا … عليه بإشفاق ، وإن كان لا يجدى\nيخلن به مسا أصاب فؤاده … وليس به مس سوى حرق الوجد\nبه علة إن لم تصبها سلامة … من الله كادت نفس حاملها تردي\nومن عجب الأيام أني مولع … بمن ليس يعنيه بكائي ولا سهدي\nأبيت عليلا في ( سرنديب ) ساهرا … أعالج ما ألقاه من لوعتي وحدي\nأدور بعينى لا أرى وجه صاحب … يريع لصوتي ، أو يرق لما أبدي\nومما شجانى بارق طار موهنا … كما طار منبث الشرار من الزند\nيمزق أستار الدجنة ضوء ه … فينسلها ما بين غور إلى نجد\nأرقت له ، والشهب حيرى كليلة … من السير ، والآفاق حالكة البرد\nفبت كأنى بين أنياب حية … من الرقط ، أو في برثنى أسد ورد\nأقلب طرفى ، والنجوم كأنها … قتير من الياقوت يلمع فى سرد\nولا صاحب غير الحسام منوطة … حمائله منى على عاتق صلد\nإذا حركته راحتى لملمة … تطلع نحوي يشرئب من الغمد\nأشد مضاء من فؤادي على العدا … وأبطأ في نصري على الشوق من ( فند )6\nأقول له والجفن يكسو نجاده … دموعا كمرفض الجمان من العقد\nلقد كنت لى عونا على الدهر مرة … فما لي أراك اليوم منثلم الحد ؟\nفقال إذا لم تستطع سورة الهوى … وأنت جليد القوم ، ما أنا بالجلد\nوهل أنا إلا شقة من حديدة … ألح عليها القين بالطرق والحد ؟\nفما كنت لولا أنني واهن القوى … أعلق فى خيط ، وأحبس في جلد\nفدونك غيرى ، فاستعنه على الجوى … ودعنى من الشكوى ، فداء الهوى يعدى\nخليلى ! هذا الشوق لا شك قاتلى … فميلا إلى ' المقياس ' إن خفتما فقدى\nففى ذلك الوادى الذى أنبت الهوى … شفائي من سقمي ، وبرئي من وجدي\nملاعب لهو ، طالما سرت بينها … على أثر اللذات فى عيشة رغد\nإذا ذكرتها النفس سالت من الأسى … مع الدمع ، حتى لا تنهنه بالرد\nفيا منزلا رقرقت ماء شبيبتي … بأفنائه بين الأراكة والرند !\nسرت سحرا فاستقبلتك يد الصبا … بأنفاسها ، وانشق فجرك بالحمد\nوزر عليك الأفق طوق غمامة … خضيبة كف البرق حنانة الرعد\nفلست بناس ليلة سلفت لنا … بواديه ، والدنيا تغر بما تسدي\nإذا العيش ريان الأماليد ، والهوى … جديد ، وإذ ( لمياء صافية الود )\nمنعمة ، للبدر ما فى قناعها … وللغصن ما دارت به عقدة البند\nسبتنى بعينها ، وقالت لتربها … ألا ما لهذا الغر يتبعني قصدي ؟\nولم تدر ذات الخال والحب فاضح … بأن الذى أخفيه غير الذى أبدى\nحنانيك ، إن الرأي حار دليله … فضل ، وعاد الهزل فيك إلى الجد\nفلا تسألي مني الزيادة في الهوى … رويدا ، فهذا الوجد آخر ما عندى\nوها أنا منقاد كما حكم الهوى … لأمرك ، فاخشى حرمة الله والمجد\nفلو قلت قم فاصعد إلى رأس شاهق … وألق إذا أشرفت نفسك للوهد\nلألقيتها طوعا ، لعلك بعدها … تقولين : حيا الله عهدك من عهد\nسجية نفس لا تخون خليلها … ولا تركب الأهوال إلا على عمد\nوإنى لمقدام على الهول والردى … بنفسى ، وفى الأقدام بالنفس ما يردى\nوإنى لقوال إذا التبس الهدى … وجارت حلوم القوم عن سنن القصد\nفإن صلت فدانى الكمى بنفسه … وإن قلت لبانى الوليد من المهد\nولي كل ملساء المتون غريبة … إذا أنشدت أفضت لذكر بني سعد\nأخف على الأسماع من نغم الحدا … وألطف عند النفس من زمن الورد\nمخدرة تمحو بأذيال حسنها … أساطير من قبلى ، وتعجز من بعدى\nكذلك إنى قائل ثم فاعل … فعالى ، وغيرى قد ينير ولا يسدى"},{"id":"diwan-barudi:119","bookId":"diwan-barudi","type":"poem","seq":119,"chapter":"البحر: كامل تام","title":"ردي الكرى لأراك في أحلامه","page":"","text":"ردي الكرى لأراك في أحلامه … إن كان وعدك لا يفي بذمامه\nأو فابعثي قلبي إلي ؛ فإنه … جارى هواك ، فقاده بزمامه\nقد كان خلفني لموعد ساعة … من يومه ، فقضى مسيرة عامه\nلم أدر : هل ثابت إليه أناته … أم لم يزل في غيه وهيامه\nعهدي به صعب القياد . فما له … ألقى يدا للسلم بعد غرامه\nخدعته ساحرة العيون بنظرة … منها ؛ فملكها عذار لجامه\nيا ، هل يعود إلى الجوانح بعدما … سلبت فتاة الحي ثني لجامه ؟\nتالله ، لو ملكت يداي جماحه … لعقدت قائم رسنه بخدامه\nيا لائم المشتاق في أطرابه … مهلا ، إليك ؛ فلست من لوامه\nأظننت لوعته فكاهة مازح … فطفقت تعذله على تهيامه ؟\nإن كنت تنكر شجوه ، فانظر إلى … أنفاسه ، ودموعه ، وسقامه\nصب ، برته يد الضنى ؛ حتى اختفى … عن أعين العواد غير كلامه\nنطقت مدامعه بسر ضميره … وذكت جوانحه بنار غرامه\nطورا يخامره الذهول ، وتارة … يبكي بكاء الطفل عند فطامه\nيصبو إلى بان العقيق ، ورنده … وعراره ، وبريره ، وبشامه\nواد ، سرى في جوه كنسيمه … وبكى على أغصانه كحمامه\nأرج النبات ، كأنما غمر الثرى … طيبا مرور ' الخضر ' بين إكامه\nمالت خمائله بخضر غصونه … وصفت موارده بزرق جمامه\nيا صاحبي ! إن جئت ذياك الحمى … فاحذر عيون العين من آرامه\nواسأل عن البدر الذي كسميه … في نور غرته ، وبعد مرامه\nفإن اشتبهت ، ولم تجد لك هاديا … فاسمع أنين القلب عند خيامه\nفبذلك الوادي غزالة كلة … تروي حديث الفتك عن ضرغامه\nضاهت بقامتها سراح قناته … وحكت بلحظتها مضاء حسامه\nهي مثله في الفتك ، أو هو مثلها … سيان وقع لحاظها وسهامه\nفسقى الحمى دمعي إذا ضن الحيا … بجمان درته سلافة جامه\nمغنى ، رعيت به الشبيبة غضة … ورويت قلبي من سلاف غمامه\nفنسيم روحي من أثير هوائه … وقوام جسمي من مزاج رغامه\nلا ينتهي شوقي إليه . وقلما … يسلو حمام الأيك عن ترنامه\nيا حبذا عصر الشباب ، وحبذا … روض جنيت الورد من أكمامه\nعصر ، إذا رسم الخيال مثاله … في لوح فكري لاح لي بتمامه\nإني لأذكره ، وأعلم أنني … باق على التبعات من آثامه\nما كان أحسن عهده لو دام لي … منه الوداد . وكيف لي بدوامه ؟\nوالدهر مصدر عبرة لو أننا … نتلو سجل الغدر من آثامه\nعمري ، لقد رحل الشباب ، وعادني … شيب تحيف لمتي بثغامه"},{"id":"diwan-barudi:120","bookId":"diwan-barudi","type":"poem","seq":120,"chapter":"البحر: مخلع البسيط","title":"هل لسلام العليل رد ؟","page":"","text":"هل لسلام العليل رد ؟ … أم لصباح اللقاء وعد ؟\nأبيت أرعى الدجى بعين … غذاؤها مدمع وسهد\nلا صاحب إن شكوت حالى … يرثى ، ولا سامع يرد\nبين قنان على ثراها … من سترات الغمام برد\nأظل فيها أنوح فردا … وكل نائي الديار فرد\nفمن لقلبي بظبي واد … بين وشيج الرماح يعدو ؟\nصار بحكم الهوى مليكى … وما لحكم الهوى مرد\nيا سعد ، قل لي ، فأنت أدرى … متى رعان العقيق تبدو ؟\nأشتاق نجدا وساكنيه … وأين مني الغداة نجد ؟\nذاب فؤادى بحب ليلى … يا لفؤاد براه وجد !\nفكيف أمسي بغير قلب ؟ … يا نور عيني ، وكيف أغدو ؟\nلكل شئ وإن تمادى … حد ، وما للغرام حد\nفليس قبل الغرام قبل … وليس بعد الغرام بعد\nفهل لنيل الوصال يوما … بعد مديد الصدود عهد ؟\nوهل أرآنى رفيق حاد … بمدح خير الأنام يحدو ؟\nعسى إلهى يفك أسرى … فهو فعول لما يود"},{"id":"diwan-barudi:121","bookId":"diwan-barudi","type":"poem","seq":121,"chapter":"البحر: بسيط تام","title":"أعد على السمع ذكر البان والعلم","page":"","text":"أعد على السمع ذكر البان والعلم … واعذر شآبيب دمعي إن جرت بدم\nملاعب للصبا أقوت ، وما برحت … ملاعبا للأسى والأعين السجم\nكانت لنا سكنا ، حتى إذا قويت … منا ، غدت سكنا للريح والديم\nلم أتخذ بعدها دارا أقيم بها … إلا تذكرت أيامي بذي سلم\nوكيف أنسى ديارا قد نشأت بها … في منبت العز بين الأهل والحشم\nيا منزلا ، لم يدع وشك الفراق به … إلا رسوما كوحي الخط بالقلم\nأين الذين بهم كانت نواظرنا … ترعى المحاسن من فرع إلى قدم\nودعت شطر حياتي يوم فرقتهم … وصافحتني يد الأحزان والهرم\nفيا أخا العذل ! لا تعجل بلائمة … علي ؛ فالحب معدود من القسم\nأسرفت في اللوم ، حتى لو أصبت به … مقاطع الحق لم تسلم من التهم\nفارحم شباب فتى ألوت بنضرته … أيدي الضنى ، فغدا لحما على وضم\nتالله ما غدرة الخلان من أربى … ولا التلون في الأخلاق من شيمي\nفكيف أنكر ودا قد أخذت به … على الوفاء عهودا برة القسم ؟\nإن لم يكن للفتى عقل يصون به … علائق الود ضاعت ذمة الحرم\nوأين من تملك الأحرار شيمته … والغدر في الناس داءق غير منحسم ؟\nفانفض يديك من الدنيا ؛ فلست ترى … خلا وفيا ، وعهدا غير منصرم\nهيهات ، لم يبق في الدنيا أخو ثقة … يرعى المودة ، أو يلقى يد السلم\nفلا يغرنك من وجه بشاشته … فالنار كامنة في ناخر السلم\nتغير الناس عما كنت أسمعه … واستحكم الغدر في السادات والحشم\nوظل أعدل من تلقاه من رجل … أعدى على الخلق من ذئب على غنم\nمن كل أشوه في عرنينه فطس … خال من الفضل ، مملوء من النهم\nسود الخلائق ، دلاجون ، ما طبعوا … على المحارم هداجون في الظلم\nلا يحسنون التقاضي في الحقوق ، ولا … يوفون بالعهد إلا خيفة النقم\nصفر الوجوه من الأحقاد ، تحسبهم … وهم أصحاء - في درع من السقم\nفلا ذمامة في قول ولا عمل … ولا أمانة في عهد ولا قسم\nبلوت منهم خلالا لو وسمت بها … وجه الغزالة لم تشرق على علم\nلم أدر ، هل نبغت في الأرض نابغة … أم هذه شيمة الدنيا من القدم ؟\nلا يدرك المجد إلا من إذا نهضت … به الحمية لم يقعد على رغم\nلو لم يكن في المساعي ما يبين به … فضل الرجال تساوى الناس في القيم\nفأي غامضة لم تجلها فطني ؟ … وأي باذخة لم تعلها قدمي ؟\nوكيف لا تسبق الماضين بادرتي ؟ … والسمهرية تخشى الفتك من قلمي ؟\nلكل عصر رجال يذكرون به … والفضل بالنفس ليس الفضل بالقدم"},{"id":"diwan-barudi:122","bookId":"diwan-barudi","type":"poem","seq":122,"chapter":"البحر: خفيف تام","title":"أنسيم سرى بنفحة رند ؟","page":"","text":"أنسيم سرى بنفحة رند ؟ … أم رسول أدى تحية هند ؟\nأطربتنى أنفاسه ، فكأنى … ملت سكرا من جرعة من برندي\nوأخو الوجد لا يزال طروبا … يتبع الشوق بين سهل وفند\nطال شوقي إلى الديار ، ولكن … أين من مصر من أقام بكندى ؟\nحبذا النيل حين يجري فيبدي … رونق السيف ، واهتزاز الفرند\nتتثنى الغصون في حافتيه … كالعذارى يسحبن وشي الفرند\nقلدتها يد الغمام عقودا … هي أبهى من كل عقد وبند\nكيف لاتهتف الحمام عليه ؟ … وهى تسقى به سلافة قند\nهو مرمى نبلى ، وملعب خيلى … وحمى أسرتى ، ومركز بندى\nكلما صورته نفسى لعينى … قدح الشوق فى الفؤاد بزند\nلي به صاحب علي عزيز … مثل ما عنده من الشوق عندى\nأتمناه غير أن فؤادي … من إسار النوى محاط بجند\nفاهد مني له تحية صدق … وتلطف بحالتي يا أفندي !\nأنا والله مغرم بهواه … حيثما درت بين هند وسند\nإن شوقي إليه أسرع شأوا … من سليك والوصل في بطء فند\nأسأل الدهر نعمة القرب منه … وهو كر بنعمة ، ليس يندي\nلو سوى الدهر رام غبنى ؛ لأصحر … ت مشيحا بالنصل فوق سمند\nلست أقوى على الزمان ؛ وإن كن … ت أفل العدا بقوة زندى"},{"id":"diwan-barudi:123","bookId":"diwan-barudi","type":"poem","seq":123,"chapter":"البحر: خفيف تام","title":"من لعين إنسانها لا ينام","page":"","text":"من لعين إنسانها لا ينام … وفؤاد قضى عليه الغرام\nأقطع الليل بين حزن ودمع … وسهاد ، والناس عني نيام\nلا صديق يرثي لما بت ألقا … ه ، ولا مسعد - فأين الكرام ؟\nلم تدع لوعة الصبابة مني … غير نفس غذاؤها الآلام\nرق طبع النسيم رفقا بحالي … وبكى رحمة علي الحمام\nوبنفسي - لو كنت أملك نفسي - … قمر نوره علي ظلام\nتستطيب القلوب فيه الرزايا … وتلذ الضنى به الأجسام\nغيرته الوشاة ؛ فازور عني … وهو منى بنجوة لا ترام\nزعموني أتيت ذنبا ، وما لي - … يعلم الله - في هواه أثام\nسوف يلقى كل امرىء ما جناه … وإلى الله ترجع الأحكام\nيا نديمي ! علالاني ، فلن ته … لك نفس قد عللتها الندام\nرب قول يرد لهفة قلب … وكلام تجف منه الكلام\nومن الماس من تراه سليما … وهو داء تدوى به الأفهام\nقد - لعمري - بلوت دهري ، فما أح … مدت منه ما تحمد الأقوام\nصلف لا يبل غلة صاد … ومراع هشيمها لا يشام\nأطلب الصدث في الوداد … يصدق الود والعهود رمام ؟\nكلما قلت قد أصبت خليلا … فانظروا : كيف تعبد الأصنام ؟\nفتفرد تعش بنفسك حرا … رب فرد يخشاه جيش لهام\nواحذر الضيم أن يمسك ؛ فالضي … م حمام يفر منه الحمام\nضل قوم توهموا الصبر حاما … وهو - إلا لدى الكريهو - ذام\nيحسبون الحياة في الذل عيشا … وهو موت يعيش فيه اللئام"},{"id":"diwan-barudi:124","bookId":"diwan-barudi","type":"poem","seq":124,"chapter":"البحر: طويل","title":"خليلى هل طال الدجى ؟ أم تقيدت","page":"","text":"خليلى هل طال الدجى ؟ أم تقيدت … كواكبه ، أم ضل عن نهجه الغد\nأبيت حزينا في ( سرنديب ) ساهرا … طوال الليالى ، والخليون هجد\nأحاول مالا أستطيع طلابه … كذا النفس تهوى غير ما تملك اليد\nإذا خطرت من نحو حلوان نسمة … نزت بين قلبي شعلة تتوقد\nوهيهات ، ما بعد الشبيبة موسم … يطيب ، ولا بعد الجزيرة معهد\nشباب وإخوان رزئت ودادهم … وكل امرئ فى الدهر يشقى ويسعد\nوما كنت أخشى أن أعيش بغربة … يعللني فيها خويدم أسود"},{"id":"diwan-barudi:125","bookId":"diwan-barudi","type":"poem","seq":125,"chapter":"البحر: خفيف تام","title":"يا نديمي في ' سرنديب ' كفا","page":"","text":"يا نديمي في ' سرنديب ' كفا … عن ملامي ، فليس يغني الملام\nأنا في هذه الديار غريب … وغريب الديار ليس يلام\nواذكرا لي ' فسطاط ' مصر ؛ فإني … بهواها متيم مستهام"},{"id":"diwan-barudi:126","bookId":"diwan-barudi","type":"poem","seq":126,"chapter":"البحر: طويل","title":"أرى نفحة دلت على كبدى الوجدا","page":"","text":"أرى نفحة دلت على كبدى الوجدا … فمن كان ' بالمقياس ' أقربكم عهدا ؟\nملاعب آرام ، ومجرى جداول … وملتف أفنان تقى الحر والبردا\nإذا انبعثت فيه النسائم خلتها … تنير على متن الغدير به بردا\nكأن الصبا تلقي عليه إذا جرت … مسائل في الأرقام ، أو تلعب النردا\nأقام الربيع الطلق في حجراتها … وأسدى لها من نعمة النيل ما أسدى\nفلله كم من صبوة كان لى بها … رواح إلى حسانة الجيد أو مغدى\nإذ الدهر لم يخفر ذماما ، ولم يخن … نظاما ، ولم يحمل على ذى هوى حقدا\nتدور علينا بالأحاظي شموسه … وتمسي علينا طير أنجمه سعدا\nويا رب ليل لفنا بردائه … عناقا ، كما لف الصبا البان والرندا\nولثم توالى إثر لثم بثغرها … كما شافه البازى على ظمأ وردا\nفتاة كأن الله صور لحظها … ليهتك أسرار القلوب به عمدا\nلها عبثات عند كل تحية … تسوق إليها عن فرائسها الأسدا\nإذا انفتلت بالكأس خلت بنانها … تدير علينا من جنى خدها وردا\nوما أنسه لا أنس يوما تسابقت … به عبرتاها ، والنوى تصدع الصلدا\nفلم أر لحظا كان أقتل باكيا … وأمضى الظبا فى الفتك ما سال إفرندا\nحرام على العينين إن لم تسل دما … على بينها والقلب إن لم يذب وقدا\nفيا قلب ماأشجى إذا الدار باعدت ! … ويا دمع ما أجرى ، ويا بين ما أردى !\nويا صاحبى المذخور للسر ! إننى … ضللت ، فهل من وثبة تكسب الحمدا ؟\nحلفت بما استولى عليه نقابها … ويا لك حلفا ! ما أرق وماأندى !\nبألا تفئ العين عن سنة البكى … وألا تريع النفس إن لم تمت وجدا\nوكيف يفيق القلب من سورة الهوى … وقد مده سحر العيون بما مدا ؟\nوما كنت لولا العذل أبدي خفية … ولكن توالى القدح يسترعف الزندا\nومن لي بأن القلب يكتم وجده ؟ … وكيف تسام النار أن تكتم الندا ؟\nفلا وصل إلا ذكرة تبعث الأسى … على النفس حتى لا تطيق له ردا\nأبيت قريح الجفن ، لا أعرف الكرى … طوال الليالى ، والجوانح لا تهدا\nفيأيها النوام ! والشوق عازر … ألا أحد يشرى بغفوته السهدا ؟\nلقد ذل من يبغي من الناس ناصرا … وقد خاب من يجنى من الأرقم الشهدا\nفإياك أن تخدع بشيمة صاحب … فمن ظن خيرا بالزمان فقد أكدى\nفقد طالما جربت خلا فما رعى … وحلفا فما أوفى ، وعونا فما أجدى\nوما الناس إلا طالب غير واجد … لما يبتغي ، أو واجد أخطأ القصدا\nفلا تحسبن الناس أبناء شيمة … فما كل ممدود الخطا بطلا جعدا"},{"id":"diwan-barudi:127","bookId":"diwan-barudi","type":"poem","seq":127,"chapter":"البحر: طويل","title":"محا البين ما أبقت عيون المها مني","page":"","text":"محا البين ما أبقت عيون المها مني … فشبت ولم أقض اللبانة من سنى\nعناء ، وبأس ، واشتياق ، وغربة … ألا ، شد ما ألقاه في الدهر من غبن\nفإن أك فارقت الديار فلي بها … فؤاد أضلته عيون المها مني\nبعثت به يوم النوى إثر لحظة … فأوقعه المقدار في شرك الحسن\nفهل من فتى في الدهر يجمع بيننا ؟ … فليس كلانا عن أخيه بمستغن\nولما وقفنا للوداع ، وأسبلت … مدامعنا فوق الترائب كالمزن\nأهبت بصبري أن يعود ، فعزني … وناديت حلمي أن يثوب ، فلم يغن\nولم تمض إلا خطرة ، ثم أقلعت … بنا عن شطوط الحي أجنحة السفن\nفكم مهجة من زفرة الوجد في لظى … وكم مقلة من غزرة الدمع في دجن\nوما كنت جربت النوى قبل هذه … فلما دهتني كدت أقضي من الحزن\nولكنني راجعت حلمي ، وردني … إلى الحزم رأي لا يحوم على أفن\nولولا بنيات وشيب عواطل … لما قرعت نفسي على فائت سنى\nفيا قلب صبرا إن جزعت ؛ فربما … جرت سنحا طير الحوادث باليمن\nفقد تورق الأغصان بعد ذبولها … ويبدو ضياء البدر في ظلمة الوهن\nوأي حسام لم تصبه كهامة … ولهذم رمح لا يفل من الطعن ؟\nومن شاغب الأيام لان مريره … وأسلمه طول المراس إلى الوهن\nوما المرء في دنياه إلا كسالك … مناهج لا تخلو من السهل والحزن\nفإن تكن الدنيا تولت بخيرها … فأهون بدنيا لا تدوم على فن !\nتحملت خوف المن كل رزيئة … وحمل رزايا الدهر أحلى من المن\nوعاشرت أخدانا ، فلما بلوتهم … تمنيت أن أبقى وحيدا بلا خدن\nإذا عرف المرء القلوب وما انطوت … عليه من البغضاء - عاش على ضغن\nوأي حياة لامرىء بين بلدة … وتسمع أذني ما تعاف من اللحن\nوكيف مقامي بين أرض أرى بها … من الظلم ما أخنى على الدار والسكن\nفسمع أنين الجور قد شاك مسمعي … ورؤية وجه الغدر حل عرا جفني\nوصعب على ذي اللب رئمان ذلة … يظل بها في قومه واهي المتن\nإذا المرء لم برم الهناة بمثلها … تخطى إليه الخوف من جانب الأمن\nفلا تعترف بالذل خيفة نقمة … فعيش الفتى في الذل أدهى من السجن\nوكن رجلا ، إن سيم خسفا رمت به … حميته بين الصوارم واللدن\nفلا خير في الدنيا إذا المرء لم يعش … مهيبا ، تراه العين كالنار في دغن\nولا ترهب الأخطار في طلب العلا … فمن هاب شوك النحل عاد ، ولم يجن\nولولا معاناة الشدائد ما بدت … مزايا الورى بين الشجاعة والجبن\nفإن لم تجد في المدن ما شئت من قرى … فأصحر ؛ فإن البيد خير من المدن\nصحار يعيش المرء فيها بسيفه … شديد الحميا غير مغض على دمن\nوأي حياة لامرئ بين بلدة … يطل بها بين العواثن والدخن ؟\nلعمري لكوخ من ثمام … أحب إلى قلبي من البيت ذي الكن\nوأطرب من ديك يصيح بكوة … أراكية تدعو هديلا على غصن\nوأحسن من دار وخيم هواؤها … مبيتك من بحبوحة القاع في صحن\nترى كل شيء نصب عينيك ماثلا … كأنك من دنياك في جنتي عدن\nتدور جياد الخيل حولك شربا … تجاذب أطراف الأعنة كالجن\nإذا سمعت صوت الصريخ تنصبت … فتدرك ما لا تبصر العين بالأذن\nفتلك - لعمري - عيشة بدورية … موطأة الأكناف ، راسخة الركن\nوما قلت إلا بعد علم أجد لي … يقينا نفى عني مراجعة الظن\nفقد ذقت طعم الدهر حتى لفظته … وعاشرت حتى قلت لابن أبي : دعني\nولولا أخ أحمدت في الود عهده … على حدثان الدهر - ما كنت أستثني\nورب بعيد الدار يصفيك وده … ومقترب يجني عليك ولم تجن\nوما الود في القربى وإن هي أوجبت … ولكنه في الطبع ، والشكل ، والوزن\nإذا لم يكن بين الوديدين خلة … فلا أدب يجدى ، ولا نسب يدنى\nفذاك أخ لولاه أنكرت كل ما … سمعت به عن ( أحنف الحلم ، أو\nمعن ) ) 49 ( فإن لم أصرح باسمه خوف حاسد … ينم عليه ، فهو يعلم من أعني\nعلى إن ذكراه - وإن كان نائيا - … سمير فؤادي في الإقامة والظعن\nأنوح لبعدي عنه حزنا ولوعة … كمانا من شوق ' جميل ' عاى ' بثن '\nفمن لي به خلا كريما نجاره ؟ … فقد سئمت نفسي معاشرة الهجن\nتجاذبني نفسي إليه ، ودوننا … أهاويل ملتج الغوارب مستن\nلعل يد الأيام تسخو بلقية … أراه بها بعد الكزازة والضن\nوإني وإن طال المطال لواثق … برحمة ربي ؛ فهو ذو الطول والمن"},{"id":"diwan-barudi:128","bookId":"diwan-barudi","type":"poem","seq":128,"chapter":"البحر: رجز تام","title":"وصاحب رعيت دهرا وده","page":"","text":"وصاحب رعيت دهرا وده … ولم أباين نهجه وقصده\nوكنت أرعى بالمغيب عهده … بل كنت أخشى أن أعيش بعده\nوطالما أرغمت فيه ضده … وذدت عنه ما يعوق وكده\nحتى إذا ما الدهر أروى زنده … صعر لى بعد الصفاء خده\nوجاز في بعض الأمور حده … فلم أحاول ردعه ورده\nولم أكدر بالعتاب ورده … ولو أردت أن أفل حده\nلقلت فيه ما يحز جلده … لكننى تركته وحقده\nشأن امرىء في المجد يرعى مجده … كل امرئ ينفق مما عنده\nوالمرء مجزي بما أعده … "},{"id":"diwan-barudi:129","bookId":"diwan-barudi","type":"poem","seq":129,"chapter":"البحر: بسيط تام","title":"أعائد بك - يا ريحانة - الزمن ؟","page":"","text":"أعائد بك - يا ريحانة - الزمن ؟ … فيلتقي الجفن - بعدا البين - والوسن\nأشتاق رجعة أيامي لكاظمة … وما بي الدار لولا الأهل والسكن\nفهل ترد الليالي بعض ما سلبت ؟ … أم هل تعود إلى أوطانها الظعن ؟\nأهنت للحب نفسي بعد عزتها … وأي ذي عزة للحب لا يهن ؟\nلو لم يكن في الهوى سر لما ظهرت … بوحي قدرته في العالم الفتن\nفكيف أملك نفسي بعدما علقت … بي الصبابة حتى شفني الوهن\nلولا جريرة عيني ما سمحت بها … للدمع تسفحه الأطلال والدمن\nدعت إلى الغي قلبي ؛ فاستبد به … شوق تولد منه الهم والشجن\nودون ما تبغيه النفس من أرب … بيداء تصهل في أرجائها الحصن\nوفي الأكلة آرام تطيف … أسد براثنها الخطية اللدن\nمن كل حوراء مثل الظبي ، لو نظرت … لعابد لشجاه اللهو والددن\nفي نشوة الراح من ألحاظها أثر … وفي الجآذر من ألفاظها غنن\nدقت ، وجلت ، ولانت ، وهي قاسية … كذاك حد المواضي لين خشن\nطوت بهن النوى عني بدور دجى … لا يستبين لعيني بعدها سنن\nأتبعتهم نظرات كلما بلغت … أخرى الحمول ثناها مدمع هتن\nيا راحلين وفي أحداجهم قمر … يكاد يعبده من حسنه الوثن\nمنوا علي بوصل أستعيد به … من مهجتي رمقا يحيا به البدن\nأو فاسمحوا لي بوعد إن ونت صلة … فالوعد منكم بطيب العيش مقترن\nلم ألق من بعدكم يوما أسر به … كأن كل سرور بعدكم حزن\nيا جيرة الحي ! ما لي لا أنال بكم … معونة ؛ وبكم في الناس يعتون ؟\nماذا عليكم وأنتم أهل بادرة … إذا ترنم فيكم شاعر فطن ؟\nأفي السوية أن يبكي الحمام ، ولا … يبكي على إلفه ذو لوعة ضمن ؟\nيا حبذا مصر لو دامت مودتها … وهل يدوم لحي في الورى سكن ؟\nتالله ما فارقتها النفس عن ملل … وإنما هي أيام لها إحن\nفلا يسر عداتي ما بليت به … فسوف تفنى ، ويبقى ذكري الحسن\nظنوا ابتعادي إغفالا لمنقبتي … وذاك عز لها لو أنهم فطنوا\nفإن أكن سرت عن أهلي وعن وطني … فالناس أهلي ، وكل الأرض لي وطن\nلا يطمس الجهل ما أثقبت من شرف … وكيف يحجب نور الجونة الدخن ؟\nقد يرفع العلم أقواما وإن تربوا … ويخفض الجهل أقواما وإن خزنوا\nفرب ميت له من فضله نسم … ورب حي له من جهله كفن\nفلا تغرنك أشباه تمر بها … هيهات ، ما كل طرف سابق أرن\nفلا ملام على ما كان من حدث … فكلنا بيد الأقدار مرتهن\nلو كان للمرء حكم في تصرفه … لعاش حرا ، ولم تعلق به المحن\nوأي حي - وإن طالت سلامته - … يبقى ؟ وأي عزيز ليس يمتهن ؟\nكل امريء غرض للدهر يرشقه … بأسهم لا تقي أمثالها الجنن\nفليشغب الدهر ، أو تسكن نوافره … فلست منه على ما فات أحتزن\nغنيت عما يهين النفس من عرض … فما علي لحي في الورى منن\nلكنني بين قوم لا خلاق لهم … إن عاقدوا غدروا ، أو عاشروا دهنوا\nيخفون من حسد ما في نفوسهم … ويظهرون خداعا غير ما بطنوا\nيا للحماة ! أما في الناس من رجل … وارى الضمير ، له عقل به يزن ؟\nأكل خل أراه لا وفاء له ؟ … وكل قلب علي اليوم مضطغن ؟\nتغير الناس عما كنت أعهده … فاليوم لا أدب يغنى ، ولا فطن\nفالخير منقبض ، والشر منبسط … والجهل منتشر ، والعلم مندفن\nلم تلق منهم سليما في مودته … كأن كل امرىء في قلبه دخن\nطواهم الغل طي القد ، وانتشرت … بالغدر بينهم الأحقاد والدمن\nفلا صديق يراعي غيب صاحبه … ولا رفيق على الأسرار يؤتمن\nبلوتهم ؛ فسئمت العيش ، وانصرفت … نفسي عن الناس حتى ليس لي شجن\nفإن يكن فاتني ما كنت أملكه … فالبعد عنهم لما أتلفته ثمن\nكفى بحرب النوى سلما نجوت به … ورب مخشية في طيها أمن\nلعل مزنة خير تستهل على … روض الأماني ؛ فيحيا الأصل\nوكل شيء له بدء وعاقبة … وكيف يبقى على حدثانه الزمن ؟"},{"id":"diwan-barudi:130","bookId":"diwan-barudi","type":"poem","seq":130,"chapter":"البحر: سريع","title":"من قلد الزهر جمان الندى","page":"","text":"من قلد الزهر جمان الندى … وألهم القمرى حتى شدا ؟\nوزين الأرض بألوانها … وصور الأبيض والأسودا ؟\nسبحان من أبدع في ملكه … حتى بدا من صنعه ما بدا\nتنزهت عن صفة ذاته … وقام فى لاهوته أوحدا\nفاسجد له ، واقصد حماه تجد … ربا كريما ، ومليكا هدى\nفقم بنا يا صاح نرع الندى … ونسأل الله عميم الندى\nأما ترى كيف استحار الدجى ؟ … وكيف ضل النجم حتى اهتدى ؟\nولاح خيط الفجر في سحرة … كصارم فى قسطل جردا\nفالجو قد باح بمكنونه … والأرض قد أنجزت الموعدا\nغمامة ألقت بأفلاذها … وجدول مد إلينا يدا\nفانهض ، وسر ، وانظر ، ومل ، وابتهج … وامرح ، وطب ، واشرب لتروي الصدى\nولا تسل عن خبر لم يحن … ميقاته ، وانظر إلى المبتدا\nولا تلم خلا على هفوة … فقلما تلقى فتى أمجدا\nلو علم الإنسان ما أضمرت … أحبابه ، هانت عليه العدا\nفدع بني الدنيا لأهوائهم … ولا تطع من لام ، أو فندا\nما لي وللناس وأعمالهم ؟ … كل امرئ رهن حساب غدا\nهل هي إلا مدة تنقضي ؟ … وكل نفس خلقت للردى\nفاستعمل الرفق تعش راشدا … واعطف على الأدنى تكن سيدا\nواسع لما أنت له ، فالفتى … إن هجر الراحة حاز المدى\nما خلق الله الورى باطلا … ليرتعوا بين البوادي سدى\nفاقبل وصاتى ، واستمع حكمتى … فليس من أغوى كمن أرشدا\nإني وإن كنت أخا صبوة … ومسمع يطربنى من شدا\nفقد أزور الليث فى غابه … وأهبط الأرض عليها الندى\nوأصدع الخصم ، وما خلتني … أصدع إلا البطل الأصيدا\nبلهذم ليست له صعدة … لكنه يمضي إذا سددا\nأو صارم يفري نياط الكلى … ولم يزل في جفنه مغمدا\nماضى الغرارين ، ولكنه … لا يعرف الصيقل والمبردا\nأو مشقص إن فوقت نصله … إلى امرئ غير يد أقصدا\nأو طائر فى وكره جاثم … يشوق إن هينم أو غردا\nلم يعد كنا لم يزل ساكنا … فيه ، وبابا دونه مؤصدا\nقد لان ، إلا أنه إن قسا … يوم نضال ؛ صدع الجلمدا\nمعتقل ، لكنه مطلق … يجول فى مسكنه سرمدا\nيحكم بالذوق على ما يرى … ويعرف الأصلح والأفسدا\nله صحاب قد أحاطت به … تنقل عنه نبرات الصدى\nفهو بها مجتمع شمله … إن أصدر القول بها أوردا\nمشتبهات الرصف فى جودة … تبارك الله الذي جودا\nيبيت منها وهو ذو مرة … في رصف من لؤلؤ نضدا\nذاك لساني ، وهو حسبي إذا … ما أبرق الحاسد أو أرعدا"},{"id":"diwan-barudi:131","bookId":"diwan-barudi","type":"poem","seq":131,"chapter":"البحر: كامل تام","title":"أخذ الكرى بمعاقد الأجفان","page":"","text":"أخذ الكرى بمعاقد الأجفان … وهفا السرى بأعنة الفرسان\nوالليل منثور الذوائب ضارب … فوق المتالع والربا بجران\nلا تستبين العين في ظلمائه … إلا اشتعال أسنة المران\nنسري به ما بين لجة فتنة … تسمو غواربها على الطوفان\nفي كل مربأة ، وكل ثنية … تهدار سامرة ، وعزف قيان\nتسن عادية ، ويصهل أجرد … وتصيح أحراس ، ويهتف عانى\nقوم أبى الشيطان إلا نزعهم … فتسللوا من طاعة السلطان\nملأوا الفضاء ؛ فما يبين لناظر … غير التماع البيض والخرصان\nفالبدر أكدر ، والسماء مريضة … و\nوالخيل واقفة على أرسانها … لطراد يوم كريهة ، ورهان\nوضعوا السلاح إلى الصباح ، وأقبلوا … يتكلمون بألسن النيران\nحتى إذا ما الصبح أسفر ، وارتمت … عيناي بين ربا ، وبين محاني\nفإذا الجبال أسنة ، وإذا الوها … د أعنة ، والماء أحمر قاني\nفتوجست فرط الركاب … لتهاب ؛ فامتنعت على الأرسان\nفزعت ؛ فرجعت الحنين ، وإنما … تحنانهاشجن من الأشجان\nذكرت مواردها بمصر . وأين من … ماء بمصر منازل الرومان ؟\nوالنفس مولعة - وإن هي صادفت … خلفا بأول صاحب ومكان\nفسقى السماك محلة ومقامة … في مصر كل روية مرنان\nحتى تعود الأرض بعد محولها … شتى النماء ، كثيرة الألوان\nبلد خلعت بها عذار شبيبتي … وطرحت في يمنى الغرام عناني\nفصعيدها أحوى النبات ، وسرحها … ألمى طوع تقلب الأزمان\nحمل اتلزمان علي ما لم أجنه … إن الأماثل عرضة الحدثان\nنقموا علي - وقد فتكت - شجاعتي … إن الشجاعة حلية الفتيان\nفليهنإ الدهر الغيور برحلتي … عن مصر ، ولتهدأ صروف زماني\nفلئن رجعت ، وسوف أرجع واثقا … بالله - أعلمت الزمان مكاني\nصادفت بعض القوم حتى خانني … وحفظت منه مغيبه فرماني\nزعم النصيحة بعد أن بلغت به … غشا ، وجازى الحق بالبهتان\nفليجر بعد كما أراد بنفسه … إن الشقي مطية الشيطان\nوكذا اللئيم إذا أصاب كرامة … عادى الصديق ، ومال بالإخوان\nكل امرئ يجري على أعراقه … والطبع ليس يحول في الإنسان\nفعلام يلتمس العدو مساءتي ؟ … من بعد ما عرف الخلائق شاني\nأنا لا أذل ، وإنما يزع الفتى … فقد الرجاء وقلة الأعوان\nفليعلمن أخو الجهالة قصره … عني وإن سبقت به قدمان\nفلربما رجح الخسيس من الحصى … بالدر عند تماثل الميزان\nشرف خصصت به ، وأخطأ حاسد … مسعاته ، فهذى به ، وقلاني"},{"id":"diwan-barudi:132","bookId":"diwan-barudi","type":"poem","seq":132,"chapter":"البحر: خفيف تام","title":"ما لقلبى من لوعة ليس يهدا ؟","page":"","text":"ما لقلبى من لوعة ليس يهدا ؟ … أو لم يكف أنه ذاب وجدا ؟\nوسمتني بنارها الغيد حتى … تركتنى فى عالم الحب فردا\nفضلوعي من قدحة الزند أورى … ودموعى من صفحة الغيم أندى\nما على البرق لو تحمل عني … بعض ما خف من سلام فأدى ؟\nأيها الساهرون حول وسادى … لست منكم أو تذكروا لي نجدا\nوعهودا لم يترك الدهر منها … لأخى صبوة ذماما وعهدا\nونسيما إذا سرى ضوع الآ … فاق مسكا ، وعطر الجو ندا\nلا تخوضوا فى غيره من حديث … فهو حسبى ، وأى ماء كصدا ؟\nهي أحدوثة تساق ولكن … ربما استوجبت ثناء وحمدا\nآه من لوعة أطارت بقلبى … شعلة شفت الجوانح وقدا\nكلما قلت قد تناهى غرامى … عاد منه ما كان أصمى وأردى\nيا رفيقي إذا عراني خطب … ونصيرى إذا خصيم تصدى\nأصبحت حاجتي إليك ، فخذ لي … بحقوقي من ظالم قد تعدى\nوجد القلب خاليا فاحتواه … ورأى النفس طوعه فاستبدا\nوكذاك السلطان إن ظن بالأم … ة عجزا سطا عليها وشدا\nفأقلني من عثرة الحب إن أو … تيت حكما ، أو قل لقلبى يهدا\nفمن العار غض طرفك عني … إن خير الصحاب أنفع ودا\nوبنفسى حلو الشمائل ، مر ال … هجر ، يحيي وصلا ، ويقتل صدا\nذو قوام أعدى من الرمح لينا … ولحاظ أمضى من السيف حدا\nكان قلبى وديعة عند عيني … ه ، فآلى بالسحر ألا يردا\nما على قومه وإن كنت حرا … أن دعتنى له المحبة عبدا ؟\nغصن بان ، قد أطلع الحسن فيه … بيد السحر جلنارا ووردا\nما هلال السماء ؟ ما الظبي ؟ ما الور … د جنيا ما الغصن إذ يتهدى ؟\nهو أبهى وجها ، وأقتل ألحا … ظا ، وأندى خدا ، وألين قدا\nفدع اللوم يا عذول ، فإني … لست أبغي من العواذل رشدا\nلا تخلنى على غراتك سهلا … أنا أدرى بلوعتي منك جدا\nلست أقوى على الصدود ، وإن كن … ت على سورة الحوادث جلدا\nإن تكن رحمة فنفسي أولى … أو تكن ضلة فربى أهدى"},{"id":"diwan-barudi:133","bookId":"diwan-barudi","type":"poem","seq":133,"chapter":"البحر: وافر تام","title":"صبوت إلى المدامة والغواني","page":"","text":"صبوت إلى المدامة والغواني … وحكمت الغواية في عناني\nوقلت لعفتي - بعد امتناع - … إليك ؛ فقد عناني ما عناني\nفما لي عن هوى الحسناء صبر … يوقر عند سورته جناني\nوكيف يضيق من دارت عليه … كئوس هوى من الحدق الحسان ؟\nأعاذل ، خلت = ني وشئون قلبي … وخذ ما شئته في أي شان\nفقد شب الهوى من رام نصحي … وأغرى في المحبة من نهاني\nرضيت من الهوى بنحول جسمي … ومن صلة البخيلة بالأماني\nولست بطالب في الناس خلا … يناصحني ؛ فعقلي قد كفاني\nبلوت الناس ، واستخبرت عنهم … صروف الدهر آنا بعد آن\nفما أبصرت غير أخي كذاب … خلوب الود ، مصنوع الحنان\nيصرح بالعداوة وهو ناء … ويمذق في المحية وهو داني\nله في كل جارحة لسان … وما شربي المدام هوى ، ولكن\nفلا تأمن على نجواك صدرا … فرب خديعة تحت الأمان\nولا يغررك قول دون فعل … فإن الحسن قبح في الجبان\nوما أنا والطباع لها انخداع … بذي ترف يروع بالشنان\nرغبت بشيمتي ، وعرفت نفسي … ولم أدخل - لعمرك - في قران\n … عقدت بحد سورتها لساني\nمخافة أن تهيج بنات صدري … فيظهر بعض سرى للعيان\nوفيم - وقد بلوت الدهر - أبغي - … صديقا ، أو أحن إلى مكان ؟\nولست ى سوى صبح وجنح … إلينا بالردى يتسابقان\nفيا من ظن بالأيام خيرا … رويدك ؛ فهي أقرب للحران\nأترغب في السلامة وهي داء ؟ … وتجمع للبقاء وأنت فاني ؟\nدع الدنيا ، وسل الهم عنها … إذا اعتكرت - بصافية الدنان\nفإن الراح راحة كل نفس … إذا دارت على نغم القيان\nمن الخمر التي درجت عليها … أفانين من العصر الفواني\nتخال ومسضها في الكأس نارا … فتلمسها بأطراف البنان\nفخذها غير مدخر نفيسا … فليس العمر يدخل في ضمان\nوخل الناس عنك ؛ فليس فيهم … سليم القلب عند الإمتحان\nتماثيل تدور بلا عقول … وألفاظ تمر بلا معاني\nتشابهت الأسافل بالأعالي … فما يدرى الهجين من الهجان\nترى كل ابن أنثى لا يبالي … بما جرت عليه من الهوان\nيدل بنفسه إن غبت عنه … ويشرق بالزلال إذا رآني\nفمن لي - والأماني كاذبات - … بيوم في الكريهة أرونان\nألاعب فيه أطراف العوالي … وأطلق بين هبوته حصاني\nتراني فيه أول كل داع … ويرتفع الغبار ، فلا تراني\nإلى أن تنجلي الغمرات عنه … ويعرفني بفتكي من بلاني\nأنا ابن الليل والخيل المذاكى … وبيض الهند ، والسمر اللدان\nإذا عين أجد بها طماح … جعلت مكان حبتها سناني"},{"id":"diwan-barudi:134","bookId":"diwan-barudi","type":"poem","seq":134,"chapter":"البحر: طويل","title":"لقد طال عهدي بالشباب ، وإنه","page":"","text":"لقد طال عهدي بالشباب ، وإنه … لأدعى لشوقى أن يطول به عهدى\nتبيت عيون بالكرى مطمئنة … وعيناى فى برح من الدمع والسهد\nفليت الذى حاز الشبيبة ردها … وليت الذي أهدى لنا الشيب لم يهد\nكأني وقد جاوزت ستين حجة … مسحت بها عن ناظرى سنة الفهد\nفسحقا لدار لا يدوم نعيمها … وتبا لخل لا يدوم على العهد\nوكيف يلذ المرء بالعيش بعد ما … رأى أن سم الموت في ذلك الشهد ؟\nإذا لم يكن بين الحياة وضدها … سوى مهلة ؛ فاللحد أشبه بالمهد\nوللموت أسباب ينال بها الفتى … فمن بات فى نجد كمن بات فى وهد\nوكل امرئ فى الناس لاق حمامه … فسيان رب العير والفرس النهد\nولولا ارتياع النفس من صولة الردى … لما عف عن طيب النعيم أخو زهد\nفدع ما مضى ، واصبر على حكمة القضا … فليس ينال المرء ما فات بالجهد\nولا تلتمس من غير مولاك هاديا … إذا الله لم يهد العباد ، فمن يهدي ؟"},{"id":"diwan-barudi:135","bookId":"diwan-barudi","type":"poem","seq":135,"chapter":"البحر: منسرح","title":"واطول شوقي إليك يا وطن !","page":"","text":"واطول شوقي إليك يا وطن ! … وإن عرتني بحبك المحن\nأنت المنى والحديث إن أقبل الص … صبح ، وهمي إن رنق الوسن\nفكيف أنساك بالمغيب ولي … فيك فؤاد بالحب مرتهن ؟\nلست أبالي وقد سلمت على الد … دهر إذا ما أصابني الحزن\nليت بريد الحمام يخبرني … عن أهل ودى ؛ فلي بهم شجن\nأهم على الود ، أم أطاف بهم … واش أراهم خلاف ما يقنوا ؟\nفإن نسوني فذكرتي لهم … وكيف ينسى حياته البدن ؟\nبين أناس إذا وزنتهم … بالذر عند البلاء ما وزنوا\nلا في موداتهم إذا صدقوا … ربح ، ولا في فراقهم غبن\nمن كل فظ يلوك في فمه … مضغة سوء مزاجها عفن\nينضح شدقاه بالرؤال كما … عل بنضح العتيرة الوثن\nشعث ، عراة ، كأنهم خرجوا … من نفق الأرض بعد ما دفنوا\nلا يحسنون المقال إن نطقوا … جهلا ، ولا يفقهون إن أذنوا\nأرى بهم وحشة إذا حضروا … وطيب أنس إذا هم ظعنوا\nوكيف لي بالمقام في بلد … ما لي بها صاحب ، ولا سكن\nكل خليل لخله وزر … وكل دار لأهلها أمن\nفهل إلى عودة ألم بها … شملى ، وألقى ' محمدا ' سنن ؟\nذاك الصديق الذي وثقت به … فهو بشكري ومدحتي قمن\nعاشرته حقبة ، فأنجدني … منه الحجا ، والبيان ، واللسن\nوهو إلى اليوم بعد ما علقت … بي الرزايا مخيل هتن\nينصرني حيث لا يكاد حم … يمنحني وده ، ولا ختن\nقد كان ظني يسيء بالناس لو … لاه ، وفرد يحيا به الزمن\nفهو لدى المعضلات مستند … وعند فقد الرجاء مؤتمن\nنمت على فضله شمائله … ونفحة الورد سرها علن\nلو كان يعلو السماء ذو شرف … لكان بالنيرات يقترن\nفليحى حرا ممتعا بجمي … ل الذكر فالذكر مفخر حسن"},{"id":"diwan-barudi:136","bookId":"diwan-barudi","type":"poem","seq":136,"chapter":"البحر: بسيط تام","title":"أدى الرسالة يا عصفورة الوادى","page":"","text":"أدى الرسالة يا عصفورة الوادى … وباكري الحي من قولي بإنشاد\nترقبى سنة الحراس ، وانطلقى … بين الخمائل من ( لبنان وارتادي )\nلعل نغمة ود منك شائقة … تهز عطف ( شكيب كوكب النادي )\nهو الهمام الذي أحيا بمنطقه … آثار قوم أجادوا النطق بالضاد\nتلقى به أحنف الأخلاق منتديا … وفى الكريهة عمرا ، وابن شداد\nأحى ودادا ، وحسبى أنه نسب … خالى الصحيفة من غل وأحقاد\nأفادني أدبا من منطق شهدت … بفضله الناس من قار ، ومن بادي\nعذب الشريعة ، لو أن السحاب همى … بمثله ، لم يدع في الأرض من صادي\nسرت بقلبي منه نشوة ملكت … بحسنها مسمعى عن نغمة الشادى\nيابن الكرام ! عدتني عنك عادية … كادت تسد على عيني بأسداد\nفاعذر أخاك ، فلولا ما به لجرى … في حلبة الشكر جري السابق العادي\nوهاكها تحفة مني وإن صغرت … فالدر وهو صغير حلى أجياد"},{"id":"diwan-barudi:137","bookId":"diwan-barudi","type":"poem","seq":137,"chapter":"البحر: بسيط تام","title":"خلعت في حب غزلان الحمى رسني","page":"","text":"خلعت في حب غزلان الحمى رسني … وبعت بالسهد في ليل الهوى وسني\nوأعجبتني - على ذم العذول لها - … صبابة نقلت سري إلى العلن\nفليبلغ العذل مني ما أراد ؛ فقد … أسلمت للشوق روحي والضنى بدني\nتلك الحمائم لو تدري بما لقيت … أهل المحبة لم تسجع على فنن\nيا ربة الخدر ! قومي ، فانظري عجبا … إلى غرائب لم تقدر ، ولم تكن\nهذي يدي ، جسها الآسي ، وخامره … يأس ؛ فغادرها صرعى من الوهن\nوقال : لا تكتمن أمرا علي ، فقد … علمت ما بك من باد ومكتمن\nفلم أجب ، غير أن الدمع نم على … وجدي ، ودلته أنفاسي على شجني\nعطفا علي ؛ فلم أطلب إليك سوى … أن أمتع العين من تمثالك الحسن\nما للعذول رأى وجدي ؛ فأحفظه … حتى أتاكم بقول من هن وهن ؟\nلا تقبلي العذل في مثلي ، فكل فتى … حر الشمائل محسود على الفطن\nوالناس أعداء أهل الفضل مذ خلقوا … من عهد آدم ، سباقون في الإحن\nفلا صديق على ود بمتفق … ولا خليل على سر بمؤتمن\nفليت لي ودواعي النفس كاذبة … خلا يكون سرور العين والأذن\nأصفيه ودي ، وأمليه الهوى ، وأرى … منه الصواب ، وأرجوه على الزمن\nهيهات ؛ أطلب أمرا ليس يبلغه … حي ولو سار من هند إلى يمن\nمهلا أخا الجهل ، لا يغويك ما نظرت … عيناك في هذه الدنيا من الفتن\nهذي البرية ، فانظر ، إن وجدت بها … غير الذي قلت ، فاهجرني ، ولا ترني\nأنا الذي عرف الأيام ، وانكشفت … له سرائرها من كل مختزن\nطفت البلاد ، وجربت العباد ، فلم … أركن لخل ، ولم أجنح إلى سكن\nخلقت حرا ؛ فلا قدري بمتضع … عند الملوك ، ولا عرضي بممتهن\nلا عيب في سوى أني عتبت على … دهري ؛ فقدم من دوني ، وأخرني\nوهذه شيمة الدنيا ، ومن عجب … أني أرى محنتي فيها وتعجبني\nليس السرور الذي يأتي الزمان به … يفي بقدر الذي يمضي من الحزن\nفاستبق نفسك إن كنت امرأ فطنا … واقنع بعيشك في سربالك الخشن\nولا تفه بحديث النفس ، إن به … شر الحياة ، وسعي الحاسد الأفن\nولا تسل أحدا عونا على أمل … حتى تكون أسير الشكر والمنن\nخير المعيشة ما كانت مذللة … هونا ، وثوبك معصوم من الدرن\nوعاشر الناس بالحسنى ، فإن عرضت … إساءة فتغمدها على الظنن\nفالصفح عن بعض ما يمنى الكريم به … فضل يطير به شكر بلا ثمن"},{"id":"diwan-barudi:138","bookId":"diwan-barudi","type":"poem","seq":138,"chapter":"البحر: وافر تام","title":"ألا ( يا نحلة ) سرحت فحازت","page":"","text":"ألا ( يا نحلة ) سرحت فحازت … سلالة ما تولته العهاد\nتلقتها النجاد بما أسرت … ضمائرها ، وحيتها الوهاد\nسعت جهدا ، فنالت ما تمنت … كذاك الدهر : سعي واجتهاد\nفلا عجب إذا جاءت بخير … فلولا النحل ما كان الشهاد\nوكيف ، وربها شهم ذكي … له فى كل معضلة جهاد ؟\nتجافى النوم فى طلب المعالى … وطاب لعينه فيها السهاد\nفأصبح وده فى كل قلب … نزيلا ، والقلوب له مهاد"},{"id":"diwan-barudi:139","bookId":"diwan-barudi","type":"poem","seq":139,"chapter":"البحر: كامل تام","title":"أحبب بهن معاهدا ومعانا","page":"","text":"أحبب بهن معاهدا ومعانا … كانت منازلنا بها أحيانا\nدمن عفت بعد الأنيس ، فأصبحت … للجازئات من الظباء مكانا\nولقد نرى فيها ملاعب لم تزل … تشجى الفؤاد ، ولا نرى إنسانا\nعرفت بها الجرد العتاق مجالها … فغدت تحمحم رقة وحنانا\nبتنا بها متساندين على الثرى … نصف الكلال ، ونذكر الإخوانا\nأيام لا يرد الجمام لعزها … أحد ، ولا يرعى الجميم سوانا\nفي معشر رسخت حصاة حلومهم … أدبا ، وخفوا للوغى فرسانا\nقرنوا الشجاعة بالسماحة ، فاغتدوا … قيد المحامد شدة وليانا\nطلعوا على الزمن البهيم ، فأثقبوا … نار الفضائل حجة وبيانا\nمن كل مشبوب تخال لسانه … عند التخاصم في الندي سنانا\nإن قال بر ، وإن أتاه مطرد … آوى ، وإن سئل الكرامة لانا\nأنا منهم ، والعود يتبع أصله … وابن الهجينة لا يكون هجانا\nفاكو الحسود بناظريه ، وقل له : … إن كنت تجهلنا فكيف ترانا ؟\nإنا إذا ما الحرب شب سعيرها … نحمى النزيل ، ونمنع الجيرانا\nونرد عادية الخميس بأنفس … علمت بأن من الحياة هوانا\nفترى عتاق الخيل حول بيوتنا … قب البطون ، تنازع الأرسانا\nمشق الطراد لحومهن ، فلم يدع … إلا خواصر كالقسي متانا\nمن كل منتصب على أقياده … متطلع يتنظر الحدثانا\nبذخت قوائمه ، وأقبل متنه … وانضم كلكله ، وطال عنانا\nفإذا علا حزنا أطار شراره … وإذا أتى سهلا أطار دخانا\nوالخيل أكرم صاحب يوم الوغى … والسلم ، تبعث غارة ورهانا\nفعلى بطون خيارها أرزاقنا … وعلى ظهور جيادها مغدانا\nهذا الفخار ، فدر بعينك حيثما … دار الزمان ، فلن ترى نقصانا"},{"id":"diwan-barudi:140","bookId":"diwan-barudi","type":"poem","seq":140,"chapter":"البحر: مجزوء الكامل","title":"أنا مصدر الكلم النوادي","page":"","text":"أنا مصدر الكلم النوادي … بين الحواضر والبوادي\nأنا فارس ، أنا شاعر … فى كل ملحمة ، ونادى\nفإذا ركبت فإنني … زيد الفوارس في الجلاد\nوإذا نطقت فإننى … قس بن ساعدة الإيادي\nهذا ، وذلك ديدني … في كل معضلة نآد"},{"id":"diwan-barudi:141","bookId":"diwan-barudi","type":"poem","seq":141,"chapter":"البحر: مديد تام","title":"يا قرير العين بالوسن !","page":"","text":"يا قرير العين بالوسن ! … ما الذي ألهاك عن شجني\nكيف لا ترثي لمكتئب … شفه برح من الحزن ؟\nهبك لم تسمع شكاة فمي … أو لم تبصر ضنى بدني ؟\nيا عباد الله ! من لفتى … بيد الأشواق مرتهن ؟\nرعت الأشواق مهجته … وبراه الوجد ؛ فهو ضني\nآه من ظبي خلعت به … في ميادين الهوى رسني\nساحر العينين ما برحت … لحظتاه مصدر الفتن\nسلمت بعض الوشاة به … من نميم الغي في سنن\nصرفوه عن طبيعته … \nصرفوه عن طبيعته … وعنان القلب في الأذن\nوقرين السوء مجلبة … لدواعي الهم والمحن\nفاترك الدنيا ؛ فلست ترى … صاحبا إلا على دخن\nمن جرى في غير حلبته … كان موقوفا على الظنن"},{"id":"diwan-barudi:142","bookId":"diwan-barudi","type":"poem","seq":142,"chapter":"البحر: كامل تام","title":"ومنادم غرد الحديث ، كانما","page":"","text":"ومنادم غرد الحديث ، كانما … ألفاظه فى السمع نغمة عود\nتغني الإشارة منه عن تصريحه … وتدل لفظته على المقصود\nسحر العقول بيانه ، فكأنه … يسقى الجليس سلافة العنقود"},{"id":"diwan-barudi:143","bookId":"diwan-barudi","type":"poem","seq":143,"chapter":"البحر: وافر تام","title":"أطعت الغي في حب الغواني","page":"","text":"أطعت الغي في حب الغواني … ولم أحفل مقالة من نهاني\nوما لي لا أهيم وكل شهم … بحب الغيد مشغوف الجنان ؟\nولي في الأربعين مجال لهو … تنال يدي به عقد الرهان\nفكيف أذود عن نفسي غراما … تضيف مهجتي باسم الحسان\nأبحت له الفؤاد ، فعاث فيه … وحق الضيف إعزاز المكان\nفدعني من ملامك ؛ إن قلبي … أبي لا يقر على الهوان\nفما بالحب عار أتقيه … وإن أخنى على الدمع الزمان\nرضيت من الهوى بنحول جسمي … ومن صلة البخيلة بالأماني\nولست بطالب في الناس خلا … يناصحني ؛ فعقلي قد كفاني\nفإن يكن الهوى قد راض نفسي … فلست لغيره سلس العنان\nأشد من الصخور الصم قلبي … وأرهف من شبا سيفي لساني\nولو كان الغرام يخاف بأسا … أملت إليه كفي بالسنان\nفكم بطل خضبت الأرض منه … بأحمر من دم التأمور قاني\nوما أنا بالذليل أردت ختلا … ولكني أزف إلى الطعان\nولي في ( سرنسوف ) مقام صدق … أقر به إلي الخافقان\nوما أبقت به الأشواق مني … سوى رمق تجول به الأماني\nويسلب أنفس الأبطال سيفي … وتسلب مهجتي حدق الحسان\nفلو برز الحمام إلي شخصا … دلفت إليه بالسيف اليماني"},{"id":"diwan-barudi:144","bookId":"diwan-barudi","type":"poem","seq":144,"chapter":"البحر: منسرح","title":"هل فى التصابى على امرئ فند ؟","page":"","text":"هل فى التصابى على امرئ فند ؟ … أم هل يعيب الفتى الكريم دد ؟\nكل مسوق لما أريد به … ففيم هذا الخصام واللدد ؟\nوأي لوم على امرىء طلب ال … ما شذ عن طبع والد ولد\nولو تساوى الرجال في خلق … لزال هذا الخلاف والحرد\nوالناس شتى وإن هم اجتمعوا … فى واحد ليس قبله أحد\nفزائغ في الضلال منهمك … وناسك في الصلاح مجتهد\nوأى لوم على امرئ طلب ال … لهو وأثواب عمره جدد\nلكل عصر من كبرة وصبا … شوط له بعد مهلة أمد\nفاسع لما شئت غير متئد … فلن يحوز الكمال متئد\nلولا سرى البدر ما استنار ، ولا … أدرك شأو الخطار منجرد\nولا يهمنك لوم ذى حسد … فشأن أهل العداوة الحسد\nلو حذر المرء كل لائمة … لضاع منه الصواب والرشد\nولو أصخنا لكل منتقد … فكل شيء في الدهر منتقد\nواله بما شئت قبل مندمة … يكثر فيها العناء والكمد\nفليس بعد الشباب مقترح … ولا وراء المشيب مفتقد"},{"id":"diwan-barudi:145","bookId":"diwan-barudi","type":"poem","seq":145,"chapter":"البحر: طويل","title":"نعاء عليه أيها الثقلان","page":"","text":"نعاء عليه أيها الثقلان … فقد أقصدته أسهم الحدثان\nمضى ، وأقمنا بعده في مآتم … على الفضل نبكيه بأحمر قاني\nفلا عين إلا وهي بالدمع ثرة … ولا قلب إلا وهو ذو خفقان\nحفاظا وإشفاقا على مترحل … خلت أربع من شخصه ومغاني\nفقدناه فقدان الظماء شرابهم … بديمومة والورد ليس بداني\nفيا للعلى ! كيف استبيح ذمارها … وللفضل إذ يرمى به الرجوان\nلعمري ، لقد هاج الأسى بعد فقده … بنا لوعة لا تنثني بعنان\nضمان على قلبي صيانة عهده … وما خير قلب لا يفي بضمان ؟\nتخلى عن الدنيا ، وأبقى مآثرا … يقر لها بالفضل كل لسان\nفإن يك أودى ، فهو حي بفضله … ومن كان مذكورا فليس بفاني\nوأي امرىء يبقى ؟ ودون بقائه … نهار وليل بالردى يفدلن\nألا قاتل الله الحياة ؛ فإنها … إلى الموت أدنى من فم لبنان\nإذا ما بنانا الدهر ظلت صروفه … تهدمنا ، والدهر أغدر باني\nتخادعنا الدنيا ؛ فنلهو ، ولم نخل … بأن الردى حتم على الحيوان\nإذا ما الأب الأعلى مضى لسبيله … فما لبنيه بالبقاء يدان\nلقد فجعتنا أم دفر - وما درت - … بأروع من نسل النبي هجان\nسليم نواحي الصدر ، لا يستفزه … نزاع إلى البغضاء والشنآن\nيعاشر بالحسنى فإن ريب لم يفه … بسوء ، ولم ترمز له شفتان\nلقد كان خلا لا يشان بغدرة … وصاحب غيب طاهر وعيان\nإذا قال كان القول عنوان فعله … ويا رب قول نافذ كسنان\nخلال يفوح المسك عنها محدثا … ويثنى على آثارها الملوان\nفلا غرو أن تدمى العيون أسافة … عليك ، ويرعى الحزن كل جنان\nفأنت ابن من أحيا البلاد بعلمه … وأبقى له ذكرا بكل مكان\nأفاد بني الأوطان فضلا سموا به … إلى هضبات في العلا وقنان\nوأنت ابنه ، والفرع يتبع أصله … وما منكما إلا جواد رهان\nهو الأول السباق في كل حلبة … وأنت له دون البرية ثاني\nفيا رحمة الله استهلي عليهما … بسجلين للرضوان ينهملان\nوعمى قبور العالمين كرامة … لقبرين بالبطحاء يلتقيان\nعليك سلام الله مني ، تحية … يوافيك في خلد بها الملكان"},{"id":"diwan-barudi:146","bookId":"diwan-barudi","type":"poem","seq":146,"chapter":"البحر: بسيط تام","title":"جاوزت فى اللوم حد القصد ؛ فاتئد","page":"","text":"جاوزت فى اللوم حد القصد ؛ فاتئد … فلست أشفق من نفسى على كبدى\nدعني من اللوم إن كنت امرأ فطنا … فاللوم في الحب معدود من الحسد\nإني لأرضى بما في الحب من ألم … ولست أرضى بما فى القول من فند\nلو كان للمرء عقل يستدل به … على الحقيقة لم يعتب على أحد\nإن كنت ذا إمرة ، فانه الصبابة عن … قلبي ، لتغنم شكري آخر الأبد\nأولا فدعنى ، ولا تعنف على ؛ فما … أمري إلي ، ولا حكم الهوى بيدي\nإن الفتاة التى هام الفؤاد بها … أخفت علي سبيل الحزم والسدد\nأغضبت فى حبها أهلى ، فما برحوا … إلبا على ، وكانوا لى من العدد\nقالوا تعلق بأخرى كى تذود بها … برح الأسى عن فؤاد دائم الكمد\nفقلت : هيهات أن أبغي بها بدلا … لم يخلق الله من قلبين في جسد"},{"id":"diwan-barudi:147","bookId":"diwan-barudi","type":"poem","seq":147,"chapter":"البحر: خفيف تام","title":"أي شيء يبقى على الحدثان ؟","page":"","text":"أي شيء يبقى على الحدثان ؟ … والمنايا خصيمة الحيوان\nقد بلونا كيد الزمان ، ولكن … شغلتنا عنه ضروب الأماني\nفلك ، لا يزال يجري على النا … س بضدين : من علا وهوان\nفهو طورا يكون كالوالد البر … ر ، وطورا كالناقم الغضبان\nليس يبقي على وليد ، ولا كه … ل ، ولا سوقة ، ولا سلطان\nكيف يرجو الإنسان فيه خلودا … بعد ما قد مضى أبو الإنسان\nأين من كان قبلنا منذ داركت … كرة الأرض وهي ذات دخان ؟\nأمم أخلدت إلى الدهر حينا … ثم ضاعت في لجة النسيان\nحصدتها يد المونون ، فصارت … خبرا في الوج بعد عيان\nفترسم معالم الأرض ، واسأل … فسعى أن يجيبك الهرمان\nأثر دل صنعه أن ' هرمي … س بناه من أبدع البنيان )\nخاف ضيع العلوم حين أتته … بينات دلت على الطوفان\nفبناه من الصخور اللواتي … جلبتها القيون من أسوان\nطبقات في جوفها حجرات … ضمنت كل حكمة وبيان\nبقيت بعد صانعيها ؛ فكانت … أثرا ناطقا بغير لسان\nسوف تبلى من بعد حين ، ويمحى … ذكر ' هرميس ' من سجل الزمان\nإنما هذه الحياة غرور … تنقضي بالشقاء والحرمان\nليس فيها سوى خيالات وهم … تمتريها قرائح الأذهان\nخطرات قد ضمنوها كلاما … فلسفيا لم يقترن بمعاني\nكل حي يظن أمرا ، ولكن … أين منه محجة البرهان ؟\nقد عرفنا ما كان منا قريبا … وجهلنا ما لا ترى العينان\nفدع القول في التفلسف ، واخضع … لجلال المهيمن الديان\nأنا يا دهر عالم بمصيري … فيك ، لكنني جموح العنان\nقد تماديت في الغواية حتى … كبح الدهر شرتي ، وثناني"},{"id":"diwan-barudi:148","bookId":"diwan-barudi","type":"poem","seq":148,"chapter":"البحر: وافر تام","title":"قليل من يدوم على الوداد","page":"","text":"قليل من يدوم على الوداد … فلا تحفل بقرب أو بعاد\nإذا كان التغير في الليالي … فكيف يدوم ود في فؤاد ؟\nومن لك أن ترى قلبا نقيا … ولما يخل قلب من سواد ؟\nفلا تبذل هواك إلى خليل … تظن به الوفاء ، ولا تعاد\nوكن متوسطا في كل حال … لتأمن ما تخاف من العناد\nمداراة الرجال أخف وطئا … على الإنسان من حرب الفساد\nيعيش المرء محبوبا إذا ما … نحا فى سيره قصد السداد\nوما الدنيا سوى عجز وحرص … هما أصل الخليقة في العباد\nفلولا العجز ما كان التصافي … ولولا الحرص ما كان التعادي\nوما عقد الرجال الود إلا … لنفع ، أو لمنع من تعادى\nوما كان العداء يخف لولا … أذى السلطان ، أو خوف المعاد\nفيابن أبى ! ولست به ، ولكن … كلانا زرع أرض للحصاد\nتأمل ، هل ترى أثرا ؟ فإني … أرى الآثار تذهب كالرماد\nحياة المرء في الدنيا خيال … وعاقبة الأمور إلى نفاد\nفطوبى لامرىء ، غلبت هواه … بصيرته ؛ فبات على رشاد"},{"id":"diwan-barudi:149","bookId":"diwan-barudi","type":"poem","seq":149,"chapter":"البحر: خفيف تام","title":"لاعب السكر قده ؛ فتثنى","page":"","text":"لاعب السكر قده ؛ فتثنى … ودعاه فرط السرور ؛ فغنى\nرشأ تعبد النواظر منه … واحدا في الجمال ، ليس يثنى\nأنبت الحسن فوق خديه وردا … ليس إلا بغمزة اللحظ يجنى\nلم يزل يرضع السلافة حتى … غاب عنا ، كأنه ليس منا\nفأنمناه فوق مهد وثير … برهة كي يفيق ، ثم انصرفنا\nفلبثنا هنيهة ، ثم لما … خف من سكره وأقبل قمنا\nوأدرنا الكؤوس حتى تولت … أنجم الليل من أحاد ومثنى\nيا لها ليلة ! أبحنا بها الله … وإلى وردة الغداة ، وتبنا"},{"id":"diwan-barudi:150","bookId":"diwan-barudi","type":"poem","seq":150,"chapter":"البحر: طويل","title":"إذا افتقر المرء استهان بفضله","page":"","text":"إذا افتقر المرء استهان بفضله … ذوو قربه ، واستهجنته الأباعد\nفإن قال حقا كذبوه ، وإن أبى … مجاراتهم فى الغى ؛ قالوا معاند\nفحجته مطلولة ؛ وهى حقة … ومنطقه مستكره ، وهو قاصد\nفحافظ على ما نلت بالسعي من غنى … فبالمال لا بالفضل تعنو المقاصد"},{"id":"diwan-barudi:151","bookId":"diwan-barudi","type":"poem","seq":151,"chapter":"البحر: بسيط تام","title":"دار الصديق ، ولا تأمن بوادره","page":"","text":"دار الصديق ، ولا تأمن بوادره … فربما عاد بعد الصدق خوانا\nيفضي بسرك ، أو يسعى بأمرك أو … يقول عنك حديث السوء بهتانا\nفإن تنصلت قالوا فيك معرفة … تنفي المراء مع الود الذي كانا\nوأكثر الخلق مطبوع على ظنن … تقضي عليه بلبس الحق أحيانا\nوقل في الناس من جربته ، فرأى … بين الحقيقة والبهتان فرقانا"},{"id":"diwan-barudi:152","bookId":"diwan-barudi","type":"poem","seq":152,"chapter":"البحر: كامل تام","title":"عود فؤادك أن يكون مجنة","page":"","text":"عود فؤادك أن يكون مجنة … للسر ، فهو لدى المحافل حمده\nالسر عبدك ما استطعت حفاظه … فإذا أفضت به فإنك عبده"},{"id":"diwan-barudi:153","bookId":"diwan-barudi","type":"poem","seq":153,"chapter":"البحر: كامل تام","title":"لا تخش بؤسا من عدو ظاهر","page":"","text":"لا تخش بؤسا من عدو ظاهر … واخش المكيدة من عدو باطن\nكم بين شر ظاهر مستدرك … منه الخلاص وبين سر باطن"},{"id":"diwan-barudi:154","bookId":"diwan-barudi","type":"poem","seq":154,"chapter":"البحر: سريع","title":"وصاحب لا كان من صاحب","page":"","text":"وصاحب لا كان من صاحب … أخلاقه كالمعدة الفاسده\nأقبح ما في الناس من خصلة … أحسن ما في نفسه الجامده\nلو أنه صور من طبعه … كان لعمرى عقربا راصده\nيصلح للصفع لكى لا يرى … في عدد الناس بلا فائده\nيغلبه الضعف ، ولكنه … يهدم فى قعدته المائده\nيراقب الصحن على غفلة … من أهله كالهرة الصائده\nكأنما أظفوره منجل … وبين فكيه رحى راعده\nكأنما البطة فى حلقه … نعامة فى سبسب شارده\nتسمع للبلع نقيقا ، كما … نقت ضفاى ليلة راكده\nكأنما أنفاسه حرجف … وبين جنبيه لظى واقده\nويلمه إذ مخضت ، هل درت … أن الردى فى بطنها العاقده ؟\nتبا لها شنعاء جاءت به … من لقحة في فقحة كاسده\nلا رحمة الله على والد … غم به الدنيا ، ولا والده"},{"id":"diwan-barudi:155","bookId":"diwan-barudi","type":"poem","seq":155,"chapter":"البحر: بسيط تام","title":"قد عاقني الشك في أمر أضعت له","page":"","text":"قد عاقني الشك في أمر أضعت له … عزيمة الرأي حتى ضاق كتماني\nأوليتني منك ودا قبل معرفة … ثم انثنيت بصد قبل إعلان\nفسرني منك ما قدمت مبتدأ … وساءني منك ما أخرت في الثاني\nفإن يكن سوء رأي ، أو ملال هوى … فإن كلتيهما في القبح سيان\nفاكشف لنا عن قناع الشك نحى به … إما وصالا ، وإما محض هجران"},{"id":"diwan-barudi:156","bookId":"diwan-barudi","type":"poem","seq":156,"chapter":"البحر: بسيط تام","title":"وشامخ فى ذرا شماء باذخة","page":"","text":"وشامخ فى ذرا شماء باذخة … لا يعرف الصدق إن والى وإن عادى\nيعوده الناس إن مر النسيم به … ولا يعود من الإشفاق من عادا\nلا يهدا الدهر من ظلم يحاوله … فإن قضى وطرا من غدرة عادا\nيسطو بهذا ، ويرمي ذاك عن عرض … كطارد يقتفي صيدين إذ عادى\nأباده الدهر رغما بين أسرته … كما أباد بريح صرصر عادا\nفاعرف إلهك ، واحذر أن تبيت على … وزر ، ولا تتخذ ظلم الورى عادا"},{"id":"diwan-barudi:157","bookId":"diwan-barudi","type":"poem","seq":157,"chapter":"البحر: خفيف تام","title":"أول النفس نطفة أخلصتها","page":"","text":"أول النفس نطفة أخلصتها … شهوة صاغها مزاج دفين\nقذفتها إلى البطون ظهور … وحوتها بعد الظهور بطون\nثم أرسى بها هبوط يليه … حركات من بعدهن سكون\nفهي طورا تكون في عالم الغي … ب ، وطورا في مثل ذاك تكون\nمبتداها ومنتهاها سواء … وهي ما بين ذاك حي مهين\nفعلام البكاء في إصر دار … بالرزايا فناؤها مشحون ؟\nتتقانى الرجال حرصا عليها … وهو حرص أدى إليه الجنون\nحار فيها ( أرسططاليس ) قدما … ونعاها الحكيم ( أفلاطون )"},{"id":"diwan-barudi:158","bookId":"diwan-barudi","type":"poem","seq":158,"chapter":"البحر: سريع","title":"يأيها الظالم فى ملكه","page":"","text":"يأيها الظالم فى ملكه … أغرك الملك الذي ينفد ؟\nاصنع بنا ما شئت من قسوة … فالله عدل ، والتلاقي غد"},{"id":"diwan-barudi:159","bookId":"diwan-barudi","type":"poem","seq":159,"chapter":"البحر: وافر تام","title":"وملمس عفة قد نلت منه","page":"","text":"وملمس عفة قد نلت منه … بأيدي اللهو ما شاء التمني\nملكت به عنان الشوق ؛ حتى … قضيت لبانتي ، وأرحت ظني\nفلا تسأل على ما كان منه … ولا تسأل على ما كان مني\nفلولا أن جند الصبح وافت … طلائعه وزال الليل عني\nلدمت على معاقرة الأماني … ولكن ربما عاودت فني"},{"id":"diwan-barudi:160","bookId":"diwan-barudi","type":"poem","seq":160,"chapter":"البحر: منسرح","title":"يا من إليه الوجوه خاشعة","page":"","text":"يا من إليه الوجوه خاشعة … ومن عليه في الكون معتمدى\nمددت كفى إليك مبتهلا … وأنت حسبي ، فلا ترد يدي"},{"id":"diwan-barudi:161","bookId":"diwan-barudi","type":"poem","seq":161,"chapter":"البحر: بسيط تام","title":"يا راحلا ! غاب صبري بعد فرقته","page":"","text":"يا راحلا ! غاب صبري بعد فرقته … وأصبحت أسهم الأشواق تصميني\nإن كان يرضيك ما ألقاه من كمد … في الحب مذ غبت عني ، فهو يرضيني\nلم ألق بعدك يوما أستبين به … وجه المسرة إلا ظل يبكيني\nقد كنت لا أكتفي بالشمل مجتمعا … فاليوم نظرة عين منك تكفيني"},{"id":"diwan-barudi:162","bookId":"diwan-barudi","type":"poem","seq":162,"chapter":"البحر: مجزوء الكامل","title":"لاعيش الا للنفاد","page":"","text":"لاعيش الا للنفاد … فاحبب حياتك ، أو فعاد\nوابخل بنفسك ، أو فجد … كل الأمور إلى فساد\nأين الألى شقوا البحو … ر ، وشيدوا ذات العماد ؟\nملكوا التهائم والنجا … ئد والحواضر والبوادى\nبل أين أصحاب الوفو … د ؟ وأين أرباب الجلاد ؟\nالطاعمون ، الطاعنو … ن القائلون بكل نادي\nالكاشفون الضر ، وال … عافون عن ذنب العباد\nبل أين صناع القري … ض الجزل والكلم الفراد ؟\nكالشاعر الضليل ، أو … قس بن ساعدة الإيادي\nلعب الزمان بجمعهم … ورمى بهم فى كل وادى\nفكأنهم لم يلبثوا … إلا بياضا في سواد"},{"id":"diwan-barudi:163","bookId":"diwan-barudi","type":"poem","seq":163,"chapter":"البحر: خفيف تام","title":"إن لي صاحبا ، ولا بد منه","page":"","text":"إن لي صاحبا ، ولا بد منه … قل صبري به ، وزادت شجوني\nأحمق ، لا يكاد يفقه قولا … من حديث ، والحمق نصف الجنون"},{"id":"diwan-barudi:164","bookId":"diwan-barudi","type":"poem","seq":164,"chapter":"البحر: طويل","title":"بلينا وسربال الزمان جديد","page":"","text":"بلينا وسربال الزمان جديد … وهل لامرىء في العالمين خلود ؟\nقضى آدم فى الدهر ، وهو أبو الورى … وكل الذى من صلبه سيبيد\nفلا تبكى ميتا حان يوم رحيله … فللموت ما يمضي الفتى ويرود\nولا تلتمس أمرا يزيدك يقظة … فليس لإدراك اليقين مزيد\nدع الفلك الدوار يجري ، ولا تسل … أفوز كهل أم أهل وليد ؟\nفما هذه الدنيا وإن جل قدرها … سوى مهلة نأتى لها ونعود\nتبوخ بها الأنفاس وهى نسائم … وتعفو بها الأبدان وهي صعيد\nفيا ضاربا فى الأرض يرتاد غاية … رويدك ، إن الفوز منك بعيد"},{"id":"diwan-barudi:165","bookId":"diwan-barudi","type":"poem","seq":165,"chapter":"البحر: بسيط تام","title":"إذا أتاك خليل بعد مندمة","page":"","text":"إذا أتاك خليل بعد مندمة … منه على ما مضى من زلة ، فهن\nوإن صفحت فلا تعرض بمعتبة … فالعتب يفسد ما قدمت من حسن"},{"id":"diwan-barudi:166","bookId":"diwan-barudi","type":"poem","seq":166,"chapter":"البحر: طويل","title":"دع الذل في الدنيا لمن خاف حتفه","page":"","text":"دع الذل في الدنيا لمن خاف حتفه … فللموت خير من حياة على أذى\nولا تصطحب إلا امرأ إن دعوته … لدى جمرات الحرب ، لباك واحتذى\nيسرك عند الأمن فضلا وحكمة … ويرضيك يوم الروع نبلا مقذذا\nفيا حبذا الخل الصفي ! وهل أرى … نصيبا من الدنيا إذا قلت حبذا ؟\nلعمرى لقد ناديت ، لو أن سامعا … ونوهت بالأحرار ، لو أن منقذا\nوطوفت بالآفاق ، حتى كأنني … أحاول من هذى البسيطة منفذا\nفما وقعت عيني على غير أحمق … غوى ، يظن المجد فى الرى والغذا\nإذا ما رأيت الشئ فى غير أهله … ولم أستطع ردا ، طرفت على قذى\nفحتى متى يا دهر أكتم لوعة … تكلف قلبي كلفة الريح بالشذا ؟\nألم يأن للأيام أن تبصر الهدى … فتخفض مأفونا ، وترفع جهبذا ؟\nإذا لم يكن بالدهر خبل لما غدا … يسير بنا فى ظلمة الجور هكذا"},{"id":"diwan-barudi:167","bookId":"diwan-barudi","type":"poem","seq":167,"chapter":"البحر: مخلع البسيط","title":"أحبب ، وأبغض ، وقل بحق","page":"","text":"أحبب ، وأبغض ، وقل بحق … ولا تساهل ، ولا تخاشن\nفالحب يعمى عن المساوى … والبغض يعمي عن المحاسن"},{"id":"diwan-barudi:168","bookId":"diwan-barudi","type":"poem","seq":168,"chapter":"البحر: متقارب تام","title":"تغنى الحمام ، ونم الشذا","page":"","text":"تغنى الحمام ، ونم الشذا … ولاح الصباح ، فيا حبذا !\nوما زال يرضع طفل النبات … ثدي الغمامة حتى اغتذى\nفقم نغتنم صفو أيامنا … وندفع بالراح عنا الأذى\nفما بعد عصر الصبا لذة … ولا مثل صفو الحميا غذا\nتذود عن القلب أحزانه … وتنفي عن العين شوب القذى\nوتجلو الظلام بلألائها … كأن بأيدى السقاة الجذا\nإذا ما احتساها كريم هدى … وإن عب فيها لئيم هذى\nفدع ما تولى ، وخذ ما أتى … فلن يصلح العيش إلا كذا"},{"id":"diwan-barudi:169","bookId":"diwan-barudi","type":"poem","seq":169,"chapter":"البحر: كامل تام","title":"لا تعكفن على المدام بعير ما","page":"","text":"لا تعكفن على المدام بعير ما … صوت يهيج بلحنه الندمانا\nإن الغناء سريرة في النفس قد … ضاقت بها ؛ فتفجرت ألحانا"},{"id":"diwan-barudi:170","bookId":"diwan-barudi","type":"poem","seq":170,"chapter":"البحر: طويل","title":"رمت بخيوط النور كهربة الفجر","page":"","text":"رمت بخيوط النور كهربة الفجر … ونمت بأسرار الندى شفة الزهر\nوسارت بأنفاس الخمائل نسمة … بليلة مهوى الذيل ، عاطرة النشر\nفقم نغتنم صفو البكور ، فإنها … غداة زهرها باسم الثغر\nترى بين سطح الأرض والجو نسبة … تشاكل ما بين السحائب والغدر\nففى الجو هتان يسيل ، وفى الثرى … سيول ترامى بين أودية غزر\nغمامان فياضان : هذا بأفقه … يسير ، وهذا في طباق الثرى يسري\nوقد ماجت الأغصان بين يد الصبا … كما رفرفت طير بأجنحة خضر\nكأن الندى فوق الشقيق مدامع … تجول بخد ، أو جمان على تبر\nإذا غازلتها لمعة ذهبية … من الشمس رفت كالشرار على الجمر\nففى كل مرعى لحظة وشى ديمة … وفى كل مرمى خطوة أجرع مثرى\nمروج جلاها الزهر ، حتى كأنها … سماء تروق العين بالأنجم الزهر\nكأن صحاف النور والطل جامد … مباسم أصداف تبسمن عن در\nوقد شاقنى والصبح فى خدر أمه … حنين حمامات تجاوبن في وكر\nهتفن فأطربن القلوب ، كأنما … تعلمن ألحان الصبابة من شعرى\nوقام على الجدران أعرف لم يزل … يبدد أحلام النيام ولا يدرى\nتخايل فى موشية عبقرية … مهدلة الأردان سابغة الأزر\nله كبرة تبدو عليه ، كأنه … مليك عليه التاج ينظر عن شزر\nفسارع إلى داعي الصبوح مع الندى … لنجم بأيدى اللهو باكورة العمر\nفقد نسمت ريح الشمال ، فنبهت … عيون القمارى وهى فى سنة الفجر\nونادى المنادي للصلاة بسحرة … فأحيا الورى من بعد طي إلى نشر\nفبادر لميقات الصلاة ، ومل بنا … إلى القصف ما بين الجزيرة والنهر\nإذا ما قضينا واجب الدين حقه … فليس علينا في الخلاعة من وزر\nألا رب يوم كان تاريخ صبوة … مضى غير إثر فى المخيلة أو ذكر\nعصيت به سلطان حلمي ، وقادني … إلى اللهو شيطان الخلاعة والسكر\nلدى روضة ريا الغصون ، ترنحت … معاطفها رقصا على نغمة القمري\nتدور علينا بالمدامة بينها … تماثيل ، إلا أنها بيننا تجرى\nترى كل ميلاء الخمار من الصبا … هضيمة مجرى البند ، ناهدة الصدر\nإذا انفتلت في حاجة خلت جؤذرا … أحس بصياد فأتلع من ذعر\nلوى قدها سكر الخلاعة والصبا … فمالت بشطر ، واستقامت على شطر\nوعلمها وحى الدلال كهانة … فإن نطقت جاءت بشئ من السحر\nأحست بما فى نفسها من ملاحة … فتاهت علينا ، والملاحة قد تغري\nوأعجبها وجدي بها ، فتكبرت … علي دلالا ، وهي تصدر عن أمري\nفتاة يجول السحر في لحظاتها … مجال المنايا في المهندة البتر\nإذا نظرت ، أو أقبلت ، أو تهللت … فويل مهاة الرمل ، والغصن ، والبدر\nفما زلن يغرين الطلا بعقولنا … إلى أن سقطنا لليدين وللنحر\nفمن واقع يهذي ، وآخر ذاهل … له جسد ما فيه روح سوى الخمر\nصريع يظن الشهب منه قريبة … فيسدو بكفيه إلى مطلع النسر\nإذا ما دعوت المرء دار بلحظه … إليك ، وغشاه الذهول عن الجهر\nبعيد عن الداعى وإن كان حاضرا … كأن به بعض الهنات من الوقر\nتحكمت الصهباء فيهم ، فغيرت … شمائل ما يأتى به الجد بالهذر\nفيا سامح الله الشباب وإن جنى … على ، وحيا عهده سبل القطر\nملكت به أمرى ، وجاريت صبوتى … وأصبحت مرهوب الحمية والكبر\nإذا أبصروني في الندي تحاجزوا … عن القول ، واستغنوا عن العرف بالنكر\nوقالوا فتى مالت به نشوة الصبا … وليس على الفتيان فى اللهو من حجر\nيخافون منى أن تثور حميتى … فيبغون عطفى بالخديعة والمكر\nألا ليت هاتيك الليالي وقد مضت … تعود ، وذاك العيش يأتى على قدر\nمواسم لذات تقضت ، ولم يزل … لها أثر يطوى الفؤاد على أثر\nإذا اعتورتها ذكرة النفس أبصرت … لها صورة تختال فى صفحة الفكر\nفذلك عصر قد مضى لسبيله … وخلفنى أرعى الكواكب فى عصر\nلعمرك ما في الدهر أطيب لذة … من اللهو في ظل الشبيبة واليسر"},{"id":"diwan-barudi:171","bookId":"diwan-barudi","type":"poem","seq":171,"chapter":"البحر: بسيط تام","title":"خفض عليك ، ولا تجزع لنائبة","page":"","text":"خفض عليك ، ولا تجزع لنائبة … فالدهر يعتر بالإنسان أحيانا\nفكل ناء قريب إن صبرت له … وكل صعب إذا قاومته هانا"},{"id":"diwan-barudi:172","bookId":"diwan-barudi","type":"poem","seq":172,"chapter":"البحر: طويل","title":"بناظرك الفتان آمنت بالسحر","page":"","text":"بناظرك الفتان آمنت بالسحر … وهل بعد إيمان الصبابة من كفر ؟\nفلا تعتمد بالهجر قتل متيم … فإن المنايا لا تزيد عن الهجر\nفلولاك ما حل الهوى قيد مدمعى … ولا شب نيران اللواعج في صدري\nوإنى على ما كان منك لصابر … لعلمى أن الفوز من ثمر الصبر\nفليت الذى أهدى الملامة فى الهوى … توسم خيرا ، أو تكلم عن خبر\nرأى كلفي لا يستفيق ، فظن بي … هنات ، وسوء الظن داعية الوزر\nوماذا عليه وهو خال من الجوى … إذا همت شوقا ، أو ترنمت بالشعر ؟\nفإن أك مشغوفا فذو الحلم ربما … أطاع الهوى ، والحب من عقد السحر\nوأي امرىء يقوى على رد لوعة … إذا التهبت أربت على وهج الجمر ؟\nعلى أنني لم آت في الحب زلة … تغض بذكرى فى المحافل أو تزرى\nولكنني طوفت في عالم الصبا … وعدت ولم تعلق بفاضحة أزرى\nسجية نفس آثرت ما يسرها … وللناس أخلاق على وفقها تجري\nملكت يدى عن كل سوء ومنطقى … فعشت برئ النفس من دنس العذر\nوأحسنت ظنى بالصديق ، وربما … لقيت عدوي بالطلاقة والبشر\nفأصبحت مأثور الخلال محببا … إلى الناس ، مرضي السريرة ف\nفما أنا مطلوب بوتر لمعشر … ولا أنا ملهوف الجنان على وتر\nرضيت من الدنيا وإن كنت مثريا … بعفة نفس لا تميل إلى الوفر\nوأخلصت للرحمن فيما نويته … فعاملنى باللطف من حيث لا أدرى\nإذا ما أراد الله خيرا بعبده … هداه بنور اليسر فى ظلمة العسر\nفيابن أبى والناس أبناء واحد … تقلد وصاتى ، فهى لؤلؤة الفكر\nإذا شئت أن تحيا سعيدا فلا تكن … لدودا ، ولا تدفع يد اللين بالقسر\nولاتحتقر ذا فاقة ، فلربما … لقيت به شهما يبر على المثرى\nفرب فقير يملأ القلب حكمة … ورب غنى لا يريش ولا يبرى\nوكن وسطا ، لا مشرئبا إلى السها … ولا قانعا يبغي التزلف بالصغر\nفأحمد أخلاق الفتى ما تكافأت … بمنزلة بين التواضع والكبر\nولا تعترف بالذل في طلب الغنى … فإن الغنى في الذل شر من الفقر\nوإياك والتسليم بالغيب قبل أن … ترى حجة تجلو بها غامض الأمر\nودار الذي ترجو وتخشى وداده … وكن من مودات القلوب على حذر\nفقد يغدر الخل الوفي لهفوة … ويحلو الرضا بعد العداوة والشر\nوفى الناس من تلقاه فى زى عابد … وللغدر في أحشائه عقرب تسري\nإذا أمكنته فرصة نزعت به … إلى الشر أخلاق نبتن على غمر\nولا تحسبن الحلم يمنع أهله … وقوع الأذى ، فالماء والنار من صخر\nفهذي وصاتي ، فاحتفظها تفز بما … تمنيت من نيل السعادة في الدهر\nفإنى امرؤ جربت دهرى ، وزادنى … به خبرة صبري على الحلو والمر\nبلغت مدى خمسين ، وازددت سبعة … جعلت بها أمشي على قدم الخضر\nفكيف ترانى اليوم أخشى ضلالة … وشيبى مصباح على نوره أسرى ؟\nأقول بطبع لست أحتاج بعده … إلى المنهل المطروق ، والمنهج الوعر\nولي من جناني إن عزمت ومقولي … سراج وعضب ، ذا يضئ ، وذا يفرى\nإذا جاش طبعي فاض بالدر منطقي … ولا عجب ، فالدر ينشأ في\nتدبر مقالي إن جهلت خليقتي … لتعرفني ، فالسيف يعرف بالأثر\nولا تعجبن من منطقي إن تأرجت … به كل أرض ، فهو ريحانة العصر\nسيذكرني بالشعر من لم يلاقني … وذكر الفتى بعد الممات من العمر"},{"id":"diwan-barudi:173","bookId":"diwan-barudi","type":"poem","seq":173,"chapter":"البحر: طويل","title":"أبى الشوق إلا أن يحن ضمير","page":"","text":"أبى الشوق إلا أن يحن ضمير … وكل مشوق بالحنين جدير\nوهل يستطيع المرء كتمان لوعة … ينم عليها مدمع وزفير ؟\nخضعت لأحكام الهوى ، ولطالما … أبيت فلم يحكم علي أمير\nأفل شباة الليث وهو مناجز … وأرهب لحظ الرئم وهو غرير\nويجزع قلبي للصدود ، وإنني … لدى البأس إن طاش الكمى صبور\nوما كل من خاف العيون يراعة … ولا كل من خاض الحتوف جسور\nولكن لأحكام الهوى جبرية … تبوخ لها الأنفاس وهى تفور\nوإنى على ما كان من سرف الهوى … لذو تدرإ في النائبات مغير\nيرافقنى عند الخطوب إذا عرت … جواد ، وسيف صارم ، وجفير\nويصحبني يوم الخلاعة والصبا … نديم ، وكأس رية ، ومدير\nفطورا لفرسان الصباح مطارد … وطورا لإخوان الصفاء سمير\nويا رب حي قد صبحت بغارة … تكاد لها شم الجبال تمور\nوليل جمعت اللهو فيه بغادة … لها نظرة تسدى الهوى وتنير\nعقلنا به ما ند من كل صبوة … وطرنا مع اللذات حيث تطير\nوقلنا لساقينا أدرها ، فإنما … بقاء الفتى بعد الشباب يسير\nفطاف بها شمسية ذهبية … لها عند ألباب الرجال ثئور\nإذا ما شربناها أقمنا مكاننا … وظلت بنا الأرض الفضاء تدور\nإلى أن أماط الليل ثني لثامه … وكادت أسارير الصباح تنير\nونبهنا وقع الندى فى خميلة … لها من نجوم الأقحوان ثغور\nتناغت بها الأطيار حين بدا لها … من الفجر خيط كالحسام طرير\nفهن إلى ضوء الصباح نواظر … وعن سدفة الليل المجنح زور\nخوارج من أيك ، دواخل غيره … زهاهن ظل سابغ وغدير\nتوسد هامات لهن وسائدا … من الريش فيه طائل وشكير\nكأن على أعطافها من حبيكها … تمائم لم تعقد لهن سيور\nإذا ضاحكتها الشمس رفت ، كأنما … على صفحتيها سندس وحرير\nفلما رأيت الليل ولى ، وأقبلت … طلائع من خيل الصباح تغير\nذهبت أجر الذيل تيها ، وإنما … يتيه الفتى إن عف وهو قدير\nولي شيمة تأبى الدنايا ، وعزمة … تفل شباة الخطب وهو عسير\nمعودة ألا تكف عنانها … عن الجد إلا أن تتم أمور\nلها من وراء الغيب أذن سميعة … وعين ترى ما لا يراه بصير\nوإنى امرؤ صعب الشكيمة بالغ … بنفسى شأوا ليس فيه نكير\nوفيت بما ظن الكرام فراسة … بأمري ، ومثلي بالوفاء جدير\nفما أنا عما يكسب العز ناكب … ولا عند وقع المحفظات حسير\nإذا صلت كف الدهر من غلوائه … وإن قلت غصت بالقلوب صدور\nملكت مقاليد الكلام ، وحكمة … لها كوكب فخم الضياء منير\nفلو كنت في عصر الكلام الذي انقضى … لباء بفضلي ( جرول و\nجرير ) )7 ( ولو كنت أدركت النواسى لم يقل … أجارة بيتينا أبوك غيور\nوما ضرني أني تأخرت عنهم … وفضلى بين العالمين شهير\nفيا ربما أخلى من السبق أول … وبد الجياد السابقات أخير"},{"id":"diwan-barudi:174","bookId":"diwan-barudi","type":"poem","seq":174,"chapter":"البحر: وافر تام","title":"وذي وجهين ، تلقاه طليقا","page":"","text":"وذي وجهين ، تلقاه طليقا … محياه ، وباطنه حزين\nيعاطيك المنى بلحاظ ريم … وبين ضلوعه ضب كمين"},{"id":"diwan-barudi:175","bookId":"diwan-barudi","type":"poem","seq":175,"chapter":"البحر: طويل","title":"تلاهيت إلا ما يجن ضمير","page":"","text":"تلاهيت إلا ما يجن ضمير … وداريت إلا ما ينم زفير\nوهل يستطيع المرء كتمان أمره … وفى الصدر منه بارح وسعير ؟\nفيا قاتل الله الهوى ، ما أشده … على المرء إذ يخلو به فيغير !\nتلين إليه النفس وهى أبية … ويجزع منه القلب وهو صبور\nنبذت له رمحي ، وأغمدت صارمي … ونهنهت مهري ، والمراد غزير\nوأصبحت مفلول المخالب بعدما … سطوت ولى فى الخافقين زئير\nفيا لسراة القوم ! دعوة عائذ … أما من سميع فيكم فيجير ؟\nلطال علي الليل حتى مللته … وعهدى به فيما علمت قصير\nألا ، فرعى الله الصبا ، ما أبره ! … وحيا شبابا مر وهو نضير\nإذ العيش أفواف ، ترف ظلاله … علينا ، وسلسال الوفاء نمير\nوإذ نحن فيما بين إخوان لذة … على شيم ما إن بهن نكير\nتدور علينا الكأس بين ملاعب … بها اللهو خدن ، والشباب سمير\nفألحاظنا بين النفوس رسائل … وريحاننا بين الكئوس سفير\nعقدنا جناحى ليلنا بنهارنا … وطرنا مع اللذات حيث تطير\nوقلنا لساقينا أدرها ، فإنما … بقاء الفتى بعد الشباب يسير\nفطاف بها شمسية لهبية … لها عند ألباب الرجال ثئور\nإذا ما شربناها أقمنا مكاننا … وظلت بنا الأرض الفضاء تدور\nوكم ليلة أفنيت عمر ظلامها … إلى أن بدا للصبح فيه قتير\nشغلت بها قلبي ، ومتعت ناظري … ونعمت سمعى والبنان طهور\nصنعت بها صنع الكريم بأهله … وجيرته ، والغادرون كثير\nفما راعنا إلا حفيف حمائم … لها بين أطراف الغصون هدير\nتجاوب أترابا لها في خمائل … لهن بها بعد الحنين صفير\nنواعم لا يعرفن بؤس معيشة … ولا دائرات الدهر كيف تدور\nتوسد هامات لهن وسائدا … من الريش فيه طائل وشكير\nكأن على أعطافها من حبيكها … تمائم لم تعقد لهن سيور\nخوارج من أيك ، دواخل غيره … زهاهن ظل سابغ وغدير\nإذا غازلتها الشمس رفت ، كأنما … على صفحتيها سندس وحرير\nفلما رأيت الصبح قد رف جيده … ولم يبق من نسج الظلام ستور\nخرجت أجر الذيل تيها ، وإنما … يتيه الفتى إن عف وهو قدير\nولي شيمة تأبى الدنايا ، وعزمة … ترد لهام الجيش وهو يمور\nإذا سرت فالأرض التي نحن فوقها … مراد لمهرى ، والمعاقل دور\nفلا عجب إن لم يصرنى منزل … فليس لعقبان الهواء وكور\nهمامة نفس ليس ينقى ركابها … رواح على طول المدى وبكور\nمعودة ألا تكف عنانها … عن الجد إلا أن تتم أمور\nلها من وراء الغيب أذن سميعة … وعين ترى ما لا يراه بصير\nوفيت بما ظن الكرام فراسة … بأمري ، ومثلي بالوفاء جدير\nوأصبحت محسود الجلال ، كأنني … على كل نفس فى الزمان أمير\nإذا صلت كف الدهر من غلوائه … وإن قلت غصت بالقلوب صدور\nملكت مقاليد الكلام ، وحكمة … لها كوكب فخم الضياء منير\nفلو كنت في عصر الكلام الذي انقضى … لباء بفضلي ( جرول و\nجرير ) ) 4( ولو كنت أدركت ' النواسى ' لم يقل … أجارة بيتينا أبوك غيور\nوما ضرني أني تأخرت عنهم … وفضلى بين العالمين شهير\nفيا ربما أخلى من السبق أول … وبذ الجياد السابقات أخير"},{"id":"diwan-barudi:176","bookId":"diwan-barudi","type":"poem","seq":176,"chapter":"البحر: طويل","title":"حويت من السوءات ما لو طرحته","page":"","text":"حويت من السوءات ما لو طرحته … على الشمس لم تطلع بكل مكان\nوما ترك الهاجون فيك بقية … يدور عليها في الهجاء لساني"},{"id":"diwan-barudi:177","bookId":"diwan-barudi","type":"poem","seq":177,"chapter":"البحر: بسيط تام","title":"أضوء شمس فرى سربال ديجور","page":"","text":"أضوء شمس فرى سربال ديجور … أم نور عيد بعقد التاج مشهور ؟\nوأنجم تلك أم فرسان عادية … تختال في موكب ك\nمن كل أروع يجلو ظل عثيره … بصارم كلسان النار مسعور\nلا يرهبون عدوا في مغاورة … وكيف يرهب ليث كر يعفور ؟\nمستوفزون لوحى من لدن ملك … بادي الوقار على الأعداء منصور\nفي دولة بلغت بالعدل منزلة … علياء كالشمس في بعد ، وفي نور\nطلعت فيها طلوع البدر ، فازدهرت … أقطارها بضياء منك منشور\nفليفخر التاج إذ دارت معاقده … على جبين بنور السعد مغمور\nكأنما صاغ كف الأفق أنجمه … للبدر ما بين منظوم ومنثور\nفيالها حفلة للملك ! ما برحت … تاريخ مجد بكف الدهر مسطور\nظلت بها حدق الأملاك شاخصة … إلى مهيب بفضل الحلم مشكور\nفكم أمير بحسن الحظ مبتهج … وكم وزير بكأس البشر مخمور\nفالأرض في فرح ، والدهر في مرح … والناس ما بين تهليل وتكبير\nفى كل مملكة تيار كهربة … يسرى ، وفى كل ناد صوت تبشير\nيوم به طنت الأسماع من طرب … كأن فى كل أذن سلك طنبور\nوكيف لا تبلغ الأفلاك دولة من … أضحى به العدل حلا غير محظور ؟\nهو المليك الذي لولا مآثره … ما كان في الدهر يسر بعد معسور\nفل النوائب ، فانصاحت دياجرها … بمرهف من سيوف الرأى مأثور\nوأصلحت عنت الأيام حكمته … من بعد ما كان صدعا غير مجبور\nمسدد الرأى ، موقوف الظنون على … رعى السياسة فى ثبت وتحوير\nلا يغمد السيف إلا بعد ملحمة … ولا يعاقب إلا بعد تحذير\nيأيها المالك الميمون طائره … أبشر بفتح عظيم القدر منظور\nإن الخطوب التي ذللت جانبها … بحسن رأيك لم تقدر لمقدور\nبلغت بالشرق ما أملت من وطر … ونلت بالغرب حقا غير منكور\nفمن يباريك في فضل ومكرمة ؟ … ومن يدانيك فى حزم وتدبير ؟\nلولاك ما دام ظل السلم ، وانحسرت … ضبابة الحرب إلا بعد تغرير\nولا سرى الأمن بعد الخوف ، واعتصمت … بجانب الصبر همات المغاوير\nفاسلم لملك منيع السرح تكلؤه … بعين ذي لبد ، في الغاب محذور\nواقبل هدية فكر قد تكنفها … روع الخجالة من عجز وتقصير\nوسمتها ب سمك العالي ، فألبسها … جلباب فخر طويل الذيل مجرور\nلولا صفاتك وهي الدر ما بهرت … أبياتها الغر من حسن وتحبير\nشمائل زينت قولى برونقها … كالسحر يفتن بين الأعين الحور\nشفت زجاجة فكري ، فارتسمت بها … علياك من منطقي في لوح تصوير\nفاسعد بيوم تجلى السعد فيه على … نادي علاك بتعظيم وتوقير\nودم على الدهر في ملك تعيش به … مرفه النفس حتى نفخة الصور"},{"id":"diwan-barudi:178","bookId":"diwan-barudi","type":"poem","seq":178,"chapter":"البحر: وافر تام","title":"إذا ما المرء أعقب ، ثم أودى","page":"","text":"إذا ما المرء أعقب ، ثم أودى … تعادل فهو موجود وفاني\nوما الدنيا سوى أخذ ورد … وهدم ناب عنه بناء باني"},{"id":"diwan-barudi:179","bookId":"diwan-barudi","type":"poem","seq":179,"chapter":"البحر: طويل","title":"طربت ، وعادتنى المخيلة والسكر","page":"","text":"طربت ، وعادتنى المخيلة والسكر … وأصبحت لا يلوي بشيمتي الزجر\nكأني مخمور سرت بلسانه … معتقة مما يضن بها التجر\nصريع هوى ، يلوي بي الشوق كلما … تلألأ برق ، أو سرت ديم غزر\nإذا مال ميزان النهار رأيتني … على حسرات لا يقاومها صبر\nيقول أناس إنه السحر ضلة … وما هي إلا نظرة دونها السحر\nفكيف يعيب الناس أمري ، وليس لي … ولا لامرىء في الحب نهي ولا أمر ؟\nولو كان مما يستطاع دفاعه … لألوت به البيض المباتير والسمر\nولكنه الحب الذي لو تعلقت … شرارته بالجمر لاحترق الجمر\nعلى أنني كاتمت صدري حرقة … من الوجد لا يقوى على حملها صدر\nوكفكفت دمعا ، لو أسلت شئونه … على الأرض ما شك امرؤ أنه\nحياء وكبرا أن يقال ترجحت … به صبوة ، أو فل من غربه الهجر\nوإنى امرؤ لولا العوائق أذعنت … لسلطانه البدو المغيرة والحضر\nمن النفر الغر الذين سيوفهم … لها في حواشي كل داجية فجر\nإذا استل منهم سيد غرب سيفه … تفزعت الأفلاك ، والتفت الدهر\nلهم عمد مرفوعة ، ومعاقل … وألوية حمر ، وأفنية خضر\nونار لها في كل شرق ومغرب … لمدرع الظلماء ألسنة حمر\nتمد يدا نحو السماء خضيبة … تصافحها الشعرى ، ويلثمها الغفر\nوخيل يعم الخافقين صهيلها … نزائع معقود بأعرافها النصر\nمعودة قطع الفيافى ، كأنها … خدارية فتخاء ، ليس لها وكر\nأقاموا زمانا ، ثم بدد شملهم … ملول من الأيام ، شيمته الغدر\nفلم يبق منهم غير آثار نعمة … تضوع برياها الأحاديث والذكر\nوقد تنطق الآثار وهي صوامت … ويثنى برياه على الوابل الزهر\nلعمرك ما حي وإن طال سيره … يعد طليقا والمنون له أسر\nوما هذه الأيام إلا منازل … يحل بها سفر ، ويتركها سفر\nفلا تحسبن المرء فيها بخالد … ولكنه يسعى ، وغايته العمر"},{"id":"diwan-barudi:180","bookId":"diwan-barudi","type":"poem","seq":180,"chapter":"البحر: وافر تام","title":"كتمت هواك حتى ليس يدري","page":"","text":"كتمت هواك حتى ليس يدري … لساني ما تضمنه جناني\nولي بين الجوانح منك سر … خفي لا يعيه الكاتبان\nوكيف يخطه الملكان عني … ولم ينطق بغامضه لساني ؟"},{"id":"diwan-barudi:181","bookId":"diwan-barudi","type":"poem","seq":181,"chapter":"البحر: طويل","title":"سل الجيزة الفيحاء عن هرمى مصر","page":"","text":"سل الجيزة الفيحاء عن هرمى مصر … لعلك تدري غيب ما لم تكن تدري\nبناءان ردا صولة الدهر عنهما … ومن عجب أن يغلبا صولة الدهر\nأقاما على رغم الخطوب ليشهدا … لبانيهما بين البرية بالفخر\nفكم أمم فى الدهر بادت ، وأعصر … خلت ، وهما أعجوبة العين والفكر\nتلوح لآثار العقول عليهما … أساطير لاتنفك تتلى إلى الحشر\nرموز لو استطلعت مكنون سرها … لأبصرت مجموع الخلائق فى سطر\nفما من بناء كان ، أو هو كائن … يدانيهما عند التأمل والخبر\nيقصر حسنا عنهما ( صرح بابل ) ويعترف ( الإيوان ) بالعجز والبهر ) 9 ( فلو أن ' هاروت ' انتحى مرصديهما … لألقى مقاليد الكهانة والسحر\nكأنهما ثديان فاضا بدرة … من النيل تروى غلة الأرض إذ تجرى\nوبينهما ' بلهيب ' فى زى رابض … أكب على الكفين منه إلى الصدر\nيقلب نحو الشرق نظرة وامق … كأن له شوقا إلى مطلع الفجر\nمصانع فيها للعلوم غوامض … تدل على أن ابن آدم ذو قدر\nرسا أصلها ، وامتد فى الجو فرعها … فأصبح وكرا للسماكين والنسر\nفقم نغترف خمر النهى من دنانها … ونجنى بأيدى الجد ريحانة العمر\nفثم علوم لم تفتق كمامها … وثم رموز وحيها غامض السر\nأقمت بها شهرا ، فأدركت كل ما … تمنيته من نعمة الدهر في شهر\nنروح ونغدو كل يوم لنجتنى … أزاهير علم لاتجف مع الزهر\nإذا ما فتحنا قفل رمز بدت لنا … معاريض لم تفتح بزيج ولا جبر\nفكم نكت كالسحر في حركاته … تريك مدب الروح فى مهجة الذر\nسكرنا بما أهدت لنا من لبابها … فيا لك من سكر أتيح بلا خمر !\nوما ساءنى إلا صنيع معاشر … ألحوا عليها بالخيانة والغدر\nأبادوا بها شمل العلوم ، وشوهوا … محاسن كانت زينة البر و\nفكم سملوا عينا بها تبصر العلا … وشلوا يدا كانت بها راية النصر\nتمنوا لقاط الدر جهلا ، وما دروا … بأن حصاها لا يقوم بالدر\nوفلوا لجمع التبر صم صخورها … وأيسر ما فلوه أغلى من التبر\nولكنهم خابوا ، فلم يصلوا إلى … مناهم ، ولاأبقوا عليها من الختر\nفتبا لهم من معشر نزعت بهم … إلى الغى أخلاق نبتن على غمر\nألا قبح الله الجهالة ، إنها … عدوة ما شادته فينا يد الفكر\nفلو ردت الأيام مهجة ' هرمس ' … لأعول من حزن على نوب الدهر\nفيا نسمات الفجر ! أدى تحيتى … إلى ذلك البرج المطل على النهر\nويا لمعات البرق ! إن جزت بالحمى … فصوبي عليها بالنثار من القطر\nعليها سلام من فؤاد متيم … بها ، لا بربات القلائد والشذر\nولا برحت فى الدهر وهى خوالد … خلود الدرارى والأوابد من شعرى"},{"id":"diwan-barudi:182","bookId":"diwan-barudi","type":"poem","seq":182,"chapter":"البحر: طويل","title":"يموت معي سر الصديق ولحده","page":"","text":"يموت معي سر الصديق ولحده … ضمير له الجنبان مكتنفان\nوأسأل يوم البعث عن كل ما وعى … سماع وما فاهت به شفتان\nفأنكره من بين ما في صحيفتي … وأجحده إذ يشهد الملكان\nوذنبي في ذا الجحد أيسر محملا … من الذنب في إفشائه بلساني"},{"id":"diwan-barudi:183","bookId":"diwan-barudi","type":"poem","seq":183,"chapter":"البحر: طويل","title":"أديرا كئوس الراح ، قد لمع الفجر","page":"","text":"أديرا كئوس الراح ، قد لمع الفجر … وصاحت بنا الأطيار أن وجب السكر\nأما تريان الليل كيف تسللت … كواكبه للغرب ، وانحدر النسر\nفقوما انظرا ما يصنع الصبح بالدجى … فإنى أرى ما ليس يبلغه الذكر\nأرى أدهما يتلوه أشهب طارد … كلا الفرسين اغتال شأوهما الحضر\nوقد حنت الأطيار فى وكناتها … وقام يحيينا على ساقه الزهر\nوأصبحت الغدران تصقلها الصبا … ويرقم متنيها بلؤلئه القطر\nترف كما رفت صحائف فضة … عليهن من لألاء شمس الضحى تبر\nكأن بنات الماء تقرأ متنها … صباحا ، وظل الغصن لاح بها سطر\nعصائب حول الماء يدرمن هتفا … بلحن له فى كل سامعة أثر\nإذا صرصر البازى تلبدن بالثرى … من الرعب حتى لا يبين لها صر\nيسارقنه حتى إذا غاب ظله … عن الماء عاد اللحن ، وانتشر الهدر\nتراهن أسرابا على الماء حوما … يقربها ظمء ، ويبعدها ذعر\nتروح وتغدو بين أفنان دوحة … سقاها من الوسمي مستوكف غزر\nلها في نواحي الأفق لفتة أصيد … يلوح على أطراف عرنينه الكبر\nملاعب لهو يقصر الطرف دونها … ودنيا نعيم لا يحيط بها الفكر\nفيا صاحبى نجواى ! قوما لشربها … ففى مثل هذا اليوم طابت لنا الخمر\nوشأنكما فى الراح ، فالعيش والصبا … إذا الراح لم تخفرهما فسد العمر\nخبيئة قوم خلفوها لغيرهم … خلت دونها الأيام ، واختلف العصر\nفجاءت كمصباح السماء منيرة … إذا اتقدت في الكأس سار بها السفر\nوإن أنتما غنيتمانى فلتكن … أناشيد يهفو دون تسماعها الصبر\nأناشيد فيها للمليحة والهوى … معاذير أحوال يلين لها الصخر\nلعل هواها أن يعود كما بدا … رخي الحواشي قبل أن ينشب الهجر\nمن البيض ، ميسان العشيات ، غادة … سليمة ما تحوي المعاقد والأزر\nإذا سفرت والبدر ليلة تمه … ولاحا سواء ، قيل أيهما البدر ؟\nلها لفتة الخشف الأغن ، ونظرة … تقصر عن أمثالها الفتكة البكر\nترد النفوس السالمات سقيمة … وتفعل ما لا تفعل البيض والسمر\nخفضت لها منى جناحى مودة … ودنت لعينيها كما حكم الدهر\nعلى أن ما بيني وبين عشيرها … قوارع سوء لا ينام لها وتر\nفيا ربة الخلخال ! رفقا بمهجتى … فبالغادة الحسناء لا يحسن الغدر\nوبقيا على قلبي ، فلو لم يكن به … سوى حب ' عبد الله ' كان له عذر\nأخى ، وصديقى ، وابن دى ، وصاحبى … وموضع سري حين يعتلج الصدر\nهو الصاحب المشكور في الود سعيه … وما خير ود ليس يلحقه شكر ؟\nأمين على غيب الصديق إذا ونت … عهود أناس ، أو تطرقها فتر\nفلا جهره سر ، ولا سر صدره … إذا امتحن الواشي ضمائره جهر\nيدب على المعنى الخفى بفكرة … سواء لديها السهل فى ذاك والوعر\nله البلجة الغراء يسري شعاعها … إذا غام أفق الفهم ، والتبس الأمر\nتزاحم أفواج الكلام بصدره … فلو غض من صوت لكان لها هدر\nله قلم لولا غزارة فكره … لجفت لديه السحب ، أو نفد\nإذا اختمرت بالليل قمة رأسه … تفجر من أطراف لمتها الفجر\nإليك ابن بطحاء الكلام تشذرت … بركب المعانى لا يكفكفها الزجر\nقلائص لا يرعين عازبة الكلا … ولا يستبقن الماء إن فاتها العشر\nوما هو إلا الشعر سارت عيابه … وفى طيها من طيب ما ضمنت نشر\nفألق إليه السمع ينبئك أنه … هو الشعر ، لا ما يدعى الملأ الغمر\nيزيد على الإنشاد حسنا ، كأننى … نفثت به سحرا ، وليس به سحر\nفدم للعلا ، والعلم ، والحلم ، والتقى … ونيل المنى ما أورق الغصن النضر"},{"id":"diwan-barudi:184","bookId":"diwan-barudi","type":"poem","seq":184,"chapter":"البحر: كامل تام","title":"عرف الهوى في نظرتي فنهاني","page":"","text":"عرف الهوى في نظرتي فنهاني … خل رعيت وداده فرعاني\nأخفيت عنه سريرتي ، فوشى بها … دمع أباح له حمى كتماني\nفبأي معذرة أكذب لوعة … شهدت بها العبرات من أجفاني ؟\nيا صاح ! لا أبصرت ما صنع الهوى … بأخيك يوم تفرق الأظعان\nيوم فقدت الحلم فيه ، وشفني … وله أصاب جوانحي ، فرماني\nفعليك من قلبي السلام ؛ فإنه … تبع الهوى ، فمضى بغير عنان\nهيهات يرجع بعد ما علقت به … لحظات ذاك الشادن الفتان\nوعلى الرحائل نسوة عربية … يخدعن لب الحازم اليقظان\nأغوينني ؛ فتبعت شيطان الهوى … إن النساء حبائل الشيطان\nما كنت أعلم قبل بادرة النوى … أن الأسود فرائس الغزلان\nرحلوا ! فأية عبرة مسفوحة … ويد تضم حسا من الخفقان ؟\nولقد حننت لبارق شخصت له … منا العيون بأبرق الحنان\nيستن في عرض الغمام ، كأنه … لهب تردد في سماء دخان\nفانظر ، لعلك تستبين ركابه … طوع الرياح ، يصيب أي مكان ؟\nفهناك تجتمع الشعوب ، وتلتقي … هدب الخدور على غصون البان\nفاخلع عذارك ، واغتنم زمن الصبا … قبل المشيب فكل شيء فاني"},{"id":"diwan-barudi:185","bookId":"diwan-barudi","type":"poem","seq":185,"chapter":"البحر: كامل تام","title":"لهوى الكواعب ذمة لا تخفر","page":"","text":"لهوى الكواعب ذمة لا تخفر … وأخو الوفاء بعهده لا يغدر\nفعلام ينهانى العذول عن الصبا ؟ … أوليس أن هوى النفوس مقدر ؟\nقد كان لي في بعض ما صنع الهوى … عذر ، ولكن أين من يتبصر ؟\nومن البلية غافل عما جنت … يده علي ، ولائم لا يعذر\nلم يدر من كحل الكرى أجفانه … ماذا يكابد الهوى من يسهر\nيا غافلا عنى ! وبين جوانحى … لهب يكاد له الحشا يتفطر\nدعني أبثك بعض ما أنا واجد … واحكم بما تهوى ، فأنت مخير\nفلو اطلعت على تباريح الجوى … لعلمت أى دم بحبك يهدر\nما كنت أعلم قبل حبك أننى … أغضي على مضض الهوان وأصبر\nأوردتني بلحاظ عينك موردا … للحب ، ما للقلب عنه مصدر\nهى نظرة كانت ذريعة صبوة … واللحظ أضعف ما يكون وأقدر\nما كنت أعلم قبل وحى جفونها … أن العيون الجؤذرية تسحر\nظلموا الأسنة خاطئين ، وليتهم … علموا بما صنع السنان الأحور\nأمطاعن الفرسان فى حمس الوغى … أقصر ، فرمحك عن غريمك أقصر\nأين الرماح من القدود ؟ وأين من … لحظ تهيم به السنان الأخزر ؟\nهيهات يثبت فى الوقيعة دارع … يسطو عليه مخلخل ومسور\nللحسن أسلحة إذا ما استجمعت … في حومة لا يتقيها مغفر\nفاللحظ عضب صارم ، والهدب نب … ل صائب ، والقد رمح أسمر\nأنى يطيش عن القلوب لغمزة … سهم ، وقوس الحاجبين موتر ؟\nيا للحمية من غزال صادنى … ومن العجائب أن يصيد الجؤذر\nبدر له بين القلوب منازل … يسرى بها ، ولكل بدر مظهر\nانظر لطرته وغرة وجهه … تلق الهداية ، فهو ليل أقمر\nناديت لما لاح تحت قناعه : … هذا ( المقنع فاحذروا أن تسحروا )4\nطبعته فى لوح الفؤاد مخيلتى … بزجاجة العينين ، فهو مصور\nوسرت بجسمى كهرباءة حسنه … فمن العروق به سلوك تخبر\nأنا منه بين صبابة لا ينقضى … ميقاتها ، ومواعد لا تثمر\nجسم برته يد الضنى ، حتى غدا … قفصا به للقلب طير يصفر\nلولا التنفس لاعتلت بى زفرة … فيخالني طيارة من يبصر\nلا غرو أن أصبحت تحت قياده … فالحب أغلب للنفوس وأقهر\nيعنو لقدرته المليك المتقى … ويهاب صولته الكمى القسور\nوالعشق مكرمة إذا عف الفتى … عما يهيم به الغوي الأصور\nيقوى به قلب الجبان ، ويرعوي … طمع الحريص ويخضع المتكبر\nفتحل بالأدب النفيس ، فإنه … حلي يعز به اللبيب ويفخر\nوإذا عزمت فكن بنفسك واثقا … فالمستعز بغيره لا يظفر\nإن لم يكن للمرء من بدهاته … فى الخطب هاد خانه من ينصر\nواحذر مقارنة اللئيم وإن علا … فالمرء يفسده القرين الأحقر\nومن الرجال مناسب معروفة … تزكو مودتها ، ومنهم منكر\nفانظر إلى عقل الفتى لا جسمه … فالمرء يكبر بالفعال ويصغر\nفلربما هزم الكتيبة واحد … ولربما جلب الدنيئة معشر\nإن الجمال لفى الفؤاد ، وإنما … خفي الصواب لأنه لا يظهر\nفاختر لنفسك ما تعيش بذكره … فالمرء فى الدنيا حديث يذكر"},{"id":"diwan-barudi:186","bookId":"diwan-barudi","type":"poem","seq":186,"chapter":"البحر: مجزوء الرمل","title":"سل حمام الأيك عني","page":"","text":"سل حمام الأيك عني … إنه أدرى بحزني\nنحن في الحب سواء … كلنا يبكي لغصن\nغير أن الوجد منه … ليس مثل الوجد مني\nأنا أبكي من غرامي … وهو في الغصن يغني\nوهو بالدمع بخيل … ودموعي ملء عيني\nلست في الصبوة مثلي … فانصرف يا طير عني"},{"id":"diwan-barudi:187","bookId":"diwan-barudi","type":"poem","seq":187,"chapter":"البحر: كامل تام","title":"رف الندى ، وتنفس النوار","page":"","text":"رف الندى ، وتنفس النوار … وتكلمت بلغاتها الأطيار\nوتأرجت سرر البطاح ، كأنما … في بطن كل قرارة عطار\nزهر يرف على الغصون ، وطائر … غرد الهدير ، وجدول زخار\nونواسم أنفاسهن طويلة … وهواجر أعمارهن قصار\nوالباسقات الحاملات كأنها … عمد مشعبة الذرا ومنار\nعقدت ذلاذل سوقها فى جيدها … وسمت ، فليس تنالها الأبصار\nفأصولها للسابحات ملاعب … وفروعها للنيرات مطار\nيبدو بها زهو تخال إهانه … فتلا تمشت في ذراها النار\nطورا تميل مع الرياح ، وتارة … ترتد ، فهي تحرك وقرار\nفكأنما لعبت بها سنة الكرى … فتمايلت ، أو بينها أسرار\nفإذا رأيت رأيت أحسن جنة … خضراء تجري بينها الأنهار\nيترنم العصفور فى عذباتها … ويصيح فيها العندل الصفار\nفالترب مسك ، والجداول فضة … والقطر در ، والبهار نضار\nفاشرب على وجه الربيع ، فإنه … زمن دم الآثام فيه جبار\nواعلم بأن المرء غير مخلد … والناس بعد لغيرهم أخبار\nإني وإن لعب الزمان بصعدتي … وابيض منى مفرق وعذار\nفلنعم ما بقيت لدي مهابة … تقذى بها عين العدا ووقار\nوسعى إلى الحلم فى أثوابه … طربا ، وآن لجهلى الإقصار\nأنا للصديق كما يحب ، وللعدا … عند الكريهة ضيغم زءار\nخيلي مسومة ، ورمحي ذابل … يوم الطعان ، وصارمي بتار\nوبراحتي قلم ، إذا حركته … رويت به الأمهام وهى حرار\nترتد عنه قنابل وجحافل … وتكل عنه أسنة وشفار\nغرد إذا ما جال فوق صحيفة … سجدت لحسن صريره الأوتار\nوإذا امتطى ظهر البنان لغاية … خضعت إليه قوارح ومهار\nفإذا ركبت فكل قرن أميل … وإذا نطقت فكل نطق رار\nألقى الكلام إلى ثنى عنانه … وتفاخرت بكلامى الأشعار"},{"id":"diwan-barudi:188","bookId":"diwan-barudi","type":"poem","seq":188,"chapter":"البحر: كامل تام","title":"ذكر الصبا ؛ فبكى ، ولات أوان","page":"","text":"ذكر الصبا ؛ فبكى ، ولات أوان … من بعد ما ولى به الملوان\nهيهات يرجع فائت لعبت به … عصر أوائل أردفت بثواني\nهون عليك فكل شيء ذاهب … والدهر مصدر عزة وهوان\nواحذر من الدنيا إذا هي أقبلت … بالبشر ، فهي كثيرة الألوان\nودع التعلق بالمحال ؛ فمن يعش … في غبطة يرمى به الرجوان\nلا تأملن بكل عام مقبل … خيرا ؛ فكل الدهر عام جوان\nوالدهر أيام تبيد صروفها … وتشيد فهي هوادم وبواني\nأنى يفر المرء من شرك الردى … والموت مقدور على الحيوان"},{"id":"diwan-barudi:189","bookId":"diwan-barudi","type":"poem","seq":189,"chapter":"البحر: طويل","title":"تأوب طيف من ( سميرة ) زائر","page":"","text":"تأوب طيف من ( سميرة ) زائر … وما الطيف إلا ما تريه الخواطر\nطوى سدفة الظلماء ، والليل ضارب … بأرواقه ، والنجم بالأفق حائر\nفيا لك من طيف ألم ودونه … محيط من\nتخطى إلى الأرض وجدا ، وما له … سوى نزوات الشوق حاد وزاجر\nألم ، ولم يلبث ، وسار ، وليته … أقام ولو طالت علي الدياجر\nتحمل أهوال الظلام مخاطرا … وعهدى بمن جادت به لا تخاطر\nخماسية ، لم تدر ما الليل والسرى … ولم تنحسر عن صفحتيها الستائر\nعقيلة أتراب توالين حولها … كما دار بالبدر النجوم الزواهر\nغوافل لا يعرفن بؤس معيشة … ولا هن بالخطب الملم شواعر\nتعودن خفض العيش فى ظل والد … رحيم وبيت شيدته العناصر\nفهن كعنقود الثريا ، تألقت … كواكبه في الأفق ، فهي سوافر\nتمثلها الذكرى لعينى ، كأننى … إليها على بعد من الأرض ناظر\nفطورا إخال الظن حقا ، وتارة … أهيم ، فتغشى مقلتي السمادر\nفيا بعد ما بينى وبين أحبتى ! … ويا قرب ما التفت عليه الضمائر !\nولولا أماني النفس وهي حياتها … لما طار لى فوق البسيطة طائر\nفإن تكن الأيام فرقن بيننا … فكل امرىء يوما إلى الله صائر\nهي الدار ؛ ما الأنفاس إلا نهائب … لديها ، وما الأجسام إلا عقائر\nإذا أحسنت يوما أساءت ضحى غد … فإحسانها سيف على الناس جائر\nترب الفتى ، حتى إذا تم أمره … دهته ، كما رب البهيمة جازر\nلها ترة فى كل حى ، وما لها … على طول ما تجني على الخلق واتر\nكثيرة ألوان الوداد ، ملية … بأن يتوقاها القرين المعاشر\nفمن نظر الدنيا بحكمة ناقد … درى أنها بين الأنام تقامر\nصبرت على كره لما قد أصابنى … ومن لم يجد مندوحة فهو صابر\nوما الحلم عند الخطب والمرء عاجز … بمستحسن كالحلم والمرء قادر\nولكن إذا قل النصير ، وأعوزت … دواعى المنى فالصبر فيه المعاذر\nفلا يشمت الأعداء بى ، فلربما … وصلت لما أرجوه مما أحاذر\nفقد يستقيم الأمر بعد اعوجاجه … وتنهض بالمرء الجدود العواثر\nولى أمل فى الله تحيا به المنى … ويشرق وجه الظن والخطب كاشر\nوطيد ، يزل الكيد عنه ، وتنقضي … مجاهدة الأيام وهو مثابر\nإذا المرء لم يركن إلى الله فى الذى … يحاذره من دهره فهو خاسر\nوإن هو لم يصبر على ما أصابه … فليس له في معرض الحق ناصر\nومن لم يذق حلو الزمان ومره … فما هو إلا طائش اللب نافر\nولولا تكاليف السيادة لم يخب … جبان ، ولم يحو الفضيلة ثائر\nتقل دواعى النفس وهى ضعيفة … وتقوى هموم القلب وهو مغامر\nوكيف يبين الفضل والنقص فى الورى … إذا لم تكن سوم الرجال المآثر ؟\nوما حمل السيف الكمي لزينة … ولكن لأمر أوجبته المفاخر\nإذا لم يكن إلا المعيشة مطلب … فكل زهيد يمسك النفس جابر\nفلولا العلا ما أرسل السهم نازع … ولا شهر السيف اليمانى شاهر\nمن العار أن يرضى الدنية ماجد … ويقبل مكذوب المنى وهو صاغر\nإذا كنت تخشى كل شئ من الردى … فكل الذي في الكون للنفس ضائر\nفمن صحة الإنسان ما فيه سقمه … ومن أمنه ما فاجأته المخاطر\nعلى طلاب العز من مستقره … ولا ذنب لى إن عارضتنى المقادر\nفما كل محلول العريكة خائب … ولا كل محبوك التريكة ظافر\nفماذا عسى الأعداء أن يتقولوا … على ، وعرضى ناصح الجيب وافر ؟\nفلي في مراد الفضل خير مغبة … إذا شان حيا بالخيانة ذاكر\nملكت عقاب الملك وهي كسيرة … وغادرتها فى وكرها وهى طائر\nولو رمت ما رام امرؤ بخيانة … لصبحني قسط من المال غامر\nولكن أبت نفسي الكريمة سوأة … تعاب بها ، والدهر فيه المعاير\nفلا تحسبن المال ينفع ربه … إذا هو لم تحمد قراه العشائر\nفقد يستجم المال والمجد غائب … وقد لا يكون المال والمجد حاضر\nولو أن أسباب السيادة بالغنى … لكاثر رب الفضل بالمال تاجر\nفلا غرو أن حزت المكارم عاريا … فقد يشهد السيف الوغى وهو حاسر\nأنا المرء لا يثنيه عن درك العلا … نعيم ، ولا تعدو عليه المفاقر\nقئول وأحلام الرجال عوازب … صئول وأفواه المناي فواغر\nفلا أنا إن أدناني الوجد باسم … ولا أنا إن أقصاني العدم باسر\nفما الفقر إن لم يدنس العرض فاضح … ولا المال إن لم يشرف المرء ساتر\nإذا ما ذباب السيف لم يك ماضيا … فحيلته وصم لدى الحرب ظاهر\nفإن كنت قد أصبحت فل رزية … تقاسمها فى الأهل باد وحاضر\nفكم بطل فل الزمان شباته … وكم سيد دارت عليه الدوائر\nوأى حسام لم تصبه كلالة ؟ … وأى جواد لم تخنه الحوافر ؟\nفسوف يبين الحق يوما لناظر … وتنزو بعوراء الحقود السرائر\nوما هي إلا غمرة ، ثم تنجلي … غيابتها ، والله من شاء ناصر\nفقد حاطني في ظلمة الحبس ، بعدما … ترامت بأفلاذ القلوب الحناجر\nفمهلا بني الدنيا علينا ، فإننا … إلى غاية تنفت فيها المرائر\nتطول بها الأنفاس بهرا ، وتلتوى … على فلكة الساقين فيها المآزر\nهنالك يعلو الحق ، والحق واضح … ويسفل كعب الزور ، والزور عاثر\nوعما قليل ينتهي الأمر كله … فما أول إلا ويتلوه آخر"},{"id":"diwan-barudi:190","bookId":"diwan-barudi","type":"poem","seq":190,"chapter":"البحر: بسيط تام","title":"ما أطيب العيش لولا أنه فاني","page":"","text":"ما أطيب العيش لولا أنه فاني … تبلى النفوس ولا يبلى الجديدان\nقد كنت في غرة ، حتى إذا انقشعت … أبقت تباريح لا تنفك تغشاني\nوشيبة كلسان الفجر ناطقة … بما طواه عن الإفشاء كتماني\nأضحت قذى لعيون الغانيات ، وقد … كانت حبالة أبصار وأذهان\nكأنني لم أقد شعواء جافلة … ولم أبت بين دارات وندمان\nولم أقم في مقامات وأندية … شتى الهوى غير رعديد ولا واني\nفاليوم أصبحت لا سيفي بمنصلت … على العدو ، ولا قوسى بمرنان\nلا أذكر اللهو إلا أن تذكرني … ورقاء تدعو هديلا بين أغصان\nإن الثلاثين والخمس التي عرضت … ثنت قواي وفلت غرب أشجاني\nوخلفتني على ما كان من طرب … بادي الأسافة في قومي وجيراني\nوكان يحزنني شيبي فصرت أرى … أن الذي بعده أولى يإحزاني\nوهون الأمر عندي أن كل فتى … وإن تملأ من ماء الصبا فاني\nيا نفس لا تذهبي يأسا بما كسبت … يداك ؛ فالله ذو من وغفراني\nيعفو عن الذنب حتى يستوي كرما … لديه ذو العمل المبرر والجاني\nهو الذي جعل الأفلاك دائرة … وصور الخلق من إنس ومن جان\nوقدر الشمس تجرى في منازلها … والنجم والقمر الساري بحسبان\nوأرسل الغيث أرسالا برحمته … وأنبت الأرض من حب وريحان\nشبحانه ، جل عن وصف يحيط به … وكيف يدرك وصف الدائم الفاني ؟\nلقد تفرد في لاهوت قدرته … فما لها أبدا في ملكه ثاني\nونما نحن نظريه كما سبقت … به الإرادة من وصف وتبيان\nكل يقول على مقدار فطنته … والله أعلم بالقاصي وبالداني\nتبارك الله عما قيل وابتدعت … في ذاته من أضاليل وبهتان\nقد لفقوها أساطيرا محبرة … بحكمة ذات أشكال وألوان\nكأنهم قد أصابوا طرفة عجبا … أو جاءهم نبأ صدق ببرهان\nولو تكشف هذا الأمر لارتدعت … معاشر خلطوا كفرا بإيمان\nيا رب ؛ إنك ذو من ومغفرة … فاستر بعفوك زلاتي وعصياني\nولا تكلني إلى ما كان من عملى … فإنه سبب يفضي لحرماني"},{"id":"diwan-barudi:191","bookId":"diwan-barudi","type":"poem","seq":191,"chapter":"البحر: بسيط تام","title":"أربة العود ، أم قمرية السحر","page":"","text":"أربة العود ، أم قمرية السحر … غنت فحركت الأشجان بالوتر ؟\nحوراء للسحر في ألحاظها أثر … يريك أن الرقى ضرب من الهذر\nلو لم تكن قمرا في الحسن ما ظهرت … لأعين الناس فى ليل من الشعر\nأملت علي بلحظيها حديث هوى … عرفت منه ضمير العين بالأثر\nكأنما بين جفنيها إذا نظرت … ' هاروت ' يعبث بالألباب والفكر\nلا غرو أن همت من وجد بصورتها … فالحسن مشغلة للعقل والبصر\nلا تقنع العين منها كلما نظرت … وكيف يقتنع المشتاق بالنظر ؟\nناغيتها بلسان الشوق ، فازدهرت … للحسن في وجنتيها وردتا خفر\nوازور حاجبها عن نظرة رشقت … سواد قلبي بسهم صيغ من حور\nفلم أزل برقى الأشعار أعطفها … ورقية الشعر تجري الماء في الحجر\nحتى إذا علمت أنى بها كلف … وأنني من تجنيها على خطر\nتبسمت ، فجلت للعين من فمها … ياقوتة أودعت سطرين من درر\nفبت من وصلها ، في جنة ينعت … أفنانها بثمار الأنس والحبر\nأبحت للعين فيها ما تقر به … وذدت كف الصبا عن معقد الأزر\nحتى اشرأبت عقاب الفجر ، وانطلقت … حمائم الشهب من أحبولة السحر\nفيا لها ليلة ! كانت برونقها … تاريخ لهو لما أحرزت من وطر\nوسمتها بضياء الكأس ، فالتمعت … وزينة الدهم في الأوضاح والغرر\nلو كان يسمح لى دهرى بعودتها … لبعت فيها لذيذ النوم بالسهر\nولت ، فلم يبق منها غير فذلكة … تلوح فى دفتر الأوهام والذكر\nوأى باق على الأيام نطلبه … وكل واردة يوما إلى صدر\nفلا تثق بوفاء الدهر ، إن له … غدرا يفوق بين العود والثمر\nولا تغرنك من وجه بشاشته … فالسم يوجد في نضر من الشجر\nقد كدت أتهم ظنى فى فراسته … من طول ما اشتبهت عيناي في الصور\nفخذ لنفسك من دنياك ما سمحت … به إليك ، وكن منها على حذر\nوسالم الدهر تسلم من غوائله … فصاحب الشر لا ينجو من الكدر\nلا يبلغ المرء ما يهواه من أرب … إلا بترك الذى يخشاه من ضرر\nفانعم وطب واله واطرب واسع واعل وسد … واشرب وغن وته والعب وهم وطر\nلا يقنط المرء من غفران خالقه … ما لم يكن كافرا بالبعث والقدر"},{"id":"diwan-barudi:192","bookId":"diwan-barudi","type":"poem","seq":192,"chapter":"البحر: بسيط تام","title":"لا شيء في الدهر يغني عن أخي ثقة","page":"","text":"لا شيء في الدهر يغني عن أخي ثقة … يكون فيه بلاغ السمع والبصر\nقضيت من كل شئ رمته وطرا … إلا محادثة الإخوان فى السمر"},{"id":"diwan-barudi:193","bookId":"diwan-barudi","type":"poem","seq":193,"chapter":"البحر: خفيف تام","title":"كن كما شئت من رشاد وغى","page":"","text":"كن كما شئت من رشاد وغى … كل حي بما جناه رهين\nكلنا للفناء ، أو تصعق الأر … ض ، وتأتي بعد الشئون شؤون\nيستفز الحليم رونفها البا … هر ، حتى يخف وهو ركين\nذهبا غير ذكرة سوف تفنى … بعد ضن ، وكل شيء يحين\nفاحتقب سيرة المحامد ؛ فالذك … ر حياة لمن طوته المنون"},{"id":"diwan-barudi:194","bookId":"diwan-barudi","type":"poem","seq":194,"chapter":"البحر: منسرح","title":"صبح مطير ، ونسمة عطره","page":"","text":"صبح مطير ، ونسمة عطره … وأنفس للصبوح منتظره\nفدر بعينيك حيث شئت تجد … ملكا كبيرا ، وجنة خضره\nسماؤها بالغصون واشجة … وأرضها بالنبات مؤتزره\nمنظر لهو تعيد بهجته … أكنة العيش وهي منحسره\nفالعفر تحت الظلال راتعة … والطير فوق الغصون منتشره\nوالطل ينهل من مساقطه … مثل عقود الجمان منتثره\nجداول في الفضاء جارية … ومزنة في السماء منهمره\nدنيا نعيم تكاد زهرتها … تزري على الشمس وهي مزدهره\nلا ظلها راكد النسيم ، ولا … غدرانها بالغثاء مختمره\nفيابن ودى ! هلم نقتسم ال … لهو ، فنفسي إلى الصبا حسره\nوخلنا من سياسة درجت … بين أناس قلوبهم وغره\nيقضون أيامهم على خطر … فبئس عقبى السياسة الخطره\nخديعة لا يزال صاحبها … بين هموم وعيشة كدره\nما لي وللناس ، لا لدي لهم … حق يؤدى ، ولا على تره\nقد التقينا من غير سابقة … في دار دنيا بأهلها غدره\nنلهو بها حقبة ، ونتركها … إلى مهاو فى الأرض منحدره\nكل امرئ ذاهب لغايته … وكل نفس بالغيب مؤتمره\nيا رب هب لى من الكرامة ما … يسر نفسى ، فإنها وجره\nولا تكلنى لمن يعذبنى … فإن نفسى إليك مفتقره"},{"id":"diwan-barudi:195","bookId":"diwan-barudi","type":"poem","seq":195,"chapter":"البحر: مجزوء الكامل","title":"يا ذكرة ! أبصرت في","page":"","text":"يا ذكرة ! أبصرت في … مرآتها صور التمني\nخطرت علي ؛ فنفرت … طير الكرى من وكر جفني\nعلقت حبالة خاطري … منها بمكحول أغن\nكانت مثالا خطه … بمخيلتي نقاش ذهني\nهي لقية وهمية … سمحت بها خطرات ظني"},{"id":"diwan-barudi:196","bookId":"diwan-barudi","type":"poem","seq":196,"chapter":"البحر: طويل","title":"أمريم ! لا والله أنساك بعدما","page":"","text":"أمريم ! لا والله أنساك بعدما … صحبتك فى خفض من العيش أنضر\nفقد كنت فينا برة القول سرة … سليمة قلب في مغيب ومحضر\nفلقيت من ذى العرش خير تحية … توافيك فى روض من القدس أخضر"},{"id":"diwan-barudi:197","bookId":"diwan-barudi","type":"poem","seq":197,"chapter":"البحر: كامل تام","title":"أترى الصبا خطرت بوادي المنحنة ؟","page":"","text":"أترى الصبا خطرت بوادي المنحنة ؟ … فجنت عبير المسك من ذاك الجنى ؟\nمرت بنا طفل العشي ، فما درى … أحد بسر ضميرها إلا أنا\nوتحملت سر الهوى ؛ فترددت … برسائل الأشواق فيما بيننا\nعبقت غلائلها بنشر عرارة … بدوية ، بسوى الأنامل تجتنى\nتحمي منابتها قساور غارة … يجدون صعب الموت خطبا هينا\nمن كل مشتمل بشعلة صارم … أمضى من الأجل الوحي إذ ادنا\nوبمسقط العلمين جؤذر كلة … يصمي بنظرته الأسود إذا رنا\nصنع الوشاة له حديثا كاذبا … فقسا علي ، وكان سهلا لينا\nماذا عليه ولا أريد ملامة … لو جاد معها بالتحية أو كنى ؟\nإني لأقنع من هواه بنظرة … تروي الغليل من الصدى لو أمكنا\nأخنى علي مع الزمان ، وليته … لما أساء الدهر صنعا أحسنا\nورأى المشيب تلونت ألوانه … في عارضي من الأسى ؛ فتلونا\nوالمرء في الدنيا رهين حوادث … تودى بجدته ، وتلبسه الضنى\nليت المشيب تأخرت أيامه … حتى أفوز من الشبيبة بالمنى"},{"id":"diwan-barudi:198","bookId":"diwan-barudi","type":"poem","seq":198,"chapter":"البحر: طويل","title":"بكيت عليا إذ مضى لسبيله","page":"","text":"بكيت عليا إذ مضى لسبيله … بعين تكاد الروح في دمعها تجري\nوإنى لأدرى أن حزنى لا يفى … برزئي ، ولكن لا سبيل إلى الصبر\nوكيف أذود القلب عن حسراته … وأهون ما ألقاه يصدع فى الصخر ؟\nيلوموننى أنى تجاوزت فى البكا … وهل لامرئ لم يبك فى الحزن من عذر ؟\nإذا المرء لم يفرح ويحزن لنعمة … وبؤس ، فلا يرجى لنفع ولا ضر\nوما كنت لولا قسمة الله في الورى … لأصبر ، لكنا إلى غاية نسري\nلقد خفف البلوى وإن هي أشرفت … على النفس ما أرجوه من موعد الحشر"},{"id":"diwan-barudi:199","bookId":"diwan-barudi","type":"poem","seq":199,"chapter":"البحر: بسيط تام","title":"ما لي وللدار من ' ليلى ' أحييها","page":"","text":"ما لي وللدار من ' ليلى ' أحييها … وقد خلت من غوانيها مغانيها ؟\nدع الديار لقوم يكلفون بها … واعكف على حانة كالبدر ساقيها\nكم بين دائرة أقوت معالمها … وبين عامرة تزهو بمن فيها ؟\nهيهات ، ما الدار تشجيني بساحتها … وإنما الدار تشجيني بأهليها\nفخل هذا ، وخذ في وصف غانية … سرت بحلوان في قلبي سواريها\nريانة القد ، لو أن الضجيج لها … خاف العيون عليها كاد يطويها\nفي نشوة الخمر سر من مراشفها … وفي الأراكة شكل من تهاديها\nيا ليلة بت أسقى من بنانتها … ومن لواحظها خمرا ، ومن فيها\nأحييتها ، وأمت النوم معتصما … بلذة لا يكاد الدهر ينسيها\nحتى إذا رف خيط الفجر ، وابتدرت … حمائم الأيك تشدو في أغانيها\nقامت تمايل سكرى في مآزرها … والروع يبعثها طورا ، ويثنيها\nتخشى الضياء وفي أزرارها قمر … يستوقف العين حيرى في مجاريها\nثم انثنت ويدي قيد لخاصرة … كالخيزرانة ريا في تثنيها\nفي بلجة لا تكاد العين تنكرها … وسمرة ربما شفت نواحيها\nحتى تجاوزت أحراسا على شرف … يكاد يمنع هم النفس داعيها\nوحركت حلقات الباب ، فانفتحت … عن ساحة سكنت فيها تراقيها\nفعدت والعين غرقى في مدامعها … والقلب في لوعة تنزو نوازيها\nفيا لها ليلة ! كانت بوصلتها … تاريخ لهو يهيج النفس راويها"},{"id":"diwan-barudi:200","bookId":"diwan-barudi","type":"poem","seq":200,"chapter":"البحر: سريع","title":"لم أصطبر بعدك من سلوة","page":"","text":"لم أصطبر بعدك من سلوة … لكن تصبرت على جمر\nوشيمة العاقل فى رزئه … أن يسبق السلوة بالصبر"},{"id":"diwan-barudi:201","bookId":"diwan-barudi","type":"poem","seq":201,"chapter":"البحر: بسيط تام","title":"ومسرح لسوام العين ليس له","page":"","text":"ومسرح لسوام العين ليس له … في عالم الظن تقدير ، ولا شبه\nباكرته سحرة والشمس ناعسة … في خدرها ، وحمام الأيك منتبه\nوللغمائم بين الأفق منسحب … وللنسائم نحو الروض متجه\nوالجو في حلة دكناء مازجها … خيط من الفجر يبدو ثم يشتبه\nفالنور منقبض ، والظل منبسط … والطير منشرح ، والجو مدله\nمناظر لو رأى ' بهزاد ' صورتها … لاعتاده من تمادي الحيرة البله\nكأنما الدوح قصر والحمام به … سرب من الغيد بالألحان تبتده\nطورا تغنى ، وأحيانا تنوح ، فما … ذاك الغناء ، وهذا النوح والوله ؟\nكأنما الأورق الغريد حين شدا … في سربة الإنس منها شارب فكه\nشارفت ساحتها في فتية ألفوا … صدق الوداد ، فلم تعرض لهم شبه\nموقرون ، كرام لا يخف بهم … طيش ، ولم يجر في أخلاقهم سفه\nمن كل ماضي الشبا والروع محتدم … ومستنير الحجا والأمر مشتبه\nإن حدثوا ملئوا الأسماع من أدب … هم أهله وإذا ما أنصتوا فقهوا\nشرابنا صفو ماء ، لا يمازجه … إلا حديث كنوار الربا نزه\nفإن يكن في عفاف النفس محمدة … لها ، ففي مثل هذا يحسن الشره"},{"id":"diwan-barudi:202","bookId":"diwan-barudi","type":"poem","seq":202,"chapter":"البحر: طويل","title":"صبرت ، وما بالصبر عار على الفتى","page":"","text":"صبرت ، وما بالصبر عار على الفتى … إذا لم يكن فيه معاب ولا نكر\nولو لم يكن فى الصبر أعدل شاهد … على كرم الأخلاق ما حمد الصبر"},{"id":"diwan-barudi:203","bookId":"diwan-barudi","type":"poem","seq":203,"chapter":"البحر: كامل تام","title":"أحببت من والى ' عليا ' رغبة","page":"","text":"أحببت من والى ' عليا ' رغبة … في فضله ، وكرهت من عاداه\nهو ذلك الحبر الذي من أمه … نال الرضا ، وأجيب من ناداه\nوكفى بسبطيه إماما رحمة … نالا من الرضوان ما قصداه\nقد عز من والاه في الدنيا ، وفي … يوم الحساب ، وذل من باداه\nفاقصد له ، واعرفه ، واستمسك به … تلق الهدى ، وكفى المريد هداه\nوإذا عرتك ملمو ، فاهتف به … تسمع بقلبك حيث كنت صداه"},{"id":"diwan-barudi:204","bookId":"diwan-barudi","type":"poem","seq":204,"chapter":"البحر: بسيط تام","title":"لو كان يدرى الفتى مكنون ما خبأت","page":"","text":"لو كان يدرى الفتى مكنون ما خبأت … له المقادير لم يركن إلى الحذر\nولو درى أن ما يلقاه من عنت … من خيبة الرأى لم يعتب على القدر"},{"id":"diwan-barudi:205","bookId":"diwan-barudi","type":"poem","seq":205,"chapter":"البحر: بسيط تام","title":"سل مالك الملك ؛ فهو الآمر الناهي","page":"","text":"سل مالك الملك ؛ فهو الآمر الناهي … ولا تخف عاديا ؛ فالحكم لله\nهو الذي ينعش المظلوم إن علقت … به الرزايا ، ويجزي كل تياه\nفاسجد له ، واقترب تبلغ بطاعته … ما شئت في الدهر من عز ، ومن جاه\nيا رب ! قد طال بي شوقي إلى وطني … فاحلل وثاقي ، وألحقني بأشباهي\nوامنن علي بفضل منك يعصمني … من كل سوء ، فإني عاجز واهي\nهذا دعائي ، وحسبي أنت من حكم … يعنو له كل شاه ، أو شهنشاه"},{"id":"diwan-barudi:206","bookId":"diwan-barudi","type":"poem","seq":206,"chapter":"البحر: طويل","title":"بلوت إخاء الناس دهرا ، فلم أجد","page":"","text":"بلوت إخاء الناس دهرا ، فلم أجد … أخا ثقة يرعى مغيبى كمحضرى\nفإن أتغير عن وداد ، فإنني … أرى كل شيء عرضة للتغير"},{"id":"diwan-barudi:207","bookId":"diwan-barudi","type":"poem","seq":207,"chapter":"البحر: كامل تام","title":"ديني الحنيف ، وربي الله","page":"","text":"ديني الحنيف ، وربي الله … وشهادتي أن ليس إلا هو\nلا جاه لي إلا بطاعته … ولنعم عقبى الطاعة الجاه\nأنا خاشع لجلال قدرته … متقلب الجنبين أواه\nفأضالعي للوجد نار غضى … ومحاجري بالدمع أمواه\nزهت القلوب بنور حكمته … وتعطرت بالذكر أفواه\nأنا أمة وحدي على سرف … في حبه ، والناس أشباه\nإن تاه غيري بالزمان ، فلي … قلب بذكر الله تياه"},{"id":"diwan-barudi:208","bookId":"diwan-barudi","type":"poem","seq":208,"chapter":"البحر: وافر تام","title":"أيا ملكا همت كفاه جودا","page":"","text":"أيا ملكا همت كفاه جودا … على الثقلين : من باد وقاري\nعراك النيل من بلد بعيد … فألبسه الكرامة فهو عارى"},{"id":"diwan-barudi:209","bookId":"diwan-barudi","type":"poem","seq":209,"chapter":"البحر: بسيط تام","title":"جد بالنوال ؛ فرزق الله متصل","page":"","text":"جد بالنوال ؛ فرزق الله متصل … ولا تكن عن صنيع الخير باللاهي\nفالبخل والجبن في الإنسان منقصة … لم يجنها غير سوء الظن بالله"},{"id":"diwan-barudi:210","bookId":"diwan-barudi","type":"poem","seq":210,"chapter":"البحر: طويل","title":"يسائلني عما كتمت من الهوى","page":"","text":"يسائلني عما كتمت من الهوى … صديقي ، وفي بعض الإجابة ما يزري\nفإن لم أقل حقا كذبت على الهوى … وإن قلت إنى عاشق بحت بالسر"},{"id":"diwan-barudi:211","bookId":"diwan-barudi","type":"poem","seq":211,"chapter":"البحر: بسيط تام","title":"لمصطفى صادق في الشعر منزلة","page":"","text":"لمصطفى صادق في الشعر منزلة … أمسى يعاديه فيها من يصافيه\nصاغ القريض بإتقان ، فلو تليت … صدوره علمت منها قوافيه\nمهذب الطبع ، مأمون الضمير ، إذا … بلوته كان باديه كخافيه\nحاز الكمال ، فلم يحتج لمنقبة … فلست تنعته إلا بما فيه"},{"id":"diwan-barudi:212","bookId":"diwan-barudi","type":"poem","seq":212,"chapter":"البحر: رجز تام","title":"يا رب بيضاء من الجوارى","page":"","text":"يا رب بيضاء من الجوارى … جاءت بطفل أسود كالقار\nأخرجه من لجة الأنوار … من أخرج الليل من النهار\nسبحانه من فاعل مختار … "},{"id":"diwan-barudi:213","bookId":"diwan-barudi","type":"poem","seq":213,"chapter":"البحر: سريع","title":"إن ' سرنديب ' على حسنها","page":"","text":"إن ' سرنديب ' على حسنها … يسكنها قوم قباح الوجوه\nمن كل فدم لائك مضعة … يمجها كالدم في الأرض فوه\nتحسبه من نضح أشداقه … ركية تجري دما ، أو تموه\nلا يشبه الوالد مولوده … منهم ، ولا المولود منهم أبوه\nيغلظ طبع منهم فاقد … مزية العلم ، ووجه يشوه\nمن أين يدري الفضل معدومه … لا يعرف المعروف إلا ذووه\nلا تلبث الحكمة ما بينهم … ولا يريث الفضل حتى يتوه\nتظن بعض القوم علامة … وهو إذا ينطق هام ينوه\nلا تعرف المرء بأخلاقه … في غمرة العالم حتى يفوه"},{"id":"diwan-barudi:214","bookId":"diwan-barudi","type":"poem","seq":214,"chapter":"البحر: طويل","title":"لعمرى لقد أيقظت من كان راقدا","page":"","text":"لعمرى لقد أيقظت من كان راقدا … وأنذرت ، لكن لم تكن تنفع النذر\nنصحت فكذبتم ، فلما أتى الردى … عمدتم لتصديقى وقد قضى الأمر\nفلم يبق فى أيديكم غير حسرة … ولم يبق عندي غير ما عافه الصدر\nفجاء الذي كنتم تخافون شره … وزال الذى لم يبق من بعده شعر"},{"id":"diwan-barudi:215","bookId":"diwan-barudi","type":"poem","seq":215,"chapter":"البحر: متقارب تام","title":"صبرت على ريب هذا الزمان","page":"","text":"صبرت على ريب هذا الزمان … ولولا المعاذر لم أصبر\nفلا تحسبنى جهلت الصواب … ولكن هممت فلم أقدر\nثنت عزمتي ثورة المفسدين … وغلت يدي فترة العسكر\nوكنا جميعا ، فلما وقعت … صبرت ، وغادرني معشري\nولو أننى رمت إعناتهم … لقلت مقالة مستبصر\nولكنني حين جد الخصام … رجعت إلى كرم العنصر"},{"id":"diwan-barudi:216","bookId":"diwan-barudi","type":"poem","seq":216,"chapter":"البحر: مجزوء الرجز","title":"ويلاه من نار الهوى","page":"","text":"ويلاه من نار الهوى … وآه من طول الجوى\nأرسلت طرفي رائدا … فما علا حتى هوى\nوسار قلبي خلفه … فلم يعد حتى اكتوى\nقد طالما زجرته … يا ليته كان ارعوى\nلكل شيء آفة … وآفة القلب الهوى\nأما كفى هذا الجفا … حتى أعانته النوى ؟\nأين اللوى وعهده ؟ … أيهات عهد باللوى\nوظبي أنس سمته … إنجاز وعدي ، فلوى\nطلبت منه قبلة … فازور عني ، والتوى\nوسمته وعد المنى … فانحاز عني ، وانزوى\nيا سائلي عن حالتي … دعني ؛ فصبري قد ذوى\nوكان قلبي راشدا … لكنه اليوم غوى\nأوقع في أشراكه … لكل حي ما نوى\nفكيف أمضي في الهوى … والجسم محلول القوى\nوأين أبغي ناصرا ؟ … هيهات ، والخير انطوى\nأصبحت في تيهورة … يسأم فيها من ثوى\nلا صاحب وافى ، ولا … خل إلى حالي أوى\nفيا إلهي ! راعني … وادفع عن النفس التوى\nولا تكلني للتي … لو صادفت نجما خوى"},{"id":"diwan-barudi:217","bookId":"diwan-barudi","type":"poem","seq":217,"chapter":"البحر: رمل تام","title":"شفنى وجدى ، وأبلانى السهر","page":"","text":"شفنى وجدى ، وأبلانى السهر … وتغشتني سمادير الكدر\nفسواد الليل ما إن ينقضى … وبياض الصبح ما إن ينتظر\nلا أنيس يسمع الشكوى ، ولا … خبر يأتى ، ولا طيف يمر\nبين حيطان وباب موصد … كلما حركه السجان صر\nيتمشى دونه ، حتى إذا … لحقته نبأة منى استقر\nكلما درت لأقضي حاجة … قالت الظلمة : مهلا ، لا تدر\nأتقرى الشئ أبغيه ، فلا … أجد الشئ ، ولا نفسى تقر\nظلمة ما إن بها من كوكب … غير أنفاس ترامى بالشرر\nفاصبري يا نفس حتى تظفري … إن حسن الصبر مفتاح الظفر\nهي أنفاس تقضى ، والفتى … حيثما كان أسير للقدر"},{"id":"diwan-barudi:218","bookId":"diwan-barudi","type":"poem","seq":218,"chapter":"البحر: طويل","title":"تصابيت بعد الحلم ، واعتادني شجوي","page":"","text":"تصابيت بعد الحلم ، واعتادني شجوي … وأصبحت قد بدلت نسكي باللهو\nفقم عاطنيها قبل أن يحكم النهى … علي ، ويستهوي الزمان على زهوي\nفما الدهر إلا نابل ، ذو مكيدة … إذا نزعت كفاه في القوس لم يشو\nفخذ ما صفا من وده قبل فوته … فليس بباق في الوداد على الصفو\nألا إنما الأيام دولاب خدعة … تدور ، على أن ليس من ظمإ تروي\nفبينا ترى تعلو على النجم رفعة … بمن كان يهواها إذ انقلبت تهوي\nفراقب بجد سهوة الدهر ، والتمس … مناك ، فما يعطيك إلا على السهو\nولا يزعنك الصبر عن نيل لذة … فعما قليل يسلب الشيب ما تحوي\nألا رب ليل قصر اللهو طوله … بهيفاء مثل الغصن ، بينة السرو\nفتاة تريك البدر تحت قناعها … إذا سفرت والغصن في ملعب الحقو\nإذا انفتلت بالكأس خلت بنانها … يصرف نجما زل عن دارة الجو\nوإن خطرت بين الندامى تأودت … كأن ليس عضو في القوام على عضو\nوإني من القوم الذين إذا انتووا … مهولا من الأخطار باءوا على بأو\nأناس إذا ما أجمعوا الأمر أصبحوا … وما هم بنظارين للغيم والصحو\nغذا غضبوا ردوا الأمور لأصلها … كما بدأت واستفتحوا الأرض بالغزو\nوإن حارت الأبصار في مدلهمة … من الأمر جاءوا بالإنارة والضحو\nشددت بهم أزرى ، وحكمت شرتي … فيا عجبا للقوم يبغون خطتي\nوأصبحت مرهوب اللسان ، كأنني … سعرت لظى بين الحضارة والبدو\n … وما شأوهم شأوي ، ولا عدوهم عدوي\nإذا ما رأوني مقبلا أوحدوا لهم … شكاة ، فلا زالوا على ذلك الشكو\nيرومون مسعاتي ودون منالها … مراق تظل الطير من بعدها تهوي\nولا ، وأبي ما النصل في الفعل كالعصا … ولا القوس ملآن الحقيبة كالخلو\nلقلت ، وقالوا فاعتلوت ، وخفضوا … وليس أخو صدق كمن جاء باللغو\nوما ذاك إلا أنني بت ساهرا … وناموا ، وما عقبى التيقظ كالغفو\nفأصبحت مشبوب الزئير ، وأصبحت … لواطئ فيما بين داراتها تعوى"},{"id":"diwan-barudi:219","bookId":"diwan-barudi","type":"poem","seq":219,"chapter":"البحر: طويل","title":"لئن فرقت ما بيننا شقة النوى","page":"","text":"لئن فرقت ما بيننا شقة النوى … لعمرى ، وحالت دوننا نوب الدهر\nفشخصك في عيني ، وذكرك في فمي … وحبك فى قلبى ، وسرك فى صدرى"},{"id":"diwan-barudi:220","bookId":"diwan-barudi","type":"poem","seq":220,"chapter":"البحر: طويل","title":"تصابيت بعد الحلم ، واعتادني زهوي","page":"","text":"تصابيت بعد الحلم ، واعتادني زهوي … وأبدلت مأثور النزاهة باللهو\nوما كنت أخشى أن تعود غوايتي … إلى ، ولكن نظرة حركت شجوى\nعلى أنني غالبت شوقي ، فعزني … وناديت حلمي أن يعود ، فلم يلو\nوماذا على من خامر الحب قلبه … إذا مال معه للخلاعة والصبو ؟\nإذا المرء لم يعط الحياة نصيبها … من اللهو ، قادته الهموم إلى الشكو\nوهل في الصبا واللهو عار على الفتى … إذا العرض لم يدنس بإثم ، ولا بعو ؟\nلعمرك ما قارفت في الحب زلة … ولا قادني معها إلى سوءة خطوي\nولكنني أهوى الخلاعة والصبا … وأتبع آثار الفضيلة والسرو\nسجية نفس أدركت ما تريده … من الدهر ، فاعتاضت عن السكر بالصحو\nوإني من القوم الذين إذا انتووا … مهولا من الأخطار باءوا على بأو\nأناس إذا ما أجمعوا الأمر أصبحوا … وما هم بمظارين للغيم والصحو\nإذا غضبوا ردوا الأمور لأصلها … كما بدأت ، واستفتحوا الأرض بالغزو\nوإن حارت الأبصار في مدلهمة … من الأمر ، جاءوا بالإنارة والضحو\nشددت بهم أزري ، وأحكمت مرتي … وأطلقت من حبلي ، وأبعدت في شأوي\nوأصبحت مرهوب اللسان ، كأنني … سعرت لظى بين الحضارة والبدو\nفيا عجبا للقوم يبغون خطتي … وما خطوهم خطوي ، وعدوهم عدوي\nيرومون مسعاتي ، ودون منالها … مراق تظل الطير من بعدها تهوي\nفإن تك سني ما تطاول باعها … فإني جدير بالإصابة في الأتو\nلقلت ، وقالوا ، فاعتلوت ، وخفضوا … وليس أخو صدق كمن جاء باللغو\nوما ذاك إلا أنني بت ساهرا … وناموا ، وما عقبى التيقظ كالعفو\nفأصبحت مشبوب الزئير ، وأصبحت … كأكلب حي بين داراته تلوي"},{"id":"diwan-barudi:221","bookId":"diwan-barudi","type":"poem","seq":221,"chapter":"البحر: سريع","title":"من طلب العز بلا آلة","page":"","text":"من طلب العز بلا آلة … أدركه الذل مكان الظفر\nفاصبر على المكروه تظفر بما … شئت ، فقد حاز المنى من صبر\nوقف إذا ما عرضت شبهة … فاللبث خير من ركوب الغرر\nولا تقولن لشئ مضى … يا ليته دام ، وخذ ما حضر\nولا تعامل صاحبا بالتي … ترجع عنها تائبا تعتذر\nوغض من طرفك إن خفته … فحاجب الشهوة غض البصر"},{"id":"diwan-barudi:222","bookId":"diwan-barudi","type":"poem","seq":222,"chapter":"البحر: طويل","title":"كفى بالضنى عن سورة العذل ناهيا","page":"","text":"كفى بالضنى عن سورة العذل ناهيا … فأهون ما ألقاه يرضي الأعاديا\nبلوت الهوى حتى بليت ، وطال بي … مرير النوى حتى نسيت التلاقيا\nوما كنت ذا غي ، ولكن إذا الهوى … أصاب حليم القوم أصبح غاويا\nإلى الله أشكو نظرة ما تجاوزت … حمى العين حتى أوردتني المهاويا\nرميت بها عن غير عمد ، فلم تعد … على النفس إلا بالذي كان قاضيا\nهجرت لها أهلي ، وفارقت جيرتي … وغاضبت في الخلان من كان راضيا\nوأصبحت مسلوب الجنان ، كأنني … شربت بكأس تترك العقل ساهيا\nأدور ، ولا أدري وإن كنت حازما … يميني أدنى للهدى من شماليا\nصريع هوى ، لا أذكر اليوم باسمه … ولا أعرف الأشخاص إلا تماديا\nفيا عين ، لا زالت يد السهد تمتري … أساكيب دمع منك تروى المآقيا\nفأنت التي أوردت قلبي من الهوى … موارد لم تترك من الصبر باقيا\nأطعتك ، فاستسلمت بعد شكيمة … أعضت بأطراف الشكيم المذاكيا\nفإن أنا سالمت الهوى بعد هذه … فلست ابن أم المجد إن عدت ثانيا\nيلومون أشواقي ، كأني ابتدعتها … ولو علموا لاموا الظباء الجواريا\nوما لي ذنب عندهم ، غير أنني … شدوت ، فعلمت الحمام الأغانيا\nوهل يكتم المرء الهوى وهو شاعر … ويثني على أعقابهن القوافيا ؟\nفيا نسمات الفجر ، ما لك كلما … تنسمت أضرمت الهوى في فؤاديا\nويا سجعات الأيك ! رفقا بمهجة … . . . . . . . . . . . . . . .\nويا لمحات البرق ! بالله خبري … أخلاى بالمقياس عني سلاميا\nويا عذبات البان ! إن كنت إنما … تميل معي شوقا ، فلقيت داويا\nعوائد شوق ألهبت لاعج الأسى … وردت أماني الضمير هوافيا\nلعمرك ، ما فارقت ربعي عن قلى … ولا أنا ودعت الأحبة ساليا\nولكن عدتني عن بلادي وجيرتي … عواد أبت في البعد إلا تماديا\nزمان تولى غير أعقاب ذكرة … تسوق إلى المرء الحليم التصابيا\nفيا روضة المقياس ! جادك سلسل … من النيل يدعو للحنين السواقيا\nولا برحت للفخر نسمة … ترد جبين النور أزهر ضاحيا\nبلاد صحبت العيش فيها منعما … وأجريت أفراس البطالة لاهيا\nفكم لذة أدركت فيها ، ونعمة … أصبت ، وآداب تركت ورائيا\nهي الوطن المألوف ، والنفس صبة … بمنزلها الأدنى وإن نائيا\nفلا حبذا الدنيا إذا هي أدبرت … وإن أقبلت يوما فيا حبذا هيا\nنشدت المنى عودا وقد كنت بدأة … مطاف أناس ينشدون الأمانيا\nفإن لم أنل منها نصيبا ، فإنني … أرى اليأس عن بعض المطالب كافيا\nوماذا الذي تجدى على فضائلي … إذا كن في عين العدو مساويا ؟\nفلا اخضر ساق البقل إن بت طاويا … ولا انهل ماء المزن إن مت صاديا"},{"id":"diwan-barudi:223","bookId":"diwan-barudi","type":"poem","seq":223,"chapter":"البحر: بسيط تام","title":"ونبأة أطلقت عيني من سنة","page":"","text":"ونبأة أطلقت عيني من سنة … كانت حبالة طيف زارني سحرا\nفقمت أسأل عيني رجع ما سمعت … أذني ، فقالت : لعلي أبلغ الخبرا\nثم اشرأبت ، فألفت طائرا حذرا … على قضيب يدير السمع والبصرا\nمستوفزا يتنزى فوق أيكته … تنزى القلب طال العهد فادكرا\nلا تستقر له ساق على قدم … فكلما هدأت أنفاسه نفرا\nيهفو به الغصن أحيانا ، ويرفعه … دحو الصوالج في الديمومة الأكرا\nما باله وهو فى أمن وعافية … لا يبعث الطرف إلا خائفا حذرا ؟\nإذا علا بات في خضراء ناعمة … وإن هوى ورد الغدران ، أو نقرا\nيا طير نفرت عني طيف غانية … قد كان أهدى لي السراء حين سرى\nحوراء كالرئم ألحاظا إذا نظرت … وصورة البدر إشراقا إذا سفرا\nزالت خيالتها عني ، وأعقبها … شوق أحال على الهم والسهرا\nفهل إلى سنة إن أعوزت صلة … عود ننال به من طيفها الوطرا ؟"},{"id":"diwan-barudi:224","bookId":"diwan-barudi","type":"poem","seq":224,"chapter":"البحر: وافر تام","title":"أتاني أن ' عبد الله ' أصغى","page":"","text":"أتاني أن ' عبد الله ' أصغى … إلى واش ؛ فغيره عليا\nوما عهدي به غرا ، ولكن … تولت أمر فطنته الحميا\nفقلت له : تثبت تلق رشدا … فكم من سرعة وهبتك غيا\nفإنك لو عرفت وداد قلبي … إليك ، لجئت معتذرا إليا"},{"id":"diwan-barudi:225","bookId":"diwan-barudi","type":"poem","seq":225,"chapter":"البحر: سريع","title":"ما أطول الليل على الساهر !","page":"","text":"ما أطول الليل على الساهر ! … أما لهذا الليل من آخر ؟\nيا مخلف الوعد ! ألا زورة … أقضي بها الحق من الزائر ؟\nتركتنى من غمرات الهوى … فى لج بحر بالردى زاخر\nأسمع في قلبي دبيب المنى … وألمح الشبهة فى خاطرى\nفتارة أهدأ من روعتي … وتارة أفزع كالطائر\nوبين هاتين شبا لوعة … لها بقلبى فتكة الثائر\nفهل إلى الوصلة من شافع ؟ … أم هل على الصبوة من ناصر ؟\nيا قلب لا تجزع ، فإن المنى … فى الصبر ؛ والله مع الصابر"},{"id":"diwan-barudi:226","bookId":"diwan-barudi","type":"poem","seq":226,"chapter":"البحر: مجزوء الكامل","title":"رجع الخديو لمصره","page":"","text":"رجع الخديو لمصره … وأتت طلائع نصره\nوتهللت بقدومه … فرحا أسرة عصره\nفلتبتهج أوطانه … بحلوله فى قصره\nوليشتهر تاريخه … رجع الخديو لمصره"},{"id":"diwan-barudi:227","bookId":"diwan-barudi","type":"poem","seq":227,"chapter":"البحر: سريع","title":"بك استقامت مصر حتى غدت","page":"","text":"بك استقامت مصر حتى غدت … يحمدها الوارد والصادر\nوكيف لا تبصر قصد الهدى … حكومة أنت لها ناظر ؟"},{"id":"diwan-barudi:228","bookId":"diwan-barudi","type":"poem","seq":228,"chapter":"البحر: مجتث","title":"أغرة تحت طره","page":"","text":"أغرة تحت طره … أم نور فجر بسحره ؟\nوذاك فرع ونهد … أم صولجان وأكره ؟\nسمراء تهفو بقد … كالرمح لينا وسمره\nمرت على تهادى … مثل المهاة بشبره\nفقلت : يا نور عينى ! … ما لي على الصبر قدره\nفنقبت وجنتيها … يد الحياء بحمره\nوقالت : اسكت ، وإلا … تصير في الناس شهره\nفقلت هل من وصال … يكون للحب أجره ؟\nفاستضحكت ، ثم قالت … على الخديعة : بكره !"},{"id":"diwan-barudi:229","bookId":"diwan-barudi","type":"poem","seq":229,"chapter":"البحر: خفيف تام","title":"غادة كالمهاة تهفو بخصر","page":"","text":"غادة كالمهاة تهفو بخصر … تحت بند كمعصم في سوار\nتلك عمري هي الحياة ، فلا تؤ … ثر عليها جلائل الأوطار\nفاقسم العمر بين جد ، وهزل … ووقار طورا ، وخلع عذار\nواسع تيلغ ما رمته من نفيس … فالمساعى مدارج الأحرار\nقد ينال الفتى إذا كان شهما … مبتغاه فى ضحوة من نهار"},{"id":"diwan-barudi:230","bookId":"diwan-barudi","type":"poem","seq":230,"chapter":"البحر: طويل","title":"أصافى خليلى ما صفا لى ، فإن جفا","page":"","text":"أصافى خليلى ما صفا لى ، فإن جفا … عتبت عليه غير جاف ، ولا وعر\nفإن عاد لى بالود عدت ، وإن أبى … صبرت ، لأرعى ذمة الود بالصبر\nفإن زادنى هجرا ضربت عن اسمه … وأمسكت عن سخطي عليه وعن شكري\nوما تلك منى نبوة ، غير أننى … أنزه نفسى عن ملابسة الغدر"},{"id":"diwan-barudi:231","bookId":"diwan-barudi","type":"poem","seq":231,"chapter":"البحر: بسيط تام","title":"لكل حى نذير من طبيعته","page":"","text":"لكل حى نذير من طبيعته … يوحى إليه بما تعيا به النذر\nيرجو ويخشى أمورا لو تدبرها … لزال من قلبه التأميل والحذر\nتراه يسعى لجمع المال معتقدا … أن الفتى من لديه السام والشذر\nوكيف تنفى ثياب المرء من دنس … وقلب لابسها من غدره قذر ؟\nيا فارس الخيل ، كفكف عن أعنتها … فقد شكت فعلك الأحلاس والعذر\nإن كنت تبغى بها ما لست تبلغه … من البقاء فبئس البطل والهذر\nإن الحياة وإن طالت إلى أمد … والدهر قرحان ، لا يبقى ، ولا يذر\nلا يأمن الصامت المعصوم صولته … ولا يدوم عليه الناطق البذر\nفاضرع إلى الله ، واستوهبه مغفرة … تمحو الذنوب ، فجانى الذنب يعتذر\nواعجل ، ولا تنتظر توبا غداة غد … فليس في كل حين تقبل العذر\nهيهات ، لا يستوى الشخصان فى عمل … هذا صحيح ، وهذا فاسد مذر"},{"id":"diwan-barudi:232","bookId":"diwan-barudi","type":"poem","seq":232,"chapter":"البحر: طويل","title":"ألا هتفت بالأيك ساجعة القمر","page":"","text":"ألا هتفت بالأيك ساجعة القمر … فطف بالحميا ، فهى ريحانة العمر\nوإن أنت أترعت الأباريق فلتكن … سلافا ، وإياك الفضيخ من التمر\nفقاتلة العرجون للفاقد الندى … وصافية العنقود للماجد الغمر\nموردة ، تمتد منها أشعة … تدور بها فى ظل ألوية حمر\nإذا شجها الساقون دار حبابها … عليها ، كما دار الشرار على الجمر\nثوت فى ضمير الدهر والجو ظلمة … بلا كوكب ، والأرض تسبح فى غمر\nفجاءت ، ولولا عرفها وبريقها … لكانت خفا بين الدساكر كالضمر\nتزف بألحان المثاني كئوسها … كما زفت الحسناء بالطبل والزمر\nكميت جرت في حلبة الدهر ، فانطوت … ثميلتها ، والخيل تحمد بالضمر\nفكم بين آصال أدرنا كئوسها … وبين ليال من كواكبها نمر\nإذا أنت قامرت الزمان على المنى … بما دار من أقداحها فزت بالقمر\nفخذ فى أفانين الخلاعة والصبا … ودعنى من زيد النحاة ومن عمر\nأولئك قوم فى حروب تفاقمت … ولكن خلت من فتكة البيض والسمر\nفما تصلح الأيام إلا إذا خلت … قلوب الورى فيها من الحقد والغمر\nولا تتعرض لامرىء بمساءة … ولا تحتلب ضرع الشقاق ، ولا تمر\nولا تحتقر ذا فاقة بين طمره … فيا رب فضل يبهر العقل في طمر\nوكيف يعيش المرء فى الدهر آمنا … وللموت فينا وثبة الليث والنمر ؟\nوما أحسب الأيام تصفو لعاقل … ولكن صفاء العيش للجاهل الغمر\nسعيت فأدركت المنى في طلابها … وكل امرئ فى الدهر يسعى إلى أمر"},{"id":"diwan-barudi:233","bookId":"diwan-barudi","type":"poem","seq":233,"chapter":"البحر: سريع","title":"نم الصبا ، وانتبه الطائر","page":"","text":"نم الصبا ، وانتبه الطائر … واستحر الصاهل والهادر\nوأضحت الأرض لفيض الحيا … مصقولة يلهو بها الناظر\nتبدو بها أنجم زهر لها … منازل يجهلها الخابر\nكأنما ألبسها نثرة … من النجوم الفلك الدائر\nفقم بنا نله بلذاتنا … فإنما العيش له آخر\nولا تقل : ننظر ما في غد … رب غد آمله خاسر\nفإنما العيش ولذاته … في ساعة أنت بها سادر\nلا يغنم اللذة غير امرئ … ليس له عن لهوه زاجر\nقد خبر الدهر ، فما غائب … يجهله منه ، ولا حاضر\nيا ساقيي ، اعتورا كأسها … فلي بها عن غيرها عاذر\nحمراء تلقي بلحاظ الفتى … صبغا به يعترف الناكر\nتفعل بالشارب أضعاف ما … جر على عنقودها العاصر\nعتقها الدهقان في ديره … حينا ، ولم يشعر بها شاعر\nشج بها ، يكتمها نفسه … وهو ليرضاها غدا صابر\nحتى إذا تمت مواقيتها … وزال عنها الزبد المائر\nجاءت وقد شاكلها كأسها … فاشتبه الباطن والظاهر\nبمثلها تعجبني صبوتي … ويزدهيني الليل والسامر\nفما لهذي الناس في غفلة … عما إليه ينتهى السائر ؟\nألم يروا كيف مضت قبلهم … من أمم ليس لها ذاكر ؟\nإن لم يكن في الأمر من حكمة … ففيم هذا الشغب الثائر ؟\nكل امرئ أسلمه عقله … فما له من بعده ناصر"},{"id":"diwan-barudi:234","bookId":"diwan-barudi","type":"poem","seq":234,"chapter":"البحر: طويل","title":"ولما استقل الحى فى رونق الضحى","page":"","text":"ولما استقل الحى فى رونق الضحى … وقطع أنفاس المقيم المسافر\nتحول راعى الصبر عن مستقره … وباحت بأسرار القلوب النواظر"},{"id":"diwan-barudi:235","bookId":"diwan-barudi","type":"poem","seq":235,"chapter":"البحر: بسيط تام","title":"يا بن الذي رهن الخمار سبحته","page":"","text":"يا بن الذي رهن الخمار سبحته … يوم العروبة فى عد القوارير\nما زال يشرب خمرا غير مدكر … إثما ، ويأكل سحتا غير منحور\nحتى إذا نال منه السكر قام إلى … فياضة القرء ، لم تعهد بتطهير\nفكنت نطفة سوء قد تعجلها … داعى الغواية من خمر وخنزير"},{"id":"diwan-barudi:236","bookId":"diwan-barudi","type":"poem","seq":236,"chapter":"البحر: كامل تام","title":"يأيها السرف المدل بنفسه","page":"","text":"يأيها السرف المدل بنفسه … كسفينة في لج بحر ماخره\nأتظن أن الفخر ثوب معلم … تزهو بلبسته ، وقدر باخره ؟\nهيهات ظنك ، فالعلا أمنية … من دون مبلغها بحار زاخره\nأتلفت دنياك التى أوتيتها … ولسوف تهلك حسرة في الآخره\nتالله لو راجعت نفسك مرة … لوجدتها من سوء فعلك ساخره\nحتام تفخر بالجدود ، ولم تنل … ما أحرزت تلك الجدود الفاخره ؟\nفاجعل لنفسك من فعالك شاهدا … يغنيك عن ذكر العظام الناخره"},{"id":"diwan-barudi:237","bookId":"diwan-barudi","type":"poem","seq":237,"chapter":"البحر: مجتث","title":"فعلت خيرا بقوم","page":"","text":"فعلت خيرا بقوم … فعاملونى بضير\nفلا تلمني إذا ما … أصبحت ألعن خيري"},{"id":"diwan-barudi:238","bookId":"diwan-barudi","type":"poem","seq":238,"chapter":"البحر: سريع","title":"ألهتكم الدنيا عن الآخره","page":"","text":"ألهتكم الدنيا عن الآخره … وهى من الجهل بكم ساخره\nوغركم منها وأنتم بكم … جوع إليها قدرها الباخره\nيمشي الفتى تيها ، وفي ثوبه … من معطفيه جيفة جاخره\nكأنه فى كبره سادرا … سفينة فى لجة ماخره\nكم أنفس عزت بسلطانها … فيما مضى وهي إذن داخره\nوعصبة كانت لأموالها … مظنة الفقر بها ذاخره\nفأصبحت يرحمها من يرى … وقد غنت في نعمة فاخره\nفلا جواد صاهل عزهم … يوما ، ولا خيفانة شاخره\nبل عم دنياهم صروف ، لها … من الردى أودية زاخره\nيأيها الناس اتقوا ربكم … واخشوا عذاب الله والآخره\nأنتم قعود ، والردى قائم … يسقيكم بالكوب والصاخره\nفانتبهوا من غفلات الهوى … واعتبروا بالأعظم الناخره"},{"id":"diwan-barudi:239","bookId":"diwan-barudi","type":"poem","seq":239,"chapter":"البحر: طويل","title":"لك الحمد ، إن الخير منك ، وإننى","page":"","text":"لك الحمد ، إن الخير منك ، وإننى … لصنعك يا رب السموات شاكر\nفأنت الذى أوليتنى كل نعمة … وهذبتني حتى اصطفتني العشائر\nفقرب لى الخير الذى أنا راغب … وباعدني الشر الذي أنا حاذر\nفليس لمن تقصيه فى الناس نافع … وليس لمن تدنيه في الناس ضائر\nولا لامرىء ألهمته الرشد خاذل … ولا لامرى ء أوردته الغي ناصر\nفإن أدركت نفسي المرام ، ولم أقم … مقام ضليع بالذى أنت آمر\nفلا لاح لى فى ذروة المجد كوكب … ولا طار لي في قنة العز طائر"},{"id":"diwan-barudi:240","bookId":"diwan-barudi","type":"poem","seq":240,"chapter":"البحر: بسيط تام","title":"من خالف الحزم خانته معاذره","page":"","text":"من خالف الحزم خانته معاذره … ومن أطاع هواه قل ناصره\nومن تربص بالإخوان بادرة … من الزمان فإن الله قاهره\nلا يجمل المرء فى ظرف وفى أدب … ما لم تكن فوق مرآه سرائره\nوما الصديق الذي يرضيك باطنه … مثل الصديق الذي يرضيك ظاهره\nقد لا يفوه الفتى بالأمر يضمره … وبين عينيه ما تخفي ضمائره\nأستودع الله عصرا قد خلعت به … عذر الهوى وهو غضات مكاسره\nلم يمض من حسنه ما كنت أعهده … حتى أصاب ، سواد القلب ناقره\nكيف الوصول إلى حال نعيش بها … والدهر مأمونة فينا بوادره ؟\nإذ لا صديق يسر السمع غائبه … ولا رفيق يروق العين حاضره\nكنا نود انقلابا نستريح به … حتى إذا تم ساءتنا مصايره\nفالقلب مضطرب فيما يحاوله … والعقل مختبل مما يحاذره\nقد كان فى السلف الماضين نافعه … فصار فى الخلف الباقين ضائره\nما أبعد الخير فى الدنيا لطالبه … وأقرب الشر من نفس تحاذره !\nأكلما مر من دهر أوائله … كرت بمثل أواليه أواخره ؟\nإن دام هذا أضاع الرشد كافله … فيما أرى ، وأطاع الغى زاجره\nتنكرت مصر بعد العرف ، واضطربت … قواعد الملك حتى ريع طائره\nفأهمل الأرض جرا الظلم حارثها … واسترجع المال خوف العدم تاجره\nواستحكم الهول ، حتى ما يبيت فتى … في جوشن الليل إلا وهو ساهره\nويلمه سكنا ، لولا الدفين به … من المآثر ما كنا نجاوزه\nأرضى به غير مغبوط بنعمته … وفى سواه المنى لولا عشائره\nيا نفس لا تجزعي ، فالخير منتظر … وصاحب الصبر لا تبلى مرائره\nلعل بلجة نور يستضاء بها … بعد الظلام الذى عمت دياجره\nإني أرى أنفسا ضاقت بما حملت … وسوف يشهر حد السيف شاهره\nشهران أو بعض شهر إن هى احتدمت … وفى الجديدين ما تغنى فواقره\nفإن أصبت فعن رأى ملكت به … علم الغيوب ، ورأى المرء ناظره"},{"id":"diwan-barudi:241","bookId":"diwan-barudi","type":"poem","seq":241,"chapter":"البحر: طويل","title":"أبابل رأى العين أم هذه مصر","page":"","text":"أبابل رأى العين أم هذه مصر … فإنى أرى فيها عيونا هى السحر\nنواعس أيقظن الهوى بلواحظ … تدين لها بالفتكة البيض والسمر\nفليس لعقل دون سلطانها حمى … ولا لفؤاد دون غشيانها ستر\nفإن يك موسى أبطل السحر مرة … فذلك عصر المعجزات ، وذا عصر\nفأي فؤاد لا يذوب صبابة … ومزنة عين لا يصوب لها قطر ؟\nبنفسى وإن عزت على ربيبة … من العين فى أجفان مقلتها فتر\nفتاة يرف البدر تحت قناعها … ويخطر في أبرادها الغصن النضر\nتريك جمان القطر في أقحوانة … مفلجة الأطراف ، قيل لها ثغر\nتدين لعينيها سواحر ( بابل ) وتسكر من صهباء ريقتها الخمر ) 10 ( فيا ربة الخدر الذى حال دونه … ضراغم حرب ، غابها الأسل السمر\nأما من وصال أستعيد بأنسه … نضارة عيش كان أفسده الهجر ؟\nرضيت من الدنيا بحبك عالما … بأن جنوني في هواك هو الفخر\nفلا تحسبى شوقى فكاهة مازح … فما هو إلا الجمر ، أو دونه الجمر\nهوى كضمير الزند ، لو أن مدمعى … تأخر عن سقياه لاحترق الصدر\nإذا ما أتيت الحي فارت بغيظها … قلوب رجال حشو آماقها الغدر\nيظنون بي شرا ، ولست بأهله … وظن الفتى من غير بينة وزر\nوماذا عليهم إن ترنم شاعر … بقافية لا عيب فيها ، ولا نكر ؟\nأفى الحق أن تبكى الحمائم شجوها … ويبلى فلا يبكى على نفسه حر ؟\nوأى نكير فى هوى شب وقده … بقلب أخي شوق فباح به الشعر ؟\nفلا يبتدرني بالملامة عاذل … فإن الهوى فيه لمعتذر عذر\nإذا لم يكن للحب فضل على النهى … لما ذل حى للهوى وله قدر\nوكيف أسوم القلب صبرا على الهوى … ولم يبق لي في الحب قلب ولا صبر ؟\nليهن الهوى أنى خضعت لحكمه … وإن كان لي في غيره النهي والأمر\nوإنى امرؤ تأبى لى الضيم صولة … مواقعها في كل معترك حمر\nأبي على الحدثان ، لا يستفزني … عظيم ، ولا يأوى إلى ساحتى ذعر\nإذا صلت صال الموت من وكراته … وإن قلت أرخى من أعنته الشعر"},{"id":"diwan-barudi:242","bookId":"diwan-barudi","type":"poem","seq":242,"chapter":"البحر: بسيط تام","title":"للشعر فى الدهر حكم لا يغيره","page":"","text":"للشعر فى الدهر حكم لا يغيره … ما بالحوادث من نقض وتغيير\nيسمو بقوم ، ويهوى آخرون به … كالدهر يجرى بميسور ومعسور\nله أوابد ، لا تنفك سائرة … فى الأرض ما بين إدلاج وتهجير\nمن كل عائرة تستن فى طلق … يغتال بالبهر أنفاس المحاضير\nتجرى مع الشمس فى تيار كهربة … على إطار من الأضواء مسعور\nتطارد البرق إن مرت ، وتتركه … في جوشن من حبيك المزن مزرور\nصحائف لم تزل تتلى بألسنة … للدهر فى كل ناد منه معمور\nيزهى بها كل سام في أرومته … ويتقي البأس منها كل مغمور\nفكم بها رسخت أركان مملكة … وكم بها خمدت أنفاس مغرور\nوالشعر ديوان أخلاق يلوح به … ما خطه الفكر من بحث وتنقير\nكم شاد مجدا ، وكم أودى بمنقبة … رفعا وخفضا بمرجو ومحذور\nأبقى زهير به ما شاده هرم … من الفخار حديثا جد مأثور\nوفل جرول غرب الزبرقان به … فباء منه بصدع غير مجبور\nأخزى جرير به حى النمير ، فما … عادوا بغير حديث منه مشهور\nلولا أب والطيب المأثور منطقه … ما سار فى الدهر يوما ذكر كافور"},{"id":"diwan-barudi:243","bookId":"diwan-barudi","type":"poem","seq":243,"chapter":"البحر: وافر تام","title":"فؤادى والهوى قدح وخمر","page":"","text":"فؤادى والهوى قدح وخمر … أما فى ذاك لى طرب وسكر ؟\nيلومونى على كلفى بليلى … وليلى فى سماء الحسن بدر\nلها خد به للحسن ورد … ولحظ فيه للملكين سحر\nتضن على بالتسليم تيها … وهل في سنة التسليم وزر ؟\nيلوح جبينها في طرتيها … كما أوفى على الظلماء فجر\nوتبسم عن جمان في عقيق … يقال له بحكم الذوق : ثغر"},{"id":"diwan-barudi:244","bookId":"diwan-barudi","type":"poem","seq":244,"chapter":"البحر: طويل","title":"أبى الضيم ، فاستل الحسام وأصحرا","page":"","text":"أبى الضيم ، فاستل الحسام وأصحرا … وذو الحلم إن سيم الهوان تنمرا\nوطارت به في ملتقى الخيل عزمة … أعادت خبين الصبح بالنقع أكدرا\nفرد ذباب المشرفى مثلما … وغادر صدر السمهري مكسرا\nجلاد امرئ آلى بقائم سيفه … على المجد أن يوليه نصرا مؤزرا\nجدير إذا ما هم أن يكسو القنا … وبيض الظبا ثوبا من الدم أحمرا\nوما كل من ساس الأعنة فارسا … ولا كل من ناش الأسنة قسورا"},{"id":"diwan-barudi:245","bookId":"diwan-barudi","type":"poem","seq":245,"chapter":"البحر: خفيف تام","title":"حبذا الراح فى أوان البهار","page":"","text":"حبذا الراح فى أوان البهار … واقتران الكئوس بالنوار\nورنين الأوتار في فلق الصب … ح ، وسجع الطيور فى الأوكار\nبين جو مع الغمائم سار … وفضاء مع الجداول جاري\nمنظر يفتن العقول ، ويجلو … صفحات القلوب والأبصار\nإن عصر الشباب فينا معار … والليالي ترد كل معار\nفاسرحا وامرحا ، فقد آذنتنا … نسمات الصبا بخلع العذار\nواغنما صفوة الربيع بدارا … فالأمانى معقودة بالبدار\nهو فصل تختال فيه غصون ال … روض في حلية من الأزهار\nمائسات مثل العذارى عليهن … ن ثياب درية الأزرار\nغمزتها يد الصبا ، فتلوت … راقصات على غناء القمارى\nرشفت خمرة الندى من كئوس ال … زهر حتى تمايلت من خمار\nفانتبه يا نديم ، واستصبح السا … قى بكأس تفيض بالأنوار\nواسقياني ، وغنياني بلحن … يبعث النفس من إسار الوقار\nفلقد آذن الشتاء بسير … واستهلت طلائع النوبهار\nواستدار النهار حتى تساوت … كفتاه بين الدجى والنهار"},{"id":"diwan-barudi:246","bookId":"diwan-barudi","type":"poem","seq":246,"chapter":"البحر: طويل","title":"يلوموننى فى الجود ، والجود مزنة","page":"","text":"يلوموننى فى الجود ، والجود مزنة … إذا هملت فى موضع نبت الشكر\nإذا المرء لم ينفق من المال وسع ما … دعته المعالى فالثراء هو الفقر"},{"id":"diwan-barudi:247","bookId":"diwan-barudi","type":"poem","seq":247,"chapter":"البحر: طويل","title":"أرى كل شيء عرضة للتغير","page":"","text":"أرى كل شيء عرضة للتغير … فما بالنا بعد الحقيقة نمتري ؟\nترسم فضاء الأرض شرقا ومغربا … عساك ترى آثار كسرى وقيصر"},{"id":"diwan-barudi:248","bookId":"diwan-barudi","type":"poem","seq":248,"chapter":"البحر: طويل","title":"ألائمتى كفى الملام عن الذى","page":"","text":"ألائمتى كفى الملام عن الذى … أحاوله من رحلة وسفار\nفلولا سرى البدر المنير لعاقه … عن التم لبث فى مغيب سرار"},{"id":"diwan-barudi:249","bookId":"diwan-barudi","type":"poem","seq":249,"chapter":"البحر: كامل تام","title":"هيهات ، ليس لحافظ من مشبه","page":"","text":"هيهات ، ليس لحافظ من مشبه … فى القول غير سميه الشيرازى\nجاراه في حسن البيان ، وفاته … فى المنطق العربى بالإعجاز\nلبق بتصريف الكلام يسوقه … ما شاء بين سهولة وعزاز\nفإذا تغزل فالنفوس نوازع … وإذا تحمس فالقلوب نوازى\nكالصارم البتار في إفرنده … وصقاله ، والمارن الهزهاز\nحاك القريض بلهجة عربية … أغنت عن الإسهاب بالإيجاز\nألفاظها نمت على ما تحتها … وصدورها دلت على الأعجاز\nفإذا تلاها قارئ لم يشتبه … فى القول بين حقيقة ومجاز\nعبقت كأنفاس النسيم تعلقت … بالروض غب العارض المجتاز\nقد كان جيد القول عطلا قبله … فحباه أحسن حلية وطراز\nملكت مودته القلوب ، فأصبحت … تلقاه بالتوقير والإعزاز\nلا زال يبلغ شأو كل فضيلة … بمضاء صمصام ، وصولة باز"},{"id":"diwan-barudi:250","bookId":"diwan-barudi","type":"poem","seq":250,"chapter":"البحر: كامل تام","title":"هل فى الخلاعة والصبا من باس","page":"","text":"هل فى الخلاعة والصبا من باس … بين الخليج وروضة المقياس ؟\nأرض كساها النيل من إبداعه … ولباسه الموشي أي لباس\nفكأنما هوت المجرة بينها … فتشكلت فى جملة الأغراس\nيتلهب النوار في أطرافها … فتخاله قبسا من الأقباس\nلولا مساس الطل أحرق ضوؤه … ديل الخمائل : رطبها والعاسى\nتصبو العيون إلى سناه ، فترتمي … مهوى الفراشة لامع النبراس !\nنو شام بهجتها وحسن روائها … فيما أظن لحار عقل إياس\nملهى أخي طرب ، وملعب صبوة … وثرى بلهنية ، ودار أناس\nما كنت في عمري لأغدو نحوها … حتى أبيت بها صريع الكاس\nيا ساقى ، تنبها ، فلقد بدا … فلق الصباح ، ولات حين نعاس\nطوفا علي بها ، فقد نم الصبا … أثناء روحته بسر الآس\nمن خمرة أفنى الزمان شبابها … فى مخدع بقرارة الديماس\nحبست عن الأبصار ، حتى إنها … لم تدر غير الدير والشماس\nينزو لوقع الماء در حبابها … نزو المعابل طرن عن أقواس\nفإذا تعاورها المزاج توجست … حذر المهانة أيما إيجاس\nتشتف من تحت الحباب ، كأنها … ياقوتة قد رصعت بالماس\nما حل بين القوم عقد وكائها … للشرب إلا آدبت بعطاس\nلا يخدعنك في المدامة جاهل … إن المدامة نهزة الأكياس\nإن المدام أساس كل طريفة … فاجعل بناء اللهو فوق أساس\nلا تجمع الأيام كيف تصرفت … فى القلب بين الخمر والوسواس\nفاستوثقا أخوي من شأنيكما … وذرا المطي تمور بالإحلاس\nإن الفلاة لها رجال غيرنا … يبغون نيل اليسر بالإفلاس\nإن الغنى والفقر فى هذا الورى … لمقدر ، والله ذو قسطاس\nفعلام يبلى المرء جدة عمره … متقلبا بين الرجا والياس ؟\nأو ليس أن العيش لبس عباءة … وسداد مسغبة ، ونغبة حاسي ؟\nتالله لو علم الرجال بمكرها … علمى لباعوها بغير مكاس\nهي ساعة تمضي ، وتأتي ساعة … والدهر ذو غير بهذا الناس\nفخذا من الأيام ما سمحت به … للنفس قبل تعذر وشماس\nوإذا أرابكما الزمان بوحشة … فاستمخضاه اليسر بالإيناس\nإن الروائم لا تدر لبونها … إلا بلين المسح والإبساس\nفلرب صعب عاد سهلا بعدما … قطعت عليه مرائر الأنفاس\nما كل ما طلب الفتى هو مدرك … إن الأمور بحكمة وقياس"},{"id":"diwan-barudi:251","bookId":"diwan-barudi","type":"poem","seq":251,"chapter":"البحر: طويل","title":"وذى نخوة نازعته الكأس موهنا","page":"","text":"وذى نخوة نازعته الكأس موهنا … على غرة الأحراس والليل دامس\nفما زلت أسقيه ، وأشرب مثله … إلى أن هفا سكرا وإنى لجالس\nفبت أقيه السوء إذ كان صاحبى … وأحرسه ، إني لدى الخوف حارس\nلدى موطن لا يصحب المرء قلبه … حذارا ، ولا تسرى إليه الهواجس\nعدو ، وليل مظلم ، وصواهل … تجاذب فى أرسانها وتمارس\nفلما استهل النور ، وانحسر الدجى … قليلا ، وحنت للصباح النواقس\nدنوت أفديه ، وأغمز كفه … برفق ، وأدعو باسمه وهو ناعس\nفجاوبنى والسكر فى لحظاته … يسائل : ماذا تبتغي ؟ وهو عابس\nفقلت : أفق ، هذا هو الصبح مقبل … علينا ، وهذى فى الذهاب الحنادس\nوناولته كأسا ، فمد بنانه … إليها على كره به وهو آيس\nفما ذاقها حتى تهلل ضاحكا … وأقبل مسرورا بما هو آنس\nومن شيمى بذل الوداد لأهله … كذلك ، إنى فى الوداد أنافس"},{"id":"diwan-barudi:252","bookId":"diwan-barudi","type":"poem","seq":252,"chapter":"البحر: كامل تام","title":"خل المراء لفتية الدرس","page":"","text":"خل المراء لفتية الدرس … واعكف على صفراء كالورس\nنور توقد بين آنية … كبياض صبح شف عن شمس\nهي جوهر كالنفس ، ما برحت … تهدى السرور لكل ذى نفس\nقد شاكلتها ، فهى تألفها … والجنس يألف صحبة الجنس\nرقت ، ودقت في قرارتها … فسمت عن الإدراك بالحس\nيسقيكها خنث ، شمائله … تدعو إلى التقبيل واللمس\nفاهنأ بعيش ليس يوجد فى … غير الكرى ، أو عالم الحدس"},{"id":"diwan-barudi:253","bookId":"diwan-barudi","type":"poem","seq":253,"chapter":"البحر: سريع","title":"يا رب ليل بت أسقى به","page":"","text":"يا رب ليل بت أسقى به … مشمولة صفراء كالورس\nكأنها فى كأسها شعلة … مقبوسة من كوكب الشمس"},{"id":"diwan-barudi:254","bookId":"diwan-barudi","type":"poem","seq":254,"chapter":"البحر: كامل تام","title":"أحمى الجزيرة مطلع الشمس","page":"","text":"أحمى الجزيرة مطلع الشمس … أم لاح ضوء غزالة الإنس ؟\nخرجت إلى البستان لاهية … تختال بين كواعب خمس\nفتبعت مسراها على عجل … حتى ظفرت بنظرة خلس\nفسترنها عني ، وسرن بها … في روضة فينانة الغرس\nفوقفت مطويا على كمد … ومضت على آثارها نفسي\nتلك التي لولا هواي بها … ما بت من أمل على يأس\nهيهات أنسى حسن صورتها … وحوادث الأيام قد تنسى"},{"id":"diwan-barudi:255","bookId":"diwan-barudi","type":"poem","seq":255,"chapter":"البحر: وافر تام","title":"نزعت عن الصبا ، وعصيت نفسى","page":"","text":"نزعت عن الصبا ، وعصيت نفسى … ودافعت الغواية بالتأسى\nوقلت لصبوتي والعين غرقى … بأدمعها رويدك ، لا تمسى\nفقد ولى الصبا إلا قليلا … أنازع سؤره بفضول كأسى\nومن يك جاوز العشرين تترى … وأردفها بأربعة وخمس\nفقد سفرت لعينيه الليالي … وبان له الهدى من بعد لبس\nنظرت إلى المراة فكشفت لي … قناعا لاح فيه قتير رأسى\nوكنت وكان فينانا أثيثا … أنازع شرتى ، وأذود بأسى\nفعدت وقد ذوى من بعد لين … أداري صبوتي ، وأسر يأسي\nفما أمسي كيومي حين أغدو … على كبر ، وما يومى كأمسى\nوما الأيام إلا صائبات … تمر بكل سابغة وترس\nأبادت قبلنا إرما وعادا … وطارت بين ذبيان وعبس\nوألوت بالمضلل ، واستمالت … عماد الشنفرى ، وهوت بقس\nفلا ( جمشيد ) دافع إذ أتته … بحادثها ، ولا رب الدرفس\nعلى هذا يسير الناس طرا … ويبقى الله خالق كل نفس"},{"id":"diwan-barudi:256","bookId":"diwan-barudi","type":"poem","seq":256,"chapter":"البحر: طويل","title":"أمولاى ، دم للملك ربا تسوسه","page":"","text":"أمولاى ، دم للملك ربا تسوسه … بحكمة مطبوع على الحلم والباس\nولا زالت الأعياد تجرى سعودها … عليك ، وتحظى من علاك بإيناس\nفلولاك ما فازت يد القطر بالمنى … ولا نشأت روح العدالة فى الناس\nوهذا لسان الشكر يدع ومؤرخا … حوى العيد أنواع الفخار بعباس"},{"id":"diwan-barudi:257","bookId":"diwan-barudi","type":"poem","seq":257,"chapter":"البحر: طويل","title":"يقول أناس والعجائب جمة","page":"","text":"يقول أناس والعجائب جمة … متى أصبح الوزان رب مجالس ؟\nنرى كل يوم عصبة في فنائه … تجاذبه أطراف تلك الوساوس\nفقلت لهم : لا تعجبوا لاجتماعهم … لديه ؛ فإن الحش مأوى الخنافس"},{"id":"diwan-barudi:258","bookId":"diwan-barudi","type":"poem","seq":258,"chapter":"البحر: طويل","title":"أملت رجائي في غد ، فانتظرته","page":"","text":"أملت رجائي في غد ، فانتظرته … فما جاء حتى طال حزنى على أمسى\nوقلبت أمرى فيك ، حتى إذا انقضت … وسائل ما آتي بكيت على نفسي"},{"id":"diwan-barudi:259","bookId":"diwan-barudi","type":"poem","seq":259,"chapter":"البحر: طويل","title":"متى ترد الهيم الخوامس منهلا","page":"","text":"متى ترد الهيم الخوامس منهلا … تبل به الأكباد وهي عطاش ؟\nأرى الغيث عم الأرض من كل جانب … وموضع رحلي لم يصبه رشاش\nفهل نهلة من جدول النيل ترتوي … بها كبد ظمآنة ومشاش ؟\nوهل من مقيل تحت أفنان سدرة … لها من زرابي النبات فراش ؟\nلدى أيكة ريا الغصون ، كأنما … عليها من الزهر الجني رياش\nترى الزهر ألوانا ، يطير مع الصبا … كما هاج إبان الربيع فراش\nديار يعيش المرء فيها منعما … وأطيب أرض الله حيث يعاش\nفيا رب ، رشنى كى أعيش مسددا … فقد يستقيم السهم حين يراش"},{"id":"diwan-barudi:260","bookId":"diwan-barudi","type":"poem","seq":260,"chapter":"البحر: وافر تام","title":"رميت فلم أصب ، ورمت فأصمت","page":"","text":"رميت فلم أصب ، ورمت فأصمت … فيا عجبا لسهم لا يطيش !\nحواجبها القسي ، ولحظتاها … بها سهمان ، والأهداب ريش"},{"id":"diwan-barudi:261","bookId":"diwan-barudi","type":"poem","seq":261,"chapter":"البحر: طويل","title":"ومرتبع لذنا به غب سحرة","page":"","text":"ومرتبع لذنا به غب سحرة … وللصبح أنفاس تزيد وتنقص\nوقد مال للغرب الهلال ، كأنه … بمنقاره عن حبة النجم يفحص\nرقيق حواشي النبت ، أما غصونه … فريا ، وأما زهره فمنصص\nإذا عبت أفنانه الريح خلتها … سلاسل تلوى ، أو غدائر تعقص\nكأن صحاف الزهر والطل ذائب … عيون يسيل الدمع منها وتشخص\nيكاد نسيم الفجر إن مر سحرة … بساحته الشجراء لا يتخلص\nكأن شعاع الشمس والريح رهوة … إذا رد فيه سارق يتربص\nيمد يدا دون الثمار ، كأنما … يحاول منها غاية ، ثم ينكص\nعطفنا إليه الخيل فل مسيرة … وللقوم طرف من أذى السهد أخوص\nفما أبصرته الخيل حتى تمطرت … بفرسانها ، واستتلعت كيف تخلص\nمدى لحظة حتى أتته وماؤه … على زهره ، والظل لا يتقلص\nفمدت به الأعناق تعطو وتختلى … نهابا ، وتغلى فى النبات وترخص\nأقمنا به شمس النهار ، وكلنا … على ما به من شدة العجب يحرص\nفلما استرد الشمس جنح من الدجى … وأعرض تيهور من الليل أعوص\nدعونا بأسماء الجياد ، فأقبلت … لواعب فى أرسانها تترقص\nوقمنا ، وكل بعد ما كان لاهيا … بأظلاله كره الرحيل منغص\nيود الفتى ألا يزال بنعمة … وليس له من صولة الدهر مخلص\nفلله عينا من رأى مثل حسنه … وما أنا فيما قلته أتخرص\nظفرت به فى حقبة ، فقنصته … على غرة الأيام ، واللهو يقنص"},{"id":"diwan-barudi:262","bookId":"diwan-barudi","type":"poem","seq":262,"chapter":"البحر: رمل تام","title":"بادر الفرصة ، واحذر فوتها","page":"","text":"بادر الفرصة ، واحذر فوتها … فبلوغ العز في نيل الفرص\nواغتنم عمرك إبان الصبا … فهو إن زاد مع الشيب نقص\nإنما الدنيا خيال عارض … قلما يبقى ، وأخبار تقص\nتارة تدجو ، وطورا تنجلى … عادة الظل سجا ، ثم قلص\nفابتدر مسعاك ، واعلم أن من … بادر الصيد مع الفجر قنص\nلن ينال المرء بالعجز المنى … إنما الفوز لمن هم فنص\nيكدح العاقل فى مأمنه … فإذا ضاق به الأمر شخص\nإن ذا الحاجة ما لم يغترب … عن حماه مثل طير فى قفص\nوليكن سعيك مجدا كله … إن مرعى الشر مكروه أحص\nواترك الحرص تعش في راحة … قلما نال مناه من حرص\nقد يضر الشئ ترجو نفعه … رب ظمآن بصفو الماء غص\nميز الأشياء تعرف قدرها … ليست الغرة من جنس البرص\nواجتنب كل غبى مائق … فهو كالعير ، إذا جد قمص\nإنما الجاهل في العين قذى … حيثما كان ، وفى الصدر غصص\nواحذر النمام تأمن كيده … فهو كالبرغوث إن دب قرص\nيرقب الشر ، فإن لاحت له … فرصة تصلح للختل فرص\nساكن الأطراف ، إلا أنه … إن رأى منشب أظفور رقص\nواختبر من شئت تعرفه ، فما … يعرف الأخلاق إلا من فحص\nهذه حكمة كهل خابر … فاقتنصها ، فهى نعم المقتنص"},{"id":"diwan-barudi:263","bookId":"diwan-barudi","type":"poem","seq":263,"chapter":"البحر: متقارب تام","title":"إذا سدت في معشر ، فاتبع","page":"","text":"إذا سدت في معشر ، فاتبع … سبيل الرشاد ، وكن مخلصا\nووال الكريم ، ودار السفيه … وصل من أطاع ، وخذ من عصى\nونقب لتعلم غيب الأمور … فإن من الحزم أن تفحصا\nولا تبقين على فاجر … فإن اللئام عبيد العصا\nوإن خفي الحق فاصبر له … وبادر إليه إذا حصحصا\nوأخلص لربك فى كل ما … نويت ، تجد عنده مخلصا\nفما الدهر إلا خيال سرى … وظل إذا ما سجا قلصا"},{"id":"diwan-barudi:264","bookId":"diwan-barudi","type":"poem","seq":264,"chapter":"البحر: وافر تام","title":"لعمر أبيك ما خفت حصاتي","page":"","text":"لعمر أبيك ما خفت حصاتي … لنازلة ، ولا ارتعد الفريص\nوما قصرت في طلب المعالي … ولكن ربما خاب الحريص"},{"id":"diwan-barudi:265","bookId":"diwan-barudi","type":"poem","seq":265,"chapter":"البحر: سريع","title":"أين ليالينا بوادى الغضى ؟","page":"","text":"أين ليالينا بوادى الغضى ؟ … ذلك عهد ليته ما انقضى\nكنت به من عيشتي راضيا … حتى إذا ولى عدمت الرضا\nأيام لهو وصبا ، كلما … ذكرتها ضاق علي الفضا\nفآه من دهر بأحكامه … جار علينا ، وقضى ما قضى !\nأي قناع من شباب سرا ؟ … وأى ثوب من نعيم نضا ؟\nقد بيض الأسود من لمتى … يا ليته سود ما بيضا\nعهد كطيف زار ، حتى إذا … أشرق صبح من مشيبى مضى\nما كان إلا كنسيم سرى … وعارض غام ، وبرق أضا\nولى ، ولم يعقب سوى حسرة … بين الحشا ، كالصارم المنتضى\nلولا الغضا وهو مطاف الهوى … ما شب في قلبي جمر الغضى\nأستودع الله به شادنا … عذبنى بالصد ، بل أرمضا\nمعتدل القامة ، ذو لحظة … تعلم الخطي منه المضا\nظبى حمى ، مذ غربت شمسه … عن ناظرى بالبين ما غمضا\nقد سرني حين أتى مقبلا … وساءنى حين مضى معرضا\nحملني من وجده لوعة … لو نهض الدهر بها خفضا\nقد أخذ النوم ، وما رده … واستلب القلب ، وما عوضا\nما باله ماطل فى وعده ؟ … ألم يحن للدين أن يقتضى ؟\nقاضيته عند مليك الهوى … فغل حقى ، وأساء القضا\nفمن له أشكو وقد سامني … جورا ؟ وحق الجور أن يرفضا\nتالله لولا خوف هجرانه … ما بات قلبي عانيا محرضا\nفإن لى من عزمتى صاحبا … يمنعنى فى الروع أن أدحضا\nولست ممن إن دجا حادث … ألقى زمام الأمر أو فوضا\nلكننى ألقى الردى حاسرا … وأصدع الخصم إذا عرضا\nأستحقب الشهد لمن ودني … وأنفث السم لمن أبغضا\nجردت نفسى لطلاب العلا … والسيف لا يرهب أو ينتضى\nولي من القول نصير ، إذا … دعوته في حاجة أوفضا\nسل عني المجد ، ولا تحتشم … فالمجد يدرى أى سيف نضا"},{"id":"diwan-barudi:266","bookId":"diwan-barudi","type":"poem","seq":266,"chapter":"البحر: وافر تام","title":"وروعاء المسامع ما تمطت","page":"","text":"وروعاء المسامع ما تمطت … بحمل بين سائمة مخاض\nخرجت بها على البيداء وهنا … خروج الليث من سدف الغياض\nتقلب أيديا متسابقات … إلى الغايات كالنبل المواضى\nمددت زمامها والصبح باد … فما كفكفتها والليل غاضي\nفما بلغت مغيب الشمس حتى … أضافت آتيا منه بماضي\nأحال السيرجرتها رمادا … فراحت وهي خاوية الوفاض\nوما كانت لتسأم ، غير أنى … رميت بها اعتزامي واعتراضي\nهتكت بها ستور الليل حتى … خرجت من السواد إلى البياض"},{"id":"diwan-barudi:267","bookId":"diwan-barudi","type":"poem","seq":267,"chapter":"البحر: بسيط تام","title":"رب الفتوة ، لا تسبق إلى عذل","page":"","text":"رب الفتوة ، لا تسبق إلى عذل … يبيت من مسه قلبى على مضض\nفإن تكن هفوة أو زلة عرضت … فالسهم يصدف أحيانا عن الغرض"},{"id":"diwan-barudi:268","bookId":"diwan-barudi","type":"poem","seq":268,"chapter":"البحر: طويل","title":"إذا أنت أبغضت امرا فاخش ضره","page":"","text":"إذا أنت أبغضت امرا فاخش ضره … فأنت لديه ، مثل ذاك بغيض\nفإن قلوب الناس تمتاز فطرة … فمنها لبعض آلف ونقيض\nوعاشر من الخلان من كان سالما … فليس سواء سالم ومريض\nفقد لا يفيد القول نصحا وحكمة … إذا حال من دون القريض جريض"},{"id":"diwan-barudi:269","bookId":"diwan-barudi","type":"poem","seq":269,"chapter":"البحر: طويل","title":"تحبب إلى الإخوان بالحلم تغتنم","page":"","text":"تحبب إلى الإخوان بالحلم تغتنم … مودتهم ، فالحلم للشر يرحض"},{"id":"diwan-barudi:270","bookId":"diwan-barudi","type":"poem","seq":270,"chapter":"البحر: وافر تام","title":"أبيت الرد للسؤال علما","page":"","text":"أبيت الرد للسؤال علما … بما فى ذاك من بسط وقبض\nفإما عائل فأصون منه … وإما فاجر فأصون عرضى"},{"id":"diwan-barudi:271","bookId":"diwan-barudi","type":"poem","seq":271,"chapter":"البحر: بسيط تام","title":"رضيت بالبين إيثارا على سكن","page":"","text":"رضيت بالبين إيثارا على سكن … فى معشر ودهم إن أخلصوا مرض\nفما أسيت لشيء كنت أملكه … في فقد أوجههم عن ثروتي عوض"},{"id":"diwan-barudi:272","bookId":"diwan-barudi","type":"poem","seq":272,"chapter":"البحر: بسيط تام","title":"هل فى الزمان لنا حكم فنشترط ؟","page":"","text":"هل فى الزمان لنا حكم فنشترط ؟ … أم تلك أمنية في طيها قنط\nنبكى على غير شئ ، ثم يضحكنا … ما ليس فيه لنا بقيا فنختلط\nوكيف نرجو من الأيام عافية … وصحة المرء مقرون بها السقط ؟\nنرعى من الدهر غيثا نبته أسف … للرائدين ، وروضا زهره شطط\nفلا يغرنك من دهر بشاشته … فإنما هو بشر تحته سخط\nلا يدرك الغاية القصوى سوى رجل … ثبت العزيمة ماض حيث ينخرط\nإن مسه الضيم ناجى السيف منتصرا … أو همه الأمر لم يعلق به الثبط\nفاقذف بنفسك في أقصى مطالبها … إن النجاح بسعي المرء مرتبط\nقد يظفر الفاتك الألوى بحاجته … وليس يدركها الهيابة الخلط\nوإن شأتك المنى فاقنع بأقربها … فليس في كل حين يدرك الوسط\nلا تعفلن إذا أمنية عرضت … فإنما العيش في هذا الورى لقط\nإني وإن كانت الأيام قد أخذت … منى ، وأخنى على الضعف والشمط\nفقد أذوذ السبنتى عن فريسته … وأفجأ البطل الحامي فأختبط\nوأصدع الجيش والفرسان من مرح … تحت العجاج بأطراف القنا نخط\nفما بنصلى إن لاقى ضريبته … نكل ، ولا فى جفيرى أسهم مرط\nورب يوم طويل العمر قصره … جري السوابق والوخادة النشط\nكأنما الوحش من تلهاب جمرته … مبددا تحت أشجار الغضى خبط\nترى به القوم صرعى لا حراك بهم … كأنهم من عتيق الخمر قد سقطوا\nوليلة ذات تهتان وأندية … كأنما البرق فيها صارم سلط\nلف الغمام أقاسيها ببردته … وانهل في حجرتيها وابل سبط\nبهماء لا يهتدي الساري بكوكبها … من الغمام ، ولا يبدو بها نمط\nيكاد يجهل فيها القوم أمرهم … لولا صهيل جياد الخيل واللغط\nيطغى بها البرق أحيانا ، فيزجره … مخرنطم زجل من رعدها خمط\nكأنما البرق سوط ، والحيا نجب … يلوح في جسمها من مسه حبط\nكأنه صارم يرفض من علق … بالأفق يغمد أحيانا ويخترط\nمزقت جلبابها بالخيل طالعة … مثل الحمائم فى أجيادها العلط\nوقد تخلل خيط النور ظلمتها … كما تخلل شعر اللمة الوخط\nكأنها وصديع الفجر يصدعها … من جانب أدهم قد مسه نبط\nومربع لنسيم الفجر هينمة … فيه ، وللطير في أرجائه لغط\nكأنما القطر در فى جوانبه … يكاد من صدف الأزهار يلتقط\nوللنسيم خلال النبت غلغلة … كما تغلغل وسط اللمة المشط\nوالريح تمحو سطورا ، ثم تثبتها … فى النهر ، لا صحة فيها ولا غلط\nوللسماء خيوط غير واهية … تكاد تجمع بالأيدي فترتبط\nكأنها وأكف الريح تضربها … سلوك عقد تواهت ، فهى تنخرط\nفالضوء محتبس ، والماء منطلق … والجو منقبض ، والظل منبسط\nلذنا بأطرافه والطير عاكفة … عليه ، والنور بالظلماء مختلط\nفي فتية رضعوا ثدي الوفاق ، فما … فيهم إذا ما انتشوا جور ولا شطط\nتحالفوا في صفاء الود ، واجتمعوا … على الوفاء طوال الدهر ، واشترطوا\nكالغيث إن وهبوا ، والليث إن وثبوا … والماء إن عدلوا ، والنار إن قسطوا\nتكشف الدهر عنهم بعد غمته … كما تكشف عن مكنونه السفط\nميل بأبصارهم نحوى ليستمعوا … قولي ، وكل لأمري طائع نشط\nإن سرت ساروا ، وإن أصعد إلى نشز … كانوا صعودا ، وإن أهبط بهم هبطوا\nيمشون حولي ، كما يمشي القطا بددا … فإن مضى بقط منهم أتى بقط\nأن يكنفوني من حولي فلا عجب … لا يسقط الطير إلا حيث يلتقط\nنمشى به بين أشجار كأن على … أفنانها من برود اليمنة الريط\nمثل الطواويس في أذنابها عجب … للناظرين ، وفي أجيادها عنط\nكأنهن جمالات موقرة … تمور مورا على أثباجها الغبط\nوللفواخت في أفنانها هزج … قد ماج من لحنهن السهل والفرط\nخضر الجناحين والأطواق ، تحسبها … أطفال ملك لها من سندس قمط\nحتى إذا حل ضاحي اليوم حبوته … وكادت الشمس بين الغرب تنهبط\nرحنا نجر ذيول العز ضافية … وكلنا بنعيم العيش مغتبط\nيوم من الدهر أهوى لو بذلت له … ما شاء فى مثله لو كان يشترط"},{"id":"diwan-barudi:273","bookId":"diwan-barudi","type":"poem","seq":273,"chapter":"البحر: طويل","title":"تمهل ، ولاتعجل إذا رمت حاجة","page":"","text":"تمهل ، ولاتعجل إذا رمت حاجة … فقد يلحق الخسران من يتورط\nفذو الحزم يرعى القصد فى كل حالة … وذ والجهل إما مفرط أو مفرط"},{"id":"diwan-barudi:274","bookId":"diwan-barudi","type":"poem","seq":274,"chapter":"البحر: كامل تام","title":"سكرت بخمر حديثك الألفاظ","page":"","text":"سكرت بخمر حديثك الألفاظ … وتكلمت بضميرك الألحاظ\nيا دمية لولا التقية لاستوت … في حبها الفتاك والوعاظ\nما لي منحتك خلتي ، وجزيتني … نارا لها بين الضلوع شواظ ؟\nهلا مننت إذ امتلكت ! فطالما … من الكريم وقلبه مغتاظ\nفلقد هجرت إليك جل عشيرتى … فقلوبهم أبدا علي غلاظ\nونفيت عن عيني المنام ، فمالها … غير المدامع والسهاد لماظ\nهدا ، وما اختضبت لغيرك أسهم … بدمى ، ولا احتكمت على لحاظ\nفعلام تستمعين ما يأتى به … عنى إليك الحاسد الجواظ ؟\nفصلي محبا ، ما أصاب خطيئة … في دين حبك ، والغرام حفاظ\nيهواك حتى لا يميل بطبعه … في حبك الإيذاء والإحفاظ\nناب المضاجع ، لا تزور جفونه … سنة الكرى ، وأولو الهوى أيقاظ\nمتحمل ما لو تحمل بعضه … أهل المحبة والغرام لفاظوا\nفإذا استهل تربعوا فيما جرى … من دمعه ، وإذا تنفس قاظوا\nهذا هو الحب الذي ضاقت به … تلك الصدور ، وقلت الحفاظ"},{"id":"diwan-barudi:275","bookId":"diwan-barudi","type":"poem","seq":275,"chapter":"البحر: طويل","title":"متى يجد الإنسان خلا موافقا","page":"","text":"متى يجد الإنسان خلا موافقا … يخفف عنه كلفة المتحفظ ؟\nفإنى رأيت الناس بين مخادع … لإخوانه ، أو حاسد متغيظ"},{"id":"diwan-barudi:276","bookId":"diwan-barudi","type":"poem","seq":276,"chapter":"البحر: مجزوء الخفيف","title":"من لقلبي بشادن","page":"","text":"من لقلبي بشادن … لم يمتع بحظه ؟\nقد سباني بطرفه … وشجانى بلفظه\nكل شيء سيرعوي … غير قلبي ولحظه"},{"id":"diwan-barudi:277","bookId":"diwan-barudi","type":"poem","seq":277,"chapter":"البحر: خفيف تام","title":"أنت مني ما بين فكر ولفظ","page":"","text":"أنت مني ما بين فكر ولفظ … فمتى يشتفي بقربك لحظي ؟\nغبت عني مدى ثلاث ، فزادت … حسراتي ، وغاب أنسي وحظي\nفأجب دعوتي ، ولا تنس وعدا … لك بالوصل لا يزال بحفظى"},{"id":"diwan-barudi:278","bookId":"diwan-barudi","type":"poem","seq":278,"chapter":"البحر: طويل","title":"متى أنت عن أحموقة الغى نازع","page":"","text":"متى أنت عن أحموقة الغى نازع … وفى الشيب للنفس الأبية وازع ؟\nألا إن في تسع وعشرين حجة … لكل أخي لهو عن اللهو رادع\nفحتام تصبيك الغوانى بدلها … وتهف وبليتيك الحمام السواجع ؟\nأما لك فى الماضين قبلك زاجر … يكفك عن هذا ؟ بلى ، أنت طامع\nوهل يستفيق المرء من سكرة الصبا … إذا لم تهذب جانبيه الوقائع ؟\nيرى المرء عنوان المنون برأسه … ويذهب يلهى نفسه ويصانع\nألا إنما هذي الليالي عقارب … تدب ، وهذا الدهر ذئب مخادع\nفلا تحسبن الدهر لعبة هازل … فما هو إلا صرفه والفجائع\nفيا ربما بات الفتى وهو آمن … وأصبح قد سدت عليه المطالع\nففيم اقتناء الدرع والسهم نافذ ؟ … وفيم ادخار المال والعمر ضائع ؟\nيود الفتى أن يجمع الأرض كلها … إليه ، ولما يدر ما الله صانع\nفقد يستحيل المال حتفا لربه … وتأتي على أعقابهن المطامع\nألا إنما الأيام تجري بحكمها … فيحرم ذو كد ، ويرزق وادع\nفلا تقعدن للدهر تنظر غبه … على حسرة ، فالله معط ومانع\nفلو أن ما يعطى الفتى قدر نفسه … لما بات رئبال الشرى وهو جائع\nودع كل ذى عقل يسير بعقله … ينازع من أهوائه ما ينازع\nفما الناس إلا كالذى أنا عالم … قديما ، وعلم المرء بالشيء نافع\nولست بعلام الغيوب ، وإنما … أرى بلحاظ الرأي ما هو واقع\nوذرهم يخوضوا ، إنما هي فتنة … لهم بينها عما قليل مصارع\nفلو علم الإنسان ما هو كائن … لما نام سمار ، ولا هب هاجع\nوما هذه الأجسام إلا هياكل … مصورة ، فيها النفوس ودائع\nفأين الملوك الأقدمون تسنموا … قلال العلا ؟ فالأرض منهم بلاقع\nمضوا ، وأقام الدهر ، وانتاب بعدهم … ملوك ، وبادوا ، واستهلت طلائع\nأرى كل حي ذاهبا بيد الردى … فهل أحد ممن ترحل راجع ؟\nأنادى بأعلى الصوت ، أسأل عنهم … فهل أنت يا دهر الأعاجيب سامع ؟\nفإن كنت لم تسمع نداء ، ولم تحر … جوابا ، فأي الشيء أنت أنازع ؟\nخيال لعمرى ، ليس يجدى طلابه … ومأسفة تدمى عليها الأصابع\nفمن لي وروعات المنى طيف حالم … بذي خلة تزكو لديه الصنائع ؟\nأشاطره ودى ، وأفضى لسمعه … بسرى ، وأمليه المنى وهو رابع\nلعلى إذا صادفت فى القول راحة … نضحت غليلا ما روته المشارع\nلعمر أبي ، وهو الذي لو ذكرته … لما اختال فخار ، ولا احتال خادع\nلما نازعتنى النفس فى غير حقها … ولا ذللتني للرجال المطامع\nوما أنا والدنيا نعيم ولذة … بذي ترف تحنو عليه المضاجع\nفلا السيف مفلول ، ولا الرأى عازب … ولا الزند مغلول ، ولا الساق ظالع\nولكنني في معشر لم يقم بهم … كريم ، ولم يركب شبا السيف خالع\nلواعب بالأسماء يبتدرونها … سفاها ، وبالألقاب ، فهى بضائع\nوهل في التحلي بالكنى من فضيلة … إذا لم تزين بالفعال الطبائع ؟\nأعاشرهم رغما ، وودي لو ان لي … بهم نعما أدعو به فيسارع\nفيا قوم ، هبوا ، إنما العمر فرصة … وفى الدهر طرق جمة ومنافع\nأصبرا على مس الهوان وأنتم … عديد الحصى ؟ إنى إلى الله راجع\nوكيف ترون الذل دار إقامة … وذلك فضل الله فى الأرض واسع\nأرى أرؤسا قد أينعت لحصادها … فأين ولا أين السيوف القواطع ؟\nفكونوا حصيدا خامدين ، أو افزعوا … إلى الحرب حتى يدفع الضيم دافع\nأهبت ، فعاد الصوت لم يقض حاجة … إلى ، ولبانى الصدى وهو طائع\nفلم أدر أن الله صور قبلكم … تماثيل لم يخلق لهن مسامع\nفلا تدعوا هذى القلوب ، فإنها … قوارير محنى عليها الأضالع\nودونكموها صعدة منطقية … تفل شبا الأرماح وهي شوارع\nتسير بها الركبان في كل منزل … وتلتف من شوق إليها المجامع\nفمنها لقوم أوشح وقلائد … ومنها لقوم آخرين جوامع\nألا إنها تلك التى لو تنزلت … على جبل أهوت به ، فهو خاشع"},{"id":"diwan-barudi:279","bookId":"diwan-barudi","type":"poem","seq":279,"chapter":"البحر: كامل تام","title":"أترى الحمام ينوح من طرب معى","page":"","text":"أترى الحمام ينوح من طرب معى … وندى الغمامة يستهل لمدمعي ؟\nما للنسيم بليلة أذياله ؟ … أتراه مر على جداول أدمعي ؟\nبل ما لهذا البرق ملتهب الحشا ؟ … أسمت إليه شرارة من أضلعي ؟\nلم أدر هل شعر الزمان بلوعتى … فرثى لها ، أم هاجت الدنيا معى ؟\nفالغيث يهمى رقة لصبابتى … والطير تبكي رحمة لتوجعي\nخطرات شوق ، ألهبت بجوانحي … نارا يدب أزيزها في مسمعي\nوجوى كأطراف الأسنة ، لم يدع … للصبر بين مقيله من مفزع\nيأهل ذا النادى ! أليس بكم فتى … يرثى لويلات المشوق المولع ؟\nأبكي ، فيرحمني الجماد ، ولا أرى … خلا يرق إلى شكاتي ، أو يعي\nفإذا دعوت بصاحب لم يلتفت … وإذا لجأت إلى أخ لم ينفع\nومن العجائب أنني أشكو الهوى … والذنب لى فى كل ما أنا مدعى\nقد طالما يا قلب قلت لك احترس … أرأيت كيف يخيب من لم يسمع ؟\nأوقعت نفسك فى حبائل خدعة … لا تستقال ، فخذ لنفسك أو دع\nيا ظبية المقياس ! هذا مدمعى … فردى ، وهذا روض قلبى فارتعى\nإن كان لا يرضيك إلا شقوتى … فلقد بلغت مناك منها ، فاقنعى\nأنا منك بين صبابة لاتنقضى … أيامها ، وغواية لم تقلع\nفثقى بما تمليه ألسنة الهوى … وهي الدموع ، فحقها لم يدفع\nلاتحسبى قولى خديعة ماكر … إن الوفي بعهده لم يخدع\nإني لأقنع من هواك بنظرة … وأعدها صلة إذا لم تمنعي\nهذي مناي ، وحبذا لو نلتها … عن طيب نفس ، فهي أكبر مقنع"},{"id":"diwan-barudi:280","bookId":"diwan-barudi","type":"poem","seq":280,"chapter":"البحر: سريع","title":"هل من فتى ينشد قلبى معى","page":"","text":"هل من فتى ينشد قلبى معى … بين خدور العين بالأجرع ؟\nكان معى ، ثم دعاه الهوى … فمر بالحي ، ولم يرجع\nفهل إذا ناديته باسمه … يفيق من سكرته أو يعي ؟\nهيهات يلقى رشدا بعد ما … أغواه لحظ الرشإ الأتلع\nفيا دموع القطر سيلى دما … ويا بنات الأيك نوحي معي\nوأنت يا نسمة وادي الغضى … مري برياك على مربعي\nوأنت يا عصفورة المنحنى … بالله غني طربا ، واسجعي\nوأنت يا عين إذا لم تفي … بذمة الدمع ، فلا تهجعي\nصبابة أغرت علي الأسى ! … ودلت السهد على مضجعى !\nويلاه من نار الهوى ! إنها … لولا دموعي أحرقت أضلعي\nأبيت أرعى النجم فى سدفة … ضل بها الصبح ، فلم يطلع\nلاأهتدى فيها إلى حيلة … تقى حياتى من يدى مصرعى\nطورا أدارى لوعتى بالمنى … وتارة يغلبني مدمعي\nفهل إلى الأشواق من غاية ؟ … أم هل إلى الأوطان من مرجع ؟\nلا تأس يا قلب على ما مضى … لابد للمحنة من مقطع"},{"id":"diwan-barudi:281","bookId":"diwan-barudi","type":"poem","seq":281,"chapter":"البحر: طويل","title":"فؤاد بأقمار الأكلة مولع","page":"","text":"فؤاد بأقمار الأكلة مولع … وعين على إثر التفرق تدمع\nوشوق كنصل السيف ، لو شمت حده … على بطل لانقد منه المقنع\nأحاول كتمان الهوى ، فتشى به … غروب من العين القريحة تهمع\nوما الحب إلا نفثة بابلية … يكاد الصفا من مسها يتصدع\nخليلى ! هل بعد الصبابة سلوة ؟ … وهل لشباب فات بالأمس مرجع ؟\nأبيت أمنى النفس طورا فترعوى … وأتلو عليها اليأس طورا فتجزع\nوما ذكر ريعان الصبا غير حسرة … تذل لها نفس العزيز وتخضع\nفلا رحم الله المشيب وعصره … وإن كان فى أثنائه الحلم أجمع\nنهار مشيب ساءنى وهو أبيض … وليل شباب سرني وهو أسفع\nإذا شاب رأس المرء شاب فؤاده … ولم يبق فيه للبشاشة موضع\nوأى نعيم فى مشيب وراءه … هموم إذا مرت على القلب يفزع ؟\nليبك الصبا قلبي وطرفي كلاهما … وقل له مني نجيع وأدمع\nزمان تولى غير أعقاب ذكرة … إذا خطرت كادت لها النفس تنزع"},{"id":"diwan-barudi:282","bookId":"diwan-barudi","type":"poem","seq":282,"chapter":"البحر: متقارب تام","title":"كتمت الهوى خوف إفشائه","page":"","text":"كتمت الهوى خوف إفشائه … فألهب نار الغضى فى ضلوعى\nفلما خشيت على مهجتي … أذعت الهوى بلسان الدموع"},{"id":"diwan-barudi:283","bookId":"diwan-barudi","type":"poem","seq":283,"chapter":"البحر: طويل","title":"ألا بأبى من حسنه وحديثه","page":"","text":"ألا بأبى من حسنه وحديثه … إذا ما التقينا لذة العين والسمع\nرأى مقلتي ترعى رياض جماله … فعاقبها حدين : بالسهد والدمع"},{"id":"diwan-barudi:284","bookId":"diwan-barudi","type":"poem","seq":284,"chapter":"البحر: متقارب تام","title":"أليس من العدل أن تسمعا ؟","page":"","text":"أليس من العدل أن تسمعا ؟ … فأشكو إليك نموما سعى\nأطاع له الماء حتى استقى … وأمكنه الرعي حتى رعى\nأتاك فأغشيته منزلا … رحيبا ، وأرعيته مسمعا\nفأبدع ما شاء فى فرية … تأنق في صنعها وادعى\nصناع اللسان ، خلوب البيا … ن ، يخلق من ضحكه أدمعا\nحريص على الشر ، لا ينثني … عن القصد ما لم يجد منزعا\nيسير مع الرفق ، حتى إذا … تمكن من فرصة أوضعا\nوما كان لولا خلاج الظنون … ليرغب في القول ، أو يطمعا\nولا وحفاظك ، وهو اليمي … ن ما حلت عن عهدكم إصبعا\nولكنها نزغات الوشاة … أصابت هوى ، فلوت أخدعا\nوليس ملامي على من وشى … ولكن ملامى على من وعى\nأيجمل بالعهد أن يستباح … لواش ، وللود أن يقطعا ؟\nفشتان ما بيننا في الودا … د : خل أضاع ، وخل رعى\nومن أشرك الناس فى أمره … دعته الضرورة أن يخدعا\nفخذها إليك عتابية … ترد عصي المنى طيعا\nولولا مكانك من مهجتى … لما قلت لابن عثار لعا"},{"id":"diwan-barudi:285","bookId":"diwan-barudi","type":"poem","seq":285,"chapter":"البحر: خفيف تام","title":"إن قلبي وهو الأبي دهته","page":"","text":"إن قلبي وهو الأبي دهته … فرقة صيرته نهبا مشاعا\nلاترى غير واقف يسفح الدم … ع ، وساه لا يستطيع زماعا\nوصلة قربت بعادا ، وبين … من حبيب أجد فيه اجتماعا\nكنت أخشى الوداع ، حتى إذا ما … فارقوني أمسيت أرجو الوداعا"},{"id":"diwan-barudi:286","bookId":"diwan-barudi","type":"poem","seq":286,"chapter":"البحر: طويل","title":"إن كان أمر الله حتما مقدرا","page":"","text":"إن كان أمر الله حتما مقدرا … فماذا يفيد الحرص والأمر واقع ؟"},{"id":"diwan-barudi:287","bookId":"diwan-barudi","type":"poem","seq":287,"chapter":"البحر: مجزوء الكامل","title":"إن النصيحة لا تحض","page":"","text":"إن النصيحة لا تحض … على الأذى إن لم تزع\nفاسمع ، فإن خيرا أصب … ت فخذ ، وإن شرا فدع"},{"id":"diwan-barudi:288","bookId":"diwan-barudi","type":"poem","seq":288,"chapter":"البحر: بسيط تام","title":"لكل قول منار يستقيم به","page":"","text":"لكل قول منار يستقيم به … عند الخطاب : فملفوظ ومسموع\nفالعتب إن جاز حد العدل مقطعة … والنصح ما لم يكن في السر تقريع"},{"id":"diwan-barudi:289","bookId":"diwan-barudi","type":"poem","seq":289,"chapter":"البحر: طويل","title":"متى يشتفي هذا الفؤاد المفجع","page":"","text":"متى يشتفي هذا الفؤاد المفجع … وفى كل يوم راحل ليس يرجع ؟\nنميل من الدنيا إلى ظل مزنة … لها بارق فيه المنية تلمع\nوكيف يطيب العيش والمرء قائم … على حذر من هول ما يتوقع ؟\nبنا كل يوم للحوادث وقعة … تسيل لها منا نفوس وأدمع\nفأجسادنا في مطرح الأرض همد … وأرواحنا فى مسرح الجو رتع\nومن عجب أنا نساء ونرتضى … وندرك أسباب الفناء ونطمع\nولو علم الإنسان عقبان أمره … لهان عليه ما يسر ويفجع\nتسير بنا الأيام ، والموت موعد … وتدفعنا الأرحام ، والأرض تبلع\nعفاء على الدنيا ، فما لعداتها … وفاء ، ولا في عيشها متمتع\nأبعد سمير الفضل ' أحمد فارس ' … تقر جنوب ، أو يلائم مضجع ؟\nكفى حزنا أن النوى صدعت به … فؤادا من الحدثان لا يتصدع\nوما كنت مجزاعا ، ولكن ذا الأسى … إذا لم يساعده التصبر يجزع\nفقدناه فقدان الشراب على الظما … ففى كل قلب غلة ليس تنقع\nوأى فؤاد لم يبت لمصابه … على لوعة ، أو مقلة ليس تدمع ؟\nإذا لم يكن للدمع فى الخد مسرب … روي فما للحزن في القلب موضع\nمضى ، وورثناه علوما غزيرة … تظل بها هيم الخواطر تشرع\nإذا تليت آياتها فى مقامة … تنافس قلب فى هواها ومسمع\nسقى جدثا فى أرض ' لبنان ' عارض … من المزن فياض الجداول مترع\nفإن به للمكرمات حشاشة … طواها الردى ، فالقلب حران موجع\nفإن يكن ( الشدياق ) خلى مكانه … فإن ابنه عن حوزة المجد يدفع\nوما مات من أبقى على الدهر فاضلا … يؤلف أشتات المعالي ويجمع\nرزين حصاة الحلم ، لا يستخفه … إلى اللهو طبع ، فهو بالجد مولع\nتلوح عليه من أبيه شمائل … تدل على طيب الخلال ، وتنزع\nفصبرا جميلا ' يا سليم ' فإنما … يسيغ الفتى بالصبر ما يتجرع\nإذا المرء لم يصبر على ما أصابه … فماذا تراه فى المقدر يصنع ؟\nومثلك من راز الأمور بعقله … وأدرك منها ما يضر وينفع\nفلا تعطين الحزن قلبك ، واستعن … عليه بصبر ، فهو فى الحزن أنجع\nوهاك على بعد المزار قريبة … إلى النفس ، يدعوها الوفاء فتتبع\nرعيت بها حق الوداد على النوى … وللحق فى حكم البصيرة مقطع"},{"id":"diwan-barudi:290","bookId":"diwan-barudi","type":"poem","seq":290,"chapter":"البحر: كامل تام","title":"ردي التحية يا مهاة الأجرع","page":"","text":"ردي التحية يا مهاة الأجرع … وصلى بحبلك حبل من لم يقطع\nوترفقى بمتيم علقت به … نار الصبابة ، فهو ذا كى الأضلع\nطرب الفؤاد ، يكاد يحمله الهوى … شوقا إليك مع البروق اللمع\nلا يستنيم إلى العزاء ، ولا يرى … حقا لصبوته إذا لم يجزع\nضمت جوانحه إليك رسالة … عنوانها في الخد حمر الأدمع\nفمتى يبوح بما أجن ضميره … إن كنت عنه بنجوة لم تسمعي ؟\nأصبحت بعدك في دياجر غربة … ما للصباح بليلها من مطلع\nلا يهتدى فيها لرحلى طارق … إلا بأنة قلبي المتوجع\nأرعى الكواكب في السماء ، كأن لي … عند النجوم رهينة لم تدفع\nزهر تألق بالفضاء ، كأنها … حبب تردد فى غدير مترع\nوكأنها حول المجر حمائم … بيض عكفن على جوانب مشرع\nوترى الثريا فى السماء كأنها … حلقات قرط بالجمان مرصع\nبيضاء ناصعة كبيض نعامة … في جوف أدحي بأرض بلقع\nوكأنها أكر توقد نورها … بالكهرباءة فى سماوة مصنع\nوالليل مرهوب الحمية ، قائم … فى مسحه ، كالراهب المتلفع\nمتوشح بالنيرات ، كباسل … من نسل حام ، باللجين مدرع\nحسب النجوم تخلفت عن أمره … فوحى لهن من الهلال بإصبع\nما زلت أرقب فجره حتى انجلى … عن مثل شادخة الكميت الأتلع\nوترنمت فوق الأراك حمامة … تصف الهوى بلسان صب مولع\nتدعو الهديل ، وما رأته ، وتلك من … شيم الحمائم بدعة لم تسمع\nريا المسالك ، حيث أمت صادفت … ما تشتهى من مجثم أو مرتع\nفإذا علت سكنت مظلة أيكة … وإذا هوت وردت قرارة منبع\nأملت علي قصيدة فجعلتها ( لشكيب ) تحفة صادق لم يدع )4 ( هى من أهازيج الحمام ، وإنما … ضمنتها مدح الهمام الأروع\nهو ذلك الشهم الذي بلغت به … مسعاته أمد السماك الأرفع\nنبراس داجية ، وعقلة شارد … وخطيب أندية ، وفارس مجمع\nصدق البيان ، أعض جرول باسمه … وثنى ( جريرا بالجرير الأطوع )8\nلم يتخذ بدر المقنع آية … بل جاء خاطره بآية يوشع\nأحيا رميم الشعر بعد هموده … وأعاد للأيام عصر ( الأصمعي )0\nكلم لها فى السمع أطرب نغمة … وبحجرة الأسرار أحسن موقع\nكالزهر خامره الندى ، فتأرجت … أنفاسه بالعنبر المتضوع\nيعنو لها الخصم الألد ، ويغتذي … بلبانها ذهن الخطيب المصقع\nهى نجعة الأدب التى من أمها … ألقى مراسيه بواد ممرع\nملكت هوى نفسى ، وأحيت خاطرى … وروت صدى قلبي ، ولذت مسمعي\nفاسلم شكيب ولا برحت بنعمة … تحنو عليك بأيكها المتفرع\nفلأنت أجدر بالثناء لمنة … أوليتها ، والبر أفضل ما رعي\nأرهفت حدى ، فهو غير مفلل … ورعيت عهدي ، فهو غير مضيع\nوبثقت لى من فيض بحرك جدولا … غمر البحار بسيله المتدفع\nعذبت موارده ، فلو ألقت به … هيم السحاب دلاءها لم تقلع\nوزهت فرائده ، فصارت غرة … لجبين كل متوج ومقنع\nهو ذلك النظم الذي شهدت له … أهل البراعة بالمقال المبدع\nأبصرت منه أخا ( إياد ) خاطبا … وسمعت عنترة الفوارس يدعى\nوحلمت أني في خمائل جنة … ومن العجائب حالم لم يهجع\nفضل رفعت به منار كرامة … صرف العيون عن المنار ( لتبع )\nفمتى أقوم بشكر ما أوليتنى … والنجم أقرب غاية من منزعى\nفاعذر إذا قصر الثناء ، فإنني … رزت المقال فلم أجد من مقنع\nلا زلت ترفل في وشاء سعادة … وحبير عافية ، وعيش أمرع"},{"id":"diwan-barudi:291","bookId":"diwan-barudi","type":"poem","seq":291,"chapter":"البحر: بسيط تام","title":"هل بالحمى عن سرير الملك من يزع ؟","page":"","text":"هل بالحمى عن سرير الملك من يزع ؟ … هيهات ، قد ذهب المتبوع والتبع\nهذي ( الجزيرة ) فانظر هل ترى أحدا … ينأى به الخوف ، أو يدنو به الطمع ؟\nأضحت خلاء ، وكانت قبل منزلة … للملك ، منها لوفد العز مرتبع\nفلا مجيب يرد القول عن نبأ … ولا سميع إذا ناديت يستمع\nكانت منازل أملاك ، إذا صدعوا … بالأمر كادت قلوب الناس تنصدع\nعاثوا بها حقبة ، حتى إذا نهضت … طير الحوادث من أوكارها وقعوا\nلو أنهم علموا مقدار ما فغرت … به الحوادث ما شادوا ، ولا رفعوا\nدارت عليهم رحى الأيام ، فانشعبوا … أيدى سبا ، وتخلت عنهم الشيع\nكانت لهم عصب يستدفعون بها … كيد العدو ، فما ضروا ، ولا نفعوا\nأين المعاقل ، بل أين الجحافل ، بل … أين المناصل والخطية الشرع\nلا شيء يدفع كيد الدهر إن عصفت … أحداثه ، أو يقى من شر ما يقع\nزالوا ، فما بكت الدنيا لفرقتهم … ولا تعطلت الأعياد والجمع\nوالدهر ك … وإنما صفوه بين الورى لمع\nلو كان للمرء فكر في عواقبه … ما شان أخلاقه حرص ولا طبع\nوكيف يدرك ما في الغيب من حدث … من لم يزل بغرور العيش ينخدع\nدهر يغر ، وآمال تسر وأع … مار تمر ، وأيام لها خدع\nيسعى الفتى لأمور قد تضر به … وليس يعلم ما يأتي وما يدع\nيأيها السادر المزور من صلف … مهلا ، فإنك بالأيام منخدع\nدع ما يريب ، وخذ فيما خلقت له … لعل قلبك بالإيمان ينتفع\nإن الحياة لثوب سوف تخلعه … وكل ثوب إذا ما رث ينخلع"},{"id":"diwan-barudi:292","bookId":"diwan-barudi","type":"poem","seq":292,"chapter":"البحر: بسيط تام","title":"لبيك يا داعي الأشواق من داعي","page":"","text":"لبيك يا داعي الأشواق من داعي … أسمعت قلبي وإن أخطأت أسماعي\nمرنى بما شئت أبلغ كل ما وصلت … يدي إليه ، فإني سامع واعي\nفلا وربك ما أصغى إلى عذل … ولا أبيح حمى قلبي لخداع\nإني امرؤ لا يرد العذل بادرتي … ولا تفل شباة الخطب إزماعي\nأجرى على شيمة فى الحب صادقة … ليست تهم إذا ريعت بإقلاع\nللحب من مهجتي كهف يلوذ به … من غدر كل امرئ بالشر وقاع\nبذلت فى الحب نفسى وهى غالية … لباخل بصفاء الود مناع\nأشكو إليه ، ولا يصغي لمعذرتي … من غير ذنب جنته النفس أو داعي\nويلاه من حاجة في النفس هام بها … قلبي ، وقصر عن إدراكها باعي\nأسعى لها وهى منى غير دانية … وكيف يبلغ شأو الكوكب الساعى ؟\nيا حبذا جرعة من ماء محنية … وضجعة فوق برد الرمل بالقاع !\nونسمة كشميم الخلد قد حملت … ريا الأزاهير من ميث وأجراع\nيا هل أرانى بذاك الحى مجتمعا … بأهل ودى من قومى وأشياعى ؟\nوهل أسوق جوادى للطراد إلى … صيد الجآذر في خضراء ممراع ؟\nمنازل كنت منها في بلهنية … ممتعا بين غلماني وأتباعي\nإذا أشرت لهم في حاجة بدروا … قضاءها قبل أن يرتد إلماعي\nيخشى البليغ لساني قبل بادرتي … ويرعد الجيش باسمى قبل إيقاعى\nفاليوم أصبحت لا سهمي بذي صرد … إذا رميت ، ولا سيفي بقطاع\nأبيت في قنة قنواء قد بلغت … هام السماك ، وفاتته بأبواع\nيستقبل المزن ليتيها بوابله … وتصدم الريح جنبيها بزعزاع\nيظل شمراخها يبسا ، وأسفلها … مكللا بالندى يرعى به الراعى\nإذا البروق ازمهرت خلت ذروتها … شهما تدرع من تبر بأدراع\nتكاد تلمس منها الشمس دانية … وتحبس البدر عن سير وإقلاع\nأظل فيها غريب الدار مبتئسا … نابى المضاجع من هم وأوجاع\nلا فى ' سرنديب ' خل أستعين به … على الهموم إذا هاجت ، ولا راعي\nيظننى من يرانى ضاحكا جذلا … أنى خلى ، وهمى بين أضلاعى\nولا ، وربك ما وجدى بمندرس … على البعاد ولا صبرى بمطواع\nلكننى مالك حزمى ، ومنتظر … أمرا من الله يشفي برح أوجاعي\nأكف غرب دموعي وهي جارية … خوف الرقيب وقلبي جد ملتاع\nفإن يكن ساءني دهري ، وغادرني … رهن الأسى بين جدب بعد إمراع\nفإن فى مصر إخوانا يسرهم … قربي ، ويعجبهم نظمي وإبداعي"},{"id":"diwan-barudi:293","bookId":"diwan-barudi","type":"poem","seq":293,"chapter":"البحر: طويل","title":"قليل بآداب المودة من يفي","page":"","text":"قليل بآداب المودة من يفي … فمن لي بخل أصطفيه وأكتفي ؟\nبلوت بني الدنيا ، فلم أر صاحبا … يدوم على ود بغير تكلف\nفهل من فتى يسرو عن القلب همه … بشيمة مطبوع على المجد مسعف ؟\nرضيت بمن لا تشتهي النفس قربه … ومن لم يجد مندوحة يتكلف\nولو أننى صادفت خلا يسرنى … على عدواء الدار لم أتلهف\nولكنني أصبحت في دار غربة … مقيما لدى قوم على البد عكف\nزعانف هداجون في عرصاتهم … كخيط نعام بين جرداء صفصف\nحفاة عراة غير أخلاق صدرة … تطير كنسج العنكبوت المسدف\nيمجون من أفواههم رشح مضغة … كنضح دم ينهل من أنف مرعف\nإذا راطنوا بعضا سمعت لصوتهم … عزيفا كجن في المفاوز هتف\nفها أنا منهم بين شمل مبدد … ومن حسراتي بين شمل مؤلف\nأحن إلى أهلي ، وأذكر جيرتي … وأشتاق خلانى ، وأصبو لمألفى\nفلا أنا أسلو عن هواى فأنتهى … ولا أنا ألقى من أحب فأشتفي\nوإنى على ما كان من سرف النوى … لباق على ودي لمن كنت أصطفي\nسجية نفس لا تميل مع الهوى … وذمة عهد بين سيف ومصحف\nوما كل موشي الحديث بصادق … ولا كل منسوب إلى الود بالوفي\nتشابهت الأخلاق إلا بقية … بها يعرف الماضي من المتخلف\nوما شرف الإنسان إلا بنفسه … وإن كان ذا مال تليد ومطرف\nولو كان نيل الفضل سهلا لزاحمت … رجال الخنا أهل العلا والتعطف\nفإن أخلفت نفس طوية ما وأت … فلي من ( علي صاحب غير مخلف )\nهمام ، دعا باسمى ، فلبيت صوته … بيا مرحباه من فؤاد مكلف\nولو صاح بي في غارة لوزعتها … على متن محبوك السراة بمرهف\nولكنني لبيت دعوة نظمه … بأسمر مشقوق اللسان محرف\nإذا حركته راحتى فوق مهرق … بذكر علاه بذكل مثقف\nهو البطل السباق فى كل غاية … يهاب رداها المرء قبل التعسف\nإذا قال لم يترك بيانا لقائل … وإن سار لم يترك مجالا لمقتفى\nله قلم لو كان للسيف حده … لفل حبيك السرد فى كل موقف\nوشعلة فكر لو بمثل ضيائها … أنار سراج الأفق ما كان ينطفى\nفسيح مجال الفكر ، ثبت يقينه … بعيد مناط الهم ، حر التصرف\nأديب ، له فى جنة الشعر دوحة … أفاءت على الدنيا بأجمل زخرف\nإذا نورت أفنانها غب ديمة … من الفكر جاءت بالبديع المفوف\nترنم فيها من ثنائي بلبل … بلحن له في السمع نبرة معزف\nحفيت له بالود منى ، وكيف لا … أسابقه في وده وهو بي حفي ؟\nتألف نفسى بعد ما زال أنسها … ونوه باسمي بعد ما كاد يختفي\nوحرك أسلاك التراسل بيننا … بسيال ود لفظه لم يحرف\nوفى الناس معطوف على الود قلبه … ومنهم سقيم العهد بادي التحرف\nتوسمت فيه الخير قبل لقائه … وأحمدت منه الخبر بعد التعرف\nوما حركات النفس إلا دلالة … على صدق ما قالوا به في التعيف\nفقد تكذب العين الفتى وهو غافل … ويصدق ظن العاقل المتشوف\nوفيت بوعدى فى الثناء وإن يكن … مقالي بهاتيك الفضائل لا يفي\nوكيف وإن أوتيت في النظم قدرة … أضم شتات الكون فى بعض أحرف ؟"},{"id":"diwan-barudi:294","bookId":"diwan-barudi","type":"poem","seq":294,"chapter":"البحر: مجزوء المتقارب","title":"لوى جيده وانصرف","page":"","text":"لوى جيده وانصرف … فما ضره لو عطف ؟\nغزال له نظرة … أعانت علي الكلف\nتبسم عن لؤلؤ … له من عقيق صدف\nوتاه فلم يلتفت … وشأن الجمال الصلف\nجرى البند في خصره … على حركات الهيف\nوما ذاك خال بدا … ولكن وسام الترف\nرآنى به مولعا … فعاتبنى وانحرف\nولم يدر أنى به … على جمرات التلف\nفقلت له : سيدي ! … ترفق بصب دنف\nفقال : أخاف العدا … فقلت له : لا تخف\nفإنى عفيف الهوى … وما كل صب يعف\nوأنشدته قطعة … وشعرى إحدى الطرف\nفاصغى لها باسما … وبان عليه الأسف\nونمت به خجلة … تدل على ما اقترف\nوقال : أهذا الضنى … جناه عليك الشغف ؟\nفقلت : نعم ، سيدى ! … وأبرح مما أصف\nفصدق ، لكنه … تجاهل لما عرف\nوقال : أطعت المنى … وبعض الأماني سرف\nوما كل ذي حاجة … يفوز بها إن عكف\nفأشفقت من قوله … ولكن ربي لطف\nفلما رأى أدمعى … توالت ، وقلبى رجف\nتبسم لي ضاحكا … ومانع ، ثم انعطف\nفأغرمته قبلة … عفا الله عما سلف"},{"id":"diwan-barudi:295","bookId":"diwan-barudi","type":"poem","seq":295,"chapter":"البحر: بسيط تام","title":"من لي بظبية خدر كلما وعدت","page":"","text":"من لي بظبية خدر كلما وعدت … بزورة أعقبت للوعد إخلافا\nتحكى الغزالة ألحاظا إذا نظرت … والورد خدا ، وغصن البان أعطافا\nتاهت بنقطة خال فوق وجنتها … زيدت بها عشرات الحسن أضعافا"},{"id":"diwan-barudi:296","bookId":"diwan-barudi","type":"poem","seq":296,"chapter":"البحر: كامل تام","title":"بكر الندى ، وترفع السدف","page":"","text":"بكر الندى ، وترفع السدف … وأتت وفود اللهو تختلف\nودعت إلى شرب الصبوح وقد … رق الظلام حمائم هتف\nفانهض على قدم الربيع ، فما … فى نيل أيام الصبا سرف\nوانظر ، فثم غمامة أنف … تولى الجميل وروضة أنف\nزهر يرف على كمائمه … وندى يشف ، ومزنة تكف\nفالطل منتثر ، ومنتظم … والغصن مفترق ، ومؤتلف\nوالروض يرفل فى معصفرة … بالزهر للأبصار تختطف\nعنى الربيع بنسج بردتها … إن الربيع لصانع ثقف\nلا شيء أحسن من بلهنية … فى العيش قلد جيدها الشغف\nوعصابة غلب الكمال على … أخلاقهم وغذاهم الترف\nنازعتهم طرف الحديث وقد … جرت الكؤوس بنا ، فما اختلفوا\nقلبي بهم كلف ، وناظرتي … عن حسنهم تالله تنحرف\nفمحبتى لهم كما عرفوا … صدق ، ووجدي فوق ما أصف\nلله أيام بهم سلفت … لو أنها بالوصل تؤتنف\nإذ لمتي فينانة ، ويدي … فوق الأكف ، وقامتى ألف\nأجرى على إثر الشباب ، ولا … يمشي إلى ساحاتي الجنف\nضافي الغديرة ، عارم شرس … صعب المريرة ، سادر أنف\nإن سرت سار الناس لي تبعا … وإذا وقفت لحاجة وقفوا\nفالآن أصبح طائرى وقع … بعد السمو وصبوتى أسف\nوغدوت بعد الكبرياء على … كل الورى بالعجز أعترف\nوكذلك الأيام ، آخرها … بعد الشباب الضعف والخرف\nوالمرء مهما طال طائله … يوما لصائبة الردى هدف\nفلبئس ما قدم المشيب به … ولنعم ما ولى به السلف"},{"id":"diwan-barudi:297","bookId":"diwan-barudi","type":"poem","seq":297,"chapter":"البحر: طويل","title":"وذى نعرات يقطع الأرض ساريا","page":"","text":"وذى نعرات يقطع الأرض ساريا … على غير ساق وهو بالأرض أعرف\nله فوق أعناق للرياح سبائب … محبرة ، منها قصير ومسدف\nكأن سليمان بن داود فوقه … على عرشه ، والجن بالجن تعزف\nيجد بنا فى امره وهو لاعب … ويضحك أحيانا وعيناه تذرف\nتلهب فيه النار والماء سافح … فلا الماء يطفيها ، ولا النار تضعف\nإذا سار عن أرض غدت وهى جنة … وإن حل أخرى عمها منه زخرف\nيكون حياة للنفوس ، وربما … ضبت منه نار ، أو سطا منه مرهف\nله زفرة تترى ، وعين سخية … وقلب كزهراء المصابيح يرجف\nيسير على متن الهواء ، وتارة … يخضخض سجلا في البحار فيغرف\nأضر بأعناق النعائم حمله … فألقت به عن ظهرها ، فهو يرسف\nله هيدب ملء الفضاء ، كأنه … مناكب أطواد على الأرض تزحف\nفزعنا إليه ، نحسب الجون عسكرا … يسير ، فشمنا برقه وهو يخطف\nفقلنا : سحاب ، يا سقى الله أرضنا … به ، وروانا ، فهو بالناس أرأف\nفما تم أن سارت به الريح سيرة … إلينا ، ووافى رائد الحى يحلف\nفقمنا إليه واثقين بجوده … نسير ، ويعرونا السرور فنهتف\nدنا ، فتناولنا خياشيم مزنه … قعودا ، فظلت وهي بالماء ترعف\nوطافت به الولدان يخلجن ماء ه … بأكوابها ، والهم يدنو فيغرف\nفلأيا بلأى ما تولت حداءه … مزمجرة هوجاء بالقاع تعصف\nفأبقى لنا أثرا حميدا ، ونعمة … لها مسحب نضر ، وجيب مفوف\nكذلك ، ما كنا لنكفر صنعه … على أن بعض الناس بالشر أكلف"},{"id":"diwan-barudi:298","bookId":"diwan-barudi","type":"poem","seq":298,"chapter":"البحر: مجزوء الخفيف","title":"هتف الديك سحرة","page":"","text":"هتف الديك سحرة … فاصطبحنا لهتفه\nبشراب كعينه … وكباب كعرفه"},{"id":"diwan-barudi:299","bookId":"diwan-barudi","type":"poem","seq":299,"chapter":"البحر: مجزوء الوافر","title":"حياتي في الهوى تلف","page":"","text":"حياتي في الهوى تلف … وأمري فيه مختلف\nأبيت الليل مكتئبا … وقلبي في الحشا يجف\nفنومي كله سهر … وعيشك كله أسف\nوما أخفيه من وجدي … وحزنى فوق ما أصف\nفهل من صاحب يرثي … لما ألقى فينعطف ؟\nأيقتلنى الهوى ظلما … وما في الناس لي خلف ؟\nوهبنى فارس الهيجا … ء أغشاها فتنكشف\nأليس العشق سلطانا … له الأكوان ترتجف ؟\nإذا كان الهوى خصمي … فقل لى : كيف أنتصف ؟"},{"id":"diwan-barudi:300","bookId":"diwan-barudi","type":"poem","seq":300,"chapter":"البحر: مجتث","title":"قلبي عليك يرف","page":"","text":"قلبي عليك يرف … وعبرتى لا تجف\nوأنت يا نور عيني … بلوعتى تستخف\nقد شفنى طول وجدى … والحب داء يشف\nفارحم فديتك صبا … إلى لقاك يخف"},{"id":"diwan-barudi:301","bookId":"diwan-barudi","type":"poem","seq":301,"chapter":"البحر: مجزوء الكامل","title":"عيني لبعدك أصبحت","page":"","text":"عيني لبعدك أصبحت … لا تستقل الجفن ضعفا\nإنسانها في غمرة … من أدمعى ، يبدو ويخفى"},{"id":"diwan-barudi:302","bookId":"diwan-barudi","type":"poem","seq":302,"chapter":"البحر: طويل","title":"تغرب إذا أتربت ، والتمس الغنى","page":"","text":"تغرب إذا أتربت ، والتمس الغنى … فما العز إلا من وراء التعسف\nفقد يعدم الإنسان في عقر داره … مناه ، ويلقى حظه فى التطوف\nفكل مكان يضمن الرزق للفتى … إذا لم يكن فيه عديم التصرف"},{"id":"diwan-barudi:303","bookId":"diwan-barudi","type":"poem","seq":303,"chapter":"البحر: كامل تام","title":"سكن الفؤاد ، وجفت الآماق","page":"","text":"سكن الفؤاد ، وجفت الآماق … ومضت على أعقابها الأشواق\nونزعت عن نزق الشبيبة والصبا … بعد المشيب ، وللشباب نزاق\nلا الدار دار بعد ما رحل الصبا … عني ، ولا تلك الرفاق رفاق\nولقد جريت مع الغواية والصبا … جري الكميت ، وللغرام سباق\nولبست هذا الدهر من أطرافه … ونزعته وقميصه أخلاق\nفإذا الشباب وديعة ، وإذا الفتى … هدي لفاغرة المنون يساق\nلله أيام لنا معروفة … سبقت ، وليس لسبقهن لحاق\nحيث الصبا نهب ، وسلسال الهوى … عذب ، وآنية السرور دهاق\nفي جنة خضراء ، ورد خدودها … زاه ، وغيث مدامها غيداق\nسفرت بها الأقمار من أطواقها … وتجمعت بفنائها العشاق\nفالنطق جهر ، والتحية قبلة … بين الأحبة ، والسلام عناق\nلايسأمون اللهو بين ملاعب … قد قام فيها للخلاعة ساق\nيفتن عقل المرء فى تصويرها … وتحار في تمثيلها الأحداق\nفعلى المروج من الخمائل رفرف … وعلى الخمائل للغيوم رواق\nبعث الربيع لهن من أنفاسه … فسمت طباق فوقهن طباق\nدنيا نعيم لا بقاء لحسنها … ونعيم دنيا ما لها ميثاق\nفلقد مضى ذاك الزمان بحسنه … وسما إلى الهم والإيراق\nوغدوت حران الفؤاد كأنما … ضاقت على برحبها الآفاق\nنفست على بنو الزمان شمائلى … فلهم بذلك خفة ونزاق\nحسبوا التحول فى الطباع خليقة … وتحول الأخلاق ليس يطاق\nتالله أهدأ أو تقوم قيامة … فيها الدماء على الدماء تراق\nترتد عين الشمس فى ستراتها … \nشعواء تلتهم الفضاء ، ويرتقى … منها على حبك السماء نطاق\nأنا لا أقر على القبيح مهابة … إن القرار على القبيح نفاق\nقلبي على ثقة ونفسي حرة … تأبى الدني ، وصارمي ذلاق\nفعلام يخشى المرء فرقة روحه ؟ … أو ليس عاقبة الحياة فراق ؟\nفارغب بنفسك وهى فى أثوابها … إن لم تكن شام فتلك عراق\nلا خير في عيش الجبان يحوطه … من جانبيه الذل والإملاق\nعابوا علي حميتي ونكايتي … والنار ليس يعيبها الإحراق\nفاضرحهم ضرح العيون قذاتها … وحذار ، لا تعلق بك العلاق\nفالناس أشباه ، وشتى بينهم … تدنو الجسوم ، وتبعد الأخلاق\nفاعرضهم ، واحذر تشابه أمرهم … لا تستوي الأغلال والأطواق\nلا تحسبن الرفق ينزع غلهم … الشر داء ما له إفراق\nشروا الضلالة بالهدى ، واغترهم … لين الحياة ، وماؤها الرقراق\nفترى الفتى منهم كأن برأسه … نزغ الجنون ، فليس فيه لياق\nمتلون الأخلاق بين عشيره … جهلا ، كما يتلون الشقراق\nلهج بعارية الحياة ، وما درى … أن الحياة إلى المنون مساق\nلو كان يسلم فى الزمان من الردى … حى لعاش بجوه السيذاق\nأربى على شمراخ أرعن باذخ … سام ، له فوق السحائب طاق\nنهمان يعتلق القطا بمخالب … حجن ، لهن بوقعها تصعاق\nلا يستقر به الجناح ، وطرفه … متقلب يسمو به الإرشاق\nبينا كذلك إذ أصاب عصابة … للطير أرسلها صدى محراق\nفسما ، فحلق ، فاستدار ، فصكها … بمذرب تمكو له الأعناق\nتسمو ، فيتبعها ، فتهوى وهو فى … آثارها مر الشهاب حراق\nمذعورة تبغى الفرار من الردى … إن الفرار من المنون وثاق\nحتى إذا فترت ، وحط بها الونى … سقطت ، فليس لنفسها أرماق\nفأتى ، فمزقها كما حكم الردى … ولكل نفس مرة إزهاق\nأفذاك ، أم ضرغام خيس مدهس … تنجاب عن أنيابه الأشداق ؟\nمنع الطريق ، فما تجوس خلاله … في سيرها الطراق والمراق\nغضبان ، يضرب ذيله ، ويلفه … من جانبيه ، كأنه مخراق\nعصفت عليه النائجات ، وخاب من … هام الوحوش له حشا وصفاق\nفسما ، فأبصر راعيين تخلفا … بالعير ، تصدح بينهن نياق\nفأجم قوته ، وشد بوثبة … صم الصخور لوقعها أفلاق\nحتى إذا اعترض الرحال إذا بها … يقظ تلين لكفه الأرزاق\nمتقلد سيفا ترف متونه … رف المصابح شفهن لياق\nفتصاولا ، حتى إذا ما استنفدا … ما كان عندهما ، وضاق خناق\nهما ببعضهما ، فماتا ميتة … لهما بها حتى المعاد وفاق\nأم أرقش مرس يسيل كأنه … بين الخمائل جدول دفاق\nيتناذر الراقون سم لعابه … رعبا ، فليس لمسه درياق\nتسم الظلام ذبالتان برأسه … تقدان ليس عليهما أطباق\nيسرى فيقتحم السرار ، ويرتمى … بسناهما المتنبل المرشاق\nترك الوحوش له الفلاة ، وأغلت … طلب النجاة ، فجمعها أحذاق\nحتى إذا ظن الظنون بنفسه … تيها بها ، وخلت له الأعماق\nأنحى فأقصده الزمان بسهمه … إن الزمان لنا بل ميفاق\nحكم تحيرت البريه دونها … وتنازعت أسبابها الحذاق\nفاسمع ، فما كل الكلام بطيب … ولكل قول في السماع مذاق\nنزل الكلام إلى من شرفاته … وتمثلت بحديثي الافاق"},{"id":"diwan-barudi:304","bookId":"diwan-barudi","type":"poem","seq":304,"chapter":"البحر: سريع","title":"عودي بوصل ، أو خذي ما بقي","page":"","text":"عودي بوصل ، أو خذي ما بقي … فقد تداعى القلب مما لقي\nأي فؤاد بك لم يعلق … وأنت صنو القمر المشرق ؟\nعلمتني الذل ، وكنت امرأ … أفعل ما شئت ، ولا أتقي\nفارحم فؤادا أنت أبليته … ومقله لولاك لم تأرق\nلم أدر حتام أقاسي الجوى … يا ويح قلبى منك ! ماذا لقى ؟\nإذا تذكرتك فى خلوة … هوت بدمعى زفرة ترتقى\nتالله ما أنصف من لامنى … فيك ، وهل لوم على مشفق ؟\nوكيف لا أعشق من حسنه … يدعو إلى الصبوة قلب النقى ؟\nلك الجمال التم دون الورى … وليس للبدر سوى رونق\nفاعطف على قلب به لوعة … ينزو لها في الصدر كالزئبق\nيكاد يرفض هوى كلما … لاح له البرق من الأبرق\nحمى به ما شئت من صبوة … لو كان فيه من يفى ، أو يقى\nحاطت به الفرسان حور المها … يا من رأى الربرب فى الفيلق\nمن كل هيفاء كخوط القنا … بلحظة كاللهذم الأزرق\nتخطر في الفينان من فرعها … فهى على التمثيل كالبيرق\nأرنو إليها وهى فى شأنها … كنظرة العاني إلى المطلق\nفما ترانى صانعا وهى لا … تسمع ما أسرد من منطقي ؟\nيا ربة القرطق ! هل نظرة … أحيا بها ؟ ياربة القرطق !\nإن كان يرضيك ذهاب الذي … أبقيت منى ، فخذى ما بقى\nلم تبق منى صدمات الهوى … غير صدى بين حشا محرق\nقد كنت قبل الحب ذا تدرإ … أقتحم الهول ولم أفرق\nفاليوم أصبحت عديم القوى … يسبقنى الذر ولم ألحق\nوالحب ملك نافذ حكمه … من مغرب الأرض إلى المشرق\nفليقل العاذل ما شاءه … فالعشق دأب الشاعر المفلق\nلو لم أكن ذا شيمة حرة … لم أقرض الشعر ، ولم أعشق"},{"id":"diwan-barudi:305","bookId":"diwan-barudi","type":"poem","seq":305,"chapter":"البحر: خفيف تام","title":"أي قلب على صدودك يبقى ؟","page":"","text":"أي قلب على صدودك يبقى ؟ … أو لم يكف أننى ذبت عشقا ؟\nلم تدع منى الصبابة إلا … شبحا شفه السقام فدقا\nودموعا أسالها الوجد حتى … غلبت أدمع الغمامة سبقا\nفتصدق بنظرة منك تشفي … داء قلب من الغرام ملقى\nكان أبقى منه الغرام قليلا … فأذاب الصدود ما قد تبقى\nلا تسلنى عن بعض ما أنا فيه … من غرام ، فلست أملك نطقا\nسل إذا شئت أنجم الليل عني … فهى أدرى بكل ما بت ألقى\nنفس لا يبين ضعفا ، وجسم … سار فيه الضنى ، فأصبح ملقى\nفترفق بمهجة شفها الوج … د ، فذابت ، وأدمع ليس ترقا\nإن يكن دأبك الصدود فقلبي … عنك راض ، وإن غدا بك يشقى\nفعليك السلام منى ؛ فإنى … مت شوقا ، والله خير وأبقى"},{"id":"diwan-barudi:306","bookId":"diwan-barudi","type":"poem","seq":306,"chapter":"البحر: وافر تام","title":"أليلى ! ما لقلبك ليس يرثى","page":"","text":"أليلى ! ما لقلبك ليس يرثى … لما ألقاه من ألم الفراق ؟\nكتمت هواك حتى نم دمعي … وذابت مهجتي مما ألاقي\nورقت لي قلوب الناس حتى … بكى لى كل ساق فوق ساق\nتلوميني على عبرات عيني ؟ … ولولا الحب لم تجر المآقي\nومن عجب الهوى يا ليل أني … فنيت صبابة وهواك باقي\nوما إن عشت بعد البين إلا … لما أرجوه من وشك التلاقى\nولولا أننى فى قيد سقم … لطرت إليك من فرط اشتياقي"},{"id":"diwan-barudi:307","bookId":"diwan-barudi","type":"poem","seq":307,"chapter":"البحر: خفيف تام","title":"رب ، خذ لى من العيون بحقى","page":"","text":"رب ، خذ لى من العيون بحقى … وأجرني من ظالم ليس يبقي\nقد توقيت ما استطعت من الحب … ب ، ولكن ماذا يرد التوقي ؟\nوترفقت بالفؤاد ، ولكن … غلبت لوعة الصبابة رفقي\nلا تلمنى على الهوى ، فغموض ال … حق عذر يرد كل محق\nسل دموعى ، فهن ينبئن عما … في ضميري ، ويعترفن بصدقي\nكيف لى بالنجاة من شرك الحب … ب سليما ، والحب مالك رقي ؟\nقد تلقيت لوعتى من عيون … علمتني درس الهوى بالتلقي\nورشوت الهوى بلؤلؤ دمعي … والرشا وصلة لنيل الترقي\nفلعلي أفوز يوما بوصل … أتولى به إمارة عشق"},{"id":"diwan-barudi:308","bookId":"diwan-barudi","type":"poem","seq":308,"chapter":"البحر: بسيط تام","title":"هل من طبيب لداء الحب ، أوراقى ؟","page":"","text":"هل من طبيب لداء الحب ، أوراقى ؟ … يشفى عليلا أخا حزن وإيراق\nقد كان أبقى الهوى من مهجتي رمقا … حتى جرى البين ، فاستولى على الباقي\nحزن برانى ، وأشواق رعت كبدى … يا ويح نفسى من حزن وأشواق\nأكلف النفس صبرا وهى جازعة … والصبر في الحب أعيا كل مشتاق\nلافى ' سرنديب ' لى خل ألوذ به … ولا أنيس سوى همى وإطراقى\nأبيت أرعى نجوم الليل مرتفقا … في قنة عز مرقاها على الراقي\nتقلدت من جمان الشهب منطقة … معقودة بوشاح غير مقلاق\nكأن نجم الثريا وهو مضطرب … دون الهلال سراج لاح في طاق\nولا برحت من الأوراق فى حلل … من سندس عبقرى الوشى براق\nيا حبذا نسم من جوها عبق … يسرى على جدول بالماء دفاق\nبل حبذا دوحة تدعو الهديل بها … عند الصباح قمارى بأطواق\nمرعى جيادى ، ومأوى جيرتى ، وحمى … قومي ، ومنبت آدابي وأعراقي\nأصبو إليها على بعد ، ويعجبنى … أنى أعيش بها فى ثوب إملاق\nوكيف أنسى ديارا قد تركت بها … أهلا كراما لهم ودي وإشفاقي ؟\nإذا تذكرت أياما بهم سلفت … تحدرت بغروب الدمع آماقى\nفيا بريد الصبا بلغ ذوى رحمى … أنى مقيم على عهدى وميثاقى\nوإن مررت على ( المقياس ) فاهد له … منى تحية نفس ذات أعلاق\nوأنت يا طائرا يبكى على فنن … نفسي فداؤك من ساق على ساق\nأذكرتني ما مضى والشمل مجتمع … ' بمصر ' زالحرب لم تنهض على ساق\nأيام أسحب أذيال الصبا مرحا … في فتية لطريق الخير سباق\nفيا لها ذكرة ! شب الغرام بها … نارا سرت بين أردانى وأطواقى\nعصر تولى ، وأبقى فى الفؤاد هوى … يكاد يشمل أحشائي بإحراق\nوالمرء طوع الليالى فى تصرفها … لا يملك الأمر من نجح وإخفاق\nعلي شيم الغوادي كلما برقت … وما على إذا ضنت برقراق\nفلا يعبنى حسود أن جرى قدر … فليس لي غير ما يقضيه خلاقي\nأسلمت نفسى لمولى لا يخيب له … راج على الدهر ، والمولى هو الواقى\nوهون الخطب عندى أنني رجل … لاق من الدهر ما كل امرىء لاقي\nيا قلب صبرا جميلا ، إنه قدر … يجرى على المرء من أسر وإطلاق\nلا بد للضيق بعد اليأس من فرج … وكل داجية يوما لإشراق"},{"id":"diwan-barudi:309","bookId":"diwan-barudi","type":"poem","seq":309,"chapter":"البحر: طويل","title":"دعانى إلى غى الصبا بعد ما مضى","page":"","text":"دعانى إلى غى الصبا بعد ما مضى … مكان كفردوس الجنان أنيق\nفسيح مجال العين ، أما غديره … فطام ، وأما غصنه فرشيق\nكسا أرضه ثوبا من الظل باسق … من الأيك فينان السراة وريق\nسمت صعدا أفنانه ، فكأنما … لها عند إحدى النيرات عشيق\nيمد شعاع الشمس فى حجراتها … سلاسل من نور لهن بريق\nويشدو بها القمري حتى كأنه … أخو صبوة ، أو دب فيه رحيق\nتمر طيور الماء فيها عصائبا … كركب عجال ضمهن طريق\nإذا أبصرت زرق الموارد رفرفت … عليها : فطاف فوقها ، وغريق\nغدونا له والفجر ينصاح ضوؤه … فينمو ، وأقطار الظلام تضيق\nوللطير فى مهد الأراكة رنة … وللطل فى ثغر الأقاحة ريق\nملاعب زانتها الرفاق ، ولم يكن … ليحسن لهو يزنه رفيق\nومنزل أنس قد عقدنا بجوه … رتائم لهو عقدهن وثيق\nجمعنا به الأشتات من كل لذة … وما كل يوم بالسرور حقيق\nوغنى لنا شاد أغن مقرطق … رفيق بجس الملهيات لبيق\nإذا مد من صوت ورجع أقبلت … علينا وجوه العيش وهو رقيق\nفيا حسنه من منزل لم يطف به … غوى ، ولم يحلل حماه لصيق\nجعلناه تاريخا لأيام صبوة … إذا ذكرت مس القلوب حريق\nأقمنا به يوما طليقا ، وليلة … دجاها بلألاء المدام طليق\nفلما اتعدنا للرواح تروعت … قلوب الندامى ، والمحب شفيق\nفلله قلب بالفراق مروع … حزين ، وجفن بالدموع شريق\nوقال لى الخلان : صف حسن يومنا … فأنت بنجدي الكلام خليق\nفرويت شيئا ، ثم جئت بمنطق … ذكى يفوق المسك وهو فتيق\nوكيف يغب الفول عنى وفى فمى … لسان كغرب المشرفى ذليق ؟"},{"id":"diwan-barudi:310","bookId":"diwan-barudi","type":"poem","seq":310,"chapter":"البحر: طويل","title":"لأي خليل في الزمان أرافق","page":"","text":"لأي خليل في الزمان أرافق … وأكثر من لاقيت خب منافق ؟\nبلوت بني الدنيا ، فلم أر صادقا … فأين لعمري الأكرمون الأصادق ؟\nأحاول أمرا قصرت دونه النهى … وشابت ولم تبلغ مداه المفارق\nوأعظم ما ترجوه ما لا تناله … وأكثر من تلقاه من لا يوافق\nوما كل من حد الروية حازم … ولا كل من رام السوية فارق\nأضعت زماني بين قوم لو ان لي … بهم غيرهم ما أرهقتنى البوائق\nفإن أك ملقى الرحل فيهم فإننى … لهم بالخلال الصالحات مفارق\nمعاشر سادوا بالنفاق ، وما لهم … أصول أظلتها فروع بواسق\nفأعلمهم عند الخصومة جاهل … وأتقاهم عند العفافة فاسق\nطلاقة وجه تحتها الغيظ كاشر … ونغمة ود بينها الغدر ناعق\nوأخلاق صبيان إذا ما بلوتهم … علمت بأن الجهل في الناس نافق\nتعلمت كظم الغيظ فيهم ، وإنه … لحلم ، ولكن للحفيظة ماحق\nدعونى إلى الجلى ، فقمت مبادرا … وإنى إلى أمثال تلك لسابق\nفلما استمر الجد ساقوا حمولهم … إلى حيث لو يبلغه حاد وسائق\nفلا رحم الله امرأ باع دينه … بدنيا سواه وهو للحق رامق\nعلى أنني حذرتهم غب أمرهم … وأنذرتهم لو كان يفقه مائق\nوقلت لهم : كفوا عن الشر تغنموا … فللشر يوم - لامحالة - ماحق\nفظنوا بقولى غير ما فى يقينه … على أنني في كل ما قلت صادق\nفهل علموا أني صدعت بحجتي … وقد ظهرت بعد الخفاء الحقائق ؟\nفتبا لهم من معشر ليس فيهم … رشيد ، ولا منهم خليل مصادق\nظننت بهم خيرا ، فأبت بحسرة … لها شجن بين الجوانح لاصق\nفياليتنى راجعت حلمى ، ولم أكن … زعيما ، وعاقتنى لذاك العوائق\nويا ليتني أصبحت في رأس شاهق … ولم أرى ما آلت إليه الوثائق\nهم عرضوني للقنا ، ثم أعرضوا … سراعا ولم يطرق من الشر طارق\nوقد أقسموا ألا يزولوا ، فما بدا … سنا الفجر إلا والنساء طوالق\nمضوا غير معذورين ، لا النقع ساطع … ولا البيض في أيدي الكماة دوالق\nولكن دعتهم نبأة ، فتفرقوا … كما انقض في سرب من الطير باشق\nفكم آبق تلقاه من غير طارد … وكم واقف تلقاه والعقل آبق\nإذا أبصروا شخصا يقولون جحفل … وجبن الفتى سيف لعينيه بارق\nأسود لدى الأبيات بين نسائهم … ولكنهم عند الهياج نقانق\nإذا المرء لم ينهض بقائم سيفه … فيا ليت شعرى ، كيف تحمى الحقائق ؟"},{"id":"diwan-barudi:311","bookId":"diwan-barudi","type":"poem","seq":311,"chapter":"البحر: كامل تام","title":"إن ابن آدم ذو طبائع أربع","page":"","text":"إن ابن آدم ذو طبائع أربع … مجموعة الأجزاء فى أخلاقه\nتبدو فواعلها على حركاته … فى بطشه وسكونه ونزاقه\nفإذا تغلب واحد منها على … أقرانه أدى إلى إقلاقه\nبينا تراه كالزلال لطافه … ألفيته كالنار في إحراقه\nأو كالتراب يهيل من عقداته … أو كالهواء يجول في آفاقه\nفإذا تعادل جمعها ، وتوازنت … حركاتها كانت دليل وفاقه\nوالمرء مهما كان في أفعاله … لا ينتهي إلا إلى أعراقه"},{"id":"diwan-barudi:312","bookId":"diwan-barudi","type":"poem","seq":312,"chapter":"البحر: وافر تام","title":"أضن بصاحبى ، وأذود عنه","page":"","text":"أضن بصاحبى ، وأذود عنه … وأمنحه السوية فى الحقوق\nوإن غدر الزمان به فإنى … أقوم بنصره فعل الصديق\nإذا ما المرء لم ينفع أخاه … على الحالين في سعة وضيق\nفدعه غير مأسوف عليه … فخير منه إخوان الطريق"},{"id":"diwan-barudi:313","bookId":"diwan-barudi","type":"poem","seq":313,"chapter":"البحر: طويل","title":"إذا المرء لم يرم الهناة بمثلها","page":"","text":"إذا المرء لم يرم الهناة بمثلها … ليدفع ضيما ، فهو بالذل أخلق\nومن شهد الهيجاء من غير آلة … يذود بها عن نفسه ، فهو أحمق"},{"id":"diwan-barudi:314","bookId":"diwan-barudi","type":"poem","seq":314,"chapter":"البحر: كامل تام","title":"اكتم ضميرك من عدوك جاهدا","page":"","text":"اكتم ضميرك من عدوك جاهدا … وحذار لا تطلع عليه رفيقا\nفلربما انقلب الصديق معاديا … ولربما رجع العدو صديقا"},{"id":"diwan-barudi:315","bookId":"diwan-barudi","type":"poem","seq":315,"chapter":"البحر: طويل","title":"ترنم بأشعاري ، ودع كل منطق","page":"","text":"ترنم بأشعاري ، ودع كل منطق … فما بعد قولي من بلاغ لمفلق\nهو العسل الماذي طورا ، وتارة … يثور الشجا منه مكان المخنق\nيغنى به شاد ، ويحدو ركابه … به كل حاد بين بيداء سملق\nفطورا تراه زهرة بين مجلس … وطورا تراه لهذما بين فيلق\nوما كلفي بالشعر إلا لأنه … منار لسار ، أو نكال لأحمق\nعلقت به طفلا ، وشبت ولم يزل … شديدا بأهداب الكلام تعلقي\nإذا قلت بيتا سار في الدهر ذكره … مسير الحيا ما بين غرب ومشرق\nيهيم به رب الحسام حماسة … وتلهو به ذات الوشاح المنمق\nبلغت بشعري ما أردت ، فلم أدع … بدائع في أكمامها لم تفتق\nفهذا نمير الشعر ، فاقصد حياضه … لتروى ، وهذا مرتقى الفضل فارتق"},{"id":"diwan-barudi:316","bookId":"diwan-barudi","type":"poem","seq":316,"chapter":"البحر: طويل","title":"سل الفلك الدوار إن كان ينطق","page":"","text":"سل الفلك الدوار إن كان ينطق … وكيف يحير الهوى أخرس مطرق ؟\nنسائله عن شأنه وهو صامت … ونخبر ما في نفسه وهو مطبق\nفلا سره يبدو ، ولا نحن نرعوى … ولا شأوه يدنو ، ولا نحن نلحق\nوكيف تنال النفس منه لبانة … وأقرب ما فيه عن الظن أسحق ؟\nفضاء يرد العين حسرى ، ومسرح … يقص جناح الفكر وهو محلق\nأقام على رغم الفناء ، وكل ما … تراه على وجه البسيطة ينفق\nفكم ثل عرشا ، واستباح قبيلة … وفرق جمعا وهو لا يتفرق\nتحسى مرارات الكبود ، فلم تزل … به صبغة من لونها ، فهو أزرق\nنهار وليل يدأبان ، وأنجم … تغيب إلى ميقاتها ، ثم تشرق\nترف كزهر طوحته عواصف … بلجة ماء ، فهو يطفو ويغرق\nسوابح لا تنفك تجرى لغاية … يقصر عنها الكاهن المتعمق\nفيأيها الساري على غير هدية … رويدا ، فإن الباب دونك مغلق\nأتحسب أن الظن يدرك بعض ما … تحاوله والظن للمرء موبق ؟\nوكيف ينال الحس وهو محدد … سريرة غيب دونها الحس يصعق ؟\nفلا تتبع ريب الظنون ، فكل ما … تصوره الإنسان وهم ملفق\nولا تحسبن الحدس يدرك ما نأى … فما كل حين قائف الحدس يصدق\nوأين من المخلوق إدراك حكمة … بها ينشيء الله القرون ويمحق ؟\nفلو علم الإنسان حالة نفسه … كفاه ، ولكن ابن آدم أخرق\nإذا المرء لم يملك بوادر وهمه … عن القول فيما لم يفد فهو أحمق\nفإياك والدنيا ، فإن نعيمها … يزول ، وملبوس الجديدين يخلق\nفإن هي أعطتك الليان فإنها … ستخشن من بعد الليان وتخرق\nفلا ودها يبقى ، ولا صفو عيشها … يدوم ، ولا موعودها يتحقق\nفكم أخلفت وعدا ، وملت صحابة … وخانت وفيا ، فهى بلهاء تنزق\nوكيف يعيش الدهر خلوا من الأسى … سقيم يغادى بالهموم ويطرق ؟\nلعمر أبي إن الحياة وإن صفت … مسافة يوم - فهو صفو مرنق\nففيم يود المرء طول حياته … وفى طولها شمل الهناء مفرق ؟\nوما الدهر إلا مستعد لوثبة … فحذرك ، منه ، فهو غضبان مطرق\nكأن هلال الأفق سيف مجرد … علينا به ، والنجم سهم مفوق\nأباد بنيه ظالما غير راحم … فيا عجبا من والد ليس يشفق\nفلا تبتئس بالأمر تخشى وقوعه … فقد يأمن الإنسان من حيث يفرق\nفما كل ما تهواه يأتيك بالمنى … ولا كل ما تخشاه في الدهر يطرق\nوكن واثقا بالله فى كل محنة … فلله أولى بالعباد وأرفق"},{"id":"diwan-barudi:317","bookId":"diwan-barudi","type":"poem","seq":317,"chapter":"البحر: طويل","title":"أسلة سيف ، أم عقيقة بارق","page":"","text":"أسلة سيف ، أم عقيقة بارق … أضاءت لنا وهنا سماوة بارق ؟\nلوى الركب أعناقا إليها خواضعا … بزفرة محزون ، ونظرة وامق\nوفى حركات البرق للشوق آية … تدل على ما جنه كل عاشق\nتفض جفونا عن دموع سوائل … وتفري صدورا عن قلوب خوافق\nوكيف يعى سر الهوى غير أهله … ويعرف معنى الشوق من لم يفارق\nلعمر الهوى إنى لدن شفنى النوى … لفى وله من سورة الوجد ماحق\nكفى بمقامى فى ' سرنديب ' غربة … نزعت بها عني ثياب العلائق\nومن رام نيل العز فليصطبر على … لقاء المنايا ، واقتحام المضايق\nفإن تكن الأيام رنقن مشربى … وثلمن حدى بالخطوب الطوارق\nفما غيرتني محنة عن خليقتي … ولا حولتنى خدعة عن طرائقى\nولكنني باق على ما يسرني … ويغضب أعدائى ، ويرضى أصادقى\nفحسرة بعدى عن حبيب مصادق … كفرحة بعدي عن عدو مماذق\nفتلك بهذى ، والنجاة غنيمة … من الناس ، والدنيا مكيدة حاذق\nألا ، أيها الزارى على بجهله … ولم يدر أنى درة فى المفارق\nتعز عن العلياء باللؤم ، واعتزل … فإن العلا ليست بلغو المناطق\nفما أنا ممن تقبل الضيم نفسه … ويرضى بما يرضى به كل مائق\nإذا المرء لم ينهض لما فيه مجده … قضى وهو كل في خدور العواتق\nوأى حياة لامرئ إن تنكرت … له الحال لم يعقد سيور المناطق ؟\nفما قذفات العز إلا لماجد … إذا هم جلى عزمه كل غاسق\nيقول أناس ، إننى ثرت خالعا … وتلك هنات لم تكن من خلائقي\nولكنني ناديت بالعدل طالبا … رضا الله ، واستنهضت أهل الحقائق\nأمرت بمعروف ، وأنكرت منكرا … وذلك حكم في رقاب الخلائق\nفإن كان عصيانا قيامى ، فإننى … أردت بعصياني إطاعة خالقي\nوهل دعوة الشورى علي غضاضة … وفيها لمن يبغي الهدى كل فارق ؟\nبلى ، إنها فرض من الله واجب … على كل حي من مسوق وسائق\nوكيف يكون المرء حرا مهذبا … ويرضى بما يأتى به كل فاسق ؟\nفإن نافق الأقوام فى الدين غدرة … فإنى بحمد الله غير منافق\nعلى أنني لم آل نصحا لمعشر … أبى غدرهم أن يقبلوا قول صادق\nرأوا أن يسوسوا الناس قهرا ، فأسرعوا … إلى نقض ما شادته أيدي الوثائق\nفلما استمر الظلم قامت عصابة … من الجند تسعى تحت ظل الخوافق\nوشايعهم أهل البلاد ، فأقبلوا … إليهم سراعا بين آت ولاحق\nيرومون من مولى البلاد نفاذ ما … تألاه من وعد إلى الناس صادق\nفهذا هو الحق المبين ، فلا تسل … سواي ، فإني عالم بالحقائق\nفيا ( مصر ) مد الله ظلك ، وارتوى … ثراك بسلسال من النيل دافق\nولا برحت تمتار منك يد الصبا … أريجا يداوى عرفه كل ناشق\nفأنت حمى قومي ، ومشعب أسرتي … وملعب أترابى ، ومجرى سوابقى\nبلاد بها حل الشباب تمائمي … وناط نجاد المشرفى بعاتقى\nإذا صاغها بهزار فكري تصورت … لعيني في زي من الحسن رائق\nتركت بها أهلا كراما ، وجيرة … لهم جيرة تعتادنى كل شارق\nهجرت لذيذ العيش بعد فراقهم … وودعت ريعان الشباب الغرانق\nفهل تسمح الأيام لى بلقائهم … ويسعد في الدنيا مشوق بشائق ؟\nلعمرى لقد طال النوى ، وتقطعت … وسائل كانت قبل شتى المواثق\nفإن تكن الأيام ساءت صروفها … فإنى بفضل الله أول واثق\nفقد يستقيم الأمر بعد اعوجاجه … ويرجع للأوطان كل مفارق"},{"id":"diwan-barudi:318","bookId":"diwan-barudi","type":"poem","seq":318,"chapter":"البحر: رمل تام","title":"غلب الوجد عليه ، فبكى","page":"","text":"غلب الوجد عليه ، فبكى … وتولى الصبر عنه ، فشكا\nوتمنى نظرة يشفى بها … علة الشوق ، فكانت مهلكا\nيا لها من نظرة ! ما قاربت … مهبط الحكمة حتى انهتكا\nنظرة ضم عليها هدبه … ثم أغراها ، فكانت شركا\nغرست في القلب مني حبه … وسقته أدمعى حتى زكا\nآه من برح الهوى ! إن له … بين جنبى من النار ذكا\nكان أبقى الوجد منى رمقا … فاحتوى البين على ما تركا\nإن طرفى غر قلبى ، فمضى … في سبيل الشوق حتى هلكا\nقد تولى إثر غزلان النقا … ليت شعرى ، أى واد سلكا\nلم يعد بعد ، وظنى أنه … لج في نيل المنى فارتبكا\nويح قلبى من غريم ماطل … كلما جدد وعدا أفكا\nظن بى سوءا وقد ساومته … قبلة ، فازور حتى فركا\nفاغتفرها زلة من خاطئ … لم يكن بالله يوما أشركا\nيا غزالا نصبت أهدابه … بيد السحر لضمي شبكا\nقد ملكت القلب ، فاستوص به … إنه حق على من ملكا\nلا تعذبه على طاعته … بعد ما تيمته ، فهو لكا\nغلب اليأس على حسن المنى … فيك ، واستولى على الضحك البكا\nفإلى من أشتكى ما شفنى … من غرام ، وإليك المشتكى ؟\nسلكت نفسى سبيلا فى الهوى … لم تدع فيه لغيرتى مسلكا"},{"id":"diwan-barudi:319","bookId":"diwan-barudi","type":"poem","seq":319,"chapter":"البحر: سريع","title":"يا ويح نفسى من هوى شادن","page":"","text":"يا ويح نفسى من هوى شادن … غازل قلبي لحظه فانهتك\nذى نظرة كالسحر ، لو صادفت … غمزتها ليث وغى ما فتك\nفكيف أحمى مهجتى بعد ما … خامرها الوجد ؛ فطارت بتك ؟\nفلا يلمني غافل ، فالهوى … سيف إذا مر بشيء بتك\nماذا على من بخلت نفسه … بالوصل لو قبلت طرف الأتك ؟"},{"id":"diwan-barudi:320","bookId":"diwan-barudi","type":"poem","seq":320,"chapter":"البحر: كامل تام","title":"تالله لست بهالك جوعا ، ولا","page":"","text":"تالله لست بهالك جوعا ، ولا … لاق وإن طوفت إلا رزقكا\nإن كنت تؤمن بالذى خلق الورى … وأقاته ، فعلام تقتل نفسكا ؟"}]};